class ExceptionSurfaceTests(SimpleTestCase):
    """PAN-SPY-005 and PAN-VLN-004. Measured 2026-10-10.

    An anti-spyware profile can hold exceptions in FOUR places and controls.json names one.
    Counting only the named one meant a profile exempting half an estate through
    `inline-exception-ip-address` counted zero.
    """

    def test_a_profile_with_no_exceptions_anywhere_counts_nothing(self):
        self.assertEqual(exception_surfaces({"@name": "clean"}), {})

    def test_the_surface_controls_json_names(self):
        got = exception_surfaces({"threat-exception": {"entry": [
            {"@name": "12345"}, {"@name": "67890"}]}})

        self.assertEqual(got, {"threat-exception": 2})

    def test_the_three_surfaces_it_does_NOT_name(self):
        """Each of these disables a protection as surely as a signature exception, and each
        was invisible to the count before."""
        got = exception_surfaces({
            "botnet-domains": {
                "threat-exception": {"entry": [{"@name": "dns-sig"}]},
                "whitelist": {"entry": [{"@name": "example.com"}, {"@name": "b.test"}]},
            },
            "inline-exception-ip-address": {"member": ["10.0.0.1", "10.0.0.2", "10.0.0.3"]},
            "inline-exception-edl-url": {"member": ["my-edl"]},
        })

        self.assertEqual(got, {"botnet-threat-exception": 1, "botnet-whitelist": 2,
                               "inline-exception-ip-address": 3,
                               "inline-exception-edl-url": 1})

    def test_only_surfaces_that_hold_something_are_reported(self):
        """An empty surface is not a finding and must not clutter the detail."""
        got = exception_surfaces({"threat-exception": {"entry": []},
                                  "inline-exception-ip-address": {"member": []}})

        self.assertEqual(got, {})

    def test_a_vulnerability_profile_has_no_botnet_surfaces(self):
        """It has no botnet tree at all, so two of the four cannot exist there. That is a
        real difference rather than a gap - what exists is counted."""
        got = exception_surfaces({"threat-exception": {"entry": [{"@name": "1"}]},
                                  "inline-exception-ip-address": {"member": ["10.0.0.1"]}})

        self.assertNotIn("botnet-threat-exception", got)
        self.assertEqual(sum(got.values()), 2)

    def test_a_single_member_arriving_unwrapped_is_still_counted(self):
        got = exception_surfaces({"inline-exception-ip-address": {"member": "10.0.0.1"}})

        self.assertEqual(got, {"inline-exception-ip-address": 1})

    def test_the_total_is_what_the_column_stores(self):
        """`threat_exception_count` keeps its name because every consumer reads it; what
        changed is that it no longer under-counts."""
        got = exception_surfaces({
            "threat-exception": {"entry": [{"@name": "a"}]},
            "botnet-domains": {"whitelist": {"entry": [{"@name": "b"}]}},
            "inline-exception-ip-address": {"member": ["10.0.0.1", "10.0.0.2"]}})

        self.assertEqual(sum(got.values()), 4)


class InlineCloudDetectorTests(SimpleTestCase):
    """PAN-SPY-004 and PAN-VLN-003, measured on pan-fw-111 2026-10-10.

    controls.json points both at `cloud-inline-analysis/enabled`, which the device refuses
    with `cloud-inline-analysis is invalid` even with ATP licensed. The real node is
    `mica-engine-{spyware,vulnerability}-enabled`, which is what the corpus describes.
    """

    SPY = SecurityProfile.KIND_SPYWARE
    VLN = SecurityProfile.KIND_VULNERABILITY

    def test_the_two_kinds_read_DIFFERENT_nodes(self):
        """A spyware profile's detectors are not a vulnerability profile's, and reading the
        wrong node would return nothing while looking like a clean profile."""
        spyware = {"mica-engine-spyware-enabled": {"entry": [
            {"@name": "SSL Command and Control detector",
             "inline-policy-action": "reset-both"}]}}

        self.assertEqual(profile_inline_detectors(self.SPY, spyware),
                         {"SSL Command and Control detector": "reset-both"})
        self.assertEqual(profile_inline_detectors(self.VLN, spyware), {})

    def test_a_profile_naming_no_detectors_yields_nothing_to_read(self):
        self.assertEqual(profile_inline_detectors(self.SPY, {"@name": "p"}), {})

    def test_the_catalogue_falls_back_to_the_measured_key_space(self):
        """UNLIKE the antivirus ML models, which could rely on the predefined profile
        carrying every one. A predefined spyware profile need not mention this engine at
        all, and an empty catalogue would write no rows - which reads as "nothing is
        unprotected", the direction these controls must never fail in."""
        self.assertEqual(sorted(inline_detector_catalogue([], self.SPY)),
                         sorted(SecurityProfileInlineDetector.SPYWARE_DETECTORS))
        self.assertEqual(sorted(inline_detector_catalogue([], self.VLN)),
                         sorted(SecurityProfileInlineDetector.VULNERABILITY_DETECTORS))

    def test_the_catalogue_picks_up_a_detector_the_constant_does_not_have(self):
        """A content release that adds one is assessed with no code change."""
        class Fake:
            kind = SecurityProfile.KIND_VULNERABILITY
            inline_detectors = {"Brand New Detector": "alert"}

        got = inline_detector_catalogue([Fake()], self.VLN)
        self.assertIn("Brand New Detector", got)
        self.assertIn("SQL Injection", got)

    def test_spyware_offers_drop_and_vulnerability_does_not(self):
        """Measured, and the reason the action values are per kind rather than one constant.
        A shared enum would accept `drop` on a vulnerability detector, which the device
        rejects."""
        self.assertIn("drop", SecurityProfileInlineDetector.SPYWARE_ACTIONS)
        self.assertNotIn("drop", SecurityProfileInlineDetector.VULNERABILITY_ACTIONS)

    def test_alert_runs_without_blocking(self):
        """The `enable(alert-only)` case from PAN-AVW-002 under another name: a detector on
        `alert` runs and lets the traffic through, so `enabled` and `blocks` are different
        questions and the control asks the second."""
        action = "alert"
        self.assertTrue(bool(action))
        self.assertNotIn(action, SecurityProfileInlineDetector.BLOCKING_ACTIONS)

    def test_an_unmentioned_detector_neither_runs_nor_blocks(self):
        self.assertFalse(bool(""))
        self.assertNotIn("", SecurityProfileInlineDetector.BLOCKING_ACTIONS)

    def test_a_single_detector_arriving_unwrapped_is_still_read(self):
        entry = {"mica-engine-vulnerability-enabled": {"entry": {
            "@name": "SQL Injection", "inline-policy-action": "reset-both"}}}

        self.assertEqual(profile_inline_detectors(self.VLN, entry),
                         {"SQL Injection": "reset-both"})


class WildfireDeviceSettingsTests(SimpleTestCase):
    """deviceconfig/setting/wildfire. PAN-AVW-004 and PAN-AVW-005, measured 2026-10-09.

    The two things most easily got wrong are both here: session information is stored as
    EXCLUSIONS, so empty is the good state; and a size limit equal to its default was set by
    nobody, which is what makes the tuning check possible.
    """

    def test_session_information_is_stored_as_EXCLUSIONS_so_empty_is_good(self):
        """The twelve enum members are all `exclude-*`. A ticked UI checkbox means the
        exclusion is ABSENT, so an empty list is FULL sharing - the opposite of this
        codebase's usual rule that an absent key is the weaker end."""
        self.assertEqual(exclusions({}, "session-info-select"), [])
        self.assertEqual(
            exclusions({"session-info-select": {"member": ["exclude-url",
                                                           "exclude-username"]}},
                       "session-info-select"),
            ["exclude-url", "exclude-username"])

    def test_a_single_exclusion_arriving_unwrapped_is_still_read(self):
        self.assertEqual(
            exclusions({"session-info-select": {"member": "exclude-filename"}},
                       "session-info-select"),
            ["exclude-filename"])

    def test_the_inline_block_is_read_separately(self):
        node = {"session-info-select": {"member": ["exclude-url"]},
                "cloud-inline-wf-session-info-select": {"member": ["exclude-src-ip"]}}

        self.assertEqual(exclusions(node, "session-info-select"), ["exclude-url"])
        self.assertEqual(exclusions(node, "cloud-inline-wf-session-info-select"),
                         ["exclude-src-ip"])

    def test_size_limits_read_only_what_the_config_names(self):
        node = {"file-size-limit": {"entry": [
            {"@name": "pe", "size-limit": "50"},
            {"@name": "pdf", "size-limit": {"#text": "4096"}}]}}

        self.assertEqual(size_limits(node), {"pe": 50, "pdf": 4096})

    #: PAN-OS's own declared defaults, read off Panorama's Size Limit tooltip 2026-10-10.
    V11_1 = defaults_for_version("11.1.13-h3")

    def test_a_device_that_configures_NOTHING_is_entirely_untuned(self):
        """The clearest case, and the one walking only configured entries would miss: no
        file-size-limit node at all means every type is still at its default."""
        self.assertEqual(sorted(untuned({}, self.V11_1)), sorted(self.V11_1))

    def test_the_asserted_set_is_the_same_on_both_releases(self):
        """11.2 adds `eml` - ten keys on 11.1, eleven on 11.2 - but `eml` is excluded on two
        counts, so what the control asserts does not vary by release and needs no version
        key. The argument is kept for the day a release does diverge."""
        self.assertEqual(defaults_for_version("11.1.13-h3"),
                         defaults_for_version("11.2.3-h3"))
        self.assertEqual(len(self.V11_1), 10)
        self.assertNotIn("eml", self.V11_1)

    def test_ms_office_defaults_to_16384_not_16385(self):
        """The lab's template stack held 16385, and an earlier table in this project recorded
        that as the default. Panorama's own tooltip says 16384, so the extra kilobyte was
        somebody's edit."""
        self.assertEqual(self.V11_1["ms-office"], 16384)

    def test_two_types_default_to_their_MAXIMUM(self):
        """archive and linux. Worth knowing for the reading of PAN-AVW-004 that was NOT
        taken: a check asserting "raised to the platform maximum" could never fire on these
        however an estate was configured."""
        for file_type in ("archive", "linux"):
            low, high = WildfireSettings.SIZE_LIMIT_RANGE[file_type]
            self.assertEqual(self.V11_1[file_type], high)

    def test_a_type_set_to_its_own_default_counts_as_untuned(self):
        """PAN-AVW-004 is a TUNING check (Jason, 2026-10-09): the question is whether anyone
        sized this for the estate, and a value equal to the default answers no however it
        got there."""
        self.assertIn("pe", untuned({"pe": self.V11_1["pe"]}, self.V11_1))

    def test_a_type_moved_off_its_default_is_tuned_either_way(self):
        """Up or down. The vendor advises tuning DOWN against buffer space - Help p.774 -
        so a lowered limit is evidence of tuning exactly as a raised one is."""
        self.assertNotIn("pe", untuned({"pe": 50}, self.V11_1))
        self.assertNotIn("pe", untuned({"pe": 1}, self.V11_1))

    def test_eml_is_excluded_because_a_TEMPLATE_cannot_set_it(self):
        """Measured 2026-10-09 by trying: the write is refused with `eml 'eml' is not a valid
        reference`. On a Panorama-managed estate its only remediation is a device-local
        override, so asserting it would make the control unsatisfiable. It is absent from
        11.1 entirely and excluded from 11.2 when that table arrives."""
        self.assertIn("eml", WildfireSettings.TEMPLATE_UNSETTABLE)
        self.assertNotIn("eml", self.V11_1)

    def test_a_non_numeric_limit_is_skipped_rather_than_crashing(self):
        self.assertEqual(size_limits(
            {"file-size-limit": {"entry": [{"@name": "pe", "size-limit": ""}]}}), {})

    def test_the_twelve_items_are_CHILD_NODES_and_not_a_member_list(self):
        """Read off fw-core-tpa-a, serial 013201001475, 2026-10-29 - the one appliance in the
        lab that withholds anything:

            <session-info-select>
              <exclude-username>yes</exclude-username>
              <exclude-src-ip>yes</exclude-src-ip>
            </session-info-select>

        Stage 4 settled the shape by writing both forms at the same container: a `<member>` is
        REFUSED and a named child taking yes/no is ACCEPTED. Until this was fixed, the member
        branch was the only branch and this node read as the empty list - so
        `shares_full_session_info` was True, PAN-AVW-005's COMPLIANT side, on a firewall
        withholding a username and a source address."""
        node = {"session-info-select": {"exclude-username": "yes", "exclude-src-ip": "yes"}}

        self.assertEqual(exclusions(node, "session-info-select"),
                         ["exclude-src-ip", "exclude-username"])

    def test_a_child_set_to_no_is_SHARED_and_is_not_listed(self):
        """The key is present and says the item is shared, which is not a withholding."""
        node = {"session-info-select": {"exclude-url": "no", "exclude-username": "yes"}}

        self.assertEqual(exclusions(node, "session-info-select"), ["exclude-username"])

    def test_an_empty_container_withholds_nothing(self):
        """`cloud-inline-wf-session-info-select` was written as an empty container on
        fw-core-tpa-a and reads back as null. Nothing is withheld, which is full sharing."""
        self.assertEqual(
            exclusions({"cloud-inline-wf-session-info-select": None},
                       "cloud-inline-wf-session-info-select"), [])

    #: PAN-AVW-004's ALL quantifier, which is NOT `size_limits_untuned`'s ANY.
    def test_wholly_untuned_is_true_when_the_config_names_nothing(self):
        """fw-core-tpa-a's state before this wave, and pan-fw-201's today: no
        file-size-limit node at all, so nobody has sized this platform."""
        self.assertTrue(wholly_untuned({}, self.V11_1))

    def test_ONE_type_moved_answers_the_control_and_the_ANY_column_still_fires(self):
        """fw-core-tpa-a as the lab holds it: `pe` is 10 against a shipped 16, and the other
        nine are absent. The ALL column reads False - somebody sized something - while
        `size_limits_untuned` beside it still reads True, which is the disagreement stage 5
        recorded rather than resolved."""
        self.assertFalse(wholly_untuned({"pe": 10}, self.V11_1))
        self.assertTrue(bool(untuned({"pe": 10}, self.V11_1)))

    def test_a_type_set_to_its_own_default_does_not_count_as_moved(self):
        self.assertTrue(wholly_untuned({"pe": self.V11_1["pe"]}, self.V11_1))

    def test_an_unknown_release_fires_rather_than_passing(self):
        """No defaults table means the question cannot be answered, and the answer that
        cannot be wrong in the dangerous direction is the firing one."""
        self.assertTrue(wholly_untuned({"pe": 10}, {}))

    def test_the_verdict_gap_names_WHICH_half_is_missing(self):
        """The assertion is a disjunction over two booleans with a different severity on each
        half, and a clause list has no OR - so one token carries both."""
        self.assertEqual(verdict_reporting_gap(True, True), "none")
        self.assertEqual(verdict_reporting_gap(True, False), "grayware")
        self.assertEqual(verdict_reporting_gap(False, True), "benign")
        self.assertEqual(verdict_reporting_gap(False, False), "both")

    def test_the_three_lab_appliances_land_on_three_different_gap_tokens(self):
        """Measured 2026-10-29. fw-core-tpa-a (013201001475) has both leaves `yes`;
        pan-fw-111 (6A9C0A9904E7D6E) has grayware `yes` from a template and a device-local
        benign `no`; pan-fw-201 (691665AC334B458) has no wildfire node at all, so both
        leaves take the measured implicit `no`."""
        self.assertEqual(verdict_reporting_gap(True, True), "none")
        self.assertEqual(verdict_reporting_gap(False, True), "benign")
        self.assertEqual(verdict_reporting_gap(False, False), "both")


class WildfireAnalysisRuleTests(SimpleTestCase):
    """The WildFire analysis profile's match rules, measured on pan-fw-111 2026-10-09.

    The kind has NO ACTION ANYWHERE - a rule carries exactly application, file-type,
    direction and analysis, enumerated against a profile that does not exist so the answer is
    schema rather than membership. It decides what is SENT for analysis, never what happens
    to it, which is why PAN-AVW-003 asks about coverage rather than about blocking.
    """

    def test_a_profile_with_no_rules_node_submits_nothing(self):
        """Valid configuration, measured by writing it - and the state the control exists to
        find. Synthesizing a permissive row here would hide exactly that profile."""
        self.assertEqual(profile_wildfire_rules({"@name": "empty"}), [])

    def test_an_empty_rules_node_is_the_same_state(self):
        self.assertEqual(profile_wildfire_rules({"@name": "e", "rules": {}}), [])

    def test_the_shipped_default_submits_everything(self):
        """The predefined profile, read off the device: file-type any, application any,
        direction both, analysis public-cloud. The REVERSE of the antivirus kind, where the
        shipped profile fails its control - so this one is the passing case."""
        rows = profile_wildfire_rules({"@name": "default", "rules": {"entry": [
            {"@name": "default", "analysis": "public-cloud", "direction": "both",
             "file-type": {"member": ["any"]}, "application": {"member": ["any"]}}]}})

        name, apps, types, direction, analysis, all_ft, all_app, both = rows[0]
        self.assertEqual((name, apps, types), ("default", ["any"], ["any"]))
        self.assertEqual((direction, analysis), ("both", "public-cloud"))
        self.assertEqual((all_ft, all_app, both), (True, True, True))

    def test_a_named_file_type_is_not_every_file_type(self):
        rows = profile_wildfire_rules({"@name": "p", "rules": {"entry": [
            {"@name": "r", "file-type": {"member": ["pe", "pdf"]},
             "application": {"member": ["any"]}, "direction": "both"}]}})

        self.assertEqual(rows[0][2], ["pe", "pdf"])
        self.assertFalse(rows[0][5])
        self.assertTrue(rows[0][6])

    def test_an_absent_direction_and_analysis_STORE_NULL_rather_than_a_blank(self):
        """The device accepts a rule with neither key and stores neither - measured 2026-10-09.
        The UI writes `both` and `public-cloud` when a rule is added through the form, so no
        instance of the absent case exists to read and nothing establishes what the device then
        does. Stage 5 declared both columns `stores: null`, `rests_on: not_assumed`; until
        2026-10-29 this stored the empty string, which is a VALUE: `is_empty` compiles to
        `filter(field="")`, which matches `''` and does not match NULL, so a query written
        against the declaration and one written against the blank find different rows."""
        rows = profile_wildfire_rules({"@name": "p", "rules": {"entry": [
            {"@name": "r", "file-type": {"member": ["any"]},
             "application": {"member": ["any"]}}]}})

        self.assertIsNone(rows[0][3])
        self.assertIsNone(rows[0][4])
        self.assertNotEqual(rows[0][3], "")
        self.assertNotEqual(rows[0][4], "")
        self.assertIsNone(rows[0][7])

    def test_a_written_direction_and_analysis_are_stored_as_written(self):
        """The other side of the NULL: nothing is swallowed where the keys ARE written."""
        rows = profile_wildfire_rules({"@name": "p", "rules": {"entry": [
            {"@name": "r", "direction": "download", "analysis": "private-cloud"}]}})

        self.assertEqual((rows[0][3], rows[0][4]), ("download", "private-cloud"))

    def test_upload_only_does_not_cover_both_directions(self):
        rows = profile_wildfire_rules({"@name": "p", "rules": {"entry": [
            {"@name": "r", "file-type": {"member": ["any"]},
             "application": {"member": ["any"]}, "direction": "upload"}]}})

        self.assertFalse(rows[0][7])

    def test_a_rule_carrying_only_a_name_is_kept(self):
        """The device accepts it, so dropping it would lose a rule that exists."""
        rows = profile_wildfire_rules({"@name": "p", "rules": {"entry": [{"@name": "r"}]}})

        self.assertEqual(len(rows), 1)
        self.assertEqual((rows[0][1], rows[0][2]), ([], []))
        self.assertEqual((rows[0][5], rows[0][6], rows[0][7]), (False, False, None))

    def test_a_single_rule_arriving_unwrapped_is_still_read(self):
        rows = profile_wildfire_rules({"@name": "p", "rules": {"entry": {
            "@name": "r", "file-type": {"member": ["any"]}}}})

        self.assertEqual(len(rows), 1)
        self.assertTrue(rows[0][5])

    def test_a_rule_with_no_name_is_skipped_rather_than_crashing(self):
        rows = profile_wildfire_rules({"@name": "p", "rules": {"entry": [
            {"file-type": {"member": ["any"]}}, {"@name": "r"}]}})

        self.assertEqual([r[0] for r in rows], ["r"])


class WildfireCoverageAggregateTests(SimpleTestCase):
    """PAN-AVW-003's three columns on the PROFILE row, which are a UNION over its rules.

    The rows they summarise live on `SecurityProfileWildfireRule`, which is in no search
    registry - so no clause can name a column of theirs and the aggregate is the only way the
    coverage becomes reportable. Every input below is a profile stage 6 left standing on
    pan-fw-111, serial 6A9C0A9904E7D6E.
    """

    def _rules(self, *specs):
        entry = {"@name": "p", "rules": {"entry": [
            dict({"@name": f"r{i}"}, **spec) for i, spec in enumerate(specs)]}}
        return wildfire_coverage_aggregates(profile_wildfire_rules(entry))

    ANY = {"member": ["any"]}

    def test_no_rules_covers_nothing_and_the_direction_is_NULL(self):
        """oep-avw6-w4: a bare entry with no rules node. Valid committed configuration that
        submits nothing, and the commonest failing state there is - so the answer must be a
        reading and not an absence. The null reports at the baseline severity, which is what
        stage 3 prescribes for a profile that loses both directions."""
        aggregates = wildfire_coverage_aggregates([])

        self.assertEqual(aggregates, {"submits_all_file_types": False,
                                      "covers_all_applications": False,
                                      "direction_coverage": None})

    def test_one_rule_covering_everything_both_ways(self):
        """oep-avw6-w3, and the shipped predefined profile."""
        self.assertEqual(
            self._rules({"file-type": self.ANY, "application": self.ANY,
                         "direction": "both"}),
            {"submits_all_file_types": True, "covers_all_applications": True,
             "direction_coverage": "both"})

    def test_upload_only_and_download_only_are_kept_apart(self):
        """oep-avw6-w1 and oep-avw6-w2. INBOUND IS DELIVERY, so `upload` alone leaves every
        delivered file unanalysed and the two tokens cannot be collapsed."""
        self.assertEqual(
            self._rules({"file-type": self.ANY, "application": self.ANY,
                         "direction": "upload"})["direction_coverage"], "upload")
        self.assertEqual(
            self._rules({"file-type": self.ANY, "application": self.ANY,
                         "direction": "download"})["direction_coverage"], "download")

    def test_TWO_RULES_SUM_TO_BOTH_and_neither_row_says_so(self):
        """The clearest case of a union no per-rule predicate can form: one `upload` rule and
        one `download` rule cover both directions between them."""
        self.assertEqual(
            self._rules({"file-type": self.ANY, "application": self.ANY,
                         "direction": "upload"},
                        {"file-type": self.ANY, "application": self.ANY,
                         "direction": "download"})["direction_coverage"], "both")

    def test_coverage_can_be_reached_through_DIFFERENT_rules(self):
        """A profile can reach every file type through one rule and every application through
        another, with no single rule satisfying the control."""
        self.assertEqual(
            self._rules({"file-type": self.ANY, "application": {"member": ["ftp"]},
                         "direction": "both"},
                        {"file-type": {"member": ["pe"]}, "application": self.ANY,
                         "direction": "both"}),
            {"submits_all_file_types": True, "covers_all_applications": True,
             "direction_coverage": "both"})

    def test_a_narrowed_type_set_is_not_every_type(self):
        """oep-avw6-w5: every application, both directions, one file type. The column can only
        ever answer `some rule names any` - the accepted type set moves with the content
        release and is in no configuration read, so a list of named types has no denominator
        to be complete against."""
        self.assertEqual(
            self._rules({"file-type": {"member": ["pe"]}, "application": self.ANY,
                         "direction": "both"}),
            {"submits_all_file_types": False, "covers_all_applications": True,
             "direction_coverage": "both"})

    def test_a_narrowed_application_set_is_not_every_application(self):
        """oep-avw6-w6, the mirror of w5."""
        self.assertEqual(
            self._rules({"file-type": self.ANY, "application": {"member": ["ftp"]},
                         "direction": "both"}),
            {"submits_all_file_types": True, "covers_all_applications": False,
             "direction_coverage": "both"})

    def test_a_rule_with_no_direction_leaves_the_direction_NULL(self):
        """oep-avw6-w7: the two children the device makes mandatory and nothing else. What an
        absent `direction` means was never established, so the union of nothing is a null and
        not a guess - and the type and application coverage is still read."""
        self.assertEqual(
            self._rules({"file-type": self.ANY, "application": self.ANY}),
            {"submits_all_file_types": True, "covers_all_applications": True,
             "direction_coverage": None})


class AntivirusPostureAggregateTests(SimpleTestCase):
    """PAN-AVW-001 and 002's graded columns on the PROFILE row.

    The booleans beside them - `has_non_blocking_decoder` and the rest - carry the assertion;
    these carry the SEVERITY, because a grading places VALUES and a boolean has only two. The
    rows they summarise are on three models that are in no search registry.

    Every input is one of the fifteen antivirus profiles stage 6 left standing on pan-fw-111,
    serial 6A9C0A9904E7D6E.
    """

    CATALOGUE = ["MSOffice", "Windows Executables"]

    def _decoders(self, *effective_actions):
        """Only index 2 - the EFFECTIVE action - is read, so the rest is padding."""
        return [("http", "", action, False, "", "", False, "", "", False)
                for action in effective_actions]

    def test_every_decoder_allowing_is_the_weakest_reading(self):
        """oep-avw6-01: all seven protocols `allow` on all three verdict kinds."""
        self.assertEqual(
            antivirus_posture_aggregates(
                self._decoders(*["allow"] * 7), [("ftp", "allow", False)],
                {"MSOffice": "disable", "Windows Executables": "disable"}, self.CATALOGUE),
            {"weakest_decoder_action": "allow",
             "weakest_application_override_action": "allow",
             "weakest_ml_model_state": "disable"})

    def test_a_hardened_profile_reads_the_strongest_token_on_all_three(self):
        """oep-avw6-06: reset-both everywhere, an exception doing the same, every model on."""
        self.assertEqual(
            antivirus_posture_aggregates(
                self._decoders(*["reset-both"] * 7), [("ftp", "reset-both", True)],
                {"MSOffice": "enable", "Windows Executables": "enable"}, self.CATALOGUE),
            {"weakest_decoder_action": "reset-both",
             "weakest_application_override_action": "reset-both",
             "weakest_ml_model_state": "enable"})

    def test_ONE_weak_protocol_decides_the_whole_profile(self):
        """What the aggregate is for: six protocols hardened and one left open is a profile
        malware walks through, and the severity must follow the weakest."""
        self.assertEqual(
            antivirus_posture_aggregates(
                self._decoders("reset-both", "reset-both", "reset-both", "reset-both",
                               "reset-both", "reset-both", "alert"),
                [], {}, [])["weakest_decoder_action"], "alert")

    def test_ALERT_IS_WEAKER_THAN_ANY_BLOCKER_AND_STRONGER_THAN_ALLOW(self):
        """oep-avw6-02's token. The ordering is by how much of the transfer finishes, which is
        not the tokens' alphabetical or enumeration order."""
        self.assertEqual(
            antivirus_posture_aggregates(
                self._decoders("alert", "drop", "reset-both"), [], {}, []
            )["weakest_decoder_action"], "alert")
        self.assertEqual(
            antivirus_posture_aggregates(
                self._decoders("allow", "alert"), [], {}, []
            )["weakest_decoder_action"], "allow")

    def test_an_exception_on_the_literal_default_comes_back_UNRANKED(self):
        """oep-avw6-07: reset-both on all seven decoders and one ftp exception left on
        `default`, which on an exception resolves per SIGNATURE and so settles nothing. It is
        returned as the device stored it rather than called strong or weak - stage 3 grades it
        at the baseline. Returning the weakest token instead would assert a weakness nobody
        measured; dropping it would read as `no exception`, which is false."""
        self.assertEqual(
            antivirus_posture_aggregates(
                self._decoders(*["reset-both"] * 7), [("ftp", "default", None)],
                {}, [])["weakest_application_override_action"], "default")

    def test_an_exception_with_no_action_at_all_reads_as_the_absent_state(self):
        """oep-avw6-12: a bare `<entry name="ftp"/>` with no action child. The device accepts
        it and an absent action is `allow`, the permissive end."""
        self.assertEqual(
            antivirus_posture_aggregates(
                self._decoders(*["reset-both"] * 7), [("ftp", "", False)],
                {}, [])["weakest_application_override_action"], "allow")

    def test_NO_EXCEPTIONS_AT_ALL_IS_BLANK_AND_NOT_THE_WEAKEST_TOKEN(self):
        """oep-avw6-08 and most of the estate. A profile naming no application exception is
        the COMPLIANT state, measured - there is nothing overriding its decoders - so the
        weakest token would grade every clean profile at the worst severity on the strength of
        rows that do not exist. A blank matches no placement and reports at the baseline,
        which is the same mechanism `direction_coverage`'s null uses. This departs from stage
        5's declared value set for the column, which has no member for an empty collection."""
        self.assertEqual(
            antivirus_posture_aggregates(
                self._decoders(*["reset-both"] * 7), [], {}, []
            )["weakest_application_override_action"], "")

    def test_an_UNMENTIONED_ml_model_is_disabled_and_decides_the_token(self):
        """oep-avw6-16 stores no `mlav-engine-filebased-enabled` node at all, so every model
        in the catalogue is absent and absent means DISABLED - measured 2026-10-07, where such
        a profile renders every model as `disable (for all protocols)`. The aggregate
        quantifies over the CATALOGUE rather than over what the config names, exactly as the
        rows beneath it are synthesized."""
        self.assertEqual(
            antivirus_posture_aggregates(
                self._decoders(*["reset-both"] * 7), [], {}, self.CATALOGUE
            )["weakest_ml_model_state"], "disable")
        self.assertEqual(
            antivirus_posture_aggregates(
                self._decoders(*["reset-both"] * 7), [],
                {"MSOffice": "enable"}, self.CATALOGUE
            )["weakest_ml_model_state"], "disable")

    def test_ALERT_ONLY_IS_STRONGER_THAN_OFF(self):
        """oep-avw6-02's ML token, and the order a reader would guess wrong: a model that is
        off produces nothing, while one on the middle setting produces a record of the
        delivery. The wire literal has no space; the Help and the UI grid both print one."""
        self.assertEqual(
            antivirus_posture_aggregates(
                [], [], {"MSOffice": "enable(alert-only)",
                         "Windows Executables": "enable"}, self.CATALOGUE
            )["weakest_ml_model_state"], "enable(alert-only)")

    def test_an_EMPTY_catalogue_is_blank_rather_than_the_weakest_token(self):
        """No predefined profile in the build means no ML rows are written at all, so there is
        no collection to be weakest. Reporting `disable` would grade a profile over eight rows
        that do not exist."""
        self.assertEqual(
            antivirus_posture_aggregates(self._decoders("reset-both"), [], {}, [])
            ["weakest_ml_model_state"], "")

    def test_a_protocol_PAN_OS_adds_later_is_returned_unranked(self):
        """The decoder walk carries a protocol it does not know rather than dropping it, so an
        action the strength order does not place can reach here. It comes back as the device
        gave it and the grading places it unranked - which is visible, where silently calling
        it strong would not be."""
        self.assertEqual(
            antivirus_posture_aggregates(
                self._decoders("some-future-action"), [], {}, []
            )["weakest_decoder_action"], "some-future-action")


class AntivirusApplicationOverrideTests(SimpleTestCase):
    """The per-application action override, measured on pan-fw-111 2026-10-08.

    Found by enumerating the profile's key set with `action=complete` rather than reading a
    sample: the node was in the config all along and PAN-AVW-001 walked only the decoders, so a
    profile with `reset-both` everywhere and one `allow` override reported as hardened.

    Each shape below was written to a device and either accepted or refused, so none of these
    inputs is invented.
    """

    def test_no_application_node_yields_no_rows(self):
        """The normal case. UNLIKE the decoders, nothing is synthesized - an override is an
        operator-added exception, so the absence of one is the absence of an override and not a
        silent default. Synthesizing 1454 rows per profile would be the same bug inverted."""
        self.assertEqual(profile_application_overrides({"@name": "plain"}), [])

    def test_an_allow_override_does_not_block(self):
        self.assertEqual(
            profile_application_overrides({"@name": "p", "application": {"entry": [
                {"@name": "gmail-base", "action": "allow"}]}}),
            [("gmail-base", "allow", False)])

    def test_a_blocking_override_blocks(self):
        """An override may TIGHTEN an action, so this must not read as a gap."""
        self.assertEqual(
            profile_application_overrides({"@name": "p", "application": {"entry": [
                {"@name": "gmail-base", "action": "reset-both"}]}}),
            [("gmail-base", "reset-both", True)])

    def test_an_override_with_no_action_allows(self):
        """The device ACCEPTS an entry with no action and stores it absent - and refuses one
        with an empty action element. So absence is reachable and is the permissive end, the
        same rule as an absent decoder action."""
        self.assertEqual(
            profile_application_overrides({"@name": "p", "application": {"entry": [
                {"@name": "ftp"}]}}),
            [("ftp", "", False)])

    def test_default_is_UNESTABLISHED_rather_than_resolved(self):
        """`default` is accepted on an override. A decoder's `default` resolves per protocol
        and that was measured; an override is not per-protocol, so that table cannot answer it
        and no device oracle was found that does. None, not False - which the control reports
        rather than passes."""
        self.assertEqual(
            profile_application_overrides({"@name": "p", "application": {"entry": [
                {"@name": "web-browsing", "action": "default"}]}}),
            [("web-browsing", "default", None)])

    def test_alert_is_detection_without_prevention(self):
        self.assertEqual(
            profile_application_overrides({"@name": "p", "application": {"entry": [
                {"@name": "dropbox-base", "action": "alert"}]}})[0][2],
            False)

    def test_a_single_entry_arriving_unwrapped_is_still_read(self):
        """PAN-OS returns a lone entry as a dict rather than a one-item list."""
        self.assertEqual(
            profile_application_overrides({"@name": "p", "application": {"entry": {
                "@name": "ftp", "action": "allow"}}}),
            [("ftp", "allow", False)])

    def test_a_pushed_override_carries_provenance_attributes(self):
        """What a read actually returns: the action is a dict with the value under `#text`."""
        self.assertEqual(
            profile_application_overrides({"@name": "p", "application": {"entry": [
                {"@name": "ftp", "@loc": "shared",
                 "action": {"@admin": "admin", "#text": "allow"}}]}}),
            [("ftp", "allow", False)])

    def test_an_UNRECOGNISED_action_does_not_block(self):
        """A value the enum does not have today.

        The write gate refuses one now - `action 'wibble' is not an allowed keyword`, code=12 -
        so this cannot arrive from a normal write. It can arrive from a PAN-OS release that
        ADDS a member: the config would then hold a value this code has never seen. Treating
        an unknown action as blocking would silently pass whatever the new value means, so the
        row is kept, reported, and the label carries the literal for someone to look up.
        """
        self.assertEqual(
            profile_application_overrides({"@name": "p", "application": {"entry": [
                {"@name": "ftp", "action": "quarantine-to-sandbox"}]}}),
            [("ftp", "quarantine-to-sandbox", False)])

    def test_an_entry_with_no_name_is_skipped_rather_than_crashing(self):
        self.assertEqual(
            profile_application_overrides({"@name": "p", "application": {"entry": [
                {"action": "allow"}, {"@name": "ftp", "action": "allow"}]}}),
            [("ftp", "allow", False)])


class AntivirusMlModelTests(SimpleTestCase):
    """The WildFire Inline ML models, whose names come from the CONTENT release.

    controls.json says so and says to enumerate them on the target version before automating,
    so nothing here hardcodes them - the catalogue comes from the predefined profile, which
    carries every model the device knows about.
    """

    #: As the predefined profile carries them on the lab, 2026-10-07.
    EIGHT = ("Windows Executables", "PowerShell Script 1", "PowerShell Script 2",
             "Executable Linked Format", "MSOffice", "Shell", "OOXML", "MachO")

    def _entry(self, name, actions):
        return {"@name": name, "mlav-engine-filebased-enabled": {"entry": [
            {"@name": model, "mlav-policy-action": action}
            for model, action in actions.items()]}}

    def test_it_reads_what_the_config_names(self):
        entry = self._entry("p", {m: "enable" for m in self.EIGHT})

        self.assertEqual(profile_ml_models(entry), {m: "enable" for m in self.EIGHT})

    def test_a_profile_with_no_ml_node_names_nothing(self):
        """And that is the finding, not an absence of one: the UI renders every model as
        `disable` for such a profile. The catalogue puts the rows back at persist time."""
        self.assertEqual(profile_ml_models({"@name": "bare"}), {})

    def test_the_catalogue_comes_from_the_profiles_themselves(self):
        """A content update that adds a ninth model adds it here with no code change, because
        the predefined profile is read for the list rather than a constant."""
        class N:
            def __init__(self, kind, models):
                self.kind = kind
                self.ml_models = models

        predefined = N("virus", {m: "enable" for m in self.EIGHT})
        custom = N("virus", {"Windows Executables": "disable"})
        spyware = N("spyware", {})

        catalogue = ml_model_catalogue([predefined, custom, spyware])

        self.assertEqual(set(catalogue), set(self.EIGHT))
        self.assertEqual(catalogue, sorted(catalogue), "stable order, so rows do not churn")

    def test_a_model_only_a_custom_profile_names_is_still_catalogued(self):
        """Rather than dropped because the predefined profile has not heard of it."""
        class N:
            def __init__(self, kind, models):
                self.kind, self.ml_models = kind, models

        catalogue = ml_model_catalogue([
            N("virus", {"Windows Executables": "enable"}),
            N("virus", {"Some New Engine": "enable"})])

        self.assertIn("Some New Engine", catalogue)

    def test_a_non_virus_kind_contributes_nothing_to_the_catalogue(self):
        class N:
            def __init__(self, kind, models):
                self.kind, self.ml_models = kind, models

        self.assertEqual(ml_model_catalogue([N("spyware", {"Nonsense": "enable"})]), [])


class NormalizationLifecycleTests(TestCase):
    """`lifecycle.normalization_starting`: every normalizing path announces itself, a refusal
    stops it before anything is written, and normalization never deletes a collection."""

    def _station_with_a_rule(self):
        station, appliance, point = _create_panorama_enforcement_point(
            serial_number="SERIAL-LIFE-001", appliance_hostname="fw-life-01")
        EnforcementPoint.objects.filter(pk=point.pk).update(in_scope=True)
        Snapshot.objects.create(
            management_station=station, appliance=appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": {"devices": {"entry": {"vsys": {"entry": {
                "@name": "vsys1",
                "rulebase": {"security": {"rules": {"entry": [{
                    "@name": "r1", "from": {"member": ["any"]}, "to": {"member": ["any"]},
                    "source": {"member": ["any"]}, "destination": {"member": ["any"]},
                    "application": {"member": ["any"]}, "service": {"member": ["any"]},
                    "action": "allow",
                }]}}},
            }}}}}})
        _create_empty_pushed_policy_snapshot(station=station, enforcement_point=point)
        return station

    def test_normalization_keeps_snapshots(self):
        """Jason, 2026-10-15: "Normalization should never, ever, delete collections." A
        snapshot is normalization's input and what a finding records it was computed from."""
        from optivedge_integrations.integrations.platforms.pan_os.flows import (
            renormalize_in_scope_configuration)

        station = self._station_with_a_rule()
        before = set(Snapshot.objects.values_list("pk", flat=True))

        renormalize_in_scope_configuration(station)
        renormalize_in_scope_configuration(station)

        # Guards the comparison: a renormalize that wrote nothing would keep them trivially.
        self.assertTrue(SecurityRule.objects.filter(name="r1").exists())
        self.assertEqual(set(Snapshot.objects.values_list("pk", flat=True)), before)

    def test_every_normalizing_view_announces_itself_and_stops_on_refusal(self):
        from optivedge_integrations.integrations.lifecycle import (
            NormalizationRefused, normalization_starting)

        station = self._station_with_a_rule()

        def refuse(**kwargs):
            raise NormalizationRefused("A findings run is in progress.")

        normalization_starting.connect(refuse, weak=False, dispatch_uid="lifecycle-refuse")
        self.addCleanup(normalization_starting.disconnect, dispatch_uid="lifecycle-refuse")

        for name in ("management_station_sync", "management_station_in_scope_sync",
                     "management_station_renormalize",
                     "management_station_refresh_dynamic_content"):
            with self.subTest(name), \
                    patch("optivedge_integrations.integrations.views.threading.Thread") as thread, \
                    patch("optivedge_integrations.integrations.views.collect_persist_and_normalize") as sync, \
                    patch("optivedge_integrations.integrations.views."
                          "_refresh_station_dynamic_content_with_tracking") as dynamic:
                response = self.client.post(
                    reverse(name, kwargs={"pk": station.pk}), follow=True)

                thread.assert_not_called()
                sync.assert_not_called()
                dynamic.assert_not_called()
                self.assertFalse(IntegrationRun.objects.exists())
                self.assertIn("A findings run is in progress.",
                              [m.message for m in response.context["messages"]])

    def test_the_bulk_refresh_skips_a_refused_station(self):
        from optivedge_integrations.integrations.lifecycle import (
            NormalizationRefused, normalization_starting)

        self._station_with_a_rule()

        def refuse(**kwargs):
            raise NormalizationRefused("no")

        normalization_starting.connect(refuse, weak=False, dispatch_uid="lifecycle-refuse-bulk")
        self.addCleanup(normalization_starting.disconnect, dispatch_uid="lifecycle-refuse-bulk")

        with patch("optivedge_integrations.integrations.views."
                   "_refresh_station_in_scope_with_tracking") as refresh, \
                patch("optivedge_integrations.integrations.views."
                      "rebuild_all_security_rule_search_vocabulary"), \
                patch("optivedge_integrations.integrations.views.connections"), \
                self.assertLogs("optivedge_integrations.integrations.views", level="WARNING"):
            views_module._run_bulk_in_scope_refresh_in_background()

        refresh.assert_not_called()


class PasswordComplexityAbsentNodeProvenanceTests(TestCase):
    """Sixteen stored values and sixteen rows, on a firewall that has never enabled complexity.

    `password_complexity_from_snapshot` pre-populated `values`, set `provenance = []`, and then
    returned from three early exits before its declaring loop could run. The third exit is the
    ORDINARY state of a firewall - the reader's own docstring says PAN-OS never writes these
    values, so a device where nobody enabled complexity has no `password-complexity` node - so
    the common case wrote sixteen columns and zero rows, and `provenance_for` answered "nothing
    tracks this field" for all sixteen. PAN-AUTH-001 to 013 rest on those columns.

    Nothing about the declarations changed to fix it: the loop already resolved every absent key
    to `Implicit.measured(..., PASSWORD_COMPLEXITY_CITATION)`. The early returns were the only
    reason those declarations never reached a row.

    THE DECLARATIONS DID CHANGE ON 2026-10-29, and sixteen rows are still sixteen rows. Eleven
    of the thirteen keys a control reads became `Implicit.assumed` - the unconfigured form says
    what the UI renders, not what PAN-OS supplies - so their rows now read `assumed_default`
    rather than `pan_os_default`. The two post-expiration keys became `Implicit.not_assumed`,
    because 0 is the COMPLIANT value on both, so they store NOTHING and their rows read
    `not_configured`. All fourteen non-declined keys moved, the three no control reads
    included: one loop, one form reading, and nothing supports a per-key distinction.
    """

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.pcprov")
        self.group = ApplianceGroup.objects.create(
            management_station=self.station, name="g-pcprov",
            group_type=ApplianceGroup.TYPE_STANDALONE)
        self.appliance = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            serial_number="S-PCPROV", hostname="fw-pcprov")

    def _normalize(self, payload):
        Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_merged_config", collected_at=timezone.now(), payload=payload)
        normalize_appliance_password_complexity(self.appliance)
        policy = PasswordComplexityPolicy.objects.get(appliance=self.appliance)
        rows = {r.field_name: r for r in FieldProvenance.objects.filter(
            content_type=ContentType.objects.get_for_model(PasswordComplexityPolicy),
            object_id=policy.pk)}
        return policy, rows

    #: The two keys whose COMPLIANT value is 0, so an absent one is declined rather than
    #: inferred: the row reads `not_configured` and the column holds nothing.
    NOT_ASSUMED = {"post_expiration_admin_login_count", "post_expiration_grace_period"}

    #: The three shapes that each took one of the deleted early returns, and a fourth whose
    #: node IS present - which always reached the loop - with the one key it writes. Mapped to
    #: the fields that should come back `local` rather than defaulted.
    PAYLOADS = {
        "no config root": ({}, set()),
        "config but no mgt-config": ({"config": {"devices": {"entry": [{}]}}}, set()),
        "mgt-config but no password-complexity": (
            {"config": {"mgt-config": {"users": {}}}}, set()),
        "complexity present, no password-change": (
            {"config": {"mgt-config": {"password-complexity": {"enabled": "no"}}}},
            {"enabled"}),
    }

    def test_every_field_is_declared_on_every_path_that_used_to_return_early(self):
        for label, (payload, written) in self.PAYLOADS.items():
            with self.subTest(label):
                PasswordComplexityPolicy.objects.filter(appliance=self.appliance).delete()
                Snapshot.objects.filter(appliance=self.appliance).delete()
                policy, rows = self._normalize(payload)
                self.assertEqual(
                    len(rows), 16,
                    f"{label}: sixteen tracked fields, sixteen rows - a missing row means only "
                    f"that the field is not tracked, and all sixteen are")
                defaulted = {name for name in rows if name not in written}
                declined = defaulted & self.NOT_ASSUMED
                inferred = defaulted - self.NOT_ASSUMED
                self.assertEqual(
                    {rows[name].provenance_type for name in inferred}, {"assumed_default"},
                    f"{label}: an absent key is OUR inference here, not local and not a "
                    f"measured vendor default")
                self.assertEqual(
                    {rows[name].provenance_type for name in declined},
                    {"not_configured"} if declined else set(),
                    f"{label}: the two keys whose compliant value is 0 infer nothing")
                for name in written:
                    self.assertEqual(
                        rows[name].provenance_type, "local",
                        f"{label}: {name} is in the payload, so the row is the key's own")

    def test_the_stored_numbers_did_not_move(self):
        """Fourteen of the sixteen read exactly what they always did - `False` for a flag, `0`
        for a number - because 0 is the FINDING value on every one of them, and materialising
        the finding value is what makes an unknown fire."""
        policy, _ = self._normalize(self.PAYLOADS["no config root"][0])
        self.assertFalse(policy.enabled)
        self.assertFalse(policy.block_username_inclusion)
        self.assertFalse(policy.change_on_first_login)
        for field in ("minimum_length", "minimum_uppercase", "minimum_lowercase",
                      "minimum_numeric", "minimum_special", "new_differs_by_characters",
                      "history_count", "block_repeated_characters", "change_period_block",
                      "expiration_period", "expiration_warning_period"):
            with self.subTest(field):
                self.assertEqual(getattr(policy, field), 0)

    def test_the_two_keys_whose_compliant_value_is_zero_store_nothing(self):
        """PAN-AUTH-012 and 013 both assert `greater than 0`, so a materialised 0 would be the
        COMPLIANT answer about a key nobody measured - "we never asked" rendered as "we asked
        and it was fine". The column holds nothing and the flag beside it fires."""
        policy, rows = self._normalize(self.PAYLOADS["no config root"][0])
        self.assertIsNone(policy.post_expiration_admin_login_count)
        self.assertIsNone(policy.post_expiration_grace_period)
        self.assertTrue(policy.post_expiration_admin_login_count_unknown)
        self.assertTrue(policy.post_expiration_grace_period_unknown)
        for field in self.NOT_ASSUMED:
            with self.subTest(field):
                self.assertEqual(rows[field].provenance_type, "not_configured")

    def test_a_key_that_is_present_clears_its_own_flag(self):
        """The flag reports ABSENCE, so a configured value has to turn it off - otherwise every
        appliance reads as unread and the control can never pass."""
        policy, _ = self._normalize({"config": {"mgt-config": {"password-complexity": {
            "password-change": {"post-expiration-admin-login-count": "2",
                                "post-expiration-grace-period": "7"}}}}})
        self.assertEqual(policy.post_expiration_admin_login_count, 2)
        self.assertEqual(policy.post_expiration_grace_period, 7)
        self.assertFalse(policy.post_expiration_admin_login_count_unknown)
        self.assertFalse(policy.post_expiration_grace_period_unknown)

    def test_a_key_present_but_empty_reports_itself_unread(self):
        """A key PRESENT with no parseable text resolves to the implicit value too - None here -
        with the KEY's own provenance marker, so `was_absent` answers False while the column
        holds nothing. The flag is read off the stored value for exactly this shape: saying "we
        read it and it was configured" over a null is the reassuring answer about a value
        nobody has."""
        policy, _ = self._normalize({"config": {"mgt-config": {"password-complexity": {
            "password-change": {"post-expiration-grace-period": ""}}}}})
        self.assertIsNone(policy.post_expiration_grace_period)
        self.assertTrue(policy.post_expiration_grace_period_unknown)

    def test_the_row_carries_the_defaulted_value_and_no_key(self):
        """A reader of the row can see what was defaulted without resolving the field, and
        `raw_key` is empty because there was no key."""
        _, rows = self._normalize(self.PAYLOADS["mgt-config but no password-complexity"][0])
        self.assertEqual((rows["enabled"].raw_value, rows["enabled"].raw_key), ("no", ""))
        self.assertEqual((rows["minimum_length"].raw_value, rows["minimum_length"].raw_key),
                         ("0", ""))

    def test_provenance_for_no_longer_answers_none_for_a_tracked_field(self):
        """The consumer-visible defect. All sixteen PAYLOAD-BACKED fields are tracked, and
        `None` from `provenance_for` means untracked.

        The only `DERIVED_FIELDS` on this model are the two absence flags, which are computed
        from whether the parse stored anything and have no payload key of their own - so they
        can never carry a row, and `provenance_for` answers `derived` for them."""
        policy, _ = self._normalize(self.PAYLOADS["no config root"][0])
        self.assertEqual(
            PasswordComplexityPolicy.DERIVED_FIELDS,
            ("post_expiration_admin_login_count_unknown",
             "post_expiration_grace_period_unknown"))
        self.assertEqual(
            policy.provenance_for("post_expiration_grace_period_unknown").provenance_type,
            "derived")
        for field in ("enabled", "minimum_length", "post_expiration_grace_period"):
            with self.subTest(field):
                self.assertIsNotNone(policy.provenance_for(field))

    def test_the_second_consumer_still_gets_every_value(self):
        """`password_profiles.py` calls this reader as `global_values, _ =` for one comparison.
        `values` stopped being pre-populated, so the loop has to fill all sixteen keys."""
        from optivedge_integrations.integrations.platforms.pan_os.normalization.device_configuration import (  # noqa: E501
            PASSWORD_COMPLEXITY_FIELDS, password_complexity_from_snapshot)
        snapshot = Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_merged_config", collected_at=timezone.now(), payload={})
        values, provenance = password_complexity_from_snapshot(snapshot)
        self.assertEqual(set(values), {f for f, _, _, _ in PASSWORD_COMPLEXITY_FIELDS})
        self.assertEqual(len(provenance), 16)
        self.assertIn("password_expiration_period", values)


class SecurityRuleRuleTypeProvenanceTests(TestCase):
    """What an absent `rule-type` means - MEASURED 2026-10-20 on pan-fw-201, PAN-OS 11.2.5.

    `read-a-security-rule.md` said both things five lines apart: `:60-61` "treat
    <rule-type>universal</rule-type> and an absent rule-type as identical; the dataplane does",
    and `:57-58` that the 2026-10-05 pass did NOT cover this key and nothing had established it.
    The payload contract carries no `rule-type` field on either rule node. So it was measured.

    Three rules were created on pan-fw-201 for it, and read back through Panorama:

      intrazone_rule_test                 explicit `intrazone`
      interzone_rule_test                 explicit `interzone`
      explicit_universal_rule_type_test   created intrazone, then set back to universal

    Both `action=get` (candidate) and `action=show` (running) report `rule-type: universal` for
    the third, EXPLICITLY - so PAN-OS does not prune the element when it matches the default,
    and "set it back and watch it vanish" does not establish anything here. What settles it is
    `show running security-policy`: it prints `type intrazone;` and `type interzone;` for the
    first two, and NO type line at all for the third - nor for the two shared pre-rules pushed
    to the same device, which carry no `rule-type` key. The compiled policy renders an explicit
    universal and an absent key identically, which is the guide's claim measured.

    Recorded as ASSUMED and not measured, for a reason that survives the measurement: absence
    is a payload state the device keeps distinct from an explicit universal, and what the
    dataplane shows for it is SILENCE. No device output names "universal" for an absent key, so
    the VALUE is still our reading. A consumer must not render it as a vendor default.
    """

    def _rules(self, *entries):
        station, appliance, enforcement_point = _create_panorama_enforcement_point(
            serial_number="SERIAL-RULETYPE", appliance_hostname="fw-ruletype")
        Snapshot.objects.create(
            management_station=station, appliance=appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": {"devices": {"entry": {"vsys": {"entry": {
                "@name": "vsys1",
                "rulebase": {"security": {"rules": {"entry": list(entries)}}},
            }}}}}})
        _create_empty_pushed_policy_snapshot(station=station,
                                             enforcement_point=enforcement_point)
        normalize_enforcement_point_addresses(enforcement_point)
        normalize_enforcement_point_security_rules(enforcement_point)
        return {rule.name: rule for rule in SecurityRule.objects.all()}

    @staticmethod
    def _entry(name, **extra):
        return {"@name": name, "from": {"member": "any"}, "to": {"member": "any"},
                "source": {"member": "any"}, "destination": {"member": "any"},
                "application": {"member": "any"}, "service": {"member": "application-default"},
                "action": "allow", **extra}

    def test_an_absent_rule_type_stores_universal_and_says_it_is_assumed(self):
        rules = self._rules(self._entry("untouched"))
        self.assertEqual(rules["untouched"].rule_type, "universal")
        row = rules["untouched"].field_provenance.get(field_name="rule_type")
        self.assertEqual(row.provenance_type, "assumed_default")
        self.assertEqual(row.raw_value, "universal",
                         "the row carries the inferred value, so a reader sees what was "
                         "assumed without resolving the field")
        self.assertEqual(row.raw_key, "", "there was no key")

    def test_an_explicit_universal_is_local_and_not_a_default(self):
        """The distinction the device itself keeps. The column reads the same either way, and
        the row is the only thing that says whether an author wrote it - which is why the
        measurement mattered: PAN-OS stores an explicit `universal` rather than pruning it."""
        rules = self._rules(self._entry("written", **{"rule-type": "universal"}))
        self.assertEqual(rules["written"].rule_type, "universal")
        row = rules["written"].field_provenance.get(field_name="rule_type")
        self.assertEqual(row.provenance_type, "local")

    def test_the_two_measured_rule_types_are_read_as_written(self):
        rules = self._rules(self._entry("intra", **{"rule-type": "intrazone"}),
                            self._entry("inter", **{"rule-type": "interzone"}))
        self.assertEqual(rules["intra"].rule_type, "intrazone")
        self.assertEqual(rules["inter"].rule_type, "interzone")
        for name in ("intra", "inter"):
            with self.subTest(name):
                row = rules[name].field_provenance.get(field_name="rule_type")
                self.assertEqual(row.provenance_type, "local")

    def test_a_pushed_rule_type_keeps_its_marker(self):
        """`parse_text_field` replaced `scalar_value`, which had the marker already. It must
        still arrive: a control firing on rule_type has to say which template to change."""
        rules = self._rules(self._entry(
            "pushed", **{"rule-type": {"@ptpl": "stack_x", "#text": "interzone"}}))
        self.assertEqual(rules["pushed"].rule_type, "interzone")
        row = rules["pushed"].field_provenance.get(field_name="rule_type")
        self.assertEqual((row.provenance_type, row.raw_value), ("template", "stack_x"))

    def test_the_declaration_is_an_inference_and_declares_itself_one(self):
        """`assumed_default`, never `pan_os_default`: the dataplane's silence is what was
        measured, and the name is ours. `tests.py`'s ASSUMED_DEFAULTS inventory counts it."""
        from optivedge_integrations.integrations.platforms.pan_os.normalization.security_rules import (  # noqa: E501
            RULE_TYPE_IMPLICIT)
        self.assertEqual(RULE_TYPE_IMPLICIT.value, "universal")
        self.assertIsNone(RULE_TYPE_IMPLICIT.citation)
        self.assertEqual(RULE_TYPE_IMPLICIT.provenance_type, "assumed_default")
        self.assertIn("pan-fw-201", RULE_TYPE_IMPLICIT.reasoning)
        self.assertNotIn(
            "rule_type", SecurityRule.DERIVED_FIELDS,
            "it reads a payload key, so it is a row's business and not a declaration's")


class PredefinedEntryProvenanceTests(TestCase):
    """`predefined`: the entry is present and PAN-OS SHIPPED it.

    An unmarked entry records LOCAL - "defined on this device" - which was asserted about
    objects that ship with the release and cannot be edited at all. Two sites said it two
    different ways: `certificates.py` wrote the LOCAL row for predefined-scope SSL/TLS profiles
    and certificates, and `addresses.py` passed an empty provenance list for the built-in `any`
    and the predefined EDLs, so those carried no `__entry__` row and read as untracked beside
    siblings on the same model that had one.

    The scope the entry was collected from is the only thing that says so - there is no payload
    key for it - so the reading site passes the `PREDEFINED` sentinel as the raw key.
    """

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.pre")
        self.group = ApplianceGroup.objects.create(
            management_station=self.station, name="g-pre",
            group_type=ApplianceGroup.TYPE_STANDALONE)
        self.appliance = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            serial_number="S-PRE", hostname="fw-pre")

    def _entry_row(self, obj):
        return FieldProvenance.objects.filter(
            content_type=ContentType.objects.get_for_model(type(obj)),
            object_id=obj.pk, field_name="__entry__").first()

    def test_the_sentinel_classifies_as_predefined_and_carries_no_key(self):
        from optivedge_integrations.integrations.platforms.pan_os.normalization.common import (
            ABSENT, PREDEFINED, classify_prov_type, provenance_raw_key, provenance_value)
        self.assertEqual(classify_prov_type(PREDEFINED), "predefined")
        self.assertEqual(provenance_raw_key(PREDEFINED), "")
        self.assertEqual(provenance_value(PREDEFINED, None), "")
        self.assertIsNot(PREDEFINED, ABSENT,
                         "it is not an absence - the entry exists, the ORIGIN is the vendor")
        self.assertEqual(classify_prov_type(None), "local",
                         "an unmarked entry on any other scope is still local")

    def test_predefined_is_a_choice_on_the_model(self):
        self.assertIn(("predefined", "Predefined"), FieldProvenance.ProvenanceType.choices)
        self.assertNotIn("predefined", FieldProvenance.ABSENT_TYPES,
                         "an origin type, not an absent one")
        self.assertNotIn("predefined", FieldProvenance.DEFAULTED_TYPES)

    def _normalize_profiles(self, *, shared=None, predefined=None):
        config = {"devices": {"entry": [{"@name": "localhost.localdomain"}]}}
        if shared is not None:
            config["shared"] = {"ssl-tls-service-profile": {"entry": shared}}
        Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": config})
        if predefined is not None:
            Snapshot.objects.create(
                management_station=self.station, appliance=self.appliance,
                source_type="config_predefined_ssl_tls_service_profiles",
                collected_at=timezone.now(),
                payload={"ssl-tls-service-profile": {"entry": predefined}})
        normalize_appliance_certificate_objects(self.appliance)

    @staticmethod
    def _profile(name, minimum="tls1-2", certificate="cert"):
        return {"@name": name, "certificate": certificate,
                "protocol-settings": {"min-version": minimum, "max-version": "tls1-3"}}

    def test_a_predefined_profile_says_predefined_and_a_shared_one_still_says_local(self):
        """Both are unmarked. Before, both recorded `local`, and the one a reader can actually
        go and change was indistinguishable from the one shipped in the release."""
        self._normalize_profiles(shared=[self._profile("mine")],
                                 predefined=[self._profile("TLSv1.3_Default")])
        shipped = SslTlsServiceProfile.objects.get(
            appliance=self.appliance, name="TLSv1.3_Default")
        local = SslTlsServiceProfile.objects.get(appliance=self.appliance, name="mine")
        self.assertEqual(shipped.scope, "predefined")
        self.assertEqual(self._entry_row(shipped).provenance_type, "predefined")
        self.assertEqual(self._entry_row(shipped).raw_key, "")
        self.assertEqual(self._entry_row(local).provenance_type, "local")

    def test_a_marker_on_a_predefined_entry_is_still_the_better_fact(self):
        """Scope only overrides the UNMARKED case. A marker is read off the payload and says
        where to go and change it, which no inference from scope can improve on."""
        self._normalize_profiles(
            predefined=[dict(self._profile("TLSv1.3_Default"), **{"@ptpl": "stack_x"})])
        shipped = SslTlsServiceProfile.objects.get(
            appliance=self.appliance, name="TLSv1.3_Default")
        row = self._entry_row(shipped)
        self.assertEqual((row.provenance_type, row.raw_value), ("template", "stack_x"))

    def _normalize_addresses(self):
        station, appliance, enforcement_point = _create_panorama_enforcement_point(
            serial_number="SERIAL-PREADDR", appliance_hostname="fw-preaddr")
        Snapshot.objects.create(
            management_station=station, appliance=appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": {"devices": {"entry": {"vsys": {"entry": {
                "@name": "vsys1",
                "address": {"entry": [{"@name": "net-obj", "ip-netmask": "10.1.2.3/24"}]},
            }}}}}})
        _create_empty_pushed_policy_snapshot(station=station,
                                            enforcement_point=enforcement_point)
        Snapshot.objects.create(
            management_station=station, appliance=appliance,
            source_type="show_predefined_ip_block_lists", collected_at=timezone.now(),
            payload={"ip-block-list-v2": {"entry": [{
                "@name": "panw-known-ip-list", "filename": "panw-known-ip-list",
                "display-name": "Palo Alto Networks - Known malicious IP addresses",
                "description": "IP addresses used almost exclusively by malicious actors."}]}})
        normalize_enforcement_point_addresses(enforcement_point)
        return {obj.name: obj for obj in AddressObject.objects.all()}

    def test_the_builtin_any_and_a_predefined_edl_carry_an_entry_row(self):
        objects = self._normalize_addresses()
        for name in ("any", "panw-known-ip-list"):
            with self.subTest(name):
                row = self._entry_row(objects[name])
                self.assertIsNotNone(
                    row, "an empty provenance list left these two with no __entry__ row, so "
                         "'nobody tracks entry provenance here' and 'PAN-OS shipped this' read "
                         "the same")
                self.assertEqual(row.provenance_type, "predefined")
                self.assertEqual(row.raw_key, "")

    def test_a_locally_defined_sibling_on_the_same_model_still_says_local(self):
        """The comparison that makes the row worth having: three objects, one model, and the
        rows now tell a vendor object from one an administrator wrote."""
        objects = self._normalize_addresses()
        self.assertEqual(self._entry_row(objects["net-obj"]).provenance_type, "local")


class UnreadableExternalListTests(TestCase):
    """An EDL whose `type` node carries none of ip/domain/url/imei/imsi.

    Absence there means WE FAILED TO READ, not that nobody configured anything - the one
    case in the provenance work where those differ. Two instruments say so: a
    not_configured provenance row (the field is tracked and empty) and an ERROR issue (the
    payload was unreadable). This covers the second.
    """

    def _edl(self, type_node):
        from optivedge_integrations.integrations.platforms.pan_os.normalization.addresses import (
            external_list_value)
        return external_list_value({"@name": "edl-1", "type": type_node})

    def test_a_recognised_type_yields_its_list_type(self):
        value, _rk, _rv, list_type = self._edl({"ip": {"url": "https://example.test/list"}})
        self.assertEqual(list_type, "ip")
        self.assertEqual(value, "https://example.test/list")

    def test_an_unrecognised_type_node_yields_no_list_type(self):
        for node in ({"bogus": {"url": "x"}}, {}, "not-a-dict", None):
            _value, _rk, _rv, list_type = self._edl(node)
            self.assertEqual(list_type, "", f"{node!r} should not resolve a list type")

    def test_an_unreadable_edl_raises_an_error_issue_and_is_kept(self):
        from optivedge_integrations.integrations.models.policy.objects import AddressObject
        from optivedge_integrations.integrations.platforms.pan_os.normalization.addresses import (
            _unreadable_edls)
        from optivedge_integrations.integrations.platforms.pan_os.normalization.types import (
            PolicyObjectIssue)

        class Fake:
            def __init__(self, name, address_type, edl_list_type):
                self.name, self.address_type, self.edl_list_type = name, address_type, edl_list_type

        issues = _unreadable_edls([
            Fake("good", AddressObject.TYPE_EDL, "ip"),
            Fake("bad", AddressObject.TYPE_EDL, ""),
            Fake("not-an-edl", AddressObject.TYPE_IP_NETMASK, ""),
        ])
        self.assertEqual([i.name for i in issues], ["bad"],
                         "only the EDL with no resolved list type is an issue")
        self.assertEqual(issues[0].severity, PolicyObjectIssue.ERROR)
        self.assertEqual(issues[0].disposition, PolicyObjectIssue.KEPT,
                         "dropping it would fail every referencing rule, which is the "
                         "misattribution this design removes")

    def test_an_empty_url_is_readable_and_not_an_issue(self):
        """`value == ""` alone must not be the test - a readable EDL can have an empty url."""
        value, _rk, _rv, list_type = self._edl({"url": {"url": ""}})
        self.assertEqual(value, "")
        self.assertEqual(list_type, "url", "readable: the type node WAS recognised")


class LogSettingsFilterParseTests(SimpleTestCase):
    """The Log Settings filter is FREE TEXT the device evaluates, so coverage is a parse.

    `action=complete` on the key answers with an empty list, so there is no enum to compare
    against and nothing upstream states a grammar. These tests pin the three rules the
    normalizer implements, and rule 3 is the one that matters: an expression it cannot read
    covers NOTHING, which is the firing direction for `system_log_severity_gaps`.
    """

    def _covered(self, text):
        from optivedge_integrations.integrations.platforms.pan_os.normalization.log_settings import (
            severities_covered)
        return severities_covered(text)

    def test_the_two_spellings_of_unrestricted_cover_everything(self):
        """The device spells it two ways on two nodes - `All Logs` in the grid and on the Log
        Forwarding profile, empty on the Log Settings filter's own completion."""
        from optivedge_integrations.integrations.models import SYSTEM_LOG_SEVERITIES
        for text in ("All Logs", "all logs", "", "   "):
            self.assertEqual(self._covered(text), set(SYSTEM_LOG_SEVERITIES), text)

    def test_geq_covers_the_value_and_everything_above_it(self):
        self.assertEqual(self._covered("(severity geq high)"), {"critical", "high"})
        self.assertEqual(self._covered("severity geq informational"),
                         {"critical", "high", "medium", "low", "informational"})

    def test_leq_eq_and_neq(self):
        self.assertEqual(self._covered("(severity leq low)"), {"low", "informational"})
        self.assertEqual(self._covered("(severity eq critical)"), {"critical"})
        self.assertEqual(self._covered("(severity neq critical)"),
                         {"high", "medium", "low", "informational"})

    def test_and_intersects_and_or_unions(self):
        self.assertEqual(self._covered("(severity geq medium) and (severity leq high)"),
                         {"medium", "high"})
        self.assertEqual(self._covered("(severity eq critical) or (severity eq low)"),
                         {"critical", "low"})

    def test_a_filter_naming_another_dimension_covers_nothing(self):
        """RULE 3, AND IT IS DELIBERATE. `(admin eq 'x')` narrows by something this cannot see,
        so no severity has been shown to be forwarded in full. It OVER-REPORTS a gap, which is
        the side an assessor can check in a minute - the reverse would claim coverage nobody
        established."""
        self.assertEqual(self._covered("(admin eq 'oep-nobody')"), set())
        self.assertEqual(self._covered("(severity geq high) and (subtype eq general)"), set())
        self.assertEqual(self._covered("(severity eq nonsense)"), set())

    def test_unrestricted_is_not_the_same_question_as_covered(self):
        """`config_log_filter_narrows` asks only whether anything is held back, and `filter` is
        mandatory at commit validation - so no committed entry may be assumed unrestricted."""
        from optivedge_integrations.integrations.platforms.pan_os.normalization.log_settings import (
            filter_is_unrestricted)
        self.assertTrue(filter_is_unrestricted("All Logs"))
        self.assertFalse(filter_is_unrestricted("(severity geq high)"))
        self.assertFalse(filter_is_unrestricted("(admin eq 'oep-nobody')"))


class LogServerTransportGradeTests(SimpleTestCase):
    """Four grades for two measured enums, and the fourth is the state nothing can settle.

    Protocol TLS with no `tls-version` key is NOT read as 1.2: that implicit value was measured
    as a RELATION - the dialog renders 1.2 under protocol TLS and nothing under SMTP - so
    materialising it would claim a hardened setting for relays that have none.
    """

    def _grade(self, protocol, tls_version):
        from optivedge_integrations.integrations.platforms.pan_os.normalization.log_settings import (
            _transport_grade)
        return _transport_grade(protocol, tls_version)

    def test_each_measured_pair_grades(self):
        from optivedge_integrations.integrations.models import LogServerTarget
        self.assertEqual(self._grade("SMTP", ""), LogServerTarget.GRADE_SMTP)
        self.assertEqual(self._grade("TLS", "1.2"), LogServerTarget.GRADE_TLS_12)
        self.assertEqual(self._grade("TLS", "1.1"), LogServerTarget.GRADE_TLS_11)
        self.assertEqual(self._grade("TLS", ""), LogServerTarget.GRADE_TLS_VERSION_UNSET)

    def test_no_protocol_key_is_ungraded_rather_than_the_weakest_value(self):
        """`protocol` is mandatory at commit validation on both platforms, so an absent one can
        only be an uncommitted candidate state - not a configuration to report."""
        self.assertEqual(self._grade("", ""), "")

    def test_the_floor_needs_all_three_parts(self):
        from optivedge_integrations.integrations.platforms.pan_os.normalization.log_settings import (
            _meets_authenticated_tls)
        self.assertTrue(_meets_authenticated_tls("TLS", "1.2", "Auto"))
        self.assertFalse(_meets_authenticated_tls("TLS", "1.2", ""),
                         "no authentication method")
        self.assertFalse(_meets_authenticated_tls("TLS", "", "Auto"),
                         "protocol TLS with no version key is a third state, not 1.2")
        self.assertFalse(_meets_authenticated_tls("SMTP", "1.2", "Auto"))


class CentralStoreDeliveryTests(TestCase):
    """CONNECTION IS NOT DELIVERY, which is the whole reason PAN-LOG-010 exists.

    AN UNKNOWN FIRES - Jason's rule, 2026-10-23. A missing snapshot, an unreadable reply and a
    connected collector that has never delivered anything all read FALSE and raise the finding;
    healthy is true only on positive evidence of a completed forward. Until that rule landed the
    first three read None, which matched no positive comparison and so came out of the query as
    healthy - an appliance nobody had read reported as safe on the strength of nothing.
    """

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.logstatus")
        self.appliance = Appliance.objects.create(
            management_station=self.station, hostname="fw.logstatus", serial_number="LS-1")

    def _snapshot(self, entries):
        return Snapshot.objects.create(
            appliance=self.appliance, source_type="show_logging_status",
            payload={"show-logging-status": {"Conn-Info": {"entry": entries}}},
            collected_at=timezone.now())

    def _verdict(self, entries):
        from optivedge_integrations.integrations.platforms.pan_os.normalization.log_settings import (
            central_store_delivery)
        return central_store_delivery(self._snapshot(entries))

    def test_no_snapshot_fires_rather_than_reading_as_healthy(self):
        """The rule's own case: no reading at all must not come out of the query as compliant."""
        from optivedge_integrations.integrations.platforms.pan_os.normalization.log_settings import (
            central_store_delivery)
        self.assertEqual(central_store_delivery(None), (False, False))

    def test_an_inactive_connection_beside_an_active_one_is_not_a_fault(self):
        """`cms1 Inactive` beside `cms0 Active` is the ordinary state on THREE of the four lab
        appliances - measured 2026-10-23 - so the per-appliance question is whether ANY
        connection is up. Reading the first entry alone would report all three as down."""
        healthy, collected = self._verdict([
            {"@name": "lr-cms1", "conn-status": "Connection Status       : lr - Inactive",
             "system": "system         Not Available         Not Available"
                       "                        0                   0                        0"},
            {"@name": "lr-cms0", "conn-status": "Connection Status       : lr - Active",
             "system": "system   2026/10/22 00:58:21   2026/10/22 03:30:07"
                       "      7698606905303761886 7698606905303761886                       18"},
        ])
        self.assertEqual((healthy, collected), (True, True))

    def test_every_connection_inactive_is_unhealthy(self):
        self.assertEqual(self._verdict([
            {"@name": "lr-cms0", "conn-status": "Connection Status       : lr - Inactive"},
        ]), (False, True))

    def test_a_counter_that_has_not_caught_up_is_unhealthy(self):
        """The failure the control exists for: connected, and the acked sequence number is
        behind the forwarded one, so a backlog is building up."""
        self.assertEqual(self._verdict([
            {"@name": "lr-cms0", "conn-status": "Connection Status       : lr - Active",
             "traffic": "traffic   2026/10/22 00:58:21   2026/10/22 03:30:07"
                        "      7698606905303761886 7698606905303700000                    1800"},
        ]), (False, True))

    def test_logs_created_and_never_forwarded_is_unhealthy(self):
        self.assertEqual(self._verdict([
            {"@name": "lr-cms0", "conn-status": "Connection Status       : lr - Active",
             "traffic": "traffic   2026/10/22 00:58:21         Not Available"
                        "                        0                   0                        0"},
        ]), (False, True))

    def test_a_reply_naming_no_connection_at_all_is_unhealthy_and_collected(self):
        """A real reading, and not healthy: an appliance with no collector connection is not
        delivering to one."""
        self.assertEqual(self._verdict([]), (False, True))

    def test_an_unreadable_line_fires_rather_than_reading_as_healthy(self):
        """A reply shape nobody has seen is not evidence that delivery is fine, and an unknown
        fires. It read None until 2026-10-23, which passed."""
        self.assertEqual(self._verdict([
            {"@name": "lr-cms0", "conn-status": "Connection Status       : lr - Active",
             "traffic": "traffic 2026/10/22 nonsense"},
        ]), (False, True))

    def test_a_connection_that_has_never_delivered_anything_fires(self):
        """THE CHANGE OF DIRECTION, and it moves real rows: both lab PA-VMs are in this state.
        Every counter reads `Not Available`, and the read cannot tell "this appliance created no
        logs" from "nothing is populating this counter" - so it is an unknown, and an unknown
        fires. It read healthy on the strength of the Active connection alone until 2026-10-23,
        which is the naive reading stage 3 explicitly narrowed away from."""
        self.assertEqual(self._verdict([
            {"@name": "lr-cms0", "conn-status": "Connection Status       : lr - Active",
             "traffic": "traffic         Not Available         Not Available"
                        "                        0                   0                        0",
             "system": "system         Not Available         Not Available"
                       "                        0                   0                        0"},
        ]), (False, True))

    def test_one_log_type_delivering_is_enough_while_another_is_idle(self):
        """The measured lab state on both PA-5220s: System delivers and the other eleven log
        types are idle. Requiring EVERY log type to have delivered would fire on a firewall that
        is demonstrably forwarding, which is a finding with no defect behind it."""
        self.assertEqual(self._verdict([
            {"@name": "lr-cms1", "conn-status": "Connection Status       : lr - Inactive"},
            {"@name": "lr-cms0", "conn-status": "Connection Status       : lr - Active",
             "traffic": "traffic         Not Available         Not Available"
                        "                        0                   0                        0",
             "system": "system   2026/10/22 00:58:21   2026/10/22 03:30:07"
                       "      7698606905303761886 7698606905303761886                       18"},
        ]), (True, True))


class LogSettingsNormalizationTests(TestCase):
    """End to end over a synthetic merged payload, on the shapes that would bite a reader.

    The values here are deliberately NOT a device's: they exercise the per-server grain, the
    two address key names, the implicit transport, the referrer walk and the audit-tracking
    exclusion. The device readback for this domain is recorded in the stage 7 artifact.
    """

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.logsettings")
        self.appliance = Appliance.objects.create(
            management_station=self.station, hostname="fw.logsettings", serial_number="LG-1")

    def _normalize(self, config):
        from optivedge_integrations.integrations.platforms.pan_os.normalization import (
            normalize_appliance_log_settings)
        Snapshot.objects.create(
            appliance=self.appliance, source_type="show_merged_config",
            payload={"config": config}, collected_at=timezone.now())
        return normalize_appliance_log_settings(self.appliance)

    @staticmethod
    def _config(shared_log_settings=None, vsys_log_settings=None, management=None):
        return {
            "shared": {"log-settings": shared_log_settings or {}},
            "devices": {"entry": [{
                "@name": "localhost.localdomain",
                "deviceconfig": {"setting": {"management": management or {}}},
                "vsys": {"entry": [{"@name": "vsys1",
                                    "log-settings": vsys_log_settings or {}}]},
            }]},
        }

    def test_one_profile_with_two_servers_yields_two_rows_with_their_own_transports(self):
        """THE SERVER IS THE ROW because transport is per server: one profile holding a TLS
        server and a cleartext one is the case a profile-keyed row could not report."""
        from optivedge_integrations.integrations.models import LogServerTarget
        self._normalize(self._config(shared_log_settings={
            "syslog": {"entry": [{"@name": "p1", "server": {"entry": [
                {"@name": "s-plain", "server": "10.0.0.1"},
                {"@name": "s-tls", "server": "10.0.0.2", "transport": "SSL", "port": "6514"},
            ]}}]}}))
        rows = {r.server_name: r for r in LogServerTarget.objects.all()}
        self.assertEqual(set(rows), {"s-plain", "s-tls"})
        self.assertEqual(rows["s-plain"].transport, "UDP",
                         "the absent key is the MEASURED implicit, on the firing side")
        self.assertEqual(rows["s-plain"].port, 514,
                         "the absent port materialises the CLEARTEXT port, which is stage 5's "
                         "decision and the firing side; it stored null until 2026-10-30")
        self.assertEqual(rows["s-tls"].transport, "SSL")
        self.assertEqual(rows["s-tls"].port, 6514)
        self.assertEqual(rows["s-plain"].profile_name, "p1")

    def test_the_implicit_transport_records_a_measured_provenance_row(self):
        from optivedge_integrations.integrations.models import LogServerTarget
        self._normalize(self._config(shared_log_settings={
            "syslog": {"entry": [{"@name": "p1", "server": {"entry": [
                {"@name": "s1", "server": "10.0.0.1"}]}}]}}))
        row = LogServerTarget.objects.get()
        provenance = {
            r.field_name: (r.provenance_type, r.raw_value)
            for r in FieldProvenance.objects.filter(
                content_type=ContentType.objects.get_for_model(LogServerTarget),
                object_id=row.pk)}
        self.assertEqual(provenance["transport"], ("pan_os_default", "UDP"))
        self.assertEqual(provenance["port"][0], "pan_os_default",
                         "the port implicit is MEASURED now, so the row says the device's own "
                         "default rather than `not_configured`; it read the other way until "
                         "2026-10-30 and the normalizer's implicit block holds both readings")

    def test_the_email_kind_reads_gateway_and_not_server(self):
        """TWO KEY NAMES, ONE COLUMN. A normalizer reading one loses the other kind silently -
        the same trap `ServerProfile` folds three names for."""
        from optivedge_integrations.integrations.models import LogServerTarget
        self._normalize(self._config(shared_log_settings={
            "email": {"entry": [{"@name": "m1", "server": {"entry": [
                {"@name": "r1", "gateway": "10.0.0.9", "protocol": "TLS",
                 "tls-version": "1.2", "auth": "Auto"}]}}]}}))
        row = LogServerTarget.objects.get()
        self.assertEqual((row.kind, row.server_address), ("email", "10.0.0.9"))
        self.assertTrue(row.meets_authenticated_tls)
        self.assertEqual(row.transport_grade, LogServerTarget.GRADE_TLS_12)

    def test_the_absent_port_materialises_a_different_number_on_each_kind(self):
        """ONE KEY, TWO IMPLICITS. A single shared implicit would put the mail port on a syslog
        collector or the other way round, and both are stored numbers a finding prints as the
        device's own. The values are stage 5's decision, which this stage implements rather than
        revisits: its own note says both readings are recorded and a person should settle it, and
        this test is where that disagreement is held so a later change cannot resolve it
        quietly."""
        from optivedge_integrations.integrations.models import LogServerTarget
        self._normalize(self._config(shared_log_settings={
            "syslog": {"entry": [{"@name": "p1", "server": {"entry": [
                {"@name": "s1", "server": "10.0.0.1"}]}}]},
            "email": {"entry": [{"@name": "m1", "server": {"entry": [
                {"@name": "r1", "gateway": "10.0.0.9", "protocol": "SMTP"}]}}]}}))
        ports = {r.kind: r.port for r in LogServerTarget.objects.all()}
        self.assertEqual(ports, {"syslog": 514, "email": 25})

    def test_a_vsys_profile_and_a_shared_one_of_the_same_name_are_two_rows(self):
        """The collision was written on a device deliberately and both were accepted at commit.
        Keying without the scope would silently store one of the two."""
        from optivedge_integrations.integrations.models import LogServerTarget
        profile = {"entry": [{"@name": "same", "server": {"entry": [
            {"@name": "s1", "server": "10.0.0.1"}]}}]}
        self._normalize(self._config(shared_log_settings={"syslog": profile},
                                     vsys_log_settings={"syslog": profile}))
        self.assertEqual(
            sorted(LogServerTarget.objects.values_list("scope", "vsys_name")),
            [("shared", ""), ("vsys", "vsys1")])

    def test_a_match_list_member_counts_as_a_referrer_and_audit_tracking_does_not(self):
        """Of the three places this leaf appears, TWO count. Audit-tracking's own `send-syslog`
        was ruled out of scope, and counting it would make an unused profile look in use."""
        from optivedge_integrations.integrations.models import LoggingSettings, LogServerTarget
        self._normalize(self._config(
            shared_log_settings={
                "syslog": {"entry": [{"@name": "p1", "server": {"entry": [
                    {"@name": "s1", "server": "10.0.0.1"}]}}]},
                "system": {"match-list": {"entry": [{
                    "@name": "m", "filter": "All Logs",
                    "send-syslog": {"member": ["p1"]}}]}},
            },
            management={"audit-tracking": {"send-syslog": {"member": ["p1"]}}}))
        self.assertEqual(LogServerTarget.objects.get().profile_referrer_count, 1)
        row = LoggingSettings.objects.get(appliance=self.appliance)
        self.assertTrue(row.syslog_destination_in_use)
        self.assertEqual(row.system_log_severity_gaps, "",
                         "an unrestricted filter to a resolvable syslog profile covers all five")

    def test_a_member_naming_nothing_is_not_a_destination_in_use(self):
        """A profile that does not exist delivers nothing, and counting the member would make an
        appliance with a typo look like one with a working collector."""
        from optivedge_integrations.integrations.models import LoggingSettings
        from optivedge_integrations.integrations.models import ALL_SYSTEM_SEVERITIES_MISSING
        self._normalize(self._config(shared_log_settings={
            "system": {"match-list": {"entry": [{
                "@name": "m", "filter": "All Logs",
                "send-syslog": {"member": ["does-not-exist"]}}]}}}))
        row = LoggingSettings.objects.get(appliance=self.appliance)
        self.assertFalse(row.syslog_destination_in_use)
        self.assertEqual(row.system_log_severity_gaps, ALL_SYSTEM_SEVERITIES_MISSING,
                         "no off-box destination means every severity is uncovered")

    # --- PAN-LOG-001's count half ------------------------------------------------------
    # `offbox_destination_count` is the one column stage 5 commissioned for this domain, and
    # the tests below are the floor stage 7's contract sets for a measured absence: the value
    # is asserted rather than the shape, and the zero case is reached by RECOUNTING a row that
    # already held one - a test that asserts the field's own default would pass unchanged if
    # the normalizer stopped writing the column at all.

    def test_the_destination_count_is_distinct_addresses_across_both_scopes(self):
        """BOTH SCOPES AND DISTINCT BY HOST. Every appliance in this lab holds a vsys-scoped
        syslog profile, so a count taken at the shared scope alone reports `no destination` on
        all four - and two profiles naming one collector are one place the trail goes."""
        from optivedge_integrations.integrations.models import LoggingSettings
        self._normalize(self._config(
            shared_log_settings={"syslog": {"entry": [
                {"@name": "p-shared", "server": {"entry": [
                    {"@name": "s1", "server": "10.0.0.1"},
                    {"@name": "s2", "server": "10.0.0.2"}]}}]}},
            vsys_log_settings={"syslog": {"entry": [
                {"@name": "p-vsys", "server": {"entry": [
                    {"@name": "s1", "server": "10.0.0.2"},
                    {"@name": "s3", "server": "10.0.0.3"}]}}]}}))
        self.assertEqual(
            LoggingSettings.objects.get(appliance=self.appliance).offbox_destination_count, 3,
            "four server entries at two scopes, three distinct collector addresses")

    def test_an_email_relay_and_an_addressless_server_are_not_destinations(self):
        """Email NOTIFIES rather than retains, and an entry with no address key has no host to
        send to - so one syslog collector beside both of them is a count of one."""
        from optivedge_integrations.integrations.models import LoggingSettings
        self._normalize(self._config(shared_log_settings={
            "email": {"entry": [{"@name": "m1", "server": {"entry": [
                {"@name": "r1", "gateway": "10.0.0.9", "protocol": "SMTP"}]}}]},
            "syslog": {"entry": [{"@name": "p1", "server": {"entry": [
                {"@name": "s-ok", "server": "10.0.0.1"},
                {"@name": "s-no-address"}]}}]}}))
        self.assertEqual(
            LoggingSettings.objects.get(appliance=self.appliance).offbox_destination_count, 1)

    def test_the_panorama_path_is_one_destination_however_many_log_types_reach_it(self):
        """It is one place the trail goes. The per-log-type question is
        `panorama_log_type_gaps`, a different column with a different shape."""
        from optivedge_integrations.integrations.models import LoggingSettings
        self._normalize(self._config(shared_log_settings={
            "system": {"match-list": {"entry": [{
                "@name": "a", "filter": "All Logs", "send-to-panorama": "yes"}]}},
            "config": {"match-list": {"entry": [{
                "@name": "b", "filter": "All Logs", "send-to-panorama": "yes"}]}}}))
        self.assertEqual(
            LoggingSettings.objects.get(appliance=self.appliance).offbox_destination_count, 1)

    def test_an_http_collector_counts_only_where_the_named_profile_exists(self):
        """An HTTP collector retains, so it counts - but a `send-http` member naming nothing
        delivers nothing, the same reason the referrer verdicts resolve their members."""
        from optivedge_integrations.integrations.models import LoggingSettings
        self._normalize(self._config(shared_log_settings={
            "http": {"entry": [{"@name": "h1", "server": {"entry": [
                {"@name": "c1", "address": "10.0.0.7"}]}}]},
            "system": {"match-list": {"entry": [{
                "@name": "a", "filter": "All Logs",
                "send-http": {"member": ["h1", "h-does-not-exist"]}}]}}}))
        self.assertEqual(
            LoggingSettings.objects.get(appliance=self.appliance).offbox_destination_count, 1)

    def test_a_row_that_loses_its_destinations_is_recounted_to_the_firing_zero(self):
        """ZERO IS BOTH THE DEFAULT AND THE FIRING SIDE, and this is the test that proves the
        normalizer writes it rather than the field defaulting to it: the row holds one first."""
        from optivedge_integrations.integrations.models import LoggingSettings
        self._normalize(self._config(shared_log_settings={
            "syslog": {"entry": [{"@name": "p1", "server": {"entry": [
                {"@name": "s1", "server": "10.0.0.1"}]}}]}}))
        self.assertEqual(
            LoggingSettings.objects.get(appliance=self.appliance).offbox_destination_count, 1)
        self._normalize(self._config())
        self.assertEqual(
            LoggingSettings.objects.get(appliance=self.appliance).offbox_destination_count, 0,
            "an appliance that defines no off-box destination reports rather than passing")

    def test_the_other_normalizer_on_this_row_does_not_reset_the_destination_count(self):
        """TWO NORMALIZERS WRITE `LoggingSettings` and `write_node_row` passes only its own
        caller's fields to `update_or_create`, so the Setup > Management pass must leave this
        count alone. If it ever wrote a full field set instead, whichever ran last would zero
        the other's columns and PAN-LOG-001 would report every appliance in the estate."""
        from optivedge_integrations.integrations.models import LoggingSettings
        from optivedge_integrations.integrations.platforms.pan_os.normalization import (
            normalize_appliance_services_settings)
        self._normalize(self._config(shared_log_settings={
            "syslog": {"entry": [{"@name": "p1", "server": {"entry": [
                {"@name": "s1", "server": "10.0.0.1"}]}}]}}))
        normalize_appliance_services_settings(self.appliance)
        self.assertEqual(
            LoggingSettings.objects.get(appliance=self.appliance).offbox_destination_count, 1)

    def test_the_two_halves_of_the_configuration_log_verdict_are_stored_separately(self):
        """The failure is a DISJUNCTION - no destination OR a narrowing filter - and the clause
        grammar is a flat conjunction, so the halves are stored beside the verdict."""
        from optivedge_integrations.integrations.models import LoggingSettings
        self._normalize(self._config(shared_log_settings={
            "syslog": {"entry": [{"@name": "p1", "server": {"entry": [
                {"@name": "s1", "server": "10.0.0.1"}]}}]},
            "config": {"match-list": {"entry": [{
                "@name": "m", "filter": "(admin eq 'nobody')",
                "send-syslog": {"member": ["p1"]}}]}}}))
        row = LoggingSettings.objects.get(appliance=self.appliance)
        self.assertTrue(row.config_log_offbox_destination)
        self.assertTrue(row.config_log_filter_narrows)
        self.assertFalse(row.config_log_fully_offbox)

    def test_an_absent_quota_branch_reads_as_left_at_the_shipped_quotas(self):
        from optivedge_integrations.integrations.models import LoggingSettings
        self._normalize(self._config())
        self.assertFalse(
            LoggingSettings.objects.get(appliance=self.appliance).log_retention_configured)

    def test_either_platform_shape_of_the_quota_branch_counts(self):
        """The branches differ between the PA-5220 and the PA-VM, so all four are checked on
        every device rather than branching on a platform this lab cannot separate."""
        from optivedge_integrations.integrations.models import LoggingSettings
        self._normalize(self._config(management={"quota-settings": {
            "disk-quota": {"traffic": "20"}}}))
        self.assertTrue(
            LoggingSettings.objects.get(appliance=self.appliance).log_retention_configured)

    def test_the_audit_comment_key_defaults_to_the_firing_side(self):
        from optivedge_integrations.integrations.models import LoggingSettings
        self._normalize(self._config())
        row = LoggingSettings.objects.get(appliance=self.appliance)
        self.assertFalse(row.require_audit_comment)
        provenance = FieldProvenance.objects.get(
            content_type=ContentType.objects.get_for_model(LoggingSettings),
            object_id=row.pk, field_name="require_audit_comment")
        self.assertEqual((provenance.provenance_type, provenance.raw_value),
                         ("pan_os_default", "no"))

    def test_the_two_normalizers_on_one_row_do_not_erase_each_others_provenance(self):
        """`LoggingSettings` is written by TWO normalizers - the Setup > Management checkbox
        PAN-MGT-011 reads, and this domain's fourteen columns. Each deletes only the rows for
        the fields it writes, because a missing row means `not tracked` and the erasure would
        read as a deliberate statement."""
        from optivedge_integrations.integrations.models import LoggingSettings
        from optivedge_integrations.integrations.platforms.pan_os.normalization import (
            normalize_appliance_services_settings)
        self._normalize(self._config())
        normalize_appliance_services_settings(self.appliance)
        row = LoggingSettings.objects.get(appliance=self.appliance)
        names = set(FieldProvenance.objects.filter(
            content_type=ContentType.objects.get_for_model(LoggingSettings),
            object_id=row.pk).values_list("field_name", flat=True))
        self.assertEqual(names, {"require_audit_comment", "log_on_high_dp_load"})

    def test_a_vsys_gets_a_row_and_its_gaps_are_the_full_set_with_no_profile(self):
        from optivedge_integrations.integrations.models import (
            ALL_FORWARDING_LOG_TYPES_MISSING, VsysLogForwarding)
        self._normalize(self._config())
        row = VsysLogForwarding.objects.get(appliance=self.appliance)
        self.assertEqual(row.vsys_name, "vsys1")
        self.assertEqual(row.offbox_log_type_gaps, ALL_FORWARDING_LOG_TYPES_MISSING)
        self.assertFalse(row.pushed_profile_sources_collected,
                         "neither the pushed nor the predefined read exists, so the control "
                         "stays silent rather than reporting a vsys it cannot see")

    def test_a_shared_profile_counts_for_a_vsys_and_a_destinationless_match_list_does_not(self):
        from optivedge_integrations.integrations.models import VsysLogForwarding
        self._normalize(self._config(shared_log_settings={
            "syslog": {"entry": [{"@name": "p1", "server": {"entry": [
                {"@name": "s1", "server": "10.0.0.1"}]}}]},
            "profiles": {"entry": [{"@name": "lf", "match-list": {"entry": [
                {"@name": "a", "log-type": "traffic", "filter": "All Logs",
                 "send-syslog": {"member": ["p1"]}},
                {"@name": "b", "log-type": "threat", "filter": "All Logs"},
            ]}}]}}))
        row = VsysLogForwarding.objects.get(appliance=self.appliance)
        self.assertNotIn("traffic", row.offbox_log_type_gaps.split(","))
        self.assertIn("threat", row.offbox_log_type_gaps.split(","),
                      "a match list with no destination at all forwards nothing off the box")

    def test_a_vsys_that_has_gone_from_the_device_loses_its_row(self):
        """Leaving it would report a gap against an enforcement point nobody can configure."""
        from optivedge_integrations.integrations.models import VsysLogForwarding
        self._normalize(self._config())
        config = self._config()
        config["devices"]["entry"][0]["vsys"]["entry"] = [{"@name": "vsys2"}]
        self._normalize(config)
        self.assertEqual(list(VsysLogForwarding.objects.values_list("vsys_name", flat=True)),
                         ["vsys2"])

    def test_the_match_list_display_structure_keeps_every_destination_kind(self):
        """The ONLY place the Log Settings match-list content is stored, so a finding has
        evidence beside it. Not for a query: nothing may clause on a stored structure."""
        from optivedge_integrations.integrations.models import LoggingSettings
        self._normalize(self._config(shared_log_settings={
            "system": {"match-list": {"entry": [{
                "@name": "m", "filter": "All Logs",
                "send-snmptrap": {"member": ["trap1"]},
                "send-to-panorama": "yes"}]}}}))
        shown = LoggingSettings.objects.get(
            appliance=self.appliance).log_settings_match_lists
        self.assertEqual(len(shown), 1)
        self.assertEqual(shown[0]["log_type"], "system")
        entry = shown[0]["entries"][0]
        self.assertEqual(entry["destinations"]["snmptrap"], ["trap1"])
        self.assertTrue(entry["destinations"]["panorama"])

    def test_an_snmptrap_only_match_list_is_not_an_offbox_destination(self):
        """SNMP traps and email NOTIFY rather than retain, so neither leaves a durable off-box
        copy - stage 3's settlement, and it is why the gap is the full set here."""
        from optivedge_integrations.integrations.models import (
            ALL_SYSTEM_SEVERITIES_MISSING, LoggingSettings)
        self._normalize(self._config(shared_log_settings={
            "system": {"match-list": {"entry": [{
                "@name": "m", "filter": "All Logs",
                "send-snmptrap": {"member": ["trap1"]}}]}}}))
        self.assertEqual(
            LoggingSettings.objects.get(appliance=self.appliance).system_log_severity_gaps,
            ALL_SYSTEM_SEVERITIES_MISSING)

    def test_send_to_panorama_removes_only_its_own_log_type_from_the_gap(self):
        from optivedge_integrations.integrations.models import LoggingSettings
        self._normalize(self._config(shared_log_settings={
            "system": {"match-list": {"entry": [{
                "@name": "m", "filter": "All Logs", "send-to-panorama": "yes"}]}}}))
        gaps = LoggingSettings.objects.get(
            appliance=self.appliance).panorama_log_type_gaps.split(",")
        self.assertNotIn("system", gaps)
        self.assertIn("config", gaps)
        self.assertEqual(len(gaps), 15)

    def test_correlation_is_not_in_the_panorama_gap_set(self):
        """It has no `send-to-panorama` key at all, measured, and the vendor says correlation
        logs cannot be forwarded from a firewall - so listing it would be a permanent gap."""
        from optivedge_integrations.integrations.models import PANORAMA_FORWARDABLE_LOG_TYPES
        self.assertNotIn("correlation", PANORAMA_FORWARDABLE_LOG_TYPES)

    def test_email_alerting_needs_critical_coverage_and_a_profile_that_exists(self):
        from optivedge_integrations.integrations.models import LoggingSettings
        self._normalize(self._config(shared_log_settings={
            "email": {"entry": [{"@name": "m1", "server": {"entry": [
                {"@name": "r1", "gateway": "10.0.0.9", "protocol": "SMTP"}]}}]},
            "system": {"match-list": {"entry": [
                {"@name": "a", "filter": "(severity eq low)",
                 "send-email": {"member": ["m1"]}},
            ]}}}))
        row = LoggingSettings.objects.get(appliance=self.appliance)
        self.assertFalse(row.email_alerting_for_critical_system_events,
                         "a filter that excludes critical does not alert on critical")

    def test_no_merged_snapshot_writes_nothing_rather_than_an_empty_verdict(self):
        from optivedge_integrations.integrations.platforms.pan_os.normalization import (
            normalize_appliance_log_settings)
        self.assertEqual(
            normalize_appliance_log_settings(self.appliance),
            {"log_server_targets": 0, "vsys_log_forwarding": 0, "logging_settings": 0})


class DefaultRuleSourcePanoramaFlagTests(TestCase):
    """`@panorama` on a default rule, which fires on every Panorama-managed device and had no test.

    Found by `read-config-sources-DEVICE-GROUP-addition.md`, which said it was for a person rather
    than for itself, and verified 2026-10-24: `@panorama` appeared ZERO times in this file. So
    `default_rule_source`'s `"true"` branch and its `raise ValueError` had never been exercised by
    a fixture, on a function with one caller.

    THE RAISE IS THE POINT OF THE DESIGN. `@panorama="true"` says the authoritative copy of this
    default rule is the PUSHED one, so falling back to the merged copy when no pushed default
    matches would report a Panorama-delivered rule from the wrong source and look like success.
    Raising makes that loud. An untested raise is a raise nobody has seen fire.
    """

    def test_a_panorama_flagged_default_rule_takes_the_PUSHED_copy(self):
        from optivedge_integrations.integrations.platforms.pan_os.normalization.security_rules import (  # noqa: E501
            default_rule_source)

        merged = {"@name": "intrazone-default", "@panorama": "true", "action": "allow"}
        pushed = {"@name": "intrazone-default", "@loc": "shared", "action": "deny"}
        source, rule = default_rule_source(merged, {"intrazone-default": pushed})

        self.assertEqual(source, SecurityRule.SOURCE_DEFAULT)
        self.assertIs(rule, pushed)
        # The merged copy's own `action` is the wrong answer, and naming it here is what makes
        # this test fail if the branch is removed rather than merely not covered.
        self.assertEqual(rule["action"], "deny")

    def test_the_flag_is_read_case_insensitively(self):
        """The code lowercases it. A payload carrying `True` is the same claim."""
        from optivedge_integrations.integrations.platforms.pan_os.normalization.security_rules import (  # noqa: E501
            default_rule_source)

        pushed = {"@name": "interzone-default", "action": "deny"}
        for flag in ("true", "True", "TRUE"):
            _source, rule = default_rule_source(
                {"@name": "interzone-default", "@panorama": flag},
                {"interzone-default": pushed})
            self.assertIs(rule, pushed, flag)

    def test_a_flagged_rule_with_no_pushed_default_RAISES_and_names_the_rule(self):
        from optivedge_integrations.integrations.platforms.pan_os.normalization.security_rules import (  # noqa: E501
            default_rule_source)

        with self.assertRaises(ValueError) as caught:
            default_rule_source(
                {"@name": "intrazone-default", "@panorama": "true"}, {})
        # The name is in the message because the caller loops over every default rule, and a
        # bare "missing pushed default rule" would not say which one.
        self.assertIn("intrazone-default", str(caught.exception))

    def test_an_UNflagged_default_rule_keeps_the_MERGED_copy(self):
        """The other limb, and the one a standalone firewall takes. Both store SOURCE_DEFAULT, so
        the config_source does not distinguish them - which is why the rule object returned is
        what this asserts on."""
        from optivedge_integrations.integrations.platforms.pan_os.normalization.security_rules import (  # noqa: E501
            default_rule_source)

        merged = {"@name": "intrazone-default", "action": "allow"}
        pushed = {"@name": "intrazone-default", "action": "deny"}
        source, rule = default_rule_source(merged, {"intrazone-default": pushed})

        self.assertEqual(source, SecurityRule.SOURCE_DEFAULT)
        self.assertIs(rule, merged)



from optivedge_integrations.integrations.models import (  # noqa: E402
    HighAvailabilityConfig as _HighAvailabilityConfig,
    PanoramaRegistration as _PanoramaRegistration)
from optivedge_integrations.integrations.platforms.pan_os.normalization.high_availability import (  # noqa: E402
    normalize_high_availability as _normalize_ha)
from optivedge_integrations.integrations.platforms.pan_os.normalization.panorama_registration import (  # noqa: E402
    normalize_panorama_registration as _normalize_pano,
    parse_panorama_status as _parse_panorama_status)


class _HaPanoramaBase(TestCase):
    """Shared fixture for the two `ha-panorama` models.

    EVERY PAYLOAD BELOW IS A LAB SHAPE, read off the four appliances on 2026-10-29 through
    Panorama's `target=` proxy, not a shape invented to make a column pass. Where a test needs a
    state the lab is not in - a formed pair, a populated link group, a hardened channel - it says
    so and builds it, because the only HA-enabled appliances in the estate are the two members of
    one live pair and writing to them to manufacture a band is not this layer's business.
    """

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.hap")
        self.group = ApplianceGroup.objects.create(
            management_station=self.station, name="g-hap",
            group_type=ApplianceGroup.TYPE_STANDALONE)
        self.appliance = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            serial_number="S-HAP", hostname="fw-hap", software_version="11.1.13-h3")

    def _merged(self, deviceconfig):
        Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": {"devices": {"entry": [
                {"@name": "localhost.localdomain", "deviceconfig": deviceconfig}]}}})

    def _runtime(self, source_type, result):
        Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type=source_type, collected_at=timezone.now(),
            payload={"response": {"@status": "success", "result": result}})

    def _provenance(self, model, row):
        return {r.field_name: r for r in FieldProvenance.objects.filter(
            content_type=ContentType.objects.get_for_model(model), object_id=row.pk)}

    # --- the lab's own shapes -------------------------------------------------------------
    #: fw-core-tpa-a's committed `deviceconfig/high-availability`, verbatim from
    #: `show config merged` on 2026-10-29. NOTE `ha1-backup`: present with a NULL value, and
    #: `port`, `ip-address` and `netmask` all absent beneath it.
    LAB_HA_CONFIG = {
        "interface": {
            "ha1": {"ip-address": "172.30.19.101", "netmask": "255.255.255.0"},
            "ha1-backup": None, "ha2": None, "ha2-backup": None, "ha3": None,
        },
        "group": {
            "group-id": "44", "peer-ip": "172.30.19.102",
            "state-synchronization": {"enabled": "no"},
            "configuration-synchronization": {"enabled": "yes"},
            "mode": {"active-passive": None},
        },
        "enabled": "yes",
    }
    #: The same appliance's `show high-availability all`, trimmed to the keys this layer reads.
    LAB_HA_RUNTIME = {
        "enabled": "yes",
        "group": {
            "mode": "Active-Passive",
            "local-info": {
                "state": "active", "ha1-encrypt-imported": "no", "state-sync": "User-disabled",
                "ha1-ipaddr": "172.30.19.101/24", "ha1-port": "ha1-a",
                "ha1-encrypt-enable": "no",
            },
            "peer-info": {"conn-ha1": {"conn-status": "up"}, "conn-status": "up",
                          "state": "passive"},
            "link-monitoring": {"enabled": "yes", "failure-condition": "any", "groups": None},
            "path-monitoring": {"enabled": "yes", "failure-condition": "any",
                                "virtual-wire": None, "vlan": None, "virtual-router": None},
            "running-sync": "synchronized", "running-sync-enabled": "yes",
        },
    }
    #: What a PA-VM with no HA node answers to the same command. The only instrument in this
    #: estate that can tell "HA is off" from "nobody collected it".
    LAB_HA_RUNTIME_OFF = {"enabled": "no",
                          "group": {"local-info": {"ha1-encrypt-imported": "no"}}}
    LAB_PANORAMA_STATUS_TWO_SLOTS = (
        "Panorama Server 1 : 20.185.152.225\n"
        "    Connected     : yes\n"
        "    HA state      : Unknown\n"
        "Panorama Server 2 : 192.0.2.1\n"
        "    Connected     : no\n"
        "    HA state      : disconnected")
    LAB_PANORAMA_STATUS_ONE_SLOT = (
        "Panorama Server 1 : 20.185.152.225\n"
        "    Connected     : yes\n"
        "    HA state      : Unknown")


class HighAvailabilityNormalizationTests(_HaPanoramaBase):
    """PAN-HAP-001 to 004's subject: one appliance's HA relationship, configured and live."""

    def _normalize(self, ha=None, runtime=None):
        self._merged({"high-availability": ha} if ha is not None else {})
        if runtime is not None:
            self._runtime("show_high_availability_all", runtime)
        _normalize_ha(self.appliance)
        return _HighAvailabilityConfig.objects.get(appliance=self.appliance)

    def test_the_lab_pair_reads_as_configured_and_not_as_exchanging_state(self):
        """THE MEASUREMENT THIS DOMAIN TURNS ON. Both members hold `enabled: yes` and
        `configuration-synchronization/enabled: yes` while the runtime read answers
        `state-sync: User-disabled`, so a verdict over the configuration switches alone passes a
        pair that is not exchanging state. `no_live_redundant_peer` has to fire here.
        """
        row = self._normalize(self.LAB_HA_CONFIG, self.LAB_HA_RUNTIME)

        self.assertTrue(row.ha_enabled)
        self.assertTrue(row.config_sync_enabled)
        self.assertFalse(row.state_sync_enabled)
        self.assertEqual(row.ha_mode, "active-passive")
        self.assertTrue(row.ha_config_collected)
        self.assertTrue(row.ha_runtime_state_collected)
        self.assertTrue(row.no_live_redundant_peer)

    def test_the_two_monitoring_enables_are_true_from_absent_keys_and_the_verdict_still_fires(self):
        """The reading most likely to be got backwards. There is no `group/monitoring` node at
        all on either PA-5220, and the device reports BOTH enables as `yes` with `groups: null`.
        So the enables reassure and `ha_monitors_nothing` is what PAN-HAP-004 clauses on.
        """
        row = self._normalize(self.LAB_HA_CONFIG, self.LAB_HA_RUNTIME)
        prov = self._provenance(_HighAvailabilityConfig, row)

        self.assertTrue(row.link_monitoring_enabled)
        self.assertTrue(row.path_monitoring_enabled)
        self.assertEqual(prov["link_monitoring_enabled"].provenance_type, "pan_os_default")
        self.assertEqual(prov["path_monitoring_enabled"].provenance_type, "pan_os_default")
        self.assertEqual(row.monitored_link_group_count, 0)
        self.assertTrue(row.ha_monitors_nothing)
        self.assertEqual(row.ha_monitoring_state,
                         _HighAvailabilityConfig.MONITORING_ENABLED_NO_GROUP)

    def test_a_link_group_carrying_no_interface_still_monitors_nothing(self):
        """Stage 4 wrote `<entry name='...'/>` at the container and `validate full` job 536
        answered "Configuration is valid", so the state the vendor warns about twice on this
        control's own screen passes commit-time validation. A COUNT cannot report it: the count
        is one and nothing is watched.
        """
        ha = {**self.LAB_HA_CONFIG, "group": {
            **self.LAB_HA_CONFIG["group"],
            "monitoring": {"link-monitoring": {"link-group": {"entry": [{"@name": "lg-empty"}]}}}}}
        row = self._normalize(ha, self.LAB_HA_RUNTIME)

        self.assertEqual(row.monitored_link_group_count, 1)
        self.assertEqual(row.monitored_link_groups, ["lg-empty"])
        self.assertTrue(row.ha_monitors_nothing)
        self.assertEqual(row.ha_monitoring_state,
                         _HighAvailabilityConfig.MONITORING_ENABLED_NO_GROUP)

    def test_a_link_group_with_an_interface_monitors_something(self):
        ha = {**self.LAB_HA_CONFIG, "group": {
            **self.LAB_HA_CONFIG["group"],
            "monitoring": {"link-monitoring": {"link-group": {"entry": [
                {"@name": "lg", "interface": {"member": ["ethernet1/1"]}}]}}}}}
        row = self._normalize(ha, self.LAB_HA_RUNTIME)

        self.assertFalse(row.ha_monitors_nothing)
        self.assertEqual(row.ha_monitoring_state, _HighAvailabilityConfig.MONITORING_LINK_ONLY)

    def test_a_populated_path_group_beside_a_populated_link_group_is_the_top_band(self):
        ha = {**self.LAB_HA_CONFIG, "group": {
            **self.LAB_HA_CONFIG["group"],
            "monitoring": {
                "link-monitoring": {"link-group": {"entry": [
                    {"@name": "lg", "interface": {"member": "ethernet1/1"}}]}},
                "path-monitoring": {"virtual-router": {"entry": [
                    {"@name": "vr", "destination-ip": {"member": ["10.0.0.1"]}}]}}}}}
        row = self._normalize(ha, self.LAB_HA_RUNTIME)

        self.assertFalse(row.ha_monitors_nothing)
        self.assertEqual(row.ha_monitoring_state,
                         _HighAvailabilityConfig.MONITORING_LINK_AND_PATH)

    def test_both_enables_off_is_its_own_band(self):
        ha = {**self.LAB_HA_CONFIG, "group": {
            **self.LAB_HA_CONFIG["group"],
            "monitoring": {"link-monitoring": {"enabled": "no"},
                           "path-monitoring": {"enabled": "no"}}}}
        row = self._normalize(ha, self.LAB_HA_RUNTIME)

        self.assertFalse(row.link_monitoring_enabled)
        self.assertFalse(row.path_monitoring_enabled)
        self.assertEqual(row.ha_monitoring_state,
                         _HighAvailabilityConfig.MONITORING_NEITHER_ENABLED)

    def test_the_present_and_empty_backup_container_is_a_half_built_second_path(self):
        """`interface/ha1-backup` answers as a key with a NULL value on both PA-5220s while
        `port`, `ip-address` and `netmask` are all absent beneath it. `if node:` there reports a
        backup control link that does not exist; the container's KEY is the evidence, and it is
        what puts this estate in stage 3's second rank.
        """
        row = self._normalize(self.LAB_HA_CONFIG, self.LAB_HA_RUNTIME)

        self.assertEqual(row.ha1_backup_port, "")
        self.assertEqual(row.peer_ip_backup, "")
        self.assertTrue(row.no_independent_second_keepalive_path)
        self.assertEqual(row.second_keepalive_path_state,
                         _HighAvailabilityConfig.KEEPALIVE_BACKUP_WITHOUT_PEER)

    def test_no_backup_container_at_all_is_the_bottom_band(self):
        ha = {**self.LAB_HA_CONFIG,
              "interface": {"ha1": {"ip-address": "172.30.19.101", "netmask": "255.255.255.0"}}}
        row = self._normalize(ha, self.LAB_HA_RUNTIME)

        self.assertEqual(row.second_keepalive_path_state,
                         _HighAvailabilityConfig.KEEPALIVE_NEITHER)

    def test_a_complete_independent_backup_link_satisfies_the_control(self):
        ha = {**self.LAB_HA_CONFIG,
              "interface": {"ha1": {"port": "ha1-a", "ip-address": "172.30.19.101",
                                    "netmask": "255.255.255.0"},
                            "ha1-backup": {"port": "ha1-b", "ip-address": "172.30.20.101",
                                           "netmask": "255.255.255.0"}},
              "group": {**self.LAB_HA_CONFIG["group"], "peer-ip-backup": "172.30.20.102"}}
        row = self._normalize(ha, self.LAB_HA_RUNTIME)

        self.assertEqual(row.ha1_backup_port, "ha1-b")
        self.assertEqual(row.peer_ip_backup, "172.30.20.102")
        self.assertFalse(row.no_independent_second_keepalive_path)
        self.assertEqual(row.second_keepalive_path_state,
                         _HighAvailabilityConfig.KEEPALIVE_ONE_COMPLETE)

    def test_a_backup_link_on_the_primary_subnet_is_not_independent(self):
        """The vendor's own independence test, and the reason this is a normalization-time
        verdict rather than a query: it compares the backup link's subnet AGAINST the primary's,
        which is a field-to-field comparison the search layer cannot express at all.
        """
        ha = {**self.LAB_HA_CONFIG,
              "interface": {"ha1": {"port": "ha1-a", "ip-address": "172.30.19.101",
                                    "netmask": "255.255.255.0"},
                            "ha1-backup": {"port": "ha1-b", "ip-address": "172.30.19.201",
                                           "netmask": "255.255.255.0"}},
              "group": {**self.LAB_HA_CONFIG["group"], "peer-ip-backup": "172.30.19.202"}}
        row = self._normalize(ha, self.LAB_HA_RUNTIME)

        self.assertTrue(row.no_independent_second_keepalive_path)

    def test_heartbeat_backup_over_the_primarys_own_management_port_is_not_a_second_path(self):
        """The branch that REVERSES MEANING. "Use the management port as a backup path" is a
        second route only while the primary control link is not already on it; where it is, the
        switch buys one path described twice.
        """
        ha = {**self.LAB_HA_CONFIG,
              "interface": {"ha1": {"port": "management", "ip-address": "192.168.250.2",
                                    "netmask": "255.255.255.0"}},
              "group": {**self.LAB_HA_CONFIG["group"],
                        "election-option": {"heartbeat-backup": "yes"}}}
        row = self._normalize(ha, self.LAB_HA_RUNTIME)

        self.assertTrue(row.heartbeat_backup_enabled)
        self.assertTrue(row.no_independent_second_keepalive_path)
        self.assertEqual(row.second_keepalive_path_state,
                         _HighAvailabilityConfig.KEEPALIVE_NEITHER)

    def test_heartbeat_backup_beside_a_dedicated_control_port_is_a_second_path(self):
        ha = {**self.LAB_HA_CONFIG,
              "group": {**self.LAB_HA_CONFIG["group"],
                        "election-option": {"heartbeat-backup": "yes"}}}
        row = self._normalize(ha, self.LAB_HA_RUNTIME)

        self.assertFalse(row.no_independent_second_keepalive_path)
        self.assertEqual(row.second_keepalive_path_state,
                         _HighAvailabilityConfig.KEEPALIVE_ONE_COMPLETE)

    def test_the_control_link_is_unencrypted_and_the_band_names_the_port_the_runtime_read_gave(self):
        """`interface/ha1/port` is ABSENT from the configuration on both PA-5220s while the
        operational read answers `ha1-port: ha1-a`. The band uses the runtime value where the
        configuration has none - stage 3 places `unencrypted-dedicated-ha-port` and
        `unencrypted-port-unknown` at the same baseline severity, so this is accuracy at no
        severity cost.
        """
        row = self._normalize(self.LAB_HA_CONFIG, self.LAB_HA_RUNTIME)

        self.assertFalse(row.ha1_encryption_key_imported)
        self.assertTrue(row.ha1_control_link_not_encrypted)
        self.assertEqual(row.ha1_control_link_exposure,
                         _HighAvailabilityConfig.EXPOSURE_DEDICATED_HA_PORT)
        # Read off the runtime reply and carrying no provenance row, deliberately.
        self.assertNotIn("ha1_encryption_key_imported",
                         self._provenance(_HighAvailabilityConfig, row))

    def test_the_encryption_switch_alone_does_not_make_the_link_encrypted(self):
        """`validate full` job 535 refused an HA1 encryption commit with "requires an import of
        the high-availability-key", so the switch can read `yes` on a link that is not
        encrypted. All three have to hold.
        """
        ha = {**self.LAB_HA_CONFIG,
              "interface": {**self.LAB_HA_CONFIG["interface"],
                            "ha1": {**self.LAB_HA_CONFIG["interface"]["ha1"],
                                    "encryption": {"enabled": "yes"}}}}
        row = self._normalize(ha, self.LAB_HA_RUNTIME)

        self.assertTrue(row.ha1_encryption_enabled)
        self.assertTrue(row.ha1_control_link_not_encrypted)

    def test_all_three_encryption_conditions_make_the_link_encrypted(self):
        ha = {**self.LAB_HA_CONFIG,
              "interface": {**self.LAB_HA_CONFIG["interface"],
                            "ha1": {**self.LAB_HA_CONFIG["interface"]["ha1"],
                                    "encryption": {"enabled": "yes"}}}}
        runtime = {"enabled": "yes", "group": {**self.LAB_HA_RUNTIME["group"], "local-info": {
            **self.LAB_HA_RUNTIME["group"]["local-info"],
            "ha1-encrypt-imported": "yes", "ha1-encrypt-enable": "yes"}}}
        row = self._normalize(ha, runtime)

        self.assertFalse(row.ha1_control_link_not_encrypted)
        self.assertEqual(row.ha1_control_link_exposure,
                         _HighAvailabilityConfig.EXPOSURE_ENCRYPTED)

    def test_a_formed_state_exchanging_pair_has_a_live_redundant_peer(self):
        """Not a lab state: both members hold `state-synchronization/enabled: no` and the lab's
        pair is not exchanging state. Built here so the verdict is tested in both directions.
        """
        ha = {**self.LAB_HA_CONFIG,
              "group": {**self.LAB_HA_CONFIG["group"],
                        "state-synchronization": {"enabled": "yes"}}}
        runtime = {"enabled": "yes", "group": {**self.LAB_HA_RUNTIME["group"], "local-info": {
            **self.LAB_HA_RUNTIME["group"]["local-info"], "state-sync": "synchronized"}}}
        row = self._normalize(ha, runtime)

        self.assertFalse(row.no_live_redundant_peer)

    def test_a_suspended_member_has_no_live_redundant_peer(self):
        ha = {**self.LAB_HA_CONFIG,
              "group": {**self.LAB_HA_CONFIG["group"],
                        "state-synchronization": {"enabled": "yes"}}}
        runtime = {"enabled": "yes", "group": {**self.LAB_HA_RUNTIME["group"], "local-info": {
            **self.LAB_HA_RUNTIME["group"]["local-info"],
            "state": "suspended", "state-sync": "synchronized"}}}
        row = self._normalize(ha, runtime)

        self.assertTrue(row.no_live_redundant_peer)

    def test_an_appliance_with_no_ha_node_reads_as_not_in_a_relationship_and_was_collected(self):
        """Three different shapes for one absence, measured on pan-fw-201: `action=get` returns
        None, `action=show` RAISES `No such node`, and the operational read answers a VALUE -
        `enabled: no`. The merged config simply has no `high-availability` key, which is a
        READING and not a failed collection: `ha_config_collected` stays TRUE.
        """
        row = self._normalize(None, self.LAB_HA_RUNTIME_OFF)
        prov = self._provenance(_HighAvailabilityConfig, row)

        self.assertTrue(row.ha_config_collected)
        self.assertFalse(row.ha_enabled)
        self.assertEqual(prov["ha_enabled"].provenance_type, "pan_os_default")
        self.assertEqual(prov["ha_enabled"].raw_value, "no")
        self.assertEqual(row.ha_mode, "")
        self.assertTrue(row.no_live_redundant_peer)

    def test_with_no_runtime_snapshot_the_verdicts_hold_their_firing_defaults(self):
        """The state of every estate until the collector runs. `ha_runtime_state_collected` is
        what tells this apart from four findings, and the key-imported column is NULL with a
        `not_configured` row rather than False - because `ha1-encrypt-imported` is never absent
        from the reply, so a False here would claim a reading nobody took.
        """
        row = self._normalize(self.LAB_HA_CONFIG)
        prov = self._provenance(_HighAvailabilityConfig, row)

        self.assertFalse(row.ha_runtime_state_collected)
        self.assertIsNone(row.ha1_encryption_key_imported)
        # NO PROVENANCE ROW, EITHER WAY ROUND. The first readback of this stage wrote one, and on
        # all four appliances it classified as `local` - which asserts an administrator
        # configured a key with no configuration node anywhere. The provenance vocabulary has no
        # member for a runtime reply's always-present key, so the column is declared in
        # `DERIVED_FIELDS` with the reason, which is the answer `LoggingSettings` already takes
        # for its two runtime columns.
        self.assertNotIn("ha1_encryption_key_imported", prov)
        self.assertIn("ha1_encryption_key_imported",
                      _HighAvailabilityConfig.DERIVED_FIELDS)
        self.assertTrue(row.no_live_redundant_peer)
        self.assertTrue(row.ha1_control_link_not_encrypted)
        self.assertTrue(row.ha_monitors_nothing)
        self.assertTrue(row.no_independent_second_keepalive_path)
        # The config port is absent and there is no runtime read to fall back on.
        self.assertEqual(row.ha1_control_link_exposure,
                         _HighAvailabilityConfig.EXPOSURE_PORT_UNKNOWN)

    def test_a_runtime_reply_of_an_unknown_shape_counts_as_not_collected(self):
        """A reply shape nobody has seen is not evidence that the relationship is fine."""
        self._merged({"high-availability": self.LAB_HA_CONFIG})
        Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_high_availability_all", collected_at=timezone.now(),
            payload={"response": {"result": "an unparsed string"}})
        _normalize_ha(self.appliance)
        row = _HighAvailabilityConfig.objects.get(appliance=self.appliance)

        self.assertFalse(row.ha_runtime_state_collected)
        self.assertTrue(row.no_live_redundant_peer)

    def test_the_five_unmeasured_switches_are_null_and_say_why(self):
        """Each one is `not_assumed` for its own measured reason - no oracle, no payable
        positive control, or a position a PA-VM's schema does not have. A stored guess on any of
        them would decide a control on nothing.
        """
        ha = {"enabled": "yes", "interface": {}, "group": {}}
        row = self._normalize(ha, self.LAB_HA_RUNTIME)
        prov = self._provenance(_HighAvailabilityConfig, row)

        for field in ("cluster_participation_enabled", "config_sync_enabled",
                      "state_sync_enabled", "ha1_encryption_enabled",
                      "heartbeat_backup_enabled"):
            with self.subTest(field):
                self.assertIsNone(getattr(row, field))
                self.assertEqual(prov[field].provenance_type, "not_configured")

    def test_a_template_supplied_value_keeps_its_marker(self):
        """So a finding on an HA setting can say which template to change. `@ptpl` names a
        template OR a template STACK and this layer does not disambiguate them - the model layer
        records that, and a remediation that says "in the template" may name the wrong container.
        """
        ha = {**self.LAB_HA_CONFIG,
              "enabled": {"@ptpl": "ptpl_fw-core-tpa", "#text": "yes"}}
        row = self._normalize(ha, self.LAB_HA_RUNTIME)
        prov = self._provenance(_HighAvailabilityConfig, row)

        self.assertTrue(row.ha_enabled)
        self.assertEqual(prov["ha_enabled"].provenance_type, "template")
        self.assertEqual(prov["ha_enabled"].raw_value, "ptpl_fw-core-tpa")

    def test_normalizing_twice_replaces_the_row_and_its_provenance(self):
        self._normalize(self.LAB_HA_CONFIG, self.LAB_HA_RUNTIME)
        self._merged({})
        _normalize_ha(self.appliance)

        self.assertEqual(
            _HighAvailabilityConfig.objects.filter(appliance=self.appliance).count(), 1)
        row = _HighAvailabilityConfig.objects.get(appliance=self.appliance)
        self.assertFalse(row.ha_enabled)
        self.assertEqual(FieldProvenance.objects.filter(
            content_type=ContentType.objects.get_for_model(_HighAvailabilityConfig),
            object_id=row.pk, field_name="ha_enabled").count(), 1)

    def test_no_merged_snapshot_writes_nothing(self):
        """Rather than replacing a real reading with a row of defaults."""
        self.assertEqual(_normalize_ha(self.appliance), {"high_availability_configs": 0})
        self.assertFalse(_HighAvailabilityConfig.objects.filter(
            appliance=self.appliance).exists())


class PanoramaRegistrationNormalizationTests(_HaPanoramaBase):
    """PAN-HAP-005's subject: the firewall's half of the management channel."""

    def _normalize(self, local_panorama=None, secure=None, initcfg=None, status=None):
        management = {}
        if secure is not None:
            management["secure-conn-client"] = secure
        if initcfg is not None:
            management["initcfg"] = initcfg
        deviceconfig = {"setting": {"management": management}}
        if local_panorama is not None:
            deviceconfig["system"] = {"panorama": {"local-panorama": local_panorama}}
        self._merged(deviceconfig)
        if status is not None:
            self._runtime("show_panorama_status", status)
        _normalize_pano(self.appliance)
        return _PanoramaRegistration.objects.get(appliance=self.appliance)

    def test_an_absent_second_slot_is_stored_as_blank_so_the_shipped_clause_can_match_it(self):
        """THE DECISION THIS TEST EXISTS FOR. Stage 5 declared this a materialised NULL on the
        ground that PAN-HAP-005[0]'s `is empty` clause matches a null. Measured 2026-10-29: every
        per-model `build_text_compiler` in OptivEdgeAssessments compiles `is_empty` to
        `filter(field="")`, so a NULL matches nothing and the control would never fire on the
        estate it exists to report. The MEANING stage 5 declared is preserved - nothing is bound,
        and that is the finding side - and the provenance row records it as the measured vendor
        default rather than as a field nobody read.
        """
        row = self._normalize({"panorama-server": "20.185.152.225"},
                              status=self.LAB_PANORAMA_STATUS_ONE_SLOT)
        prov = self._provenance(_PanoramaRegistration, row)

        self.assertEqual(row.panorama_server_secondary, "")
        self.assertIsNotNone(row.panorama_server_secondary)
        self.assertEqual(prov["panorama_server_secondary"].provenance_type, "pan_os_default")
        # The clause the control is written with, run as the consumer compiles it.
        self.assertTrue(_PanoramaRegistration.objects.filter(
            pk=row.pk, panorama_server_secondary="").exists())

    def test_a_named_second_slot_is_not_empty(self):
        row = self._normalize(
            {"panorama-server": "20.185.152.225", "panorama-server-2": "192.0.2.1"},
            status=self.LAB_PANORAMA_STATUS_TWO_SLOTS)

        self.assertEqual(row.panorama_server_secondary, "192.0.2.1")
        self.assertFalse(_PanoramaRegistration.objects.filter(
            pk=row.pk, panorama_server_secondary="").exists())

    def test_the_applicability_predicate_applies_until_somebody_says_otherwise(self):
        """It cannot be computed from a firewall at all: the station's own HA configuration is
        out of scope, so no collector exists and none may. TRUE is the APPLYING side - a false
        would suppress the control on every firewall, which is the reassuring failure an
        applicability clause makes look careful.
        """
        row = self._normalize({"panorama-server": "20.185.152.225"},
                              status=self.LAB_PANORAMA_STATUS_ONE_SLOT)

        self.assertTrue(row.management_estate_is_a_pair)

    def test_a_bound_certificate_with_nothing_switched_on_is_not_hardened(self):
        """pan-fw-111's committed state, verbatim: the certificate is bound and
        `enable-secure-panorama-communication` and its four siblings are all absent, so the
        management conversation runs on the predefined certificate pair the appliance shipped
        with and the binding configures nothing the device presents.
        """
        row = self._normalize(
            {"panorama-server": "20.185.152.225"},
            secure={"certificate-type": {"local": {"certificate": "pan-fw-111"}}},
            status=self.LAB_PANORAMA_STATUS_ONE_SLOT)

        self.assertEqual(row.client_certificate_type, "local")
        self.assertEqual(row.client_certificate_name, "pan-fw-111")
        self.assertIsNone(row.secure_panorama_communication_enabled)
        self.assertIsNone(row.check_server_identity_enabled)
        self.assertTrue(row.management_channel_not_hardened)

    def test_the_explicit_none_branch_reads_as_a_choice_node_and_not_as_text(self):
        """pan-fw-201's committed state, and it survived this morning's power cycle: the running
        view answers `{"secure-conn-client": {"certificate-type": {"none": null}}}`, so a reader
        of a text value gets nothing and the normalizer has to read WHICH CHILD is present.
        `none` is a settable branch AND the documented default, so this and an absent key are two
        stored states with one meaning.
        """
        row = self._normalize({"panorama-server": "20.185.152.225"},
                              secure={"certificate-type": {"none": None}},
                              status=self.LAB_PANORAMA_STATUS_ONE_SLOT)

        self.assertEqual(row.client_certificate_type, "none")
        self.assertEqual(row.client_certificate_name, "")
        self.assertTrue(row.management_channel_not_hardened)

    def test_an_absent_secure_conn_client_node_reads_the_same_as_the_none_branch(self):
        row = self._normalize({"panorama-server": "20.185.152.225"},
                              status=self.LAB_PANORAMA_STATUS_ONE_SLOT)
        prov = self._provenance(_PanoramaRegistration, row)

        self.assertEqual(row.client_certificate_type, "")
        self.assertEqual(prov["client_certificate_type"].provenance_type, "not_configured")
        self.assertTrue(row.management_channel_not_hardened)

    def test_all_three_firewall_side_conditions_harden_the_channel(self):
        """Not a lab state. And even this does NOT make the channel authenticated: the station
        may still accept the shipped certificate from anybody, which is `secure-conn-server` on
        Panorama and on no firewall.
        """
        row = self._normalize(
            {"panorama-server": "20.185.152.225"},
            secure={"certificate-type": {"local": {"certificate": "oep-tpl-mgmt"}},
                    "enable-secure-panorama-communication": "yes",
                    "check-server-identity": "yes"},
            status=self.LAB_PANORAMA_STATUS_ONE_SLOT)

        self.assertFalse(row.management_channel_not_hardened)

    def test_a_switched_on_surface_with_no_certificate_bound_is_still_not_hardened(self):
        row = self._normalize(
            {"panorama-server": "20.185.152.225"},
            secure={"enable-secure-panorama-communication": "yes",
                    "check-server-identity": "yes"},
            status=self.LAB_PANORAMA_STATUS_ONE_SLOT)

        self.assertTrue(row.management_channel_not_hardened)

    def test_the_status_reply_parses_into_slots_from_plain_text(self):
        """Every other collected reply in this estate parses to a dict; this one arrives as
        pre-formatted text, so a consumer splits lines and reads labels.
        """
        Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_panorama_status", collected_at=timezone.now(),
            payload={"response": {"result": self.LAB_PANORAMA_STATUS_TWO_SLOTS}})
        slots = _parse_panorama_status(Snapshot.objects.filter(
            appliance=self.appliance, source_type="show_panorama_status").first())

        self.assertEqual(slots, [
            {"address": "20.185.152.225", "connected": "yes", "ha_state": "Unknown"},
            {"address": "192.0.2.1", "connected": "no", "ha_state": "disconnected"}])

    def test_a_connected_primary_with_no_conflicting_bootstrap_address_is_verified(self):
        row = self._normalize({"panorama-server": "20.185.152.225"},
                              status=self.LAB_PANORAMA_STATUS_ONE_SLOT)

        self.assertFalse(row.panorama_address_in_force_unverified)

    def test_a_bootstrap_address_that_differs_from_the_live_setting_leaves_it_unverified(self):
        """Stage 4 measured three shapes on four appliances - pan-fw-201 holds an
        `initcfg/panorama-server` with the SAME address as the live setting, pan-fw-111 holds an
        `initcfg` with none, and the two PA-5220s hold neither. A differing one is the
        stale-bootstrap case a predicate over the configured slot alone cannot see.
        """
        row = self._normalize({"panorama-server": "20.185.152.225"},
                              initcfg={"panorama-server": "198.51.100.7"},
                              status=self.LAB_PANORAMA_STATUS_ONE_SLOT)

        self.assertTrue(row.panorama_address_in_force_unverified)

    def test_a_matching_bootstrap_address_does_not_leave_it_unverified(self):
        row = self._normalize({"panorama-server": "20.185.152.225"},
                              initcfg={"panorama-server": "20.185.152.225"},
                              status=self.LAB_PANORAMA_STATUS_ONE_SLOT)

        self.assertFalse(row.panorama_address_in_force_unverified)

    def test_with_no_status_snapshot_the_registration_is_unverified(self):
        row = self._normalize({"panorama-server": "20.185.152.225"})

        self.assertTrue(row.panorama_address_in_force_unverified)

    def test_an_unmanaged_firewall_names_no_management_appliance(self):
        row = self._normalize(status=self.LAB_PANORAMA_STATUS_ONE_SLOT)
        prov = self._provenance(_PanoramaRegistration, row)

        self.assertTrue(row.management_config_collected)
        self.assertEqual(row.panorama_server_primary, "")
        self.assertEqual(prov["panorama_server_primary"].provenance_type, "not_configured")
        self.assertTrue(row.panorama_address_in_force_unverified)

    def test_no_merged_snapshot_writes_nothing(self):
        self.assertEqual(_normalize_pano(self.appliance), {"panorama_registrations": 0})
        self.assertFalse(_PanoramaRegistration.objects.filter(
            appliance=self.appliance).exists())


from optivedge_integrations.integrations.models import (  # noqa: E402
    AdminRolePosture as _AdminRolePosture)
from optivedge_integrations.integrations.platforms.pan_os.normalization.admin_role_posture import (  # noqa: E402
    normalize_admin_role_posture as _normalize_role_posture)


class AdminRolePostureNormalizationTests(TestCase):
    """PAN-AUTH-023's subject - a verdict over a collection whose COMMONEST state is absent.

    Measured on the lab 2026-10-29, reading all four appliances: `shared/admin-role` is absent
    on one of them, carries one entry on another and two on the two HA peers, and on every
    appliance that has a role exactly one role is assigned to exactly one account. So the
    estate exercises the counting but never the predefined-name case the intersection exists
    for, which is why that case has a test of its own here.
    """

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.arp")
        self.group = ApplianceGroup.objects.create(
            management_station=self.station, name="g-arp",
            group_type=ApplianceGroup.TYPE_STANDALONE)
        self.appliance = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            serial_number="S-ARP", hostname="fw-arp")

    def _normalize(self, shared=None, users=()):
        config = {"devices": {"entry": [{"@name": "localhost.localdomain"}]}}
        if shared is not None:
            config["shared"] = shared
        if users:
            config["mgt-config"] = {"users": {"entry": list(users)}}
        Snapshot.objects.filter(appliance=self.appliance).delete()
        _AdminRolePosture.objects.filter(appliance=self.appliance).delete()
        Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": config})
        _normalize_role_posture(self.appliance)
        return _AdminRolePosture.objects.get(appliance=self.appliance)

    def _custom(self, name, profile):
        return {"@name": name,
                "permissions": {"role-based": {"custom": {"profile": profile}}}}

    def test_an_absent_collection_still_writes_a_row_holding_the_finding(self):
        """The failing state has NO ENTRY to hang a row on, which is why the row is the
        appliance. Returning without writing would leave the appliance unreported, and this
        control's commonest true answer is "there is no scoped role here at all"."""
        row = self._normalize()
        self.assertEqual((row.scoped_role_count, row.scoped_roles_in_use_count), (0, 0))

    def test_a_template_pushed_empty_node_is_not_a_role(self):
        """`{"admin-role": None}` is what a template push of an empty node leaves behind."""
        row = self._normalize({"admin-role": None})
        self.assertEqual((row.scoped_role_count, row.scoped_roles_in_use_count), (0, 0))

    def test_roles_are_counted_and_only_the_assigned_ones_are_in_use(self):
        row = self._normalize(
            {"admin-role": {"entry": [{"@name": "r-one"}, {"@name": "r-two"}]}},
            users=[self._custom("a", "r-one"), {"@name": "b"}])
        self.assertEqual((row.scoped_role_count, row.scoped_roles_in_use_count), (2, 1))

    def test_two_accounts_on_one_role_count_the_role_once(self):
        """The column counts ROLES IN USE, not assignments - zero is the finding and two
        accounts on one role is still one role."""
        row = self._normalize(
            {"admin-role": {"entry": [{"@name": "r-one"}]}},
            users=[self._custom("a", "r-one"), self._custom("b", "r-one")])
        self.assertEqual((row.scoped_role_count, row.scoped_roles_in_use_count), (1, 1))

    def test_a_predefined_role_name_is_not_a_scoped_role_in_use(self):
        """THE CASE THE LAB CANNOT SHOW. `custom/profile` reaches a PREDEFINED role too -
        completing that leaf on a device with no custom roles returned `auditadmin`,
        `securityadmin` and `cryptoadmin` - and a predefined role is not one anybody here
        scoped. Counting the reference rather than the intersection would report a scoped role
        in use on an appliance that defines none."""
        row = self._normalize(
            {"admin-role": {"entry": [{"@name": "r-one"}]}},
            users=[self._custom("a", "auditadmin")])
        self.assertEqual((row.scoped_role_count, row.scoped_roles_in_use_count), (1, 0))

    def test_one_row_per_appliance_and_re_normalizing_updates_it(self):
        self._normalize({"admin-role": {"entry": [{"@name": "r-one"}]}})
        row = self._normalize({"admin-role": {"entry": [{"@name": "r-one"},
                                                        {"@name": "r-two"}]}})
        self.assertEqual(_AdminRolePosture.objects.filter(appliance=self.appliance).count(), 1)
        self.assertEqual(row.scoped_role_count, 2)

    def test_no_merged_snapshot_writes_nothing(self):
        self.assertEqual(_normalize_role_posture(self.appliance),
                         {"admin_role_postures": 0})
        self.assertFalse(
            _AdminRolePosture.objects.filter(appliance=self.appliance).exists())

    def test_every_column_is_derived_and_none_carries_a_provenance_row(self):
        """A derived column may never have a stored row, and both of this model's columns are
        counts. The consequence is in the model docstring: nothing here can say whether the
        roles it counted are the appliance's own or a template's."""
        row = self._normalize({"admin-role": {"entry": [{"@name": "r-one"}]}})
        self.assertFalse(FieldProvenance.objects.filter(
            content_type=ContentType.objects.get_for_model(_AdminRolePosture),
            object_id=row.pk).exists())
        self.assertEqual(
            row.provenance_for("scoped_role_count").provenance_type, "derived")


class AdminUserCredentialAndRosterColumnTests(TestCase):
    """PAN-AUTH-019's second half as its own column, and PAN-AUTH-021/022's roster caveat.

    `centrally_authenticated` is a verdict over BOTH of stage 3's halves and cannot report
    which half failed. The remediations differ - bind an identity service, against delete a
    stored credential - so the credential half needs a column a query can reach on its own.
    """

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.cred")
        self.group = ApplianceGroup.objects.create(
            management_station=self.station, name="g-cred",
            group_type=ApplianceGroup.TYPE_STANDALONE)
        self.appliance = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            serial_number="S-CRED", hostname="fw-cred")

    def _normalize(self, users):
        Snapshot.objects.filter(appliance=self.appliance).delete()
        Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": {
                "devices": {"entry": [{"@name": "localhost.localdomain"}]},
                "mgt-config": {"users": {"entry": list(users)}}}})
        _normalize_admins(self.appliance)
        return {u.name: u for u in _AdminUser.objects.filter(appliance=self.appliance)}

    def test_either_credential_alone_is_a_credential(self):
        """A DISJUNCTION, and the lab has an account of each kind. `phash` arrives as eight
        asterisks in every view, so only its presence is ever readable; the SSH key is not
        masked, and a later stage enumerating only the password would pass a key-only
        superuser."""
        rows = self._normalize([
            {"@name": "pwd-only", "phash": "$1$abc"},
            {"@name": "key-only", "public-key": "c3NoLXJzYQ=="},
            {"@name": "both", "phash": "$1$abc", "public-key": "c3NoLXJzYQ=="},
            {"@name": "neither"},
        ])
        self.assertTrue(rows["pwd-only"].has_local_credential)
        self.assertTrue(rows["key-only"].has_local_credential)
        self.assertTrue(rows["both"].has_local_credential)
        self.assertFalse(rows["neither"].has_local_credential)

    def test_the_masked_hash_is_still_a_credential(self):
        """What the device actually sends: `phash` comes back as the literal eight asterisks in
        every view on every appliance, so a value comparison has nothing to compare and a
        presence test is all this column can ever be."""
        rows = self._normalize([{"@name": "masked", "phash": "********"}])
        self.assertTrue(rows["masked"].has_local_credential)
        self.assertTrue(rows["masked"].has_password)

    def test_every_roster_declares_itself_a_floor(self):
        """Nothing in this package issues `<show><admins><all/></admins></show>`, so an
        administrator the identity service defines is not in `mgt-config/users` and is not
        counted. The column does not recover those accounts; it stops the superuser total
        reading as a census."""
        rows = self._normalize([
            {"@name": "su", "permissions": {"role-based": {"superuser": "yes"}}},
            {"@name": "other"},
        ])
        self.assertEqual(rows["su"].superuser_cohort_size, 1)
        for row in rows.values():
            self.assertTrue(row.roster_is_configuration_only)

    def test_both_columns_are_declared_derived(self):
        self.assertIn("has_local_credential", _AdminUser.DERIVED_FIELDS)
        self.assertIn("roster_is_configuration_only", _AdminUser.DERIVED_FIELDS)
        rows = self._normalize([{"@name": "a", "phash": "$1$abc"}])
        self.assertEqual(
            rows["a"].provenance_for("has_local_credential").provenance_type, "derived")


