class _NetworkHardeningBase(TestCase):
    """Shared fixture for the five `network-hardening` models and the eight Interface columns.

    EVERY PAYLOAD IN THIS AND THE FOLLOWING CLASSES IS A LAB SHAPE, read off the four
    appliances on 2026-10-29 through Panorama's `target=` proxy, not a shape invented to make
    a column pass. Appliances are named by SERIAL in the comments, because 691665AC334B458
    answers to the factory-default hostname `PA-VM` while every artifact calls it
    `pan-fw-201`.
    """

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.net")
        self.group = ApplianceGroup.objects.create(
            management_station=self.station, name="g-net",
            group_type=ApplianceGroup.TYPE_STANDALONE)
        self.appliance = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            serial_number="S-NET", hostname="fw-net", software_version="11.1.13-h3")
        self.group.active_appliance = self.appliance
        self.group.save()

    def _merged(self, *, network=None, deviceconfig=None, vsys=None):
        return Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": {"devices": {"entry": [{
                "@name": "localhost.localdomain",
                "network": network or {},
                "deviceconfig": deviceconfig or {},
                "vsys": {"entry": vsys if vsys is not None else [{"@name": "vsys1"}]},
            }]}}})


class SessionSettingsNormalizationTests(_NetworkHardeningBase):
    """PAN-NET-002 and PAN-NET-005 - two sibling leaves, one row, opposite provenance."""

    def test_the_two_lab_states_are_read_off_the_two_sibling_nodes(self):
        """013201001475's measured shape: both keys present and both `no`."""
        self._merged(deviceconfig={"setting": {
            "config": {"rematch": "no"}, "session": {"ipv6-firewalling": "no"}}})
        _nh_session(self.appliance)
        row = _NhSession.objects.get()

        self.assertFalse(row.session_rematch)
        self.assertFalse(row.ipv6_firewalling)

    def test_an_absent_rematch_key_stores_NOTHING_and_the_row_says_not_configured(self):
        """The vendor documents this one as enabled by default and nobody has measured it, so
        the honest answer is NULL - and the provenance row is what makes an unmeasured null
        distinguishable from a measured default sitting next to it on the same row."""
        self._merged(deviceconfig={"setting": {"session": {"ipv6-firewalling": "no"}}})
        _nh_session(self.appliance)
        row = _NhSession.objects.get()

        self.assertIsNone(row.session_rematch)
        self.assertEqual(
            row.provenance_for("session_rematch").provenance_type, "not_configured")

    def test_an_absent_ipv6_key_UNDER_A_PRESENT_CONTAINER_stores_the_measured_default(self):
        """6A9C0A9904E7D6E's measured shape and the third state a truthiness test loses: the
        `session` container EXISTS and carries a sibling key, so `ipv6-firewalling` is an
        absent key beneath a present node rather than an absent node."""
        self._merged(deviceconfig={"setting": {
            "config": {"rematch": "yes"}, "session": {"tcp-reject-non-syn": "no"}}})
        _nh_session(self.appliance)
        row = _NhSession.objects.get()

        self.assertTrue(row.ipv6_firewalling)
        self.assertEqual(
            row.provenance_for("ipv6_firewalling").provenance_type, "pan_os_default")

    def test_an_absent_deviceconfig_subtree_still_writes_a_row(self):
        """"We collected this appliance and it holds neither key" has to be distinguishable
        from "nobody collected this appliance", and the only thing that says so is the row."""
        self._merged()
        _nh_session(self.appliance)
        row = _NhSession.objects.get()

        self.assertIsNone(row.session_rematch)
        self.assertTrue(row.ipv6_firewalling)

    def test_no_merged_snapshot_writes_no_row_at_all(self):
        self.assertEqual(_nh_session(self.appliance), {"pan_os_session_settings": 0})
        self.assertEqual(_NhSession.objects.count(), 0)

    def test_the_row_is_replaced_and_never_duplicated(self):
        self._merged(deviceconfig={"setting": {"config": {"rematch": "no"}}})
        _nh_session(self.appliance)
        _nh_session(self.appliance)

        self.assertEqual(_NhSession.objects.count(), 1)
        # THREE AND NOT TWO SINCE 2026-10-30: `tcp_reject_non_syn` was added to this model by the
        # `zone-dos-protection` domain, which declared a `SessionSettings` model of its own and
        # found this class already owning `deviceconfig/setting/session`. The count is the
        # invariant this test exists for - one row per tracked field, never duplicated by a
        # second pass - and it moves by one for every column added to the node.
        self.assertEqual(
            FieldProvenance.objects.filter(
                content_type=ContentType.objects.get_for_model(_NhSession)).count(), 3)

    def test_a_template_decorated_leaf_reads_its_text_and_not_the_marker(self):
        """`deviceconfig/setting` is template-supplied on 013201001475 (@ptpl=shared-base) while
        its two children are firewall-local. A leaf arriving as a dict is the pushed shape."""
        self._merged(deviceconfig={"setting": {
            "@ptpl": "shared-base",
            "session": {"ipv6-firewalling": {"@ptpl": "shared-base", "#text": "no"}}}})
        _nh_session(self.appliance)
        row = _NhSession.objects.get()

        self.assertFalse(row.ipv6_firewalling)
        self.assertEqual(
            row.provenance_for("ipv6_firewalling").provenance_type, "template")


class LldpGlobalSettingsNormalizationTests(_NetworkHardeningBase):
    """PAN-NET-003's preferred value - the one leaf whose absence nobody has measured."""

    def test_the_three_lab_states(self):
        for payload, expected in (
            ({"lldp": {"enable": "yes"}}, True),       # 013201001475
            ({"lldp": {"enable": "no"}}, False),       # 691665AC334B458
            ({}, None),                                # 6A9C0A9904E7D6E - node absent
        ):
            with self.subTest(network=payload):
                _NhLldpGlobal.objects.all().delete()
                Snapshot.objects.filter(appliance=self.appliance).delete()
                self._merged(network=payload)
                _nh_lldp_global(self.appliance)

                self.assertEqual(
                    _NhLldpGlobal.objects.get().lldp_global_enable, expected)

    def test_an_absent_node_is_not_configured_rather_than_untracked(self):
        """A missing provenance row would say "nothing tracks this field" about a leaf nobody
        configured, which is the reverse of the truth."""
        self._merged()
        _nh_lldp_global(self.appliance)

        self.assertEqual(
            _NhLldpGlobal.objects.get().provenance_for(
                "lldp_global_enable").provenance_type, "not_configured")


class DhcpInterfaceConfigNormalizationTests(_NetworkHardeningBase):
    """PAN-NET-004 - a row only where DHCP is configured, and the relay verdict."""

    #: 691665AC334B458's `network/dhcp/interface` verbatim, 2026-10-29.
    LAB_DHCP = [
        {"@name": "ethernet1/3", "server": {
            "mode": "enabled", "ip-pool": {"member": ["10.98.3.100-10.98.3.200"]}}},
        {"@name": "ethernet1/4", "server": {
            "mode": "auto", "ip-pool": {"member": ["10.98.4.100-10.98.4.200"]}}},
        {"@name": "ethernet1/5", "server": {
            "mode": "disabled", "ip-pool": {"member": ["10.98.5.100-10.98.5.200"]}}},
        {"@name": "ethernet1/6", "relay": {
            "ip": {"enabled": "yes", "server": {"member": ["10.98.250.10"]}}}},
    ]

    def test_the_four_lab_entries_read_exactly_as_the_device_holds_them(self):
        self._merged(network={"dhcp": {"interface": {"entry": self.LAB_DHCP}}})

        self.assertEqual(_nh_dhcp(self.appliance),
                         {"pan_os_dhcp_interface_configs": 4})
        rows = {r.interface_name: r for r in _NhDhcp.objects.all()}
        self.assertEqual(
            [(n, rows[n].dhcp_server_configured, rows[n].dhcp_server_mode,
              rows[n].dhcp_relay_ipv4_enabled, rows[n].dhcp_relay_state)
             for n in sorted(rows)],
            [("ethernet1/3", True, "enabled", None, "not_configured"),
             ("ethernet1/4", True, "auto", None, "not_configured"),
             ("ethernet1/5", True, "disabled", None, "not_configured"),
             ("ethernet1/6", False, None, True, "relaying")])

    def test_an_absent_dhcp_container_writes_NO_ROW_which_is_the_passing_state(self):
        """6A9C0A9904E7D6E's measured state. The finding names the configuration that should
        not be there, so the compliant appliance needs no representation at all."""
        self._merged()

        self.assertEqual(_nh_dhcp(self.appliance),
                         {"pan_os_dhcp_interface_configs": 0})

    def test_a_removed_entry_stops_being_reported(self):
        """Delete-and-recreate, not update_or_create: a leftover row would report a DHCP
        server somebody has removed, which is a finding against a fixed estate."""
        self._merged(network={"dhcp": {"interface": {"entry": self.LAB_DHCP}}})
        _nh_dhcp(self.appliance)
        Snapshot.objects.filter(appliance=self.appliance).delete()
        self._merged(network={"dhcp": {"interface": {"entry": self.LAB_DHCP[:1]}}})
        _nh_dhcp(self.appliance)

        self.assertEqual([r.interface_name for r in _NhDhcp.objects.all()],
                         ["ethernet1/3"])
        self.assertEqual(
            FieldProvenance.objects.filter(
                content_type=ContentType.objects.get_for_model(_NhDhcp)).count(), 2)

    def test_a_mode_is_never_stored_for_a_branch_that_does_not_exist(self):
        """The model's own `clean()` rule, and the normalizer has to satisfy it: an entry with
        a relay and no server has no mode to store."""
        self._merged(network={"dhcp": {"interface": {"entry": [self.LAB_DHCP[3]]}}})
        _nh_dhcp(self.appliance)
        row = _NhDhcp.objects.get()
        row.clean()

        self.assertIsNone(row.dhcp_server_mode)

    def test_a_server_branch_with_no_mode_key_stores_null_and_stays_configured(self):
        """The branch's EXISTENCE is what the assertion rests on, and it does not depend on
        the mode - which is the whole reason the first half does not clause on the mode."""
        self._merged(network={"dhcp": {"interface": {"entry": [
            {"@name": "ethernet1/9", "server": {"ip-pool": {"member": ["10.0.0.1-10.0.0.9"]}}},
        ]}}})
        _nh_dhcp(self.appliance)
        row = _NhDhcp.objects.get()

        self.assertTrue(row.dhcp_server_configured)
        self.assertIsNone(row.dhcp_server_mode)
        self.assertEqual(
            row.provenance_for("dhcp_server_mode").provenance_type, "not_configured")

    def test_a_present_but_EMPTY_server_branch_is_still_a_server(self):
        """`{"server": null}` is the shape of a branch somebody emptied. Truthiness reports it
        as no server, which is the reassuring direction on a control about servers that should
        not be there."""
        self._merged(network={"dhcp": {"interface": {"entry": [
            {"@name": "ethernet1/9", "server": None}]}}})
        _nh_dhcp(self.appliance)

        self.assertTrue(_NhDhcp.objects.get().dhcp_server_configured)

    def test_the_relay_verdict_over_both_address_families(self):
        self.assertEqual(_nh_relay_state({"@name": "e"}, None), "not_configured")
        self.assertEqual(
            _nh_relay_state({"relay": None}, None), "configured_and_off")
        self.assertEqual(
            _nh_relay_state({"relay": {"ip": {"enabled": "yes"}}}, True), "relaying")
        self.assertEqual(
            _nh_relay_state({"relay": {"ip": {"enabled": "no"}}}, False),
            "configured_and_off")
        # An `ip` branch whose `enabled` key is absent: unknown, and an unknown fires.
        self.assertEqual(
            _nh_relay_state({"relay": {"ip": {"server": {"member": ["10.0.0.1"]}}}}, None),
            "relaying")
        # THE IPv6 FAMILY, which has no column: a relay configured for IPv6 only would read
        # as `not_configured` from the IPv4 key alone, which is the one place in this domain
        # where a gap produces SILENCE rather than a firing default.
        self.assertEqual(
            _nh_relay_state({"relay": {"ipv6": {"enabled": "yes"}}}, None), "relaying")
        self.assertEqual(
            _nh_relay_state({"relay": {"ipv6": {"enabled": "no"}}}, None),
            "configured_and_off")
        self.assertEqual(
            _nh_relay_state({"relay": {"ip": {"enabled": "no"},
                                       "ipv6": {"enabled": "yes"}}}, False), "relaying")


class TunnelInspectionCoverageNormalizationTests(_NetworkHardeningBase):
    """PAN-NET-006 - a verdict per enforcement point over a rulebase that is usually absent."""

    #: oep-nhd6-t1 verbatim from 013201001475/vsys2, 2026-10-29.
    LAB_ENABLED_RULE = {
        "@name": "oep-nhd6-t1", "@uuid": "47bef40c-d1ca-41ec-b6ac-8e1e2ec0721d",
        "from": {"member": ["any"]}, "to": {"member": ["any"]},
        "source": {"member": ["any"]}, "destination": {"member": ["any"]},
        "source-user": {"member": ["any"]},
        "application": {"member": ["gre", "vxlan", "ipsec", "gtp"]},
    }
    #: oep-nhd6-t2 verbatim from vsys3: populated, and opening nothing.
    LAB_DISABLED_RULE = dict(LAB_ENABLED_RULE, **{
        "@name": "oep-nhd6-t2", "disabled": "yes"})

    def test_a_row_is_written_for_every_vsys_including_a_template_contributed_one(self):
        """`action=get` on 013201001475 reports NINE vsys and `action=show` reports eight - the
        ninth, vsys8, is contributed by a template. The merged read carries it, so it gets a
        verdict like any other; omitting it would leave an enforcement point unassessed."""
        self._merged(vsys=[{"@name": f"vsys{n}"} for n in (1, 2, 8)])

        self.assertEqual(_nh_tunnel(self.appliance),
                         {"pan_os_tunnel_inspection_coverages": 3})
        self.assertEqual(sorted(_NhTunnel.objects.values_list("vsys_name", flat=True)),
                         ["vsys1", "vsys2", "vsys8"])

    def test_an_absent_rulebase_fires_at_the_worst_rank(self):
        """The state of every vsys in the lab bar three, and the one object in this domain whose
        absence fires rather than passes."""
        self._merged(vsys=[{"@name": "vsys1"}])
        _nh_tunnel(self.appliance)
        row = _NhTunnel.objects.get()

        self.assertEqual(row.tunnel_inspect_rule_count, 0)
        self.assertEqual(row.tunnel_inspection_coverage_state, "no_policy")
        self.assertTrue(row.tunnel_inspect_rules_collected)
        self.assertEqual(row.scope, "vsys")

    def test_the_did_we_collect_it_flag_separates_the_two_zeroes(self):
        """A zero count means "no rules" only because this flag says the rulebase was read. The
        flag is reported and NOT claused on: an applicability clause on it would SUPPRESS the
        control when the answer is no, which reads as careful and is the exact inversion of
        what an unknown is supposed to do."""
        self._merged(vsys=[{"@name": "vsys1"}])
        _nh_tunnel(self.appliance)

        self.assertTrue(_NhTunnel.objects.get().tunnel_inspect_rules_collected)
        # A row nobody has recomputed carries the default, which is the firing side.
        self.assertFalse(_NhTunnel._meta.get_field(
            "tunnel_inspect_rules_collected").default)

    def test_the_three_states_a_configuration_read_can_reach(self):
        self.assertEqual(_nh_coverage([], "absent"), "no_policy")
        self.assertEqual(_nh_coverage([], "empty"), "no_policy")
        self.assertEqual(_nh_coverage([self.LAB_DISABLED_RULE], "populated"),
                         "all_rules_disabled")
        self.assertEqual(_nh_coverage([self.LAB_ENABLED_RULE], "populated"),
                         "coverage_unverified_without_traffic_answer")
        # One enabled rule among disabled ones is not "all disabled".
        self.assertEqual(
            _nh_coverage([self.LAB_DISABLED_RULE, self.LAB_ENABLED_RULE], "populated"),
            "coverage_unverified_without_traffic_answer")

    def test_an_enabled_rule_naming_every_protocol_is_still_unverified(self):
        """THE REFINEMENT IS NOT A SUPPRESSION. `fully_opened` is a claim that everything
        transiting IS opened, and nothing in any configuration read says what transited - so a
        rule from any zone to any zone naming all four protocols still fires at the baseline."""
        self._merged(vsys=[{"@name": "vsys1", "rulebase": {"tunnel-inspect": {
            "rules": {"entry": [self.LAB_ENABLED_RULE]}}}}])
        _nh_tunnel(self.appliance)

        self.assertEqual(_NhTunnel.objects.get().tunnel_inspection_coverage_state,
                         "coverage_unverified_without_traffic_answer")

    def test_a_present_but_empty_rulebase_container_is_not_a_populated_one(self):
        self._merged(vsys=[{"@name": "vsys1",
                            "rulebase": {"tunnel-inspect": {"rules": None}}}])
        _nh_tunnel(self.appliance)

        self.assertEqual(_NhTunnel.objects.get().tunnel_inspection_coverage_state,
                         "no_policy")

    def test_a_null_rulebase_key_does_not_raise(self):
        """vsys10 on 013201001475 holds `rulebase: null` - the key exists and carries nothing."""
        self._merged(vsys=[{"@name": "vsys10", "rulebase": None}])

        self.assertEqual(_nh_tunnel(self.appliance),
                         {"pan_os_tunnel_inspection_coverages": 1})

    def test_tunnel_acceleration_absent_asserts_ENABLED_which_narrows_the_assertion(self):
        """The direction that matters: a query treating a missing node as "acceleration off"
        would assert a GTP-U rule is required on every appliance that has never touched the
        setting."""
        self._merged(vsys=[{"@name": "vsys1"}])
        _nh_tunnel(self.appliance)
        row = _NhTunnel.objects.get()

        self.assertTrue(row.tunnel_acceleration)
        self.assertEqual(
            row.provenance_for("tunnel_acceleration").provenance_type, "pan_os_default")

    def test_tunnel_acceleration_no_is_read_and_recorded_as_local(self):
        """6A9C0A9904E7D6E is the only appliance in the estate where the leaf has a value."""
        self._merged(vsys=[{"@name": "vsys1"}],
                     deviceconfig={"setting": {"tunnel-acceleration": "no"}})
        _nh_tunnel(self.appliance)
        row = _NhTunnel.objects.get()

        self.assertFalse(row.tunnel_acceleration)
        self.assertEqual(
            row.provenance_for("tunnel_acceleration").provenance_type, "local")

    def test_a_pushed_rulebase_produces_a_SECOND_row_at_device_group_scope(self):
        """THE OMISSION THIS EXISTS FOR: the merged view carries no pushed policy, so a vsys
        whose coverage comes entirely from Panorama reads as having no policy at all - a wrong
        finding on exactly the estates that are centrally managed. The pushed payload spells
        the rulebase `policy/panorama/pre-rulebase`, NOT `rulebase`, and both pushed rulebases
        are read because a vsys evaluates both."""
        self._merged(vsys=[{"@name": "vsys1"}])
        point = EnforcementPoint.objects.create(
            management_station=self.station, appliance_group=self.group,
            vsys_name="vsys1", vsys_display_name="vsys1")
        Snapshot.objects.create(
            management_station=self.station, enforcement_point=point,
            source_type="show_pushed_shared_policy_vsys", collected_at=timezone.now(),
            payload={"policy": {"panorama": {
                "pre-rulebase": {"tunnel-inspect": {
                    "rules": {"entry": [self.LAB_ENABLED_RULE]}}},
                "post-rulebase": {"security": {"rules": None}}}}})
        _nh_tunnel(self.appliance)

        rows = {r.scope: r for r in _NhTunnel.objects.all()}
        self.assertEqual(sorted(rows), ["device-group", "vsys"])
        self.assertEqual(rows["vsys"].tunnel_inspection_coverage_state, "no_policy")
        self.assertEqual(rows["device-group"].tunnel_inspect_rule_count, 1)
        self.assertEqual(rows["device-group"].tunnel_inspection_coverage_state,
                         "coverage_unverified_without_traffic_answer")

    def test_a_pushed_read_with_NO_tunnel_inspect_key_writes_no_second_row(self):
        """The lab's measured shape - each pushed rulebase holds `security` and nothing else,
        on three vsys across two appliances. A second row saying `no_policy` would double every
        finding this control raises while telling nobody anything new; the cost is that "the
        device group pushes none" and "nobody asked Panorama" both produce no row."""
        self._merged(vsys=[{"@name": "vsys1"}])
        point = EnforcementPoint.objects.create(
            management_station=self.station, appliance_group=self.group,
            vsys_name="vsys1", vsys_display_name="vsys1")
        Snapshot.objects.create(
            management_station=self.station, enforcement_point=point,
            source_type="show_pushed_shared_policy_vsys", collected_at=timezone.now(),
            payload={"policy": {"panorama": {
                "pre-rulebase": {"security": {"rules": None}},
                "post-rulebase": {"default-security-rules": None,
                                  "security": {"rules": None}}}}})
        _nh_tunnel(self.appliance)

        self.assertEqual(list(_NhTunnel.objects.values_list("scope", flat=True)), ["vsys"])

    def test_a_vsys_with_no_device_group_assignment_does_not_raise(self):
        """`show config pushed-shared-policy` answers a plain string for a vsys Panorama does
        not push to, which `Snapshot.payload` stores as a `str`. The shipped reader answers {}
        for it, which is a legitimate operational state rather than an error."""
        self._merged(vsys=[{"@name": "vsys1"}])
        point = EnforcementPoint.objects.create(
            management_station=self.station, appliance_group=self.group,
            vsys_name="vsys1", vsys_display_name="vsys1")
        Snapshot.objects.create(
            management_station=self.station, enforcement_point=point,
            source_type="show_pushed_shared_policy_vsys", collected_at=timezone.now(),
            payload="No shared policy pushed to device")

        self.assertEqual(_nh_tunnel(self.appliance),
                         {"pan_os_tunnel_inspection_coverages": 1})

    def test_every_derived_column_carries_no_provenance_row(self):
        self._merged(vsys=[{"@name": "vsys1"}])
        _nh_tunnel(self.appliance)
        row = _NhTunnel.objects.get()
        stored = set(FieldProvenance.objects.filter(
            content_type=ContentType.objects.get_for_model(_NhTunnel),
            object_id=row.pk).values_list("field_name", flat=True))

        self.assertEqual(stored & set(_NhTunnel.DERIVED_FIELDS), set())
        self.assertEqual(stored, {"tunnel_acceleration"})


class RoutingAdjacencyNormalizationTests(_NetworkHardeningBase):
    """PAN-NET-007 - the adjacencies that carry authentication, and what each one amounts to."""

    #: `oep-nhd6-vr1` on 013201001475 verbatim, 2026-10-29, trimmed to the keys this reads.
    LAB_ROUTER = {
        "@name": "oep-nhd6-vr1",
        "interface": {"member": ["ethernet1/22", "ethernet1/23"]},
        "protocol": {
            "bgp": {
                "enable": "no", "router-id": "10.99.0.1", "local-as": "64999",
                "auth-profile": {"entry": [
                    {"@name": "oep-nhd6-ba1", "secret": "-AQ==REDACTED="}]},
                "peer-group": {"entry": [{
                    "@name": "oep-nhd6-g1", "enable": "no", "type": {"ebgp": None},
                    "peer": {"entry": [
                        {"@name": "oep-nhd6-p1", "enable": "no", "peer-as": "64801"},
                        {"@name": "oep-nhd6-p2", "enable": "no", "peer-as": "64802",
                         "connection-options": {"authentication": "oep-nhd6-ba1"},
                         "max-prefixes": "5000"},
                        {"@name": "oep-nhd6-p3", "enable": "no", "peer-as": "64803",
                         "connection-options": {"authentication": "oep-nhd6-ba1"},
                         "max-prefixes": "unlimited"},
                    ]}}]}},
            "ospf": {
                "enable": "no", "router-id": "10.99.0.1",
                "auth-profile": {"entry": [
                    {"@name": "oep-nhd6-oa1", "password": "-AQ==REDACTED="},
                    {"@name": "oep-nhd6-oa2", "md5": {"entry": [
                        {"@name": "1", "key": "-AQ==REDACTED=", "preferred": "yes"}]}}]},
                "area": {"entry": [
                    {"@name": "0.0.0.9", "type": {"normal": None}},
                    {"@name": "0.0.0.0", "type": {"normal": None},
                     "virtual-link": {"entry": [
                         {"@name": "oep-nhd6-v1", "enable": "no",
                          "authentication": "oep-nhd6-oa1"},
                         {"@name": "oep-nhd6-v2", "enable": "no",
                          "authentication": "oep-nhd6-oa2"},
                         {"@name": "oep-nhd6-v3", "enable": "no"},
                     ]}}]}},
            "ospfv3": {"enable": "no", "auth-profile": None},
        },
    }

    def test_the_six_lab_adjacencies_and_what_each_one_amounts_to(self):
        """Three BGP peers and three OSPF virtual links. The virtual links are read because
        they are where this estate's only OSPF authentication stands: both areas carry NO
        `interface` entries at all, so reading area interfaces alone would leave
        `ospf_authentication_profile` empty on every row in the estate and `cleartext_password`
        with no device proof anywhere."""
        self._merged(network={"virtual-router": {"entry": [self.LAB_ROUTER]}})

        self.assertEqual(_nh_adjacencies(self.appliance),
                         {"pan_os_routing_adjacencies": 6})
        rows = {r.adjacency_name: r for r in _NhAdjacency.objects.all()}
        self.assertEqual(
            [(n, rows[n].protocol, rows[n].authentication_profile,
              rows[n].authentication_strength, rows[n].max_prefixes,
              rows[n].prefix_limit_state)
             for n in sorted(rows)],
            [("oep-nhd6-p1", "bgp", "", "none", None, "no_ceiling"),
             ("oep-nhd6-p2", "bgp", "oep-nhd6-ba1", "weak_digest", "5000", "enforcing"),
             ("oep-nhd6-p3", "bgp", "oep-nhd6-ba1", "weak_digest", "unlimited",
              "unlimited"),
             ("oep-nhd6-v1", "ospf", "oep-nhd6-oa1", "cleartext_password", None,
              "no_ceiling"),
             ("oep-nhd6-v2", "ospf", "oep-nhd6-oa2", "weak_digest", None, "no_ceiling"),
             ("oep-nhd6-v3", "ospf", "", "none", None, "no_ceiling")])

    def test_the_per_protocol_columns_keep_their_own_measurement(self):
        """The coalesced column sits on TOP of the two measured references rather than
        replacing them, so no measurement is thrown away by having a verdict above it."""
        self._merged(network={"virtual-router": {"entry": [self.LAB_ROUTER]}})
        _nh_adjacencies(self.appliance)
        peer = _NhAdjacency.objects.get(adjacency_name="oep-nhd6-p2")
        link = _NhAdjacency.objects.get(adjacency_name="oep-nhd6-v1")

        self.assertEqual(peer.bgp_authentication_profile, "oep-nhd6-ba1")
        self.assertEqual(peer.ospf_authentication_profile, "")
        self.assertEqual(link.ospf_authentication_profile, "oep-nhd6-oa1")
        self.assertEqual(link.bgp_authentication_profile, "")
        self.assertEqual(
            peer.provenance_for("bgp_authentication_profile").provenance_type, "local")
        self.assertEqual(
            _NhAdjacency.objects.get(adjacency_name="oep-nhd6-p1").provenance_for(
                "bgp_authentication_profile").provenance_type, "pan_os_default")

    def test_a_reference_resolves_within_its_OWN_router_and_nowhere_else(self):
        """Measured: the pool is per router. A name that exists on another router does not
        satisfy the adjacency, and treating it as satisfied would report an unauthenticated
        peer as authenticated."""
        other = {"@name": "vr_other", "protocol": {"bgp": {
            "auth-profile": {"entry": [{"@name": "shared-name", "secret": "x"}]}}}}
        mine = {"@name": "vr_mine", "protocol": {"bgp": {"peer-group": {"entry": [
            {"@name": "g", "peer": {"entry": [
                {"@name": "p", "connection-options": {"authentication": "shared-name"}}]}}]}}}}
        self._merged(network={"virtual-router": {"entry": [other, mine]}})
        _nh_adjacencies(self.appliance)
        row = _NhAdjacency.objects.get(router_name="vr_mine")

        self.assertEqual(row.authentication_profile, "shared-name")
        self.assertEqual(row.authentication_strength, "none")

    def test_an_unresolvable_name_is_no_authentication_and_not_unknown(self):
        """A null join sits on the compliant side of a plain comparison and would be dropped,
        so the graded column has to decide it. `none` fires."""
        self.assertEqual(_nh_strength("bgp", "missing", {"bgp": {}}), "none")
        self.assertEqual(_nh_strength("bgp", "", {"bgp": {}}), "none")

    def test_the_strength_ladder_over_what_a_profile_actually_holds(self):
        profiles = {
            "bgp": {"md5-only": {"secret": "x"}, "bare": {}},
            "ospf": {"clear": {"password": "x"}, "digest": {"md5": {"entry": []}},
                     "both": {"password": "x", "md5": {"entry": []}}, "bare": {}},
        }
        self.assertEqual(_nh_strength("bgp", "md5-only", profiles), "weak_digest")
        self.assertEqual(_nh_strength("bgp", "bare", profiles), "none")
        self.assertEqual(_nh_strength("ospf", "clear", profiles), "cleartext_password")
        self.assertEqual(_nh_strength("ospf", "digest", profiles), "weak_digest")
        # WEAKEST WINS where a profile carries both, which is the ordering the vendor's own
        # "narrower attachment overrides the wider" statement implies.
        self.assertEqual(_nh_strength("ospf", "both", profiles), "cleartext_password")
        self.assertEqual(_nh_strength("ospf", "bare", profiles), "none")

    def test_the_prefix_ceiling_states_a_configuration_read_can_reach(self):
        self.assertEqual(_nh_prefix_limit(None), "no_ceiling")
        self.assertEqual(_nh_prefix_limit(""), "no_ceiling")
        self.assertEqual(_nh_prefix_limit("unlimited"), "unlimited")
        self.assertEqual(_nh_prefix_limit("5000"), "enforcing")
        # `warn_only` is unreachable: no measured key says whether the limit warns or stops,
        # so a ceiling that only warns is stored as `enforcing`. Same severity, wrong
        # remediation text.
        self.assertNotIn("warn_only", {_nh_prefix_limit(v)
                                       for v in (None, "", "unlimited", "1", "99999")})

    def test_the_routing_engine_has_three_answers_and_the_absence_is_UNKNOWN(self):
        """Resolving the absence to `legacy` would assert a vendor fact nobody measured. The
        leaf is absent on all four lab appliances."""
        self.assertEqual(_nh_engine({}), "unknown")
        self.assertEqual(
            _nh_engine({"deviceconfig": {"setting": {}}}), "unknown")
        self.assertEqual(
            _nh_engine({"deviceconfig": {"setting": {"advance-routing": "yes"}}}),
            "advanced")
        self.assertEqual(
            _nh_engine({"deviceconfig": {"setting": {"advance-routing": "no"}}}),
            "legacy")

    def test_an_advanced_routing_tree_with_entries_is_REPORTED_and_not_read(self):
        """The silent zero this exists to prevent: nothing normalizes `network/logical-router`,
        so an estate running the Advanced Routing Engine would produce no adjacency row at all
        - which is the reassuring direction on every assertion in this domain. No instance of
        that tree exists on any appliance this was measured against, so reading it would be a
        guess at a shape nobody has seen."""
        self._merged(network={"logical-router": {"entry": [{"@name": "lr1"}]}})
        _nh_adjacencies(self.appliance)
        issue = NormalizationIssue.objects.get(kind="routing_adjacency")

        self.assertEqual(issue.name, "network/logical-router")
        self.assertEqual(issue.disposition, NormalizationIssue.Disposition.SKIPPED)
        self.assertIn("NOT represented", issue.reason)

    def test_an_empty_logical_router_container_reports_nothing(self):
        """`network/logical-router` is ABSENT on all four lab appliances. Reporting that would
        put a permanent warning on every device in every estate."""
        self._merged(network={"logical-router": None,
                              "virtual-router": {"entry": [self.LAB_ROUTER]}})
        _nh_adjacencies(self.appliance)

        self.assertEqual(
            NormalizationIssue.objects.filter(kind="routing_adjacency").count(), 0)

    def test_a_removed_adjacency_stops_being_reported(self):
        self._merged(network={"virtual-router": {"entry": [self.LAB_ROUTER]}})
        _nh_adjacencies(self.appliance)
        Snapshot.objects.filter(appliance=self.appliance).delete()
        self._merged(network={"virtual-router": {"entry": [
            {"@name": "oep-nhd6-vr1", "protocol": {"bgp": {"peer-group": {"entry": [
                {"@name": "oep-nhd6-g1", "peer": {"entry": [
                    {"@name": "oep-nhd6-p1"}]}}]}}}}]}})
        _nh_adjacencies(self.appliance)

        self.assertEqual([r.adjacency_name for r in _NhAdjacency.objects.all()],
                         ["oep-nhd6-p1"])

    def test_a_router_with_no_protocol_branch_produces_no_row(self):
        """`oep-nhd6-vr2` on 691665AC334B458 holds five interfaces and no routing protocol at
        all - it exists only because PAN-OS will not commit a DHCP configuration on an
        interface that is in no virtual router."""
        self._merged(network={"virtual-router": {"entry": [
            {"@name": "oep-nhd6-vr2", "interface": {"member": ["ethernet1/3"]}}]}})

        self.assertEqual(_nh_adjacencies(self.appliance),
                         {"pan_os_routing_adjacencies": 0})

    def test_a_template_decorated_router_is_read_and_nothing_says_it_is_pushed(self):
        """`vr_pan-fw-111` is supplied entirely by template `ptpl-pan-fw-111`. It is stored as
        the firewall's own, which is this model's known limitation: a remediation would tell an
        engineer to attach a profile at a node the firewall will not accept the edit on."""
        self._merged(network={"virtual-router": {"@ptpl": "ptpl-pan-fw-111", "entry": [{
            "@name": "vr_pan-fw-111", "@ptpl": "ptpl-pan-fw-111",
            "protocol": {"@ptpl": "ptpl-pan-fw-111", "bgp": {
                "@ptpl": "ptpl-pan-fw-111",
                "enable": {"@ptpl": "ptpl-pan-fw-111", "#text": "no"},
                "peer-group": {"entry": [{"@name": "g", "peer": {"entry": [
                    {"@name": "p", "connection-options": {
                        "authentication": {"@ptpl": "ptpl-pan-fw-111",
                                           "#text": "tpl-profile"}}}]}}]}}}}]}})
        _nh_adjacencies(self.appliance)
        row = _NhAdjacency.objects.get()

        self.assertEqual(row.bgp_authentication_profile, "tpl-profile")
        self.assertEqual(
            row.provenance_for("bgp_authentication_profile").provenance_type, "template")

    def test_every_derived_column_carries_no_provenance_row(self):
        self._merged(network={"virtual-router": {"entry": [self.LAB_ROUTER]}})
        _nh_adjacencies(self.appliance)
        ct = ContentType.objects.get_for_model(_NhAdjacency)
        stored = set(FieldProvenance.objects.filter(content_type=ct)
                     .values_list("field_name", flat=True))

        self.assertEqual(stored & set(_NhAdjacency.DERIVED_FIELDS), set())


class InterfaceNetworkHardeningColumnTests(_NetworkHardeningBase):
    """PAN-NET-001 and PAN-NET-003's eight columns on the shipped `Interface` model."""

    #: 013201001475's ethernet container, 2026-10-29, trimmed to the shapes this reads.
    LAB_ETHERNET = [
        {"@name": "ethernet1/9", "layer3": {
            "lldp": {"enable": "yes", "profile": "oep-nhd6-lp1"}}},
        {"@name": "ethernet1/13", "layer3": {"lldp": {"enable": "yes"}}},
        {"@name": "ethernet1/14", "layer3": {
            "lldp": {"enable": "yes", "profile": "oep-nhd6-lp5"}}},
        {"@name": "ethernet1/15", "layer3": {"lldp": {"enable": "no"}}},
        {"@name": "ethernet1/16", "layer3": None},
        {"@name": "ethernet1/17", "link-state": "down", "layer3": None},
        {"@name": "ethernet1/18", "link-state": "auto", "link-speed": "1000",
         "layer3": None},
        {"@name": "ethernet1/19", "link-state": "auto", "layer3": {
            "ip": {"entry": [{"@name": "10.99.19.1/30"}]}}},
        {"@name": "ethernet1/20", "link-state": "down", "layer3": {
            "interface-management-profile": "oep-nhd6-mp1"}},
        {"@name": "ethernet1/21", "link-state": "down", "layer3": {
            "interface-management-profile": "oep-p2-imp"}},
        {"@name": "ethernet1/22", "link-state": "down", "layer3": None},
        {"@name": "ethernet1/24", "link-state": "down", "layer3": None},
    ]
    #: The lab's five LLDP profiles verbatim. NOTE THE TWO SPELLINGS: `management-address`
    #: arrives as a CONTAINER with its own `enabled` child while `system-description` and
    #: `system-name` arrive as the bare string "yes". Measured on 013201001475.
    LAB_LLDP_PROFILES = [
        {"@name": "oep-nhd6-lp1", "mode": "transmit-receive",
         "option-tlvs": {"management-address": {"enabled": "yes"}}},
        {"@name": "oep-nhd6-lp2", "mode": "transmit-receive",
         "option-tlvs": {"system-description": "yes"}},
        {"@name": "oep-nhd6-lp3", "mode": "transmit-receive",
         "option-tlvs": {"system-name": "yes"}},
        {"@name": "oep-nhd6-lp4", "mode": "transmit-receive"},
        {"@name": "oep-nhd6-lp5", "mode": "receive-only"},
    ]
    #: `oep-nhd6-mp1` sets no permitted-ip; `oep-p2-imp` sets two. Both verbatim.
    LAB_PROFILES = [
        {"@name": "oep-nhd6-mp1", "https": "yes"},
        {"@name": "oep-p2-imp", "@ptpl": "shared-base",
         "ping": {"@ptpl": "shared-base", "#text": "yes"},
         "permitted-ip": {"@ptpl": "shared-base", "entry": [
             {"@name": "10.77.1.0/24", "@ptpl": "shared-base"},
             {"@name": "10.77.2.0/24", "@ptpl": "shared-base"}]}},
        # The third state: present and EMPTY, which exists on 6A9C0A9904E7D6E.
        {"@name": "oep-mgt6-p02", "https": "yes", "permitted-ip": None},
    ]

    def _lab(self, *, vsys=None):
        return self._merged(
            network={
                "interface": {"ethernet": {"entry": self.LAB_ETHERNET}},
                "virtual-router": {"entry": [{
                    "@name": "oep-nhd6-vr1",
                    "interface": {"member": ["ethernet1/22"]}}]},
                "profiles": {
                    "interface-management-profile": {"entry": self.LAB_PROFILES},
                    "lldp-profile": {"entry": self.LAB_LLDP_PROFILES}},
            },
            vsys=vsys if vsys is not None else [{"@name": "vsys1"}])

    def _rows(self):
        return {i.name: i for i in Interface.objects.filter(appliance=self.appliance)}

    def test_the_residue_ranking_over_the_twelve_lab_ports(self):
        """Every one of these ports was committed by stage 6 to stand for one rank, and the
        ranking is a precedence rather than a set of flags - the WORST thing held wins."""
        self._lab()
        normalize_interfaces(self.appliance)
        rows = self._rows()

        self.assertEqual(
            {n: rows[n].out_of_service_residue for n in sorted(rows)},
            {"ethernet1/9": "administrative_state_unknown",
             "ethernet1/13": "administrative_state_unknown",
             "ethernet1/14": "administrative_state_unknown",
             "ethernet1/15": "administrative_state_unknown",
             "ethernet1/16": "administrative_state_unknown",
             "ethernet1/17": "stripped_and_shut_down",
             "ethernet1/18": "comment_or_link_settings_only",
             "ethernet1/19": "address_only",
             "ethernet1/20": "unrestricted_management_binding",
             "ethernet1/21": "restricted_management_binding",
             "ethernet1/22": "routing_instance_without_address",
             "ethernet1/24": "stripped_and_shut_down"})

    def test_link_state_is_the_CONFIGURED_state_and_null_where_the_key_is_absent(self):
        """Nothing is assumed: the only oracle for the administrative state conflates it with
        the physical link, so guessing `auto` would assert that every port with no key is not
        shut down - the reassuring direction on the one key the fourth clause turns on."""
        self._lab()
        normalize_interfaces(self.appliance)
        rows = self._rows()

        self.assertIsNone(rows["ethernet1/16"].link_state)
        self.assertEqual(rows["ethernet1/17"].link_state, "down")
        self.assertEqual(rows["ethernet1/18"].link_state, "auto")

    def test_a_port_holding_nothing_and_NOT_shut_down_still_fires(self):
        """THE PLACE THE VOCABULARY RUNS OUT: stripped but administratively enabled is the
        second half of what the control asks for and has no token. It reads
        `administrative_state_unknown`, which fires, because the one member that reads as
        fully compliant would say "shut down" about a port that is not - and `link_state`
        beside it is what separates the two states this token carries."""
        self.assertEqual(
            _nh_residue(profile_name="", restricted=False, zone_name="", addressing="none",
                        ipv4=[], ipv6=[], link_state="auto", in_routing_instance=False,
                        has_link_settings=False),
            "administrative_state_unknown")
        self.assertEqual(
            _nh_residue(profile_name="", restricted=False, zone_name="", addressing="none",
                        ipv4=[], ipv6=[], link_state="down", in_routing_instance=False,
                        has_link_settings=False),
            "stripped_and_shut_down")

    def test_a_dhcp_addressed_port_is_address_only_despite_holding_no_address(self):
        """`ipv4_addresses` is empty for a DHCP client because the lease is runtime state, so a
        residue reading the address list alone would report the port as holding nothing."""
        self.assertEqual(
            _nh_residue(profile_name="", restricted=False, zone_name="",
                        addressing="dhcp-client", ipv4=[], ipv6=[], link_state="down",
                        in_routing_instance=False, has_link_settings=False),
            "address_only")

    def test_the_source_restriction_has_three_states_and_two_of_them_restrict_nothing(self):
        profiles = {p["@name"]: p for p in self.LAB_PROFILES}

        self.assertTrue(_nh_restricts("oep-p2-imp", profiles))
        self.assertFalse(_nh_restricts("oep-nhd6-mp1", profiles))
        # Present and EMPTY: `{"permitted-ip": null}` restricts nothing, and a truthiness
        # test on the container cannot tell it from a populated one.
        self.assertFalse(_nh_restricts("oep-mgt6-p02", profiles))
        # A binding naming a profile that does not exist still permits whatever the port's
        # own surface permits, so the unrestricted reading is the right one.
        self.assertFalse(_nh_restricts("gone", profiles))
        self.assertFalse(_nh_restricts("", profiles))

    def test_the_zone_is_read_from_the_ZONE_end_across_every_member_list(self):
        """The zone names its members and the interface does not name its zone. Every one of
        the six subtrees a zone can carry is walked, not only layer3."""
        device_entry = {"vsys": {"entry": [{
            "@name": "vsys1", "zone": {"entry": [
                {"@name": "oep-nhd6-z2", "network": {"layer3": {
                    "member": ["ethernet1/1", "ethernet1/3"]}}},
                {"@name": "l2zone", "network": {"layer2": {"member": ["ethernet1/8"]}}},
                {"@name": "vwzone", "network": {
                    "virtual-wire": {"member": ["ethernet1/11"]}}},
                # Template-supplied and carrying no member key at all, which is what both
                # PA-VMs' `Private` and `Public` look like.
                {"@name": "Private", "@ptpl": "creds_tpl",
                 "network": {"@ptpl": "creds_tpl", "layer3": {"@ptpl": "creds_tpl"}}},
                # Present and empty.
                {"@name": "oep-iot6-z2", "network": None},
            ]}}]}}

        self.assertEqual(_nh_zones(device_entry),
                         {"ethernet1/1": "oep-nhd6-z2", "ethernet1/3": "oep-nhd6-z2",
                          "ethernet1/8": "l2zone", "ethernet1/11": "vwzone"})

    def test_a_zone_member_arriving_as_a_decorated_dict_is_read(self):
        """A pushed member list is `[{"@ptpl": "...", "#text": "ethernet1/1"}]`, not a list of
        strings, and a reader taking the dict's str() would store the whole mapping."""
        device_entry = {"vsys": {"entry": [{"@name": "vsys1", "zone": {"entry": [
            {"@name": "untrust", "network": {"layer3": {"member": [
                {"@ptpl": "ptpl-pan-fw-111", "#text": "ethernet1/1"}]}}}]}}]}}

        self.assertEqual(_nh_zones(device_entry), {"ethernet1/1": "untrust"})

    def test_the_announced_content_ladder_over_the_five_lab_profiles(self):
        """The five profiles stage 6 committed, one per rank, plus the two states that need no
        profile at all."""
        profiles = {p["@name"]: p for p in self.LAB_LLDP_PROFILES}

        self.assertEqual(_nh_announced(True, "oep-nhd6-lp1", profiles),
                         "management_address")
        self.assertEqual(_nh_announced(True, "oep-nhd6-lp2", profiles),
                         "system_description")
        self.assertEqual(_nh_announced(True, "oep-nhd6-lp3", profiles),
                         "hostname_or_role")
        # Transmitting with every optional TLV unset still puts the MANDATORY chassis
        # identifier and port name on the wire, which is why this is not "nothing".
        self.assertEqual(_nh_announced(True, "oep-nhd6-lp4", profiles),
                         "port_and_chassis_only")
        self.assertEqual(_nh_announced(True, "oep-nhd6-lp5", profiles),
                         "receive_only_or_off")
        # Running the protocol with no profile: the vendor says the firewall uses its global
        # defaults and no document says what those transmit, so what the port leaks is
        # UNKNOWN rather than low - and an unknown fires.
        self.assertEqual(_nh_announced(True, "", profiles), "unknown_global_defaults")
        # A dangling reference is treated the same way rather than as a pass.
        self.assertEqual(_nh_announced(True, "gone", profiles), "unknown_global_defaults")
        self.assertEqual(_nh_announced(False, "oep-nhd6-lp1", profiles),
                         "receive_only_or_off")

    def test_a_TLV_is_read_in_BOTH_of_the_two_spellings_the_device_uses(self):
        """Measured 2026-10-29: `management-address` is a container with its own `enabled`
        child while `system-description` is the bare string "yes". A reader of one shape gets
        nothing from the other, and getting nothing reads as "not announced"."""
        self.assertEqual(
            _nh_announced(True, "p", {"p": {"mode": "transmit-receive", "option-tlvs": {
                "management-address": {"enabled": "yes"}}}}),
            "management_address")
        self.assertEqual(
            _nh_announced(True, "p", {"p": {"mode": "transmit-receive", "option-tlvs": {
                "management-address": "yes"}}}),
            "management_address")
        # And a container whose `enabled` child says no, or is absent, is not announced.
        self.assertEqual(
            _nh_announced(True, "p", {"p": {"mode": "transmit-receive", "option-tlvs": {
                "management-address": {"enabled": "no"}}}}),
            "port_and_chassis_only")
        self.assertEqual(
            _nh_announced(True, "p", {"p": {"mode": "transmit-receive", "option-tlvs": {
                "management-address": None}}}),
            "port_and_chassis_only")

    def test_the_lldp_node_presence_is_element_presence_and_not_a_value(self):
        """An empty `<lldp/>` serialises as None, so a truthiness test reports a port that HAS
        a node as having none - and the distinction is behavioural: `show lldp config all`
        lists an interface if and only if the node exists."""
        self._merged(network={"interface": {"ethernet": {"entry": [
            {"@name": "ethernet1/1", "layer3": {"lldp": None}},
            {"@name": "ethernet1/2", "layer3": {}},
        ]}}})
        normalize_interfaces(self.appliance)
        rows = self._rows()

        self.assertTrue(rows["ethernet1/1"].lldp_node_present)
        self.assertFalse(rows["ethernet1/1"].lldp_enabled)
        self.assertFalse(rows["ethernet1/2"].lldp_node_present)

    def test_a_template_supplied_lldp_node_reads_its_text(self):
        """6A9C0A9904E7D6E's ethernet1/1, ethernet1/2 and ethernet1/7 all carry
        `lldp: {enable: no}`, the first two of them decorated down to the leaf."""
        self._merged(network={"interface": {"ethernet": {"entry": [
            {"@name": "ethernet1/1", "@ptpl": "ptpl-pan-fw-111", "layer3": {
                "@ptpl": "ptpl-pan-fw-111", "lldp": {
                    "@ptpl": "ptpl-pan-fw-111",
                    "enable": {"@ptpl": "ptpl-pan-fw-111", "#text": "no"}}}},
        ]}}})
        normalize_interfaces(self.appliance)

        row = self._rows()["ethernet1/1"]
        self.assertTrue(row.lldp_node_present)
        self.assertFalse(row.lldp_enabled)

    def test_a_subinterface_gets_its_own_eight_columns_from_its_own_entry(self):
        """A unit carries its addressing and its bindings directly rather than under a type
        key - the type key is on the parent - so a reader that looked under the subtree would
        find nothing on every subinterface on the device."""
        self._merged(
            network={"interface": {"ethernet": {"entry": [{
                "@name": "ethernet1/1", "layer3": {"units": {"entry": [
                    {"@name": "ethernet1/1.1101",
                     "ip": {"entry": [{"@name": "10.110.1.1/24"}]},
                     "lldp": {"enable": "yes"}}]}}}]}}},
            vsys=[{"@name": "vsys1", "zone": {"entry": [
                {"@name": "extranet", "network": {
                    "layer3": {"member": ["ethernet1/1.1101"]}}}]}}])
        normalize_interfaces(self.appliance)
        unit = self._rows()["ethernet1/1.1101"]

        self.assertEqual(unit.security_zone_name, "extranet")
        self.assertTrue(unit.lldp_node_present)
        self.assertTrue(unit.lldp_enabled)
        self.assertEqual(unit.lldp_announced_content, "unknown_global_defaults")
        self.assertEqual(unit.out_of_service_residue, "security_zone_membership")

    def test_the_zone_beats_the_address_and_the_binding_beats_the_zone(self):
        """The precedence, tested where two residues sit on one port - which is the ordinary
        case on a real firewall and the thing a set of flags cannot express."""
        self._merged(
            network={"interface": {"ethernet": {"entry": [
                {"@name": "ethernet1/1", "layer3": {
                    "ip": {"entry": [{"@name": "10.0.0.1/24"}]}}},
                {"@name": "ethernet1/2", "layer3": {
                    "ip": {"entry": [{"@name": "10.0.1.1/24"}]},
                    "interface-management-profile": "oep-nhd6-mp1"}},
            ]}}, "profiles": {"interface-management-profile": {
                "entry": self.LAB_PROFILES}}},
            vsys=[{"@name": "vsys1", "zone": {"entry": [{
                "@name": "z", "network": {"layer3": {
                    "member": ["ethernet1/1", "ethernet1/2"]}}}]}}])
        normalize_interfaces(self.appliance)
        rows = self._rows()

        self.assertEqual(rows["ethernet1/1"].out_of_service_residue,
                         "security_zone_membership")
        self.assertEqual(rows["ethernet1/2"].out_of_service_residue,
                         "unrestricted_management_binding")

    def test_this_model_records_NO_provenance_for_any_of_the_eight(self):
        """`Interface` carries no `ProvenancedMixin`, so a missing row here means the model is
        not tracked and nothing more - which is the REVERSE of the reading a normalizer author
        finds written down elsewhere. The eight derived columns cannot be declared either."""
        self._lab()
        normalize_interfaces(self.appliance)

        self.assertFalse(hasattr(Interface, "DERIVED_FIELDS"))
        self.assertEqual(
            FieldProvenance.objects.filter(
                content_type=ContentType.objects.get_for_model(Interface)).count(), 0)


# ---------------------------------------------------------------------------
# Platform lifecycle - PAN-PLT-001 to PAN-PLT-006
# ---------------------------------------------------------------------------
#
# THE LAB CANNOT DISCRIMINATE MOST OF THIS DOMAIN'S BRANCHES, which is why these tests exist and
# what they are for. The readback over all four appliances produced ONE value of
# `content_currency_state` on four rows out of six possible tokens, one value of
# `support_entitlement_state` out of five, and three of the five `alarm_mechanism_state` tokens.
# A readback over one estate is not evidence about a branch that estate cannot reach, so every
# state no appliance here holds is driven from a payload shaped like the reply that would produce
# it - and the shapes are the ones stage 4 measured rather than ones invented to pass.

from optivedge_integrations.integrations.models import (  # noqa: E402
    ConfigurationBackupEvidence as _PltBackup,
    DataplaneUtilisation as _PltDataplane,
    FirewallContentStreams as _PltStreams,
    GlobalProtectPortalPresence as _PltPortal,
    LicenceEntitlement as _PltEntitlement,
    LicenceInventory as _PltInventory,
    LogAlarmSettings as _PltAlarm)
from optivedge_integrations.integrations.platforms.pan_os.collectors.platform_lifecycle import (  # noqa: E402
    DEVICE_TELEMETRY_XPATH as _PLT_TELEMETRY_XPATH,
    LOG_ALARM_SETTINGS_XPATH as _PLT_ALARM_XPATH,
    SHOW_RESOURCE_MONITOR_COMMAND as _PLT_RM_COMMAND,
    collect_device_telemetry as _plt_collect_telemetry,
    collect_log_alarm_settings as _plt_collect_alarm)
from optivedge_integrations.integrations.platforms.pan_os.normalization.platform_lifecycle import (  # noqa: E402
    alarm_mechanism_state as _plt_alarm_state,
    build_content_streams as _plt_build_streams,
    build_dataplane_utilisation as _plt_build_dataplane,
    build_licence_inventory as _plt_build_licences,
    build_log_alarm_settings as _plt_build_alarm,
    build_portal_presence as _plt_build_portal,
    content_currency_state as _plt_currency_state,
    portal_container_state as _plt_portal_state)
from optivedge_integrations.integrations.platforms.pan_os.session import (  # noqa: E402
    PANSessionAPIError as _PltAPIError)
from optivedge_integrations.integrations.platforms.pan_os.normalization.common import (  # noqa: E402
    classify_prov_type as _plt_classify_prov)
from datetime import datetime as _PltDateTime  # noqa: E402


def _plt_system(**overrides):
    """A `show system info` reply shaped like the lab's, with the clock the age rests on."""
    reply = {
        "time": "Thu Oct 29 09:48:06 2026",
        "app-version": "9161-10297",
        "app-release-date": "2026/10/28 01:27:15 GMT",
        "av-version": "5709-6237",
        "av-release-date": "2026/10/29 01:00:30 GMT",
        "threat-version": "9161-10297",
        "threat-release-date": "2026/10/28 01:27:15 GMT",
        "wildfire-version": "1130785-1135443",
        "url-filtering-version": "20261029.20147",
        "device-dictionary-version": "249-772",
        "device-dictionary-release-date": "2026/10/24 02:35:51 GMT",
        "device-certificate-status": "None",
    }
    for key, value in overrides.items():
        if value is None:
            reply.pop(key, None)
        else:
            reply[key] = value
    return reply


class PlatformLifecycleContentCurrencyTests(SimpleTestCase):
    """The content verdict, including the five states this lab cannot produce.

    THE READBACK PRODUCED `stream_never_installed` ON ALL FOUR APPLIANCES and nothing else: both
    PA-5220s hold antivirus, threats and WildFire at `0`, one PA-VM holds antivirus at `0` and
    the other holds WildFire at `0`. So the entire severity axis above that token is untested by
    the estate, and these are what test it.
    """

    def test_an_uncollected_appliance_holds_the_empty_string_and_not_a_token(self):
        """The one state the choice list does not carry, and it is not `current`.

        A token here would be a verdict over a reply nobody received. The empty string is not
        `current`, the control's clause is a negated equality against `current`, so it FIRES.
        """
        built = _plt_build_streams(None, None)
        self.assertFalse(built.collected)
        self.assertEqual(built.currency_state, "")
        self.assertEqual(built.app_version if hasattr(built, "app_version") else "", "")

    def test_every_stream_fresh_is_current(self):
        built = _plt_build_streams(_plt_system(
            **{"app-release-date": "2026/10/29 01:27:15 GMT",
               "threat-release-date": "2026/10/29 01:27:15 GMT",
               "av-release-date": "2026/10/29 01:00:30 GMT",
               "wildfire-version": "1130785-1135443"}), None)
        self.assertEqual(built.currency_state, "current")

    def test_a_week_old_applications_stream_is_outside_preferred_and_inside_minimum(self):
        built = _plt_build_streams(_plt_system(
            **{"app-release-date": "2026/10/20 01:27:15 GMT",
               "threat-release-date": "2026/10/20 01:27:15 GMT"}), None)
        self.assertEqual(built.currency_state, "inside_minimum_outside_preferred")

    def test_a_three_week_old_threat_stream_is_behind(self):
        """Rank 1: that stream carries the vulnerability and spyware signatures."""
        built = _plt_build_streams(_plt_system(
            **{"threat-release-date": "2026/10/05 01:27:15 GMT"}), None)
        self.assertEqual(built.currency_state, "applications_and_threats_behind")

    def test_a_fortnight_old_antivirus_stream_is_a_behind_malware_stream(self):
        """Rank 2, and it must not be reported as rank 1: the streams are graded separately."""
        built = _plt_build_streams(_plt_system(
            **{"av-release-date": "2026/10/14 01:00:30 GMT"}), None)
        self.assertEqual(built.currency_state, "malware_stream_behind")

    def test_an_installed_stream_with_no_date_is_not_reported_as_behind(self):
        """BOTH PA-5220s ARE IN THIS STATE FOR A REASON THAT IS NOT THEIR CONTENT.

        A real `app-version` with no `app-release-date` key at all: the stream is installed and
        the date is simply not reported, so the arithmetic cannot be performed. It gets its own
        token rather than collapsing into `behind`, which would blame the appliance for the
        reply's shape.
        """
        built = _plt_build_streams(_plt_system(**{"app-release-date": None}), None)
        self.assertEqual(built.currency_state, "release_date_not_reported")
        self.assertEqual(built.release_dates["app"], "")
        self.assertFalse(built.release_date_reported)

    def test_the_never_installed_sentinel_outranks_every_staleness_state(self):
        """`0` is TRUTHY and is not a low version number. Both literals are the same state."""
        self.assertEqual(
            _plt_build_streams(_plt_system(**{"av-version": "0", "av-release-date": None}),
                               None).currency_state,
            "stream_never_installed")
        self.assertEqual(
            _plt_build_streams(_plt_system(**{"wildfire-version": "0"}), None).currency_state,
            "stream_never_installed")

    def test_release_date_reported_consults_the_version_beside_each_date(self):
        """An UNINSTALLED stream with no date is not a missing date.

        The comparison between two columns that no predicate can make, and the reason this is a
        stored column rather than a clause.
        """
        built = _plt_build_streams(
            _plt_system(**{"av-version": "0", "av-release-date": None}), None)
        self.assertTrue(built.release_date_reported)

    def test_the_verdict_cannot_be_a_token_where_nothing_was_collected(self):
        """The model's own `clean()` refuses the pair, so a stale verdict cannot be persisted."""
        row = _PltStreams(content_streams_collected=False,
                          content_currency_state="current")
        with self.assertRaises(ValidationError):
            row.clean()


# PlatformLifecycleTelemetryTests WAS HERE AND WENT WITH THE MODEL, ruling P374a 2026-10-29. Its
# five shapes were not thrown away: every one of them is asserted against the surviving model, end
# to end through the normalizer rather than against a builder, in
# `DeviceServicesTelemetryUsesTheConfigurationThatWasCollected` below.


class PlatformLifecycleAlarmTests(SimpleTestCase):
    """The alarm mechanism, where the unknown is the normal state rather than the edge case."""

    def test_a_read_that_never_happened_blanks_the_verdict(self):
        values, _prov = _plt_build_alarm(False, None)
        self.assertEqual(values["alarm_mechanism_state"], "")
        self.assertFalse(values["alarm_generation_enabled_known"])
        self.assertFalse(values["alarm_settings_node_present"])

    def test_an_absent_node_is_node_absent_and_still_not_known(self):
        """THE BUG THE READBACK CAUGHT. The committed read answering `No such node` is a reading
        about the device - so the verdict is `node_absent` - and it carries NO master switch, so
        the companion must say unknown. The first version stored True here beside a NULL switch,
        which is the column that answers "is this unknown" claiming the unknown was known."""
        values, _prov = _plt_build_alarm(True, None)
        self.assertEqual(values["alarm_mechanism_state"], "node_absent")
        self.assertIsNone(values["alarm_generation_enabled"])
        self.assertFalse(values["alarm_generation_enabled_known"])

    def test_an_emptied_container_is_present_and_is_not_an_absent_node(self):
        """Deleting the leaves and leaving the container reads as PRESENT, which stage 6's own
        teardown note depends on - it is a different verdict from the node being absent."""
        values, _prov = _plt_build_alarm(True, {})
        self.assertTrue(values["alarm_settings_node_present"])
        self.assertEqual(values["alarm_mechanism_state"], "generation_off")
        self.assertFalse(values["alarm_generation_enabled_known"])

    def test_generation_off_with_everything_else_set(self):
        values, _prov = _plt_build_alarm(True, {
            "enable-alarm-generation": "no",
            "log-databases-alarm-threshold": {"system": "85"},
            "enable-cli-alarm-notification": "yes"})
        self.assertEqual(values["alarm_mechanism_state"], "generation_off")
        self.assertTrue(values["alarm_generation_enabled_known"])

    def test_on_without_thresholds(self):
        values, _prov = _plt_build_alarm(True, {"enable-alarm-generation": "yes"})
        self.assertEqual(values["alarm_mechanism_state"], "on_without_thresholds")
        self.assertEqual(values["log_db_alarm_threshold_count"], 0)
        self.assertIsNone(values["log_db_alarm_threshold_lowest"])

    def test_on_with_thresholds_and_no_route(self):
        values, _prov = _plt_build_alarm(True, {
            "enable-alarm-generation": "yes",
            "log-databases-alarm-threshold": {"system": "85", "config": "80", "alarm": "0"},
            "enable-cli-alarm-notification": "no",
            "enable-web-alarm-notification": "no"})
        self.assertEqual(values["alarm_mechanism_state"], "on_with_thresholds_no_route")
        self.assertFalse(values["alarm_notification_route_present"])
        # THE SENTINEL IS KEPT AND NOT DROPPED. Zero is inside the grammar's range and the
        # device accepts it, and whether it means "alarm always" or "alarm never" is unmeasured -
        # so a query ranking "lower is stricter" may be exactly inverted at this one value.
        self.assertEqual(values["log_db_alarm_threshold_lowest"], 0)
        self.assertEqual(values["log_db_alarm_threshold_count"], 3)

    def test_on_with_thresholds_and_a_route_is_the_only_acceptable_state(self):
        values, _prov = _plt_build_alarm(True, {
            "enable-alarm-generation": "yes",
            "log-databases-alarm-threshold": {"system": "85"},
            "enable-cli-alarm-notification": "yes",
            "enable-web-alarm-notification": "no"})
        self.assertEqual(values["alarm_mechanism_state"], "on_with_thresholds_and_route")
        self.assertTrue(values["alarm_notification_route_present"])

    def test_either_route_alone_is_a_route(self):
        """A DISJUNCTION OVER TWO NULLABLE BOOLEANS, which is not expressible as a clause list."""
        for cli, web in (("yes", "no"), ("no", "yes")):
            values, _prov = _plt_build_alarm(True, {
                "enable-alarm-generation": "yes",
                "log-databases-alarm-threshold": {"system": "85"},
                "enable-cli-alarm-notification": cli,
                "enable-web-alarm-notification": web})
            self.assertTrue(values["alarm_notification_route_present"], (cli, web))

    def test_an_absent_leaf_declares_not_configured_rather_than_guessing(self):
        """On this subject a provenance row can only ever say "normalization declined to guess",
        and saying it is the point: a MISSING row would say "nothing tracks this field"."""
        _values, provenance = _plt_build_alarm(True, None)
        self.assertEqual({name for name, _rk, _rv in provenance},
                         {"alarm_generation_enabled", "cli_alarm_notification_enabled",
                          "web_alarm_notification_enabled", "log_db_alarm_thresholds"})
        for _name, raw_key, _raw_value in provenance:
            self.assertEqual(_plt_classify_prov(raw_key), "not_configured")

    def test_the_count_must_agree_with_the_map(self):
        row = _PltAlarm(log_db_alarm_thresholds={"system": 85}, log_db_alarm_threshold_count=3)
        with self.assertRaises(ValidationError):
            row.clean()

    def test_a_null_switch_takes_the_off_branch_and_the_companion_is_the_separator(self):
        """The one place this classification cannot keep "off" and "unknown" apart, stated rather
        than hidden: the node is present, the switch is not in it, and the token says
        `generation_off`. The direction is the firing one either way."""
        self.assertEqual(
            _plt_alarm_state(answered=True, node_present=True, generation=None,
                             threshold_count=3, route_present=True),
            "generation_off")


class PlatformLifecyclePortalPresenceTests(SimpleTestCase):
    """The four container shapes, and the vsys sweep a vsys1-only read gets wrong."""

    def test_the_container_shapes(self):
        self.assertEqual(_plt_portal_state({}), ("container_absent", 0))
        self.assertEqual(
            _plt_portal_state({"global-protect": {"global-protect-portal": None}}),
            ("container_empty", 0))
        self.assertEqual(
            _plt_portal_state({"global-protect": {"global-protect-portal": {
                "entry": {"@name": "p1"}}}}),
            ("entries_present", 1))

    def test_a_staged_container_is_not_an_empty_one(self):
        """MEASURED BY STAGE 4 AS A REAL SHAPE: `{"@admin": "admin", "@dirtyId": "50"}` with no
        non-attribute content at all. `entry_container` classes it empty, correctly for its own
        purpose; an appliance reported as a portal on the strength of it would have an advisory
        triaged onto a firewall with no portal configured."""
        self.assertEqual(
            _plt_portal_state({"global-protect": {"global-protect-portal": {
                "@admin": "admin", "@dirtyId": "50"}}}),
            ("container_staged_uncommitted", 0))

    def test_a_portal_in_a_later_vsys_makes_the_appliance_a_portal(self):
        """A VSYS1-ONLY READ ANSWERS "NOT A PORTAL" ON AN APPLIANCE THAT IS ONE, which is the
        state of both PA-5220s in this lab. The verdict spans every vsys, so the strongest shape
        found anywhere is what it reports."""
        device = {
            "@name": "localhost.localdomain",
            "vsys": {"entry": [
                {"@name": "vsys1"},
                {"@name": "vsys3", "global-protect": {"global-protect-portal": {
                    "entry": [{"@name": "a"}, {"@name": "b"}]}}},
            ]},
        }
        snapshot = SimpleNamespace(payload={"config": {"devices": {"entry": [device]}}})
        built = _plt_build_portal(snapshot)
        self.assertEqual(built["portal_entry_count"], 2)
        self.assertEqual(built["portal_container_state"], "entries_present")
        self.assertEqual(built["portal_vsys_coverage"], "every_vsys_read")
        self.assertEqual((built["vsys_read_count"], built["vsys_total_count"]), (2, 2))

    def test_an_appliance_with_no_vsys_node_is_not_collected_rather_than_portal_free(self):
        """`container_absent` would claim the appliance has no portal, which nobody established."""
        device = {"@name": "localhost.localdomain"}
        snapshot = SimpleNamespace(payload={"config": {"devices": {"entry": [device]}}})
        built = _plt_build_portal(snapshot)
        self.assertEqual(built["portal_container_state"], "not_collected")
        self.assertEqual(built["portal_vsys_coverage"], "no_vsys_read")

    def test_a_vsys_entry_without_a_name_is_counted_as_unread(self):
        """The coverage column's only discriminator on this read path, and it has to have one:
        a vsys the walk cannot key is a vsys nothing looked in."""
        device = {"@name": "localhost.localdomain",
                  "vsys": {"entry": [{"@name": "vsys1"}, {"no-name": True}]}}
        snapshot = SimpleNamespace(payload={"config": {"devices": {"entry": [device]}}})
        built = _plt_build_portal(snapshot)
        self.assertEqual(built["portal_vsys_coverage"], "some_vsys_unread")
        self.assertEqual((built["vsys_read_count"], built["vsys_total_count"]), (1, 2))


class PlatformLifecycleLicenceTests(SimpleTestCase):
    """The licence table's three shapes, and the verdicts over them."""

    @staticmethod
    def _snapshot(payload):
        return SimpleNamespace(payload=payload, collected_at=_PltDateTime(2026, 10, 29, 9, 48))

    @staticmethod
    def _row(**overrides):
        row = {"feature": "Threat Prevention", "description": "Antivirus and anti-spyware",
               "expires": "Never", "expired": "no", "base-license-name": "PA-VM",
               "authcode": None}
        row.update(overrides)
        return {k: v for k, v in row.items() if v is not None or k == "authcode"}

    def test_a_read_that_never_happened_is_not_collected(self):
        built = _plt_build_licences(None)
        self.assertEqual(built.inventory_read, "not_collected")
        self.assertEqual(built.entitlement_state, "inventory_not_collected")
        self.assertEqual(built.support_state, "inventory_not_collected")

    def test_a_null_licenses_element_is_unknown_and_not_nothing_licensed(self):
        """MEASURED ON BOTH PA-5220s. The outer dict is TRUTHY and the inner value is None, so
        `if result:` reports licences present and `result["licenses"]["entry"]` raises. The token
        is named for the SHAPE because nothing in the payload separates "none installed" from
        "nothing returned"."""
        built = _plt_build_licences(self._snapshot({"licenses": None}))
        self.assertEqual(built.inventory_read, "null_licenses_element")
        self.assertEqual(built.entitlement_state, "no_licence_rows_returned")
        self.assertEqual(built.row_count, 0)

    def test_a_single_row_arrives_as_a_dict_and_is_not_lost(self):
        """A normalizer written without the project's own list-coercion loses every row but one
        on an appliance holding a single licence."""
        built = _plt_build_licences(self._snapshot({"licenses": {"entry": self._row()}}))
        self.assertEqual(built.inventory_read, "rows_returned")
        self.assertEqual(built.row_count, 1)
        self.assertEqual(built.features_held, ["Threat Prevention"])

    def test_never_is_a_sentinel_and_not_a_date(self):
        built = _plt_build_licences(self._snapshot({"licenses": {"entry": [self._row()]}}))
        self.assertEqual(built.rows[0]["values"]["expires"], "Never")
        self.assertEqual(built.entitlement_state, "active_beyond_90_days")
        self.assertEqual(built.expiring_count, 0)

    def test_the_expired_flag_is_un_inverted(self):
        """STAGE 4 MEASURED THIS KEY'S POLARITY AS NEGATED - the only one in the domain - and
        warned that storing it without knowing stores the opposite of "licensed". Getting it
        wrong is a wrong finding in both directions at once and in silence."""
        built = _plt_build_licences(self._snapshot({"licenses": {"entry": [
            self._row(expired="yes", expires="September 20, 2026")]}}))
        self.assertIs(built.rows[0]["values"]["expired"], True)
        self.assertEqual(built.expired_count, 1)
        self.assertEqual(built.entitlement_state, "expired_entitlement_present")

    def test_an_expiry_inside_thirty_days_is_counted_and_graded(self):
        built = _plt_build_licences(self._snapshot({"licenses": {"entry": [
            self._row(expires="November 10, 2026")]}}))
        self.assertEqual(built.expiring_count, 1)
        self.assertEqual(built.entitlement_state, "expiring_within_30_days")

    def test_an_expiry_inside_ninety_days_is_the_low_band(self):
        built = _plt_build_licences(self._snapshot({"licenses": {"entry": [
            self._row(expires="December 20, 2026")]}}))
        self.assertEqual(built.expiring_count, 0)
        self.assertEqual(built.entitlement_state, "active_inside_90_days")

    def test_an_unreadable_expiry_never_reaches_the_passing_token(self):
        """Stage 5's vocabulary has no token for an expiry no parser reads, and this is where
        that gap lands: on the lowest FINDING band, never on `active_beyond_90_days`."""
        built = _plt_build_licences(self._snapshot({"licenses": {"entry": [
            self._row(expires="whenever")]}}))
        self.assertEqual(built.entitlement_state, "active_inside_90_days")

    def test_an_absent_base_licence_name_asserts_the_row_is_the_base_licence(self):
        """THE ONE IMPLICIT IN THIS DOMAIN WHERE THE ABSENCE IS THE DISCRIMINATOR. The empty
        string is stored and the provenance row is what separates it from nobody looking."""
        built = _plt_build_licences(self._snapshot({"licenses": {"entry": [
            self._row(feature="PA-VM", description="Standard VM-300",
                      **{"base-license-name": None})]}}))
        self.assertEqual(built.rows[0]["values"]["base_license_name"], "")
        provenance = dict((name, _plt_classify_prov(rk))
                          for name, rk, _rv in built.rows[0]["provenance"])
        self.assertEqual(provenance["base_license_name"], "pan_os_default")
        self.assertEqual(provenance["expires"], "local")

    def test_no_support_row_is_a_finding_and_not_a_pass(self):
        """NO APPLIANCE IN THIS ESTATE CARRIES ONE, so this is the value every row holds today -
        and an absent row is the same shape as a subscription nobody bought."""
        built = _plt_build_licences(self._snapshot({"licenses": {"entry": [self._row()]}}))
        self.assertEqual(built.support_state, "absent_from_inventory")

    def test_a_support_row_is_recognised_and_graded(self):
        """The state the lab cannot produce. A word-boundary match on `support`, which is the
        test stage 6's independent second reading made."""
        for expires, expected in (("Never", "active_beyond_90_days"),
                                  ("November 10, 2026", "expires_within_90_days")):
            built = _plt_build_licences(self._snapshot({"licenses": {"entry": [
                self._row(feature="Premium Support", expires=expires)]}}))
            self.assertEqual(built.support_state, expected, expires)

    def test_an_expired_support_row_is_expired(self):
        built = _plt_build_licences(self._snapshot({"licenses": {"entry": [
            self._row(feature="Standard Support", expired="yes",
                      expires="September 20, 2026")]}}))
        self.assertEqual(built.support_state, "expired")

    def test_a_feature_merely_containing_the_letters_is_not_a_support_row(self):
        """A word boundary and not a substring: `supported` is not `support`."""
        built = _plt_build_licences(self._snapshot({"licenses": {"entry": [
            self._row(feature="Supported Platforms Pack")]}}))
        self.assertEqual(built.support_state, "absent_from_inventory")

    def test_the_feature_list_cannot_name_more_than_the_count_counts(self):
        row = _PltInventory(entitlement_features_held=["a", "b"], licence_row_count=1)
        with self.assertRaises(ValidationError):
            row.clean()


class PlatformLifecycleDataplaneTests(SimpleTestCase):
    """The dataplane load, where a wall of zeroes is not an absence."""

    @staticmethod
    def _payload(name="s1dp0", values=("0,0,0,1", "0,0,0,0")):
        return {"resource-monitor": {"data-processors": {name: {"minute": {
            "task": None,
            "cpu-load-average": {"entry": [
                {"coreid": str(i), "value": v} for i, v in enumerate(values)]}}}}}}

    def test_a_read_that_never_happened_is_not_collected(self):
        values = _plt_build_dataplane(None)
        self.assertFalse(values["resource_monitor_collected"])
        self.assertIsNone(values["dataplane_cpu_load_max_percent"])
        self.assertEqual(values["dataplane_count"], 0)
        self.assertEqual(values["collected_window"], "")

    def test_the_comma_separated_value_is_split_and_not_parsed_as_a_number(self):
        values = _plt_build_dataplane(self._payload())
        self.assertEqual(values["dataplane_cpu_load_samples"]["s1dp0"]["0"], [0, 0, 0, 1])
        self.assertEqual(values["dataplane_cpu_load_max_percent"], 1)
        self.assertTrue(values["resource_monitor_collected"])

    def test_the_processor_name_is_platform_shaped_and_kept_verbatim(self):
        """`dp0` on a PA-VM and `s1dp0` on a PA-5220. A reader hard-coding either returns
        nothing on half the estate."""
        for name in ("dp0", "s1dp0"):
            values = _plt_build_dataplane(self._payload(name=name))
            self.assertEqual(values["dataplane_count"], 1)
            self.assertIn(name, values["dataplane_cpu_load_samples"])

    def test_a_wall_of_zeroes_is_collected_and_its_maximum_is_zero(self):
        """MEASURED ON ALL FOUR LAB APPLIANCES - populated, truthy and all zero. The companion is
        the only thing that separates it from a read that never ran."""
        values = _plt_build_dataplane(self._payload(values=("0,0,0,0",)))
        self.assertTrue(values["resource_monitor_collected"])
        self.assertEqual(values["dataplane_cpu_load_max_percent"], 0)

    def test_a_reply_with_processors_and_no_series_is_not_collected(self):
        """A true flag beside a null maximum would read as an idle appliance."""
        payload = {"resource-monitor": {"data-processors": {"dp0": {"minute": {"task": None}}}}}
        values = _plt_build_dataplane(payload)
        self.assertEqual(values["dataplane_count"], 1)
        self.assertFalse(values["resource_monitor_collected"])
        self.assertIsNone(values["dataplane_cpu_load_max_percent"])


class PlatformLifecycleBackupEvidenceTests(SimpleTestCase):
    """The trap column, and the guard that stops it being read as evidence."""

    def test_a_count_with_no_enumeration_behind_it_is_refused(self):
        """A positive comparison on the count would read "this appliance has snapshots, therefore
        it is backed up", which INVERTS the control. Nothing can enumerate the snapshot names, so
        a non-zero count beside a false flag cannot be allowed to look like a measurement."""
        row = _PltBackup(on_box_snapshot_list_collected=False,
                         on_box_saved_configuration_count=4)
        with self.assertRaises(ValidationError):
            row.clean()

    def test_zero_and_uncollected_is_the_honest_state(self):
        row = _PltBackup(on_box_snapshot_list_collected=False,
                         on_box_saved_configuration_count=0)
        row.clean()


class PlatformLifecycleCollectorTests(SimpleTestCase):
    """The committed-local reads, where an absence is the answer and not a failed read."""

    class _Session:
        target = "SERIAL-PLT-001"

        def __init__(self, error=None, result=None):
            self.error = error
            self.result = result
            self.calls = []

        def request_xml_api(self, params, *, target=None):
            self.calls.append((dict(params), target))
            if self.error is not None:
                raise self.error
            return {"response": {"@status": "success", "result": self.result}}

    def test_no_such_node_is_recorded_as_an_empty_result(self):
        """The refusal IS the reading. An empty result is the same shape the helper already
        produces for an xpath that matches nothing, so the normalizer has one thing to read."""
        session = self._Session(error=_PltAPIError("No such node"))
        collected = _plt_collect_alarm(session)
        self.assertEqual(collected.source_type, "config_log_alarm_settings")
        self.assertEqual(collected.response["response"]["result"], {})
        params, target = session.calls[0]
        self.assertEqual(params["action"], "show")
        self.assertEqual(params["xpath"], _PLT_ALARM_XPATH)
        self.assertEqual(target, "SERIAL-PLT-001")

    def test_any_other_refusal_propagates_so_no_snapshot_is_written(self):
        """An unreachable appliance must not read as a configured-nothing one: no snapshot at
        all is the third state, and it is what the companion columns report."""
        session = self._Session(error=_PltAPIError("Invalid credential"))
        with self.assertRaises(_PltAPIError):
            _plt_collect_telemetry(session)

    def test_a_present_node_comes_back_as_the_node(self):
        session = self._Session(result={"device-telemetry": {"product-usage": "yes"}})
        collected = _plt_collect_telemetry(session)
        self.assertEqual(collected.response["response"]["result"],
                         {"device-telemetry": {"product-usage": "yes"}})
        self.assertEqual(session.calls[0][0]["xpath"], _PLT_TELEMETRY_XPATH)

    def test_the_resource_monitor_command_names_one_window_and_not_the_bare_form(self):
        """The bare form returns all five windows at once - 43,184 bytes against 13,587 for the
        largest single one - and a column derived from "every window" has no defined meaning."""
        self.assertIn("<minute><last>60</last></minute>", _PLT_RM_COMMAND)
        self.assertNotIn("<resource-monitor/>", _PLT_RM_COMMAND)

    def test_the_collectors_and_normalizers_are_wired_into_the_flow(self):
        """Nothing fails if a collector is written and never called: the snapshot never exists
        and every column resting on it holds its default for ever. The only thing that catches
        that is a reader of the flow, which is what this is."""
        import inspect

        from optivedge_integrations.integrations.platforms.pan_os import flows

        source = inspect.getsource(flows.collect_appliance_platform_lifecycle)
        for name in ("collect_log_alarm_settings", "collect_show_running_resource_monitor"):
            self.assertIn(name, source, name)
        # NOT CALLED FROM ANYWHERE NOW. It moved to the device-services collection under ruling
        # P374a and was removed from the collection altogether under USE THE CONFIGURATION THAT
        # WAS COLLECTED. The collector is still DEFINED in this domain's collectors module, which
        # the ruling permits - it governs what a CONTROL rests on, not OptivEdgeIntegrations'
        # collection surface at large.
        self.assertNotIn(
            "collect_device_telemetry,", source)
        for label, function in (
            ("platform content streams", flows.normalize_appliance_platform_content_streams),
            ("GlobalProtect portal presence",
             flows.normalize_appliance_globalprotect_portal_presence),
            ("licence inventory", flows.normalize_appliance_licence_inventory),
            ("log alarm settings", flows.normalize_appliance_log_alarm_settings),
            ("configuration backup evidence",
             flows.normalize_appliance_configuration_backup_evidence),
            ("dataplane utilisation", flows.normalize_appliance_dataplane_utilisation),
        ):
            self.assertIn((label, function), flows.APPLIANCE_OBJECT_NORMALIZERS, label)


class PlatformLifecycleDerivedFieldTests(SimpleTestCase):
    """Every declared derived column is a real field, and the measured ones are NOT declared.

    `DerivedFieldDeclarationTests` already asserts the first half across the whole app. This
    asserts the half that is specific to this domain: `LicenceEntitlement`'s five measured
    columns and `LogAlarmSettings`' five are deliberately OUT of `DERIVED_FIELDS` so that
    normalization writes them real provenance rows - which on the alarm node is the only place
    "normalization declined to guess" is ever recorded.
    """

    def test_the_measured_columns_are_not_declared_derived(self):
        for model, columns in (
            (_PltEntitlement, ("expires", "expired", "base_license_name", "description")),
            (_PltAlarm, ("alarm_generation_enabled", "cli_alarm_notification_enabled",
                         "web_alarm_notification_enabled", "log_db_alarm_thresholds")),
        ):
            for column in columns:
                self.assertNotIn(column, model.DERIVED_FIELDS, f"{model.__name__}.{column}")

    def test_every_verdict_column_is_declared_derived(self):
        for model, columns in (
            (_PltStreams, ("content_currency_state", "content_streams_collected",
                           "release_date_reported")),
            (_PltPortal, ("portal_entry_count", "portal_container_state",
                          "portal_vsys_coverage")),
            (_PltInventory, ("entitlement_state", "support_entitlement_state",
                             "licence_inventory_read")),
            (_PltAlarm, ("alarm_mechanism_state", "alarm_generation_enabled_known",
                         "alarm_settings_node_present")),
            (_PltBackup, ("on_box_snapshot_list_collected",)),
            (_PltDataplane, ("resource_monitor_collected",)),
        ):
            for column in columns:
                self.assertIn(column, model.DERIVED_FIELDS, f"{model.__name__}.{column}")

    def test_the_appliance_certificate_column_is_blank_and_not_nullable(self):
        """Blank means nobody looked; the word `None` means the appliance looked and has no
        certificate. A NULL would stop a negated equality matching at all, so the reading that
        must FIRE would silently pass."""
        field = Appliance._meta.get_field("device_certificate_status")
        self.assertFalse(field.null)
        self.assertTrue(field.blank)


# ---------------------------------------------------------------------------------------------
# user-id - PAN-UID-002 to PAN-UID-006
#
# EVERY PAYLOAD BELOW IS A LAB SHAPE, read off serial 013201001475 and the two PA-VMs on
# 2026-10-29 through Panorama's `target=` proxy with `type=config&action=get` at each subject's
# own xpath, and cross-checked against the same appliances' `show config merged`. Nothing here is
# a shape invented to make a column pass. The cases the LAB DOES NOT HOLD are in
# `UserIdBranchesTheLabCannotShowTests`, named as such, because a branch proved only against a
# hand-built payload is proved against this module's own understanding of the device.
from optivedge_integrations.integrations.models import (  # noqa: E402
    UserIdCollectorSettings as _UidSettings,
    UserIdDiscoveryBound as _UidBound,
    UserIdMonitoredServer as _UidServer,
)
from optivedge_integrations.integrations.platforms.pan_os.normalization.common import (  # noqa: E402,E501
    Implicit as _Implicit,
)
from optivedge_integrations.integrations.platforms.pan_os.normalization.user_id import (  # noqa: E402,E501
    collector_settings_values as _uid_settings_values,
    discovery_bound_verdict as _uid_verdict,
    monitored_servers as _uid_servers,
    normalize_user_id as _uid_normalize,
    reaches_public_space as _uid_public,
)


class UserIdPureReadingTests(SimpleTestCase):
    """The three readers, against the states the lab holds and against the RFC boundary."""

    def test_an_absent_settings_node_yields_the_four_measured_implicits(self):
        """THE NORMAL CASE IN THIS ESTATE: `setting` is absent on all four lab appliances and all
        twenty vsys, so these six values ARE the content of every row the estate would store."""
        values, provenance = _uid_settings_values({"@name": "vsys8"})

        self.assertEqual(values, {
            "enable_probing": False, "enable_session": False,
            "enable_mapping_timeout": True, "ip_user_mapping_timeout": 45,
            "wmi_account": "", "syslog_service_profile": ""})
        # Each absent key still records a row - four `pan_os_default` and two `not_configured` -
        # because a MISSING row means only that nothing tracks the field.
        self.assertEqual(len(provenance), 6)
        self.assertTrue(all(isinstance(raw_key, _Implicit) for _, raw_key, _ in provenance))

    def test_a_collector_container_with_no_setting_child_is_not_a_settings_node(self):
        """pan-fw-111/vsys1 verbatim: a committed firewall-local `user-id-collector` holding two
        empty children and NO `setting`. The parent's presence says nothing."""
        values, _ = _uid_settings_values({"user-id-collector": {
            "server-monitor": None, "include-exclude-network": None}})

        self.assertEqual(values["ip_user_mapping_timeout"], 45)
        self.assertTrue(values["enable_mapping_timeout"])

    def test_the_mapping_timeout_implicit_points_the_other_way_from_its_neighbours(self):
        """The one value in this domain a reader is most likely to invert: expiry ON is good,
        where probing ON and session-reading ON are bad."""
        values, _ = _uid_settings_values({})

        self.assertTrue(values["enable_mapping_timeout"])
        self.assertFalse(values["enable_probing"])
        self.assertFalse(values["enable_session"])

    def test_a_disabled_include_entry_is_not_in_force(self):
        """fw-core-tpa-a/vsys5 verbatim. The `disabled` key is NEGATED with implicit `no`, so an
        entry carrying no key is in force - and one carrying `yes` bounds nothing while looking
        configured in the grid."""
        verdict = _uid_verdict({"user-id-collector": {"include-exclude-network": {"entry": [
            {"@name": "oep-uid6-n5", "discovery": "include",
             "network-address": "10.50.0.0/16", "disabled": "yes"}]}}})

        self.assertEqual(verdict["list_shape"], _UidBound.SHAPE_NO_ENTRIES)
        self.assertEqual(verdict["include_entry_count"], 0)
        self.assertEqual(verdict["include_networks"], [])

    def test_an_include_and_an_exclude_in_force_reads_as_include_present(self):
        """fw-core-tpa-a/vsys1 verbatim: a /16 include narrowed by a /24 exclude."""
        verdict = _uid_verdict({"user-id-collector": {"include-exclude-network": {"entry": [
            {"@name": "oep-uid6-n1", "discovery": "include",
             "network-address": "10.10.0.0/16"},
            {"@name": "oep-uid6-n2", "discovery": "exclude",
             "network-address": "10.10.5.0/24"}]}}})

        self.assertEqual(verdict["list_shape"], _UidBound.SHAPE_INCLUDE_PRESENT)
        self.assertEqual((verdict["include_entry_count"], verdict["exclude_entry_count"]), (1, 1))
        self.assertEqual(verdict["include_networks"], ["10.10.0.0/16"])

    def test_excludes_with_no_include_is_its_own_verdict(self):
        """fw-core-tpa-a/vsys2 verbatim. The vendor says twice that an exclude-only list excludes
        EVERY subnetwork and not only the ones named, so user mapping stops - a functional fault
        rather than an exposure, which is why it is not folded into `no_entries`."""
        verdict = _uid_verdict({"user-id-collector": {"include-exclude-network": {"entry": [
            {"@name": "oep-uid6-n3", "discovery": "exclude",
             "network-address": "10.20.0.0/16"}]}}})

        self.assertEqual(verdict["list_shape"], _UidBound.SHAPE_EXCLUDE_ONLY)
        self.assertEqual((verdict["include_entry_count"], verdict["exclude_entry_count"]), (0, 1))

    def test_an_include_over_public_space_outranks_merely_having_an_include(self):
        """fw-core-tpa-a/vsys4 verbatim. The precedence is what makes this one answer rather than
        four tests, and reversing it is the mutation this test exists to catch."""
        verdict = _uid_verdict({"user-id-collector": {"include-exclude-network": {"entry": [
            {"@name": "oep-uid6-n4", "discovery": "include",
             "network-address": "203.0.113.0/24"}]}}})

        self.assertEqual(verdict["list_shape"], _UidBound.SHAPE_INCLUDE_COVERS_PUBLIC)

    def test_one_public_include_beside_a_private_one_decides_the_row(self):
        verdict = _uid_verdict({"user-id-collector": {"include-exclude-network": {"entry": [
            {"@name": "a", "discovery": "include", "network-address": "10.0.0.0/8"},
            {"@name": "b", "discovery": "include", "network-address": "203.0.113.0/24"}]}}})

        self.assertEqual(verdict["list_shape"], _UidBound.SHAPE_INCLUDE_COVERS_PUBLIC)
        self.assertEqual(verdict["include_entry_count"], 2)

    def test_the_bounded_set_is_rfc_1918_and_rfc_3927_and_nothing_else(self):
        """DELIBERATELY NOT `ipaddress.is_private`, which is wider and has moved between Python
        releases - a verdict that moved with the interpreter would be a different control on a
        different machine. The cost is that 100.64/10 and the IPv6 unique-local range answer TRUE
        and over-fire, which is stage 5's literal reading and is reported rather than widened."""
        for cidr in ("10.0.0.0/8", "10.1.2.3", "172.16.0.0/12", "192.168.1.0/24",
                     "169.254.0.0/16"):
            self.assertFalse(_uid_public(cidr), cidr)
        for cidr in ("172.15.0.0/16", "172.32.0.0/16", "203.0.113.0/24", "8.8.8.8",
                     "0.0.0.0/0", "100.64.0.0/10", "fc00::/7"):
            self.assertTrue(_uid_public(cidr), cidr)

    def test_an_unreadable_or_empty_range_reaches_public_space(self):
        """The firing side. A range nobody can parse is a range nobody has established as
        bounded, and reporting the strongest verdict in the set on the strength of a parse
        failure is the error that cannot be checked in a minute."""
        self.assertTrue(_uid_public(""))
        self.assertTrue(_uid_public("rubbish"))

    def test_the_kind_is_which_child_is_present_and_not_a_value(self):
        """fw-core-tpa-a/vsys1 and /vsys4 verbatim: three syslog senders, one AD server carrying
        a host and no transport selector, one Exchange server."""
        rows = _uid_servers({"user-id-collector": {"server-monitor": {"entry": [
            {"@name": "oep-uid6-s1", "syslog": {"address": "192.0.2.11",
                                                "connection-type": "udp"}},
            {"@name": "oep-uid6-s2", "syslog": {"address": "192.0.2.12",
                                                "connection-type": "ssl"}},
            {"@name": "oep-uid6-s4", "active-directory": {"host": "192.0.2.21"}},
            {"@name": "oep-uid6-s5", "exchange": {"host": "192.0.2.22"}}]}}},
            tls_profile_bound=False)
        by_name = {values["name"]: values for values, _, _ in rows}

        self.assertEqual(by_name["oep-uid6-s1"]["monitored_server_kind"], "syslog")
        self.assertEqual(by_name["oep-uid6-s1"]["connection_type"], "udp")
        self.assertEqual(by_name["oep-uid6-s2"]["connection_type"], "ssl")
        self.assertEqual(by_name["oep-uid6-s4"]["monitored_server_kind"], "active-directory")
        self.assertEqual(by_name["oep-uid6-s4"]["connection_type"], "")
        self.assertEqual(by_name["oep-uid6-s5"]["monitored_server_kind"], "exchange")

    def test_the_transport_is_read_off_the_branch_and_not_off_the_entry(self):
        """The two nodes are a level apart. Reading `connection-type` off the entry answers the
        empty string for every sender in the estate - silently, and `` fires, so a reader would
        see a page of findings on senders that are correctly configured."""
        rows = _uid_servers({"user-id-collector": {"server-monitor": {"entry": [
            {"@name": "s", "connection-type": "ssl", "syslog": {"connection-type": "udp"}}]}}},
            tls_profile_bound=False)

        self.assertEqual(rows[0][0]["connection_type"], "udp")

    def test_a_disabled_monitored_server_still_gets_a_row(self):
        """oep-uid6-s3 verbatim: a udp sender carrying `disabled: yes`, so the grid's Enabled
        column reads unticked. NO COLUMN STORES THAT, because stage 5 declares none - so the row
        exists and nothing downstream can tell it from an in-force sender. Asserted rather than
        quietly fixed: adding an undeclared column here would be this stage deciding what the
        finding says."""
        rows = _uid_servers({"user-id-collector": {"server-monitor": {"entry": [
            {"@name": "oep-uid6-s3", "disabled": "yes",
             "syslog": {"connection-type": "udp"}}]}}}, tls_profile_bound=False)

        self.assertEqual(len(rows), 1)
        self.assertEqual(rows[0][0]["connection_type"], "udp")

    def test_a_nameless_entry_is_dropped_rather_than_stored_with_an_empty_subject(self):
        rows = _uid_servers({"user-id-collector": {"server-monitor": {"entry": [
            {"syslog": {"connection-type": "udp"}}]}}}, tls_profile_bound=False)

        self.assertEqual(rows, [])

    def test_a_present_but_unparseable_timeout_falls_back_and_keeps_the_keys_provenance(self):
        """The value falls back to the measured implicit and the provenance stays the KEY's: the
        device does hold something here, and it is not a default."""
        values, provenance = _uid_settings_values({"user-id-collector": {"setting": {
            "ip-user-mapping-timeout": "not-a-number"}}})
        raw_key = [k for name, k, _ in provenance if name == "ip_user_mapping_timeout"][0]

        self.assertEqual(values["ip_user_mapping_timeout"], 45)
        self.assertIsNone(raw_key)

    def test_a_template_marked_leaf_is_read_through_its_marker(self):
        """The pushed-VALUE case. Stage 4 measured no pushed content under `user-id-collector` on
        any lab appliance, so this is the one part of the provenance story the estate cannot
        show - and a reader that took `{'#text': ..., '@ptpl': ...}` for a string would store
        the dict's repr."""
        values, provenance = _uid_settings_values({"user-id-collector": {"setting": {
            "enable-probing": {"#text": "yes", "@ptpl": "a_template"}}}})
        raw_key, raw_value = [(k, v) for name, k, v in provenance
                              if name == "enable_probing"][0]

        self.assertTrue(values["enable_probing"])
        self.assertEqual((raw_key, raw_value), ("@ptpl", "a_template"))


class UserIdNormalizationTests(TestCase):
    """The rows, their provenance, and what a vsys holding nothing stores."""

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.uid")
        self.group = ApplianceGroup.objects.create(
            management_station=self.station, name="g-uid",
            group_type=ApplianceGroup.TYPE_STANDALONE)
        self.appliance = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            serial_number="S-UID", hostname="fw-uid", software_version="11.1.13-h3")
        self.point = EnforcementPoint.objects.create(
            management_station=self.station, appliance=self.appliance,
            vsys_name="vsys1", vsys_display_name="vsys1")

    def _merged(self, vsys=None):
        return Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": {"devices": {"entry": [{
                "@name": "localhost.localdomain",
                "vsys": {"entry": [dict({"@name": "vsys1"}, **(vsys or {}))]}}]}}})

    def test_a_vsys_with_no_collector_node_still_gets_both_singleton_rows(self):
        """The whole reason those two models exist. All twenty lab vsys are in this state, and
        the agent-setup panel renders values for every one of them - so a vsys with no node is
        not a vsys with no settings, it is a vsys running the vendor's."""
        self._merged()

        counts = _uid_normalize(self.point)

        self.assertEqual(counts["user_id_collector_settings"], 1)
        self.assertEqual(counts["user_id_discovery_bounds"], 1)
        self.assertEqual(counts["user_id_monitored_servers"], 0)
        settings = _UidSettings.objects.get(enforcement_point=self.point)
        self.assertEqual(settings.ip_user_mapping_timeout, 45)
        self.assertTrue(settings.enable_mapping_timeout)
        bound = _UidBound.objects.get(enforcement_point=self.point)
        self.assertEqual(bound.list_shape, _UidBound.SHAPE_NO_ENTRIES)

    def test_an_absent_key_records_a_provenance_row_saying_which_kind_of_absence(self):
        """Four `pan_os_default` and two `not_configured`. A MISSING row would say "nothing
        tracks this field" about a value PAN-OS supplied, which is the correction normalization
        made across this package on 2026-09-21."""
        self._merged()
        _uid_normalize(self.point)
        settings = _UidSettings.objects.get(enforcement_point=self.point)

        types = {name: settings.provenance_for(name).provenance_type
                 for name in ("enable_probing", "enable_session", "enable_mapping_timeout",
                              "ip_user_mapping_timeout", "wmi_account",
                              "syslog_service_profile")}

        self.assertEqual(types["enable_probing"], "pan_os_default")
        self.assertEqual(types["ip_user_mapping_timeout"], "pan_os_default")
        self.assertEqual(types["wmi_account"], "not_configured")
        self.assertEqual(types["syslog_service_profile"], "not_configured")
        self.assertEqual(
            settings.provenance_for("ip_user_mapping_timeout").raw_value, "45")

    def test_a_locally_set_key_records_local_and_not_a_default(self):
        """fw-core-tpa-a/vsys1 verbatim: `enable-probing: yes` and no other leaf."""
        self._merged({"user-id-collector": {"setting": {"enable-probing": "yes"}}})
        _uid_normalize(self.point)
        settings = _UidSettings.objects.get(enforcement_point=self.point)

        self.assertTrue(settings.enable_probing)
        self.assertEqual(settings.provenance_for("enable_probing").provenance_type, "local")
        # The sibling it did NOT move still reads as the vendor's.
        self.assertEqual(
            settings.provenance_for("enable_session").provenance_type, "pan_os_default")

    def test_the_verdict_row_carries_no_provenance_row_at_all(self):
        """Every column is in `DERIVED_FIELDS`, so `provenance_for` answers `derived` without a
        stored row - and `DerivedFieldDeclarationTests` fails if one exists."""
        self._merged()
        _uid_normalize(self.point)
        bound = _UidBound.objects.get(enforcement_point=self.point)

        self.assertEqual(bound.field_provenance.count(), 0)
        self.assertEqual(bound.provenance_for("list_shape").provenance_type, "derived")

    def test_a_monitored_server_gets_an_entry_row_and_a_transport_row(self):
        self._merged({"user-id-collector": {"server-monitor": {"entry": [
            {"@name": "s1", "syslog": {"connection-type": "udp"}},
            {"@name": "s2", "active-directory": {"host": "192.0.2.21"}}]}}})
        _uid_normalize(self.point)

        syslog = _UidServer.objects.get(enforcement_point=self.point, name="s1")
        directory = _UidServer.objects.get(enforcement_point=self.point, name="s2")

        self.assertEqual(syslog.provenance_for("__entry__").provenance_type, "local")
        self.assertEqual(syslog.provenance_for("connection_type").provenance_type, "local")
        # The other three branches carry no such leaf, so the field is NOT TRACKED on that row
        # rather than defaulted - which is the one thing a missing row still means.
        self.assertIsNone(directory.provenance_for("connection_type"))

    def test_the_tls_binding_is_resolved_from_the_collector_in_the_same_pass(self):
        """The one cross-subject resolution in this domain, two rows apart. Resolved from the
        payload this call parses rather than from the row it is about to write, so the pass
        carries no ordering obligation on its caller."""
        self._merged({"user-id-collector": {
            "setting": {"syslog-service-profile": "tls-prof"},
            "server-monitor": {"entry": [{"@name": "s1", "syslog": {
                "connection-type": "ssl"}}]}}})
        _uid_normalize(self.point)

        self.assertTrue(_UidServer.objects.get(enforcement_point=self.point)
                        .tls_service_profile_bound)

    def test_a_renormalize_replaces_rows_and_their_provenance_rather_than_adding(self):
        """A leftover row reports a host somebody has already removed - a finding against a fixed
        estate, with nothing noticing. The provenance sweep has to run FIRST and be scoped by
        object id: `FieldProvenance` is a generic relation with no cascade, so deleting the
        subject rows first orphans their provenance against a primary key the database reuses."""
        self._merged({"user-id-collector": {"server-monitor": {"entry": [
            {"@name": "gone", "syslog": {"connection-type": "udp"}}]}}})
        _uid_normalize(self.point)
        self.assertEqual(_UidServer.objects.count(), 1)

        self._merged()
        _uid_normalize(self.point)

        self.assertEqual(_UidServer.objects.count(), 0)
        self.assertEqual(_UidSettings.objects.count(), 1)
        self.assertEqual(_UidBound.objects.count(), 1)
        content_type = ContentType.objects.get_for_model(_UidServer)
        self.assertEqual(
            FieldProvenance.objects.filter(content_type=content_type).count(), 0)

    def test_a_missing_merged_snapshot_raises_rather_than_storing_a_clean_vsys(self):
        """The point-level failure the platform layering says still raises: there is nothing to
        iterate, and a silent empty result would report every vsys of an uncollected appliance as
        one whose collector settings are the vendor's."""
        with self.assertRaises(ValueError):
            _uid_normalize(self.point)


class UserIdBranchesTheLabCannotShowTests(SimpleTestCase):
    """The states no lab appliance holds, asserted against the readers instead of the device.

    NOT A DEVICE PROOF, and the distinction is the point. Stage 6 left no vsys with an SSL/TLS
    service profile bound to its syslog listener, no eDirectory monitored server, and no
    committed syslog sender with `connection-type` absent - and a stage 7 run may not build a lab
    subject stage 6 chose not to leave. So each of these proves the COMPUTATION and not the
    reading, and the stage 7 artifact names them as unproved on a device.
    """

    def test_an_edirectory_server_is_the_fourth_kind_and_nothing_in_the_lab_holds_one(self):
        rows = _uid_servers({"user-id-collector": {"server-monitor": {"entry": [
            {"@name": "edir", "e-directory": {"host": "192.0.2.90"}}]}}},
            tls_profile_bound=False)

        self.assertEqual(rows[0][0]["monitored_server_kind"], "e-directory")
        self.assertEqual(rows[0][0]["connection_type"], "")

    def test_an_entry_with_no_type_branch_stores_a_blank_kind_and_SUPPRESSES(self):
        """The one direction in this domain that cannot be arranged away: a row holding `` matches
        no kind clause, so every control on this model reports NOTHING for it. No value would be
        safer - any value would put the row into some other kind's control - so the mitigation is
        ordering. On a committed device it should be impossible: the useridd daemon refuses such
        an entry at commit phase 1 with `Error: server <name> type is unknown`."""
        rows = _uid_servers({"user-id-collector": {"server-monitor": {"entry": [
            {"@name": "orphan"}]}}}, tls_profile_bound=False)

        self.assertEqual(rows[0][0]["monitored_server_kind"], "")

    def test_two_kinds_sharing_one_name_stay_two_rows(self):
        """Why the kind is in the uniqueness constraint. Without it the survivor is whichever was
        written last, and the name is the string the grid shows and the string the daemon's error
        quotes back - so the collision is not hypothetical."""
        rows = _uid_servers({"user-id-collector": {"server-monitor": {"entry": [
            {"@name": "same", "syslog": {"connection-type": "udp"}},
            {"@name": "same", "exchange": {"host": "192.0.2.80"}}]}}},
            tls_profile_bound=False)

        self.assertEqual(sorted(r[0]["monitored_server_kind"] for r in rows),
                         ["exchange", "syslog"])

    def test_a_committed_syslog_sender_with_no_transport_key_reads_as_empty_and_fires(self):
        """Stage 4 could not establish whether this state is reachable - its own subject on this
        object was never committable - so the clause is written as `is not ssl` rather than
        `eq udp`, which makes it fire whether or not the state exists."""
        rows = _uid_servers({"user-id-collector": {"server-monitor": {"entry": [
            {"@name": "s", "syslog": {"address": "192.0.2.99"}}]}}}, tls_profile_bound=False)

        self.assertEqual(rows[0][0]["connection_type"], "")
        self.assertEqual(rows[0][0]["monitored_server_kind"], "syslog")

    def test_absent_empty_and_no_collector_are_collapsed_into_one_verdict(self):
        """THE ONE BRANCH THIS LAB CANNOT DISCRIMINATE, and it was collapsed on purpose: an empty
        list bounds nothing, exactly as no list does. A mutation replacing `entry_container` with
        a truthiness test is the one mutation the device readback did NOT catch, because the only
        lab appliance holding the empty-committed shape gives the same answer either way. The
        failure to avoid is the opposite one - a query testing node PRESENCE rather than an
        in-force include entry answers `bounded` on an appliance that is not."""
        for payload in ({"user-id-collector": {}},
                        {"user-id-collector": {"include-exclude-network": None}},
                        {}):
            self.assertEqual(_uid_verdict(payload)["list_shape"], _UidBound.SHAPE_NO_ENTRIES)

    def test_an_include_entry_with_no_range_bounds_nothing_so_it_fires(self):
        verdict = _uid_verdict({"user-id-collector": {"include-exclude-network": {"entry": [
            {"@name": "n", "discovery": "include"}]}}})

        self.assertEqual(verdict["list_shape"], _UidBound.SHAPE_INCLUDE_COVERS_PUBLIC)
        self.assertEqual(verdict["include_networks"], [""])

    def test_a_wmi_account_longer_than_the_column_is_sliced_rather_than_refused(self):
        """255 is this store's number and not the device's - no `maxLength` was measured for any
        field of this domain - so the slice is where a value longer than the proposal lands."""
        values, _ = _uid_settings_values({"user-id-collector": {"setting": {
            "wmi-account": "OEPLAB\\" + "u" * 300}}})

        self.assertEqual(len(values["wmi_account"]), 255)


class UserIdModelShapeTests(SimpleTestCase):
    """The nullability and the declarations the controls rest on."""

    def test_every_settings_column_is_non_nullable(self):
        """LOAD-BEARING rather than tidy. The clause grammar has no is-null operator: a `> 60`
        over a NULL is silent on every compiler in this consumer, and a negated equality against
        one matches neither value - so a nullable spelling of any of these would invert its
        control in silence, with nothing erroring at any layer."""
        for name in ("enable_probing", "enable_session", "enable_mapping_timeout",
                     "ip_user_mapping_timeout", "wmi_account", "syslog_service_profile"):
            self.assertFalse(_UidSettings._meta.get_field(name).null, name)

    def test_the_two_text_columns_are_blank_and_not_null(self):
        for model, name in ((_UidSettings, "wmi_account"),
                            (_UidSettings, "syslog_service_profile"),
                            (_UidServer, "connection_type"),
                            (_UidServer, "monitored_server_kind"),
                            (_UidBound, "list_shape")):
            field = model._meta.get_field(name)
            self.assertFalse(field.null, f"{model.__name__}.{name}")
            self.assertTrue(field.blank, f"{model.__name__}.{name}")

    def test_the_defaults_are_the_sides_stage_5_measured(self):
        defaults = {name: _UidSettings._meta.get_field(name).default
                    for name in ("enable_probing", "enable_session",
                                 "enable_mapping_timeout", "ip_user_mapping_timeout")}

        self.assertEqual(defaults, {
            "enable_probing": False, "enable_session": False,
            "enable_mapping_timeout": True, "ip_user_mapping_timeout": 45})

    def test_the_computed_columns_are_declared_derived_and_the_read_ones_are_not(self):
        for name in ("list_shape", "include_entry_count", "exclude_entry_count",
                     "include_networks"):
            self.assertIn(name, _UidBound.DERIVED_FIELDS, name)
        for name in ("monitored_server_kind", "tls_service_profile_bound"):
            self.assertIn(name, _UidServer.DERIVED_FIELDS, name)
        for name in ("name", "connection_type"):
            self.assertNotIn(name, _UidServer.DERIVED_FIELDS, name)
        for name in ("enable_probing", "ip_user_mapping_timeout", "wmi_account"):
            self.assertNotIn(name, _UidSettings.DERIVED_FIELDS, name)

    def test_the_listener_honesty_column_is_declared_derived_and_fires_by_default(self):
        field = ManagementInterface._meta.get_field("userid_listener_state_established")

        self.assertIn("userid_listener_state_established",
                      ManagementInterface.DERIVED_FIELDS)
        self.assertFalse(field.default)

    def test_the_timeout_range_is_the_devices_and_not_the_helps(self):
        """The Help documents 3,600 on three builds and the write gate refuses anything over
        1440 with code=12, measured. A remediation written from the Help is refused."""
        row = _UidSettings(ip_user_mapping_timeout=3600)
        with self.assertRaises(ValidationError):
            row.clean()
        row.ip_user_mapping_timeout = 1440
        row.clean()

    def test_a_verdict_that_contradicts_its_own_counts_is_refused(self):
        row = _UidBound(list_shape=_UidBound.SHAPE_INCLUDE_PRESENT,
                        include_entry_count=0, exclude_entry_count=0, include_networks=[])
        with self.assertRaises(ValidationError):
            row.clean()
        row = _UidBound(list_shape=_UidBound.SHAPE_NO_ENTRIES, include_entry_count=0,
                        exclude_entry_count=1, include_networks=[])
        with self.assertRaises(ValidationError):
            row.clean()

    def test_the_json_list_has_to_agree_with_the_count_a_control_reads(self):
        """The convention `InterfaceManagementProfile` and `Certificate` already follow: a column
        derived from a JSON field gets a `clean()` asserting the two agree."""
        row = _UidBound(list_shape=_UidBound.SHAPE_INCLUDE_PRESENT, include_entry_count=2,
                        exclude_entry_count=0, include_networks=["10.0.0.0/8"])
        with self.assertRaises(ValidationError):
            row.clean()

    def test_a_transport_on_a_non_syslog_branch_is_refused(self):
        row = _UidServer(name="s", monitored_server_kind=_UidServer.KIND_EXCHANGE,
                         connection_type="udp")
        with self.assertRaises(ValidationError):
            row.clean()


from optivedge_integrations.integrations.models import (  # noqa: E402
    SecretFingerprintKey as _SecretFingerprintKey, ServerProfile as _AaaServerProfile)
from optivedge_integrations.integrations.platforms.pan_os.normalization.server_profiles import (  # noqa: E402
    SECRET_STORED_LENGTH_FOR_ONE_BLOCK as _ONE_BLOCK,
    normalize_server_profiles as _normalize_server_profiles)


class AaaSecretAndSigningTests(TestCase):
    """PAN-AAA-005 and 009 - the two columns on `ServerProfile` that no single key answers.

    THE TWO BRANCHES THE LAB CANNOT DISCRIMINATE ARE HERE ON PURPOSE. A readback over the
    standing stage 6 subjects proves neither: every RADIUS server entry on the lab carries a
    secret, so the absent-secret branch is never taken, and a mutation that made an absent
    secret store "" moved not one row. The same mutation run against this class fails it.

    NO FIXTURE HERE IS A STORED SECRET OR A PLAINTEXT. `_form()` builds a string of the right
    LENGTH and nothing else: the length is all the band reads, and the equality-group id is a
    keyed digest of whatever it is given, so a real stored form would prove nothing a filler
    string does not.
    """

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.aaa")
        self.group = ApplianceGroup.objects.create(
            management_station=self.station, name="g-aaa",
            group_type=ApplianceGroup.TYPE_STANDALONE)

    def _appliance(self, serial):
        return Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            serial_number=serial, hostname=f"fw-{serial.lower()}")

    def _normalize(self, appliance, shared=None, profiles=None):
        config = {"shared": {"server-profile": shared or {},
                             "authentication-profile": {"entry": list(profiles or [])}},
                  "devices": {"entry": [{"@name": "localhost.localdomain"}]}}
        Snapshot.objects.create(
            management_station=self.station, appliance=appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": config})
        _normalize_server_profiles(appliance)
        return {(p.kind, p.name): p
                for p in _AaaServerProfile.objects.filter(appliance=appliance)}

    @staticmethod
    def _form(length, filler="f"):
        """A string of `length` characters standing in for a stored form. NOT a secret and not
        the device's encoding of one - `_equality_group` keys a digest over whatever it is
        handed, and the length band is the only thing that reads the characters' count."""
        return filler * length

    @staticmethod
    def _radius(name, *secrets):
        """A RADIUS profile with one server entry per secret. A `None` secret means the key is
        absent on that entry, which is the state stage 4 never read."""
        servers = []
        for index, secret in enumerate(secrets):
            entry = {"@name": f"10.0.0.{index}", "ip-address": f"10.0.0.{index}"}
            if secret is not None:
                entry["secret"] = secret
            servers.append(entry)
        return {"@name": name, "protocol": {"CHAP": None}, "server": {"entry": servers}}

    def test_one_equality_group_id_per_server_entry_and_never_the_secret(self):
        """Jason's standing ruling, and `ike.py::IkeGateway`'s shipped reading of it: the value
        is never stored. What the column holds is a keyed id per server entry - equal secrets
        give equal ids - and the LENGTH is taken before the id is computed."""
        long_form, short_form = self._form(77, "a"), self._form(57, "b")
        rows = self._normalize(self._appliance("S-K1"), shared={
            "radius": {"entry": [self._radius("two-servers", long_form, short_form),
                                 self._radius("same-twice", long_form, long_form)]}})
        row = rows[("radius", "two-servers")]
        self.assertEqual(len(row.secret_digests), 2, "one per server entry, in their own order")
        for digest in row.secret_digests:
            self.assertEqual(len(digest), _AaaServerProfile.EQUALITY_GROUP_HEX_LENGTH)
            self.assertRegex(digest, r"^[0-9a-f]+$")
        self.assertEqual(row.secret_shortest_stored_length, 57,
                         "measured on the stored form, before the id replaced it")
        twice = rows[("radius", "same-twice")].secret_digests
        self.assertEqual(twice[0], twice[1], "one secret, one group")
        self.assertNotEqual(row.secret_digests[0], row.secret_digests[1],
                            "two secrets, two groups")
        self.assertEqual(row.secret_digests[0], twice[0],
                         "the same secret on two profiles of one station shares its group")

    def test_the_stored_form_never_appears_in_the_column(self):
        """The invariant the whole change exists for. A stored form is 57 or 77 characters and an
        id is 32, so `clean()` refuses one on width alone - and nothing in the row, in any
        column, contains the string the device sent."""
        long_form, short_form = self._form(77, "c"), self._form(57, "d")
        rows = self._normalize(self._appliance("S-K1b"), shared={
            "radius": {"entry": [self._radius("kept", long_form, short_form)]}})
        row = rows[("radius", "kept")]
        row.clean()
        stored_anywhere = " ".join(
            str(getattr(row, field.name))
            for field in row._meta.fields if not field.is_relation)
        for form in (long_form, short_form):
            self.assertNotIn(form, stored_anywhere)
            self.assertNotIn(form[:33], stored_anywhere,
                             "not even the digest-and-prefix half of it")
        row.secret_digests = [long_form]
        with self.assertRaises(ValidationError):
            row.clean()

    def test_the_id_is_keyed_so_two_stations_do_not_share_a_group(self):
        """KEYED AND NOT A BARE HASH: PAN-OS's stored form is derivable from a guessed plaintext
        for its first 33 characters, so a plain digest of it is brute-forceable from a word list.
        The key is per management station, which is also what keeps the cross-appliance equality
        test alive - and what makes two estates' ids incomparable, which is correct."""
        form = self._form(77, "e")
        first = rows_a = self._normalize(self._appliance("S-K1c"), shared={
            "radius": {"entry": [self._radius("here", form)]}})[("radius", "here")]
        other_station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.other")
        other_group = ApplianceGroup.objects.create(
            management_station=other_station, name="g-other",
            group_type=ApplianceGroup.TYPE_STANDALONE)
        appliance = Appliance.objects.create(
            management_station=other_station, appliance_group=other_group,
            serial_number="S-K1d", hostname="fw-other")
        Snapshot.objects.create(
            management_station=other_station, appliance=appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": {"shared": {"server-profile": {"radius": {"entry": [
                self._radius("here", form)]}}},
                "devices": {"entry": [{"@name": "localhost.localdomain"}]}}})
        _normalize_server_profiles(appliance)
        second = _AaaServerProfile.objects.get(appliance=appliance, name="here")
        self.assertNotEqual(first.secret_digests, second.secret_digests)
        self.assertEqual(_SecretFingerprintKey.objects.count(), 2, "one key per station")
        self.assertNotEqual(_SecretFingerprintKey.objects.first().key_hex,
                            _SecretFingerprintKey.objects.last().key_hex)
        self.assertEqual(len(_SecretFingerprintKey.objects.first().key_hex),
                         2 * _SecretFingerprintKey.KEY_BYTES)
        assert rows_a is first

    def test_a_server_entry_with_no_secret_contributes_nothing(self):
        """THE ABSENT-KEY BEHAVIOUR, which stage 5 declared `not_stored` because stage 4 never
        read an absent `secret` - the key was written on both of its subjects.

        A "" in the list would make the shortest stored length 0, which is the firing side of a
        reading nobody took. The lab cannot show this: every RADIUS server entry standing on it
        has a secret."""
        rows = self._normalize(self._appliance("S-K2"), shared={
            "radius": {"entry": [self._radius("one-bare", self._form(77), None),
                                 self._radius("all-bare", None)]}})
        self.assertEqual(len(rows[("radius", "one-bare")].secret_digests), 1,
                         "one server entry had a secret; the other contributes nothing")
        self.assertEqual(rows[("radius", "one-bare")].secret_shortest_stored_length, 77)
        self.assertEqual(rows[("radius", "all-bare")].secret_digests, [])
        self.assertEqual(rows[("radius", "all-bare")].secret_shortest_stored_length, 0)
        self.assertEqual(rows[("radius", "all-bare")].secret_weakness, "")

    def test_only_a_radius_profile_records_a_secret(self):
        """A TACACS+ server entry stores a secret too, in the byte-identical form - measured by
        stage 4 and read back off three committed profiles on 2026-10-29. PAN-AAA-005 is a
        RADIUS assertion and stage 5 declares these columns on the radius subject alone, so a
        tacplus row carries no digest and no verdict rather than a digest with no verdict."""
        rows = self._normalize(self._appliance("S-K3"), shared={
            "tacplus": {"entry": [{"@name": "tac", "protocol": "CHAP", "server": {"entry": [
                {"@name": "10.0.0.1", "address": "10.0.0.1",
                 "secret": self._form(77)}]}}]}})
        row = rows[("tacplus", "tac")]
        self.assertEqual(row.secret_digests, [])
        self.assertEqual(row.secret_shortest_stored_length, 0)
        self.assertEqual(row.secret_weakness, "")

    def test_the_length_band_sits_at_one_cipher_block(self):
        """57 characters is one block and means a plaintext of fifteen or fewer; 77 is two.
        Measured at the boundary on pan-fw-111: stage 6 wrote 15 and 16 characters and this run
        read 57 and 77 back."""
        rows = self._normalize(self._appliance("S-K4"), shared={
            "radius": {"entry": [self._radius("short", self._form(_ONE_BLOCK)),
                                 self._radius("long", self._form(_ONE_BLOCK + 20))]}})
        self.assertEqual(rows[("radius", "short")].secret_weakness,
                         _AaaServerProfile.SecretWeakness.BELOW_SIXTEEN_CHARACTERS)
        self.assertEqual(rows[("radius", "long")].secret_weakness,
                         _AaaServerProfile.SecretWeakness.MEETS_FLOOR)

    def test_reuse_is_counted_across_appliances_and_not_within_one(self):
        """Stage 3's assertion as stage 5 carried it: the stored form is byte-identical to one
        on ANOTHER appliance. Two profiles on one appliance sharing a secret are not that - and
        on the lab that is the common state, seven profiles of pan-fw-111 sharing one form."""
        shared_form = self._form(77, "s")
        first = self._appliance("S-K5a")
        second = self._appliance("S-K5b")
        self._normalize(first, shared={"radius": {"entry": [
            self._radius("twin-a", shared_form), self._radius("twin-b", shared_form),
            self._radius("alone", self._form(77, "u"))]}})
        rows = self._normalize(second, shared={"radius": {"entry": [
            self._radius("other-appliance", shared_form)]}})
        self.assertEqual(rows[("radius", "other-appliance")].secret_weakness,
                         _AaaServerProfile.SecretWeakness.REUSED_ACROSS_APPLIANCES)
        on_first = {(p.kind, p.name): p
                    for p in _AaaServerProfile.objects.filter(appliance=first)}
        self.assertEqual(on_first[("radius", "twin-a")].secret_weakness,
                         _AaaServerProfile.SecretWeakness.REUSED_ACROSS_APPLIANCES)
        self.assertEqual(on_first[("radius", "alone")].secret_weakness,
                         _AaaServerProfile.SecretWeakness.MEETS_FLOOR,
                         "a secret nobody else holds is not reuse")

    def test_the_station_verdict_does_not_depend_on_which_appliance_ran_first(self):
        """The first appliance normalized cannot see the second's digests, so the verdict is
        re-derived for the whole station at the end of every pass. Without that the answer would
        depend on collection order, which is the asymmetry this shape exists to avoid."""
        shared_form = self._form(77, "o")
        first = self._appliance("S-K6a")
        second = self._appliance("S-K6b")
        self._normalize(first, shared={
            "radius": {"entry": [self._radius("early", shared_form)]}})
        self.assertEqual(
            _AaaServerProfile.objects.get(appliance=first, name="early").secret_weakness,
            _AaaServerProfile.SecretWeakness.MEETS_FLOOR,
            "nothing else held it yet")
        self._normalize(second, shared={
            "radius": {"entry": [self._radius("late", shared_form)]}})
        self.assertEqual(
            _AaaServerProfile.objects.get(appliance=first, name="early").secret_weakness,
            _AaaServerProfile.SecretWeakness.REUSED_ACROSS_APPLIANCES,
            "the appliance that ran first has to be revisited")

    def _saml(self, name, **keys):
        entry = {"@name": name, "certificate": "cert", "entity-id": f"urn:{name}",
                 "sso-url": "https://10.0.0.9/sso", "sso-bindings": "post"}
        entry.update(keys)
        return entry

    @staticmethod
    def _saml_user(name, target, certificate=None):
        branch = {"server-profile": target}
        if certificate is not None:
            branch["request-signing-certificate"] = certificate
        return {"@name": name, "method": {"saml-idp": branch},
                "allow-list": {"member": ["all"]}}

    def test_message_signing_needs_the_flag_and_a_certificate_to_sign_with(self):
        """Help p.939: the firewall signs using the Certificate for Signing Requests specified
        in an AUTHENTICATION PROFILE. So the flag on with nothing named is a request to sign
        with nothing, and a query on the flag alone reports it as compliant."""
        rows = self._normalize(
            self._appliance("S-K7"),
            shared={"saml-idp": {"entry": [
                self._saml("signed"),
                self._saml("no-certificate"),
                self._saml("flag-off", **{"want-auth-requests-signed": "no"}),
                self._saml("unreferenced"),
            ]}},
            profiles=[self._saml_user("ap-ok", "signed", "signing-cert"),
                      self._saml_user("ap-none", "no-certificate"),
                      self._saml_user("ap-off", "flag-off", "signing-cert")])
        self.assertTrue(rows[("saml-idp", "signed")].message_signing_effective)
        self.assertFalse(rows[("saml-idp", "no-certificate")].message_signing_effective)
        self.assertFalse(rows[("saml-idp", "flag-off")].message_signing_effective)
        self.assertFalse(rows[("saml-idp", "unreferenced")].message_signing_effective,
                         "nothing sends a message, so nothing is signed")
        self.assertTrue(rows[("saml-idp", "unreferenced")].saml_want_auth_requests_signed,
                        "the flag itself is still the vendor's implicit yes")

    def test_one_authentication_profile_without_a_certificate_is_enough_to_fail_it(self):
        """Two profiles reach one IdP profile and only one names a certificate. The conjunction
        is over EVERY referrer, because the one that signs with nothing is the one an attacker
        uses."""
        rows = self._normalize(
            self._appliance("S-K8"),
            shared={"saml-idp": {"entry": [self._saml("two-users")]}},
            profiles=[self._saml_user("ap-ok", "two-users", "signing-cert"),
                      self._saml_user("ap-bare", "two-users")])
        self.assertFalse(rows[("saml-idp", "two-users")].message_signing_effective)


class AaaAuthenticationProfileColumnTests(TestCase):
    """PAN-AAA-007, 008 and 010's columns on `AuthenticationProfile`."""

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.aaap")
        self.group = ApplianceGroup.objects.create(
            management_station=self.station, name="g-aaap",
            group_type=ApplianceGroup.TYPE_STANDALONE)
        self.appliance = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            serial_number="S-AAAP", hostname="fw-aaap")

    def _normalize(self, *entries):
        Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": {
                "shared": {"authentication-profile": {"entry": list(entries)}},
                "devices": {"entry": [{"@name": "localhost.localdomain"}]}}})
        _normalize_profiles(self.appliance)
        return {p.name: p for p in _AuthenticationProfile.objects.filter(
            appliance=self.appliance)}

    def test_a_realm_absent_on_both_keys_stores_NULL_and_not_a_blank(self):
        """Stage 5 declared both `default.stores: null`, `rests_on: not_assumed` - stage 4 held
        the single-sign-on reading back on its positive control and never reached the method
        branch at all. `is_empty` compiles to `field=""`, which matches a blank and not a null,
        so a blank would answer a question nobody settled."""
        rows = self._normalize({"@name": "no-realm", "method": {"local-database": None},
                                "allow-list": {"member": ["all"]}})
        row = rows["no-realm"]
        self.assertIsNone(row.sso_realm)
        self.assertIsNone(row.kerberos_method_realm)
        self.assertFalse(row.kerberos_realm_configured)
        self.assertFalse(row.kerberos_realm_is_uppercase)

    def test_both_keys_can_hold_a_realm_and_the_method_branch_has_no_vendor_page(self):
        rows = self._normalize(
            {"@name": "on-sso", "single-sign-on": {"realm": "EXAMPLE.COM"},
             "method": {"kerberos": {"server-profile": "k"}},
             "allow-list": {"member": ["all"]}},
            {"@name": "on-method",
             "method": {"kerberos": {"server-profile": "k", "realm": "EXAMPLE.COM"}},
             "allow-list": {"member": ["all"]}})
        self.assertEqual(rows["on-sso"].sso_realm, "EXAMPLE.COM")
        self.assertIsNone(rows["on-sso"].kerberos_method_realm)
        self.assertEqual(rows["on-method"].kerberos_method_realm, "EXAMPLE.COM")
        self.assertIsNone(rows["on-method"].sso_realm)
        for name in ("on-sso", "on-method"):
            self.assertTrue(rows[name].kerberos_realm_configured)
            self.assertTrue(rows[name].kerberos_realm_is_uppercase)

    def test_the_case_test_is_exact_because_every_text_operator_is_not(self):
        """The compiler maps `eq` to `iexact` and `contains` to `icontains`, so no clause can
        tell EXAMPLE.COM from example.com. A mutation making this comparison case-insensitive
        moves exactly one row on the lab, which is why it is also asserted here."""
        rows = self._normalize(
            {"@name": "lower", "method": {"kerberos": {"realm": "example.com"}},
             "allow-list": {"member": ["all"]}},
            {"@name": "mixed", "method": {"kerberos": {"realm": "Example.COM"}},
             "allow-list": {"member": ["all"]}},
            {"@name": "upper", "method": {"kerberos": {"realm": "EXAMPLE.COM"}},
             "allow-list": {"member": ["all"]}},
            {"@name": "one-of-two-lower", "single-sign-on": {"realm": "EXAMPLE.COM"},
             "method": {"kerberos": {"realm": "example.com"}},
             "allow-list": {"member": ["all"]}})
        self.assertFalse(rows["lower"].kerberos_realm_is_uppercase)
        self.assertFalse(rows["mixed"].kerberos_realm_is_uppercase)
        self.assertTrue(rows["upper"].kerberos_realm_is_uppercase)
        self.assertFalse(rows["one-of-two-lower"].kerberos_realm_is_uppercase,
                         "either key can be the realm the firewall uses")

    def test_an_empty_allow_list_is_not_the_same_width_as_all(self):
        """An empty allow list admits NOBODY - Help p.839 and the admin guide's p.288 step 6 -
        and `all` admits everybody. Both are "no named group" and every comparison a clause can
        make collapses them into one."""
        rows = self._normalize(
            {"@name": "everyone", "method": {"local-database": None},
             "allow-list": {"member": ["all"]}},
            {"@name": "nobody", "method": {"local-database": None}, "allow-list": None},
            {"@name": "a-group", "method": {"local-database": None},
             "allow-list": {"member": ["cn=admins"]}})
        self.assertEqual(rows["everyone"].allow_list_width, "all")
        self.assertEqual(rows["nobody"].allow_list_width, "empty")
        self.assertEqual(rows["a-group"].allow_list_width, "named_group")
        self.assertEqual(rows["nobody"].allow_list_count, 0)
        self.assertFalse(rows["nobody"].allow_list_is_all)

    def test_the_saml_references_store_NULL_when_absent(self):
        """Both are `not_reached` in stage 4: no certificate profile existed on any appliance it
        read, so no subject carrying either key could be built."""
        rows = self._normalize(
            {"@name": "bare-saml", "method": {"saml-idp": {"server-profile": "idp"}},
             "allow-list": {"member": ["all"]}},
            {"@name": "anchored", "method": {"saml-idp": {
                "server-profile": "idp", "certificate-profile": "cp",
                "request-signing-certificate": "signing"}},
             "allow-list": {"member": ["all"]}})
        self.assertIsNone(rows["bare-saml"].saml_certificate_profile)
        self.assertIsNone(rows["bare-saml"].saml_request_signing_certificate)
        self.assertEqual(rows["anchored"].saml_certificate_profile, "cp")
        self.assertEqual(rows["anchored"].saml_request_signing_certificate, "signing")

    def test_the_width_and_the_count_have_to_agree_with_the_member_list(self):
        rows = self._normalize({"@name": "ok", "method": {"local-database": None},
                                "allow-list": {"member": ["all"]}})
        row = rows["ok"]
        row.clean()
        row.allow_list_width = "named_group"
        with self.assertRaises(ValidationError):
            row.clean()


class AaaSequenceGradingTests(TestCase):
    """PAN-AAA-012's grading column, and the branch the lab cannot discriminate.

    No sequence standing on the lab holds BOTH a `none` member and a `local-database` one, so a
    mutation reversing the order of `WEAKEST_FIRST` moved not one row of the readback. That
    ordering is the whole point of the column - stage 3 grades `none` above `local-database` -
    so it is asserted here.
    """

    PROFILES = [
        {"@name": "ldap-p", "method": {"ldap": {"server-profile": "l"}}},
        {"@name": "local-p", "method": {"local-database": None}},
        {"@name": "none-p", "method": {"none": None}},
    ]

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.aaaq")
        self.group = ApplianceGroup.objects.create(
            management_station=self.station, name="g-aaaq",
            group_type=ApplianceGroup.TYPE_STANDALONE)
        self.appliance = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            serial_number="S-AAAQ", hostname="fw-aaaq")

    def _normalize(self, *sequences):
        Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": {
                "shared": {"authentication-profile": {"entry": list(self.PROFILES)},
                           "authentication-sequence": {"entry": list(sequences)}},
                "devices": {"entry": [{"@name": "localhost.localdomain"}]}}})
        _normalize_profiles(self.appliance)
        _normalize_sequences(self.appliance)
        return {s.name: s for s in _AuthenticationSequence.objects.filter(
            appliance=self.appliance)}

    @staticmethod
    def _seq(name, *members):
        return {"@name": name, "authentication-profiles": {"member": list(members)}}

    def test_none_is_graded_worse_than_local_database(self):
        rows = self._normalize(
            self._seq("both", "ldap-p", "local-p", "none-p"),
            self._seq("local-only", "ldap-p", "local-p"),
            self._seq("none-only", "ldap-p", "none-p"),
            self._seq("external-only", "ldap-p"),
            self._seq("empty"))
        self.assertEqual(rows["both"].weakest_member_method, "none",
                         "the vendor's own description of `none` is no authentication at all")
        self.assertEqual(rows["local-only"].weakest_member_method, "local-database")
        self.assertEqual(rows["none-only"].weakest_member_method, "none")
        self.assertEqual(rows["external-only"].weakest_member_method, "")
        self.assertEqual(rows["empty"].weakest_member_method, "")

    def test_an_unresolvable_member_leaves_the_grading_blank_rather_than_guessing(self):
        """Stage 4's reading: an unresolvable member proves NOTHING about where the credential
        is checked. `unresolved_member_count` is the column that reports it."""
        rows = self._normalize(self._seq("ghost", "no-such-profile"))
        self.assertEqual(rows["ghost"].weakest_member_method, "")
        self.assertEqual(rows["ghost"].unresolved_member_count, 1)
        self.assertFalse(rows["ghost"].has_local_member)
        self.assertFalse(rows["ghost"].all_members_external)

    def test_the_grading_has_to_agree_with_the_resolved_methods(self):
        rows = self._normalize(self._seq("both", "local-p", "none-p"))
        row = rows["both"]
        row.clean()
        row.weakest_member_method = "local-database"
        with self.assertRaises(ValidationError):
            row.clean()
# ===========================================================================
# device-services, stage 7: PAN-SVC-001 to PAN-SVC-010
#
# EVERY MEASURED ABSENCE IN THIS DOMAIN GETS A TEST THAT ASSERTS ITS VALUE, not its shape.
# That is the floor stage 7's contract writes down: the device reading sits in a handback, the
# value sits in the normalizer, and without a test nothing fails when a later edit changes what
# an absence stores. A test that would still pass if the normalizer stopped storing the column
# is not that test.
# ===========================================================================

