class _IpsecBase(SimpleTestCase):
    """The payload shapes below are the LAB's, read 2026-10-29 through Panorama's proxy.

    Every entry here was copied out of a live `action=get` at the collection's own xpath on
    pan-fw-111 (serial 6A9C0A9904E7D6E) or pan-fw-201 (serial 691665AC334B458) - the subjects
    stage 6 left standing, plus the three factory-named profiles and the factory monitor profile.
    They are fixtures of a measurement rather than of an understanding, which is the distinction
    stage 7's contract draws.
    """

    #: `oep-ips6-p01`: the null cipher with md5, no per-association key agreement, 30 days.
    P01 = {"@name": "oep-ips6-p01",
           "esp": {"encryption": {"member": ["null"]},
                   "authentication": {"member": ["md5"]}},
           "dh-group": "no-pfs", "lifetime": {"days": "30"}}
    #: `oep-ips6-p04`: the profile at three of this domain's four boundaries.
    P04 = {"@name": "oep-ips6-p04",
           "esp": {"encryption": {"member": ["aes-256-cbc"]},
                   "authentication": {"member": ["sha384"]}},
           "dh-group": "group14", "lifetime": {"hours": "1"}}
    #: `oep-ips6-p05`: the MINUTE branch.
    P05 = {"@name": "oep-ips6-p05",
           "esp": {"encryption": {"member": ["aes-256-cbc"]},
                   "authentication": {"member": ["sha512"]}},
           "dh-group": "group15", "lifetime": {"minutes": "240"}}
    #: `oep-ips6-p06`: the SECOND branch.
    P06 = {"@name": "oep-ips6-p06",
           "esp": {"encryption": {"member": ["aes-128-cbc"]},
                   "authentication": {"member": ["sha384"]}},
           "dh-group": "group16", "lifetime": {"seconds": "43200"}}
    #: `oep-ips6-p08`: the integrity-only AH branch, no cipher of any kind.
    P08 = {"@name": "oep-ips6-p08",
           "ah": {"authentication": {"member": ["sha256"]}},
           "dh-group": "group14", "lifetime": {"hours": "1"}}
    #: `oep-ips6-p09`: NOTHING BUT THE MANDATORY LIFETIME. Committed, and standing on the lab.
    P09 = {"@name": "oep-ips6-p09", "lifetime": {"hours": "1"}}
    #: `oep-ips6-p10`: the hardened profile - AEAD only, hash declined, group21, one hour.
    P10 = {"@name": "oep-ips6-p10",
           "esp": {"encryption": {"member": ["aes-256-gcm"]},
                   "authentication": {"member": ["none"]}},
           "dh-group": "group21", "lifetime": {"hours": "1"}}
    #: `oep-ips6-p11`: a cipher that only encrypts with the hash DECLINED beside it.
    P11 = {"@name": "oep-ips6-p11",
           "esp": {"encryption": {"member": ["aes-128-cbc"]},
                   "authentication": {"member": ["none"]}},
           "dh-group": "group14", "lifetime": {"hours": "1"}}
    #: `default` on pan-fw-201: the factory profile, and the content PAN-IPS-009 tests against.
    SHIPPED = {"@name": "default",
               "esp": {"encryption": {"member": ["aes-128-cbc", "3des"]},
                       "authentication": {"member": ["sha1"]}},
               "dh-group": "group2", "lifetime": {"hours": "1"}}

    #: `oep-ips6-t01`: both switches explicitly OFF.
    T01 = {"@name": "oep-ips6-t01", "tunnel-interface": "tunnel.61", "disabled": "yes",
           "anti-replay": "no", "tunnel-monitor": {"enable": "no"}}
    #: `oep-ips6-t02`: both keys ABSENT ENTIRELY rather than set to no, and no crypto reference.
    T02 = {"@name": "oep-ips6-t02", "tunnel-interface": "tunnel.61", "disabled": "yes"}
    #: `oep-ips6-t03`: monitoring on, with a target and a profile that fails over.
    T03 = {"@name": "oep-ips6-t03", "tunnel-interface": "tunnel.61", "disabled": "yes",
           "anti-replay": "yes",
           "tunnel-monitor": {"enable": "yes", "destination-ip": "192.0.2.61",
                              "tunnel-monitor-profile": "oep-ips6-m01"}}
    #: `oep-ips6-t04`: the auto-key branch, naming a gateway and the hardened profile.
    T04 = {"@name": "oep-ips6-t04", "tunnel-interface": "tunnel.61", "disabled": "yes",
           "auto-key": {"ike-gateway": {"entry": [{"@name": "oep-ike6-g01"}]},
                        "ipsec-crypto-profile": "oep-ips6-p10"}}

    #: `oep-ips6-m01` / `-m02` / `-m03`: fail-over, wait-recover, and an entry with NO CHILD KEY.
    M01 = {"@name": "oep-ips6-m01", "interval": "2", "threshold": "2", "action": "fail-over"}
    M02 = {"@name": "oep-ips6-m02", "interval": "100", "threshold": "10",
           "action": "wait-recover"}
    M03 = {"@name": "oep-ips6-m03"}

    def device_entry(self, *, profiles=(), tunnels=(), monitors=(), satellites=None):
        """A merged-config device entry holding the three collections.

        `satellites=None` leaves `global-protect-site-to-site` ABSENT, which is pan-fw-111's and
        pan-fw-201's state; `satellites=[]` makes it present and empty, which is both PA-5220s'.

        Deep-copied, because the entries above are CLASS attributes: a test that marks one with
        `@ptpl` would otherwise leak that marker into every later test in file order, which is
        exactly what happened the first time this block ran.
        """
        import copy
        profiles = copy.deepcopy(list(profiles))
        tunnels = copy.deepcopy(list(tunnels))
        monitors = copy.deepcopy(list(monitors))
        satellites = None if satellites is None else copy.deepcopy(list(satellites))
        tunnel_node = {"ipsec": {"entry": list(tunnels)} if tunnels else None}
        if satellites is not None:
            tunnel_node["global-protect-site-to-site"] = (
                {"entry": list(satellites)} if satellites else None)
        return {
            "@name": "localhost.localdomain",
            "network": {
                "ike": {"crypto-profiles": {
                    "ipsec-crypto-profiles": (
                        {"entry": list(profiles)} if profiles else None)}},
                "tunnel": tunnel_node,
                "profiles": {"monitor-profile": (
                    {"entry": list(monitors)} if monitors else None)},
            },
        }

    def profile(self, entry):
        return ipsec_norm.profile_values(entry)[0]

    def tunnel(self, entry, *, profiles=(), monitors=()):
        content = {e["@name"]: ipsec_norm._profile_content(self.profile(e)) for e in profiles}
        actions = ipsec_norm.monitor_profile_actions(
            self.device_entry(monitors=monitors))
        return ipsec_norm.tunnel_values(
            entry, profile_content=content, monitor_actions=actions)[0]


class IpsecAbsentKeyTests(_IpsecBase):
    """WHAT EACH ABSENT KEY STORES, asserted on the VALUE and not on the shape.

    Stage 7's contract, as of 2026-10-29: "A column whose absent-key behaviour you measured owes a
    test asserting it. That is the cheapest place in this pipeline to lose a measurement: the
    device reading sits in your handback, the value sits in the normaliser, and nothing fails when
    a later edit changes what an absence stores."

    Nine keys in this domain have a declared absent behaviour - four measured vendor facts, three
    storing nothing, and two inferences - and every one of them is below. The two inferences are
    asserted as stage 5 declared them, which is what holds the disagreement in a place a later
    change cannot quietly resolve.
    """

    def test_an_absent_cipher_list_stores_null_and_not_an_empty_list(self):
        """Measured: an absent list means NOTHING IS OFFERED. NULL and `[]` are different
        answers, and stage 5 declares the materialised value as null - the substitution of `''`
        or `[]` for a declared null is the defect 0110_wildfire_rule_absence_is_null corrected."""
        values = self.profile(self.P09)
        self.assertIsNone(values["esp_encryption"])
        self.assertIsNone(values["esp_authentication"])
        self.assertIsNone(values["ah_authentication"])

    def test_an_absent_dh_group_stores_the_measured_group2(self):
        """THE SHARPEST MEASUREMENT IN THIS DOMAIN, and it FIRES: PAN-IPS-004 ranks group2 high,
        the key is optional at commit validation, and a profile that simply omits it behaves as a
        failing value. Leaving the column null would have made the commonest omission in the
        domain pass every threshold."""
        self.assertEqual(self.profile(self.P09)["dh_group"], "group2")
        self.assertFalse(self.profile(self.P09)["dh_group_meets_target"])

    def test_an_absent_disabled_key_stores_false(self):
        """Measured through commit validation in both directions over three commits: absent
        behaves identically to `no`. NOT EXERCISED BY THE LAB - all four standing tunnels set
        `disabled` explicitly - so this test is the only thing holding the measurement."""
        entry = dict(self.T02)
        entry.pop("disabled")
        self.assertIs(self.tunnel(entry)["is_disabled"], False)

    def test_an_absent_anti_replay_stores_nothing_and_the_companion_fires(self):
        """Stage 4 measured NOTHING about this absence, so neither value may be materialised: a
        `false` would report a finding nobody measured and a `true` would report a clean estate
        for the same reason. The firing moves to the companion."""
        values = self.tunnel(self.T02)
        self.assertIsNone(values["anti_replay"])
        self.assertIs(values["anti_replay_determined"], False)

    def test_an_explicit_anti_replay_no_is_not_an_unknown(self):
        """The distinction the companion column exists to carry: `no` is a reading and an absent
        key is not, and a clause on `anti_replay` alone cannot tell them apart."""
        values = self.tunnel(self.T01)
        self.assertIs(values["anti_replay"], False)
        self.assertIs(values["anti_replay_determined"], True)

    def test_an_absent_monitor_branch_stores_nothing_and_the_companion_fires(self):
        """An unmonitored tunnel is the COMMONEST shape of PAN-IPS-007's failure, and a
        materialised `false` here would match nothing and pass it in silence."""
        values = self.tunnel(self.T02)
        self.assertIsNone(values["tunnel_monitor_enable"])
        self.assertIs(values["tunnel_monitor_enable_determined"], False)
        self.assertIsNone(values["tunnel_monitor_destination_ip"])
        self.assertIsNone(values["tunnel_monitor_profile_name"])

    def test_a_monitor_branch_with_the_enable_key_absent_is_also_undetermined(self):
        """Deliberately the same answer as no branch at all: stage 4 measured no implicit for
        either, so the two absences assert the same nothing."""
        entry = {"@name": "t", "tunnel-monitor": {"destination-ip": "192.0.2.1"}}
        values = self.tunnel(entry)
        self.assertIsNone(values["tunnel_monitor_enable"])
        self.assertIs(values["tunnel_monitor_enable_determined"], False)
        self.assertEqual(values["tunnel_monitor_destination_ip"], "192.0.2.1")

    def test_an_absent_destination_stores_null_rather_than_the_empty_string(self):
        """`common.py::parse_text_field` COERCES a null implicit to `''` in its own body, so this
        column goes through `_nullable_text`. `is_empty` compiles to a filter on the empty string
        and does not match NULL, so the two spellings find different rows."""
        values = self.tunnel(self.T01)
        self.assertIsNone(values["tunnel_monitor_destination_ip"])
        self.assertNotEqual(values["tunnel_monitor_destination_ip"], "")

    def test_an_absent_crypto_profile_reference_stores_the_inferred_default(self):
        """AN INFERENCE AND NOT A MEASUREMENT, implemented as stage 5 declared it. It is
        admissible only because it lands on the FIRING side: the literal `default` resolves to
        nothing on three of the four lab appliances, so the commonest configuration reports."""
        values = self.tunnel(self.T02)
        self.assertEqual(values["crypto_profile_name"], "default")
        self.assertIs(values["crypto_profile_found"], False)
        self.assertIs(values["effective_crypto_profile_chosen"], False)

    def test_an_absent_ike_gateway_list_stores_nothing(self):
        """`not_reached` is its own answer: state B could not be run because satisfying the key
        needs an IKE gateway, which stage 4 declared out of scope before it wrote anything."""
        self.assertIsNone(self.tunnel(self.T02)["ike_gateway_names"])

    def test_an_absent_monitor_action_stores_the_inferred_wait_recover(self):
        """The second inference, and it FIRES - `wait-recover` is the value PAN-IPS-007's second
        record treats as failing, which is the only reason an unmeasured implicit may be
        materialised here. Standing on the lab as `oep-ips6-m03`, an entry with no child key."""
        self.assertEqual(ipsec_norm.monitor_profile_values(self.M03)[0]["action"], "wait-recover")

    def test_the_two_inferences_are_the_only_ones_this_module_makes(self):
        """The census `ImplicitDeclarationTests` enforces, asserted from the other side so that a
        promotion to `measured` or a new inference shows up as this test's failure too."""
        inferred = [name for name, value in vars(ipsec_norm).items()
                    if isinstance(value, Implicit) and value.citation is None
                    and value.value is not None]
        self.assertEqual(sorted(inferred),
                         ["CRYPTO_PROFILE_ABSENT", "MONITOR_ACTION_ABSENT"])


class IpsecComputationTests(_IpsecBase):
    """The derived columns, over the standing subjects and over the states they do not cover."""

    def test_the_protocol_branch_is_whichever_container_exists(self):
        self.assertEqual(self.profile(self.P04)["protocol_branch"], "esp")
        self.assertEqual(self.profile(self.P08)["protocol_branch"], "ah")
        self.assertEqual(self.profile(self.P09)["protocol_branch"], "none")

    def test_the_branchless_profile_fires_every_algorithm_column(self):
        """`none` is a COMMITTED state - `lifetime` is the only mandatory key - and stage 3's
        grading had no rank for it. Every verdict over an absent list reads its worst value."""
        values = self.profile(self.P09)
        self.assertEqual(values["weakest_encryption_offered"], "")
        self.assertEqual(values["weakest_integrity_offered"], "")
        self.assertIs(values["all_offered_ciphers_authenticate"], False)
        self.assertIs(values["integrity_meets_sha2_floor"], False)

    def test_the_weakest_cipher_is_read_off_the_whole_offer_set(self):
        """THE LAB CANNOT SHOW THIS AND THE SHIPPED PROFILE CAN: fifteen of the sixteen standing
        profiles offer exactly ONE cipher, so the ordering is only exercised by `default`, which
        offers aes-128-cbc beside 3des. A `contains` clause for the strong member would report
        that profile compliant; the weakest member is 3des and it fires."""
        self.assertEqual(self.profile(self.SHIPPED)["weakest_encryption_offered"], "3des")
        self.assertEqual(self.profile(self.P01)["weakest_encryption_offered"], "null")
        self.assertEqual(self.profile(self.P10)["weakest_encryption_offered"], "aes-256-gcm")

    def test_the_cipher_order_places_the_cleartext_cipher_below_3des(self):
        """Stage 5 gives a SEVERITY order and not a total one - `null` and `3des` share `high` -
        so this tie is broken here. It is deliberately inconsequential: a profile offering both
        reports at `high` whichever way it falls, and the tie-break only decides which value the
        finding prints."""
        entry = {"@name": "x", "esp": {"encryption": {"member": ["3des", "null"]},
                                       "authentication": {"member": ["sha256"]}},
                 "lifetime": {"hours": "1"}}
        self.assertEqual(self.profile(entry)["weakest_encryption_offered"], "null")

    def test_the_weakest_integrity_comes_from_whichever_branch_exists(self):
        """NOT EXERCISED BY THE LAB either: every standing profile offers exactly ONE integrity
        algorithm, so reversing the order changes no stored row. Two sibling lists with one of
        them chosen by the presence of a third node is why this is a column and not a clause."""
        self.assertEqual(self.profile(self.P08)["weakest_integrity_offered"], "sha256")
        entry = {"@name": "x", "esp": {"encryption": {"member": ["aes-256-cbc"]},
                                       "authentication": {"member": ["sha512", "md5"]}},
                 "lifetime": {"hours": "1"}}
        self.assertEqual(self.profile(entry)["weakest_integrity_offered"], "md5")

    def test_the_ah_branch_never_reads_the_esp_list(self):
        """One grid column serves both branches, measured, so a reading taken off the screen
        cannot say which list it came from - which is why they are two columns."""
        entry = {"@name": "x", "ah": {"authentication": {"member": ["sha256"]}},
                 "esp": None, "lifetime": {"hours": "1"}}
        values = self.profile(entry)
        self.assertEqual(values["protocol_branch"], "ah")
        self.assertEqual(values["weakest_integrity_offered"], "sha256")
        self.assertIsNone(values["esp_authentication"])

    def test_an_unranked_cipher_is_returned_as_the_device_gave_it(self):
        """The value set is a LOWER BOUND - `action=complete` answers a successful EMPTY list at
        this leaf on all four appliances - so a build offering a member nobody has seen must reach
        the report unranked rather than as a collection that was never weak."""
        entry = {"@name": "x", "esp": {"encryption": {"member": ["aes-512-quux"]},
                                       "authentication": {"member": ["sha384"]}},
                 "lifetime": {"hours": "1"}}
        self.assertEqual(self.profile(entry)["weakest_encryption_offered"], "aes-512-quux"[:16])
        self.assertIs(self.profile(entry)["all_offered_ciphers_authenticate"], False)

    def test_aead_applicability_is_over_every_cipher_and_not_any(self):
        """The vendor states the hash is IGNORED for these ciphers, so the exclusion holds only
        where EVERY cipher authenticates. A mixed profile needs `non-auth` for the AEAD member and
        a SHA-2 member for the other, so `any` would excuse it."""
        self.assertIs(self.profile(self.P10)["all_offered_ciphers_authenticate"], True)
        self.assertIs(self.profile(self.P11)["all_offered_ciphers_authenticate"], False)
        mixed = {"@name": "x",
                 "esp": {"encryption": {"member": ["aes-256-gcm", "aes-128-cbc"]},
                         "authentication": {"member": ["none"]}},
                 "lifetime": {"hours": "1"}}
        self.assertIs(self.profile(mixed)["all_offered_ciphers_authenticate"], False)

    def test_the_sha2_floor_is_over_every_member(self):
        self.assertIs(self.profile(self.P04)["integrity_meets_sha2_floor"], True)
        self.assertIs(self.profile(self.P08)["integrity_meets_sha2_floor"], True)
        self.assertIs(self.profile(self.P01)["integrity_meets_sha2_floor"], False)
        self.assertIs(self.profile(self.P10)["integrity_meets_sha2_floor"], False)
        mixed = {"@name": "x", "esp": {"encryption": {"member": ["aes-256-cbc"]},
                                       "authentication": {"member": ["sha384", "sha1"]}},
                 "lifetime": {"hours": "1"}}
        self.assertIs(self.profile(mixed)["integrity_meets_sha2_floor"], False)

    def test_no_pfs_and_an_absent_key_are_different_facts_that_both_fail(self):
        """`no-pfs` reuses the key already agreed; an absent key re-keys on a 1024-bit group.
        Both fail PAN-IPS-004 and the remediation differs, which is why `dh_group` keeps the
        device's own token rather than collapsing to the verdict."""
        self.assertEqual(self.profile(self.P01)["dh_group"], "no-pfs")
        self.assertEqual(self.profile(self.P09)["dh_group"], "group2")
        self.assertIs(self.profile(self.P01)["dh_group_meets_target"], False)

    def test_a_post_quantum_group_and_the_literal_none_both_fail_the_target(self):
        """Nineteen values stage 3 leaves UNRANKED reach the report through this column reading
        false - not because a post-quantum group is weak, but because no ordering places it."""
        for group in ("kyber-768", "none", "group15", "group2", "group1"):
            entry = {"@name": "x", "dh-group": group, "lifetime": {"hours": "1"}}
            self.assertIs(self.profile(entry)["dh_group_meets_target"], False, group)
        for group in ("group19", "group20", "group21"):
            entry = {"@name": "x", "dh-group": group, "lifetime": {"hours": "1"}}
            self.assertIs(self.profile(entry)["dh_group_meets_target"], True, group)

    def test_all_four_lifetime_unit_branches_convert_to_hours(self):
        """ALL FOUR ARE STANDING ON THE LAB at this path, which they are not at the sibling IKE
        path: `oep-ips6-p01` writes days, `-p03` hours, `-p05` minutes and `-p06` seconds, and
        every one of them reads back as a BARE INTEGER STRING. The conversion is arithmetic across
        a column chosen by WHICH CHILD EXISTS, and a threshold on the number without its unit
        inverts the verdict."""
        self.assertEqual(self.profile(self.P01)["lifetime_unit"], "days")
        self.assertEqual(self.profile(self.P01)["lifetime_hours"], 720)
        self.assertEqual(self.profile(self.P04)["lifetime_hours"], 1)
        self.assertEqual(self.profile(self.P05)["lifetime_unit"], "minutes")
        self.assertEqual(self.profile(self.P05)["lifetime_hours"], 4)
        self.assertEqual(self.profile(self.P06)["lifetime_unit"], "seconds")
        self.assertEqual(self.profile(self.P06)["lifetime_hours"], 12)

    def test_a_sub_hour_lifetime_rounds_up_to_one_and_never_to_zero(self):
        """Forced by stage 5's own declaration - `lifetime_hours` carries `minimum: 1` - so a
        lifetime under an hour lands IN the acceptable band rather than outside every band. The
        helper that does it is shared with the sibling IKE normaliser, and this assertion is what
        makes a change there fail here rather than silently re-grade PAN-IPS-005."""
        entry = {"@name": "x", "lifetime": {"seconds": "180"}}
        self.assertEqual(self.profile(entry)["lifetime_hours"], 1)
        self.assertIs(self.profile(entry)["lifetime_within_target"], True)

    def test_the_lifetime_target_is_one_hour(self):
        self.assertIs(self.profile(self.P04)["lifetime_within_target"], True)
        self.assertIs(self.profile(self.P05)["lifetime_within_target"], False)
        self.assertIs(self.profile(self.P01)["lifetime_within_target"], False)


class IpsecBindingTests(_IpsecBase):
    """The three cross-object columns, every one of which reaches across a name resolution."""

    def test_a_resolvable_hardened_profile_is_the_only_chosen_state(self):
        values = self.tunnel(self.T04, profiles=[self.P10])
        self.assertEqual(values["crypto_profile_name"], "oep-ips6-p10")
        self.assertIs(values["crypto_profile_found"], True)
        self.assertIs(values["effective_crypto_profile_chosen"], True)

    def test_a_resolvable_profile_carrying_the_shipped_content_is_not_chosen(self):
        """THE TEST IS ON CONTENT AND NOT ON THE NAME. A renamed copy of the shipped proposal
        passes a name test and fails this one - which is the inversion stage 3 changed the control
        for."""
        renamed = dict(self.SHIPPED, **{"@name": "corporate-standard"})
        entry = dict(self.T04, **{
            "auto-key": {"ipsec-crypto-profile": "corporate-standard"}})
        values = self.tunnel(entry, profiles=[renamed])
        self.assertIs(values["crypto_profile_found"], True)
        self.assertIs(values["effective_crypto_profile_chosen"], False)

    def test_the_shipped_content_is_compared_as_a_set_and_not_as_a_list(self):
        """The device keeps its own order and `action=set` with one member APPENDS, so a
        reordered copy of the shipped proposal is still the shipped proposal."""
        reordered = {"@name": "default",
                     "esp": {"encryption": {"member": ["3des", "aes-128-cbc"]},
                             "authentication": {"member": ["sha1"]}},
                     "dh-group": "group2", "lifetime": {"hours": "1"}}
        entry = dict(self.T04, **{"auto-key": {"ipsec-crypto-profile": "default"}})
        self.assertIs(
            self.tunnel(entry, profiles=[reordered])["effective_crypto_profile_chosen"], False)

    def test_a_dangling_reference_is_the_majority_state_in_this_lab(self):
        """On both PA-5220s and on pan-fw-111 the literal `default` resolves to NOTHING, measured.
        A null join sits on the compliant side of a plain comparison and is silently dropped,
        which is why `crypto_profile_found` is a column rather than a join."""
        entry = dict(self.T04, **{"auto-key": {"ipsec-crypto-profile": "oep-ips6-gone"}})
        values = self.tunnel(entry, profiles=[self.P10])
        self.assertIs(values["crypto_profile_found"], False)
        self.assertIs(values["effective_crypto_profile_chosen"], False)

    def test_the_monitor_action_resolves_through_the_named_profile(self):
        self.assertEqual(
            self.tunnel(self.T03, monitors=[self.M01, self.M02])["monitor_action_effective"],
            "fail-over")
        entry = dict(self.T03, **{"tunnel-monitor": dict(
            self.T03["tunnel-monitor"], **{"tunnel-monitor-profile": "oep-ips6-m02"})})
        self.assertEqual(
            self.tunnel(entry, monitors=[self.M01, self.M02])["monitor_action_effective"],
            "wait-recover")

    def test_the_three_blank_states_of_the_monitor_action_are_all_blank(self):
        """Stage 5 declares all three and says the day a clause is written here they have to be
        told apart by a companion that fires. Named here so the claim is checked rather than
        asserted in prose."""
        self.assertEqual(self.tunnel(self.T02)["monitor_action_effective"], "")
        self.assertEqual(
            self.tunnel(self.T03, monitors=[])["monitor_action_effective"], "")
        self.assertEqual(
            self.tunnel(self.T01, monitors=[self.M01])["monitor_action_effective"], "")


class IpsecBranchesTheLabCannotShowTests(_IpsecBase):
    """Branches a readback against this estate CANNOT discriminate, each proved by mutation.

    Every case below was found by damaging the real normaliser at one named point and re-running
    the device readback: the mutation changed no stored column on any of the four appliances, so
    the lab cannot tell the right behaviour from the wrong one and only these assertions can.
    """

    def test_the_lsvpn_satellite_reference_is_counted(self):
        """THE MUTATION THAT PROVED THIS: pointing `SATELLITE_TUNNEL_PATH` at a collection that
        does not exist changed NOTHING, because no appliance in this lab holds a satellite tunnel
        entry - the container is absent on the two PA-VMs and present-and-empty on both PA-5220s.
        Stage 4 settled by enumeration that this leaf draws from the SAME crypto-profile
        collection, and a count over the auto-key leaf alone reports an LSVPN-only profile as
        unused - whose remediation is to delete it."""
        satellite = {"@name": "lsvpn-1",
                     "client": {"ipsec-crypto-profile": "oep-ips6-p10"}}
        counts = ipsec_norm.crypto_profile_reference_counts(
            self.device_entry(profiles=[self.P10], tunnels=[], satellites=[satellite]))
        self.assertEqual(counts.get("oep-ips6-p10"), 1)

    def test_both_referring_leaves_add_up_on_one_profile(self):
        counts = ipsec_norm.crypto_profile_reference_counts(self.device_entry(
            profiles=[self.P10], tunnels=[self.T04],
            satellites=[{"@name": "lsvpn-1",
                         "client": {"ipsec-crypto-profile": "oep-ips6-p10"}}]))
        self.assertEqual(counts["oep-ips6-p10"], 2)

    def test_the_gateway_to_client_leaf_is_not_counted(self):
        """The third candidate leaf draws from the GlobalProtect app crypto collection and not
        from this one - stage 4's enumeration pointing the other way, which is what makes the
        satellite result mean anything."""
        entry = self.device_entry(profiles=[self.P10])
        entry["network"]["tunnel"]["global-protect-gateway"] = {"entry": [
            {"@name": "gw-1", "ipsec": {"ipsec-crypto-profile": "oep-ips6-p10"}}]}
        self.assertEqual(
            ipsec_norm.crypto_profile_reference_counts(entry).get("oep-ips6-p10", 0), 0)

    def test_a_tunnel_with_no_reference_is_unchosen_even_where_default_resolves(self):
        """THE MUTATION THAT PROVED THIS: dropping the was-the-reference-written test changed no
        stored row, because no appliance holding a tunnel also holds a profile named `default`.
        Stage 5 declares the no-reference state false unconditionally - a proposal nobody chose is
        a proposal nobody owns - and on an estate that kept the factory profile the two readings
        differ."""
        hardened_default = dict(self.P10, **{"@name": "default"})
        values = self.tunnel(self.T02, profiles=[hardened_default])
        self.assertEqual(values["crypto_profile_name"], "default")
        self.assertIs(values["crypto_profile_found"], True)
        self.assertIs(values["effective_crypto_profile_chosen"], False)

    def test_a_named_profile_storing_no_action_resolves_to_the_inferred_value(self):
        """THE MUTATION THAT PROVED THIS: dropping the monitor profile's inferred default changed
        no stored row, because no standing tunnel names `oep-ips6-m03` - the keyless entry.
        Resolving such a name to blank would report a monitored tunnel as unresolvable when the
        device would in fact wait for the dead tunnel, which is the failing answer."""
        entry = dict(self.T03, **{"tunnel-monitor": dict(
            self.T03["tunnel-monitor"], **{"tunnel-monitor-profile": "oep-ips6-m03"})})
        self.assertEqual(
            self.tunnel(entry, monitors=[self.M03])["monitor_action_effective"], "wait-recover")

    def test_the_integrity_order_is_exercised_by_nothing_on_this_estate(self):
        """THE MUTATION THAT PROVED THIS: reversing `INTEGRITY_ORDER` changed NOT ONE of the 276
        compared values, because every one of the sixteen standing profiles offers exactly ONE
        integrity algorithm. The ordering decides PAN-IPS-003's severity, so it is asserted here
        rather than resting on a readback that cannot see it."""
        entry = {"@name": "x", "esp": {"encryption": {"member": ["aes-256-cbc"]},
                                       "authentication": {"member": [
                                           "sha512", "sha384", "sha256", "sha1", "md5", "none"]}},
                 "lifetime": {"hours": "1"}}
        self.assertEqual(self.profile(entry)["weakest_integrity_offered"], "none")
        entry["esp"]["authentication"]["member"] = ["sha512", "sha256"]
        self.assertEqual(self.profile(entry)["weakest_integrity_offered"], "sha256")


class IpsecContainerStateTests(_IpsecBase):
    """ABSENT, EMPTY and POPULATED, which this estate holds all three of at once.

    Measured 2026-10-29 at `action=get` and again through the whole-config merged read:
    `ipsec-crypto-profiles` is absent on both PA-5220s and populated on both PA-VMs;
    `tunnel/ipsec` is EMPTY on both PA-5220s, populated on pan-fw-111 and ABSENT on pan-fw-201.
    A reader testing truthiness reports absent and empty identically.
    """

    def test_an_empty_collection_yields_no_entry_and_does_not_raise(self):
        state, entries = entry_container(
            self.device_entry(), "network", "ike", "crypto-profiles", "ipsec-crypto-profiles")
        self.assertEqual(state, "empty")
        self.assertEqual(entries, [])

    def test_an_absent_collection_is_told_apart_from_an_empty_one(self):
        entry = self.device_entry()
        del entry["network"]["profiles"]
        self.assertEqual(
            entry_container(entry, "network", "profiles", "monitor-profile")[0], "absent")
        self.assertEqual(
            entry_container(self.device_entry(), "network", "profiles", "monitor-profile")[0],
            "empty")

    def test_a_single_entry_iterates_like_many(self):
        """A single entry arrives as a BARE DICT and not a list of one."""
        entry = self.device_entry(monitors=[self.M01])
        entry["network"]["profiles"]["monitor-profile"]["entry"] = self.M01
        _, entries = entry_container(entry, "network", "profiles", "monitor-profile")
        self.assertEqual([e["@name"] for e in entries], ["oep-ips6-m01"])

    def test_an_absent_tunnel_collection_leaves_every_profile_unreferenced(self):
        """pan-fw-201's state. Zero is what an absent container means and not a missing read."""
        self.assertEqual(
            ipsec_norm.crypto_profile_reference_counts(self.device_entry(profiles=[self.P10])),
            {})


class IpsecNormalizationTests(TestCase):
    """The persisted side: rows, the uniqueness constraint, and the provenance census.

    The payload is the lab's, read 2026-10-29 off pan-fw-111 - the thirteen standing profiles
    reduced to the four that carry this domain's distinct states, plus all four tunnels and all
    three monitor profiles.
    """

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA,
            name="probe", hostname="panorama.test")
        self.group = ApplianceGroup.objects.create(
            management_station=self.station, name="probe-group")
        self.appliance = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            hostname="pan-fw-111", serial_number="6A9C0A9904E7D6E")
        base = _IpsecBase()
        self.device = base.device_entry(
            profiles=[base.P01, base.P09, base.P10], tunnels=[base.T02, base.T04],
            monitors=[base.M01, base.M03])
        self.snapshot = Snapshot.objects.create(
            appliance=self.appliance, source_type="show_merged_config",
            payload={"config": {"devices": {"entry": [self.device]}}},
            collected_at=timezone.now())

    def _normalize(self):
        return (normalize_ipsec_crypto_profiles(self.appliance),
                normalize_ipsec_tunnels(self.appliance),
                normalize_monitor_profiles(self.appliance))

    def test_every_entry_becomes_exactly_one_row(self):
        profiles, tunnels, monitors = self._normalize()
        self.assertEqual([p.profile_name for p in profiles],
                         ["oep-ips6-p01", "oep-ips6-p09", "oep-ips6-p10"])
        self.assertEqual([t.tunnel_name for t in tunnels], ["oep-ips6-t02", "oep-ips6-t04"])
        self.assertEqual([m.profile_name for m in monitors],
                         ["oep-ips6-m01", "oep-ips6-m03"])

    def test_the_referrer_count_comes_from_the_same_payload_as_the_profiles(self):
        """So neither normalizer depends on the other having run and the two cannot disagree.
        `oep-ips6-t04` names `oep-ips6-p10`; `oep-ips6-t02` names nothing and is inferred onto the
        literal `default`, which does not exist here."""
        profiles, _, _ = self._normalize()
        counts = {p.profile_name: p.referencing_tunnel_count for p in profiles}
        self.assertEqual(counts, {"oep-ips6-p01": 0, "oep-ips6-p09": 0, "oep-ips6-p10": 1})

    def test_the_tunnel_resolves_its_binding_without_the_profile_rows_existing(self):
        """Normalizing tunnels FIRST, with no profile row in the database at all."""
        tunnels = normalize_ipsec_tunnels(self.appliance)
        self.assertEqual(IpsecCryptoProfile.objects.count(), 0)
        t04 = next(t for t in tunnels if t.tunnel_name == "oep-ips6-t04")
        self.assertIs(t04.crypto_profile_found, True)
        self.assertIs(t04.effective_crypto_profile_chosen, True)

    def test_a_second_pass_replaces_rather_than_duplicates(self):
        self._normalize()
        self._normalize()
        self.assertEqual(IpsecCryptoProfile.objects.filter(appliance=self.appliance).count(), 3)
        self.assertEqual(IpsecTunnel.objects.filter(appliance=self.appliance).count(), 2)
        self.assertEqual(MonitorProfile.objects.filter(appliance=self.appliance).count(), 2)

    def test_a_second_pass_leaves_no_orphan_provenance_row(self):
        self._normalize()
        self._normalize()
        for model in (IpsecCryptoProfile, IpsecTunnel, MonitorProfile):
            content_type = ContentType.objects.get_for_model(model)
            live = set(model.objects.values_list("pk", flat=True))
            recorded = set(FieldProvenance.objects.filter(
                content_type=content_type).values_list("object_id", flat=True))
            self.assertLessEqual(recorded, live, model.__name__)

    def test_an_absent_key_records_a_row_saying_what_the_absence_means(self):
        """Skipping the absent ones is what left "PAN-OS supplied it", "we inferred it" and
        "nobody tracks it" sharing one blank. Four of this domain's declarations are measured
        vendor facts, three store nothing, and two are inferences the report renders as not
        measured - and all three kinds are below."""
        profiles, tunnels, monitors = self._normalize()
        p09 = next(p for p in profiles if p.profile_name == "oep-ips6-p09")
        self.assertEqual(p09.provenance_for("dh_group").provenance_type, "pan_os_default")
        self.assertEqual(p09.provenance_for("dh_group").raw_value, "group2")
        self.assertEqual(p09.provenance_for("esp_encryption").provenance_type, "pan_os_default")
        t02 = next(t for t in tunnels if t.tunnel_name == "oep-ips6-t02")
        self.assertEqual(t02.provenance_for("anti_replay").provenance_type, "not_configured")
        self.assertEqual(
            t02.provenance_for("crypto_profile_name").provenance_type, "assumed_default")
        self.assertEqual(t02.provenance_for("crypto_profile_name").raw_value, "default")
        m03 = next(m for m in monitors if m.profile_name == "oep-ips6-m03")
        self.assertEqual(m03.provenance_for("action").provenance_type, "assumed_default")

    def test_an_unmarked_entry_is_local_and_never_predefined(self):
        """The factory-named entries are ordinary writable, deletable config - measured as
        carrying no attribute but `@name` on all four appliances - so the PREDEFINED sentinel,
        which asserts "shipped in the release and not editable here", must never be given. That
        they are deletable is what makes PAN-IPS-009's remedy possible."""
        profiles, _, _ = self._normalize()
        for profile in profiles:
            self.assertEqual(profile.provenance_for("__entry__").provenance_type, "local")

    def test_a_template_marked_entry_records_the_template(self):
        """NOT EXERCISED BY THIS ESTATE - zero @ptpl at all three paths on all four appliances,
        measured twice - so the mapping is asserted here rather than by a readback."""
        self.device["network"]["ike"]["crypto-profiles"]["ipsec-crypto-profiles"]["entry"][0][
            "@ptpl"] = "tpl-branch"
        self.snapshot.payload = {"config": {"devices": {"entry": [self.device]}}}
        self.snapshot.save()
        profiles = normalize_ipsec_crypto_profiles(self.appliance)
        row = profiles[0].provenance_for("__entry__")
        self.assertEqual(row.provenance_type, "template")
        self.assertEqual(row.raw_value, "tpl-branch")

    def test_the_uniqueness_constraint_is_the_two_columns_stage_5_declared(self):
        for model, column, name in (
                (IpsecCryptoProfile, "profile_name",
                 "integrations_unique_ipsec_crypto_profile_per_appliance"),
                (IpsecTunnel, "tunnel_name", "integrations_unique_ipsec_tunnel_per_appliance"),
                (MonitorProfile, "profile_name",
                 "integrations_unique_monitor_profile_per_appliance")):
            constraint = next(c for c in model._meta.constraints if c.name == name)
            self.assertEqual(list(constraint.fields), ["appliance", column], model.__name__)

    def test_an_appliance_with_nothing_writes_no_row_and_raises_nothing(self):
        """Both PA-5220s' committed state. The entry grain has NO ROW for "no IPSec crypto
        profile is defined here", so every assertion over "every profile the firewall holds" is
        VACUOUSLY TRUE on such an appliance - this domain's one wrong-direction limit, recorded in
        stage 5's `not_stored` and closable only by a per-appliance coverage row."""
        bare = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            hostname="fw-core-tpa-a", serial_number="013201001475")
        Snapshot.objects.create(
            appliance=bare, source_type="show_merged_config",
            payload={"config": {"devices": {"entry": [
                {"@name": "localhost.localdomain",
                 "network": {"tunnel": {"ipsec": None}}}]}}},
            collected_at=timezone.now())
        self.assertEqual(normalize_ipsec_crypto_profiles(bare), [])
        self.assertEqual(normalize_ipsec_tunnels(bare), [])
        self.assertEqual(normalize_monitor_profiles(bare), [])

    def test_a_missing_snapshot_raises_rather_than_writing_an_empty_estate(self):
        bare = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            hostname="pan-fw-999", serial_number="999")
        with self.assertRaises(ValueError):
            normalize_ipsec_crypto_profiles(bare)

    def test_an_entry_with_no_name_and_a_duplicate_name_are_both_skipped(self):
        """Neither can satisfy the uniqueness constraint. A duplicate name is not expressible in
        PAN-OS, so this is defensive rather than observed."""
        entries = self.device["network"]["ike"]["crypto-profiles"]["ipsec-crypto-profiles"]["entry"]
        entries.append({"lifetime": {"hours": "1"}})
        entries.append({"@name": "oep-ips6-p01", "lifetime": {"hours": "2"}})
        self.snapshot.payload = {"config": {"devices": {"entry": [self.device]}}}
        self.snapshot.save()
        profiles = normalize_ipsec_crypto_profiles(self.appliance)
        self.assertEqual([p.profile_name for p in profiles],
                         ["oep-ips6-p01", "oep-ips6-p09", "oep-ips6-p10"])
        self.assertEqual(profiles[0].lifetime_hours, 720)


class IpsecModelShapeTests(SimpleTestCase):
    """What the columns are declared as, where the declaration is the load-bearing part."""

    def test_the_three_models_carry_no_scope_and_no_vsys_column(self):
        """All three collections are DEVICE-WIDE - one for the whole appliance even on the
        multi-vsys PA-5220, measured - and stage 5 declared the identity as two columns. The
        sibling `IkeCryptoProfile` carries both so its constraint matches
        `ApplianceScopedObject`'s four; this domain was told two."""
        for model in (IpsecCryptoProfile, IpsecTunnel, MonitorProfile):
            names = {f.name for f in model._meta.get_fields()}
            self.assertNotIn("scope", names, model.__name__)
            self.assertNotIn("vsys_name", names, model.__name__)

    def test_the_columns_a_declared_null_must_reach_the_database_as_null(self):
        """`is_empty` compiles to a filter on the empty string and does NOT match NULL, so a
        column stage 5 declared as storing null and one storing a blank find different rows.
        Migration 0110 on another model is the correction that established this."""
        for column in ("tunnel_monitor_destination_ip", "tunnel_monitor_profile_name"):
            self.assertTrue(IpsecTunnel._meta.get_field(column).null, column)
        for column in ("anti_replay", "tunnel_monitor_enable"):
            self.assertTrue(IpsecTunnel._meta.get_field(column).null, column)
        for column in ("esp_encryption", "esp_authentication", "ah_authentication"):
            self.assertTrue(IpsecCryptoProfile._meta.get_field(column).null, column)

    def test_the_columns_whose_blank_has_to_fire_are_not_nullable(self):
        """A NEGATED equality over NULL answers NULL and SQL drops the row, so a column whose
        clause is `is not <value>` must hold the empty string when nobody read it."""
        for column in ("protocol_branch", "weakest_encryption_offered",
                       "weakest_integrity_offered", "lifetime_unit"):
            field = IpsecCryptoProfile._meta.get_field(column)
            self.assertFalse(field.null, column)
            self.assertEqual(field.default, "", column)
        self.assertFalse(IpsecTunnel._meta.get_field("monitor_action_effective").null)

    def test_every_verdict_defaults_to_the_side_that_reports(self):
        """A row nobody has recomputed is reported rather than cleared, which is rules.md's
        direction-of-error rule applied to a migration default. `is_disabled` is the one
        exception and it is a measured vendor fact rather than a convenience."""
        for column in ("integrity_meets_sha2_floor", "dh_group_meets_target",
                       "lifetime_within_target", "all_offered_ciphers_authenticate"):
            self.assertIs(IpsecCryptoProfile._meta.get_field(column).default, False, column)
        self.assertEqual(IpsecCryptoProfile._meta.get_field("referencing_tunnel_count").default, 0)
        for column in ("anti_replay_determined", "tunnel_monitor_enable_determined",
                       "crypto_profile_found", "effective_crypto_profile_chosen"):
            self.assertIs(IpsecTunnel._meta.get_field(column).default, False, column)
        self.assertIs(IpsecTunnel._meta.get_field("is_disabled").default, False)

    def test_dh_group_carries_no_choices_tuple(self):
        """Ten values on 11.1 and twenty-nine on 11.2 - a BUILD difference, with `kyber-768` and
        the literal `none` accepted on a PA-VM and refused on a PA-5220. A choices list would
        either refuse a value one build stores or admit one another build refuses."""
        self.assertFalse(IpsecCryptoProfile._meta.get_field("dh_group").choices)

    def test_the_derived_fields_are_declared_and_the_measured_ones_are_not(self):
        """A field in neither list reads as untracked; a measured field wrongly declared derived
        would tell a reader "we computed this" about a value the firewall holds."""
        self.assertIn("referencing_tunnel_count", IpsecCryptoProfile.DERIVED_FIELDS)
        self.assertIn("protocol_branch", IpsecCryptoProfile.DERIVED_FIELDS)
        self.assertNotIn("dh_group", IpsecCryptoProfile.DERIVED_FIELDS)
        self.assertNotIn("esp_encryption", IpsecCryptoProfile.DERIVED_FIELDS)
        self.assertIn("crypto_profile_found", IpsecTunnel.DERIVED_FIELDS)
        self.assertNotIn("crypto_profile_name", IpsecTunnel.DERIVED_FIELDS)
        self.assertNotIn("action", MonitorProfile.DERIVED_FIELDS)

    def test_a_row_may_not_name_an_appliance_from_another_station(self):
        other = ManagementStation(pk=99, station_type="pan_panorama", hostname="other")
        appliance = Appliance(pk=98, management_station=other)
        row = IpsecCryptoProfile(management_station_id=1, appliance=appliance)
        with self.assertRaises(ValidationError):
            row.clean()


class ContentUpdateScheduleNormalizationTests(TestCase):
    """One firewall's dynamic content update schedule, all five content types. PAN-UPD-001 to 005.

    The payload shapes here are the ones stage 4 and stage 6 measured on the four lab appliances,
    including the three that bite: a cadence expressed as WHICH BRANCH ELEMENT EXISTS rather than
    as a value, a branch element arriving as `None` where it carries no children (`real-time`,
    `every-min`), and a leaf arriving as `{"#text": ..., "@dirtyId": ...}` because the merged view
    follows the candidate.
    """

    def _appliance(self, serial="SERIAL-UPD", hostname="fw-upd"):
        station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="panorama.upd")
        return Appliance.objects.create(
            management_station=station, serial_number=serial, hostname=hostname)

    def _snapshot(self, appliance, device_entry):
        return Snapshot.objects.create(
            management_station=appliance.management_station,
            appliance=appliance,
            source_type="show_merged_config",
            collected_at=timezone.now(),
            payload={"config": {"devices": {"entry": device_entry}}},
        )

    def _normalize(self, device_entry, appliance=None):
        from optivedge_integrations.integrations.platforms.pan_os.normalization import (
            normalize_appliance_content_update_schedule)
        appliance = appliance or self._appliance()
        self._snapshot(appliance, device_entry)
        normalize_appliance_content_update_schedule(appliance)
        return ContentUpdateSchedule.objects.get(appliance=appliance)

    # ------------------------------------------------------------------ the cadences

    def test_the_cadence_is_the_branch_element_name(self):
        """It is not a key and has no value: the recurrence is WHICH of a measured set of sibling
        elements exists under `recurring`. Every one of these five is a reading taken off a
        committed lab appliance by the stage 6 run."""
        row = self._normalize({"deviceconfig": {"system": {
            "hostname": "fw-upd",
            "update-schedule": {
                "anti-virus": {"recurring": {"hourly": {"at": "17", "action": "download-only"}}},
                "threats": {"recurring": {"daily": {"at": "03:20", "action": "download-only"}}},
                "wildfire": {"recurring": {"every-15-mins": {
                    "at": "7", "action": "download-and-install"}}},
                "global-protect-datafile": {"recurring": {"weekly": {
                    "day-of-week": "tuesday", "at": "02:15", "action": "download-and-install"}}},
                "global-protect-clientless-vpn": {"recurring": {"daily": {
                    "at": "02:45", "action": "download-and-install"}}},
            },
        }}})
        self.assertEqual(row.av_recurrence, "hourly")
        self.assertEqual(row.av_action, "download-only")
        self.assertEqual(row.threats_recurrence, "daily")
        self.assertEqual(row.wildfire_recurrence, "every-15-mins")
        self.assertEqual(row.wildfire_action, "download-and-install")
        self.assertEqual(row.gp_datafile_recurrence, "weekly")
        self.assertEqual(row.gp_clientless_vpn_recurrence, "daily")
        self.assertTrue(row.update_schedule_collected)
        self.assertEqual(row.scope, "device-local")

    def test_a_branch_carrying_no_children_is_still_the_cadence(self):
        """`real-time` and `every-min` parse to a key with a `None` value, because the element is
        empty. Measured: 013201001475 holds `real-time` for WildFire and 6A9C0A9904E7D6E holds
        `every-min`. A reader that walks into the value gets nothing and reports `none`, which
        would say the appliance fetches no WildFire content at all."""
        row = self._normalize({"deviceconfig": {"system": {
            "hostname": "fw-upd",
            "update-schedule": {"wildfire": {"recurring": {"real-time": None}}},
        }}})
        self.assertEqual(row.wildfire_recurrence, "real-time")
        self.assertEqual(row.wildfire_action, "none",
                         "an empty branch carries no action key, and the run takes neither action")

    def test_a_leaf_carrying_a_dirty_marker_is_read_through_its_text(self):
        """The merged view follows the CANDIDATE, so a leaf still carrying an uncommitted edit
        arrives as a dict rather than a bare string. Code written against one view reads `None`
        out of the other, which stage 4 measured on this very object."""
        row = self._normalize({"deviceconfig": {"system": {
            "hostname": "fw-upd",
            "update-schedule": {"anti-virus": {"recurring": {"daily": {
                "at": {"@admin": "admin", "@dirtyId": "1", "#text": "23:55"},
                "action": {"@admin": "admin", "@dirtyId": "1",
                           "#text": "download-and-install"},
            }}}},
        }}})
        self.assertEqual(row.av_recurrence, "daily")
        self.assertEqual(row.av_action, "download-and-install")

    def test_a_threshold_sibling_is_not_mistaken_for_a_cadence(self):
        """`threshold`, `new-app-threshold` and `sync-to-peer` sit BESIDE the branch elements
        under `recurring`, not under one. A reader taking whatever key is there would report
        `threshold` as the cadence on an appliance whose only setting is a delay."""
        row = self._normalize({"deviceconfig": {"system": {
            "hostname": "fw-upd",
            "update-schedule": {"threats": {"recurring": {
                "threshold": "24", "new-app-threshold": "48", "sync-to-peer": "yes",
            }}},
        }}})
        self.assertEqual(row.threats_recurrence, "none")
        self.assertEqual(row.threats_action, "none")
        self.assertEqual(row.threats_threshold_hours, 24)
        self.assertEqual(row.threats_new_app_threshold_hours, 48)

    def test_an_unknown_branch_name_reports_rather_than_resembling_a_known_one(self):
        """The five branch sets are the device's own, measured identically on two platforms and
        two major versions. A cadence a later build adds reads as `none`, which FIRES on every
        clause in this domain, rather than being reported as the member it resembles."""
        row = self._normalize({"deviceconfig": {"system": {
            "hostname": "fw-upd",
            "update-schedule": {"anti-virus": {"recurring": {
                "every-5-mins": {"action": "download-and-install"}}}},
        }}})
        self.assertEqual(row.av_recurrence, "none")

    # ------------------------------------------- what an absent key stores, measured

    def test_an_absent_branch_element_stores_none_and_fires(self):
        """An absent content-type child means the appliance runs NO automatic retrieval for that
        content - nothing checked for, nothing downloaded, nothing installed - measured with a
        natural experiment that cost no writes: 013201001475 carried no `update-schedule` node at
        all before stage 6's fixtures and all three config views agreed.

        `none` is the FIRING value of every clause that names these columns, and it is distinct
        from `""`, which is an appliance nobody read."""
        row = self._normalize({"deviceconfig": {"system": {"hostname": "fw-upd"}}})
        self.assertTrue(row.update_schedule_collected,
                        "the parent node answered, so this appliance WAS read")
        for column in ("av_recurrence", "av_action", "threats_recurrence", "threats_action",
                       "wildfire_recurrence", "wildfire_action",
                       "gp_datafile_recurrence", "gp_datafile_action",
                       "gp_clientless_vpn_recurrence", "gp_clientless_vpn_action"):
            self.assertEqual(getattr(row, column), "none", column)

    def test_an_explicit_none_element_stores_the_same_token_as_an_absence(self):
        """Two spellings for one state, and stage 4 measured them as meaning the same thing."""
        row = self._normalize({"deviceconfig": {"system": {
            "hostname": "fw-upd",
            "update-schedule": {"anti-virus": {"recurring": {"none": None}}},
        }}})
        self.assertEqual(row.av_recurrence, "none")
        self.assertEqual(row.av_action, "none")

    def test_a_committed_branch_with_no_action_key_stores_none(self):
        """Measured on a COMMITTED timed branch carrying `at` and no `action` key: `show config
        running` showed `daily: {at: "23:50"}` and nothing else, the screen rendered `(None, ...)`
        and the dialog's OK button wrote nothing - which is what rules out "the rendered None is a
        value the form holds". Commit job 129 returned OK with the key absent while job 127 had
        refused the same branch for a missing `at` and never mentioned `action`, so the key
        genuinely CAN lack a value on a committed object.

        Reproduced in the lab by the stage 6 run on two more content types: pan-fw-201 holds a
        `global-protect-datafile` `daily` branch and a `global-protect-clientless-vpn` `weekly`
        branch, both with no `action` key."""
        row = self._normalize({"deviceconfig": {"system": {
            "hostname": "fw-upd",
            "update-schedule": {
                "global-protect-datafile": {"recurring": {"daily": {"at": "03:40"}}},
                "global-protect-clientless-vpn": {"recurring": {"weekly": {
                    "day-of-week": "thursday", "at": "04:10"}}},
            },
        }}})
        self.assertEqual(row.gp_datafile_recurrence, "daily")
        self.assertEqual(row.gp_datafile_action, "none")
        self.assertEqual(row.gp_clientless_vpn_recurrence, "weekly")
        self.assertEqual(row.gp_clientless_vpn_action, "none")

    def test_an_absent_threshold_stores_null_and_not_a_number(self):
        """WHAT AN ABSENT THRESHOLD DOES IS UNMEASURED, so nothing is stored. stage4-updates.json
        records `implicit.status: unmeasured`, `consumer_disposition: not_assumed` and
        `may_materialise: false` for both keys, because the only control goes blank: with the key
        deleted the dialog's Threshold field renders ` [1 - 336]` with `is_hint: True`, an
        emptyText placeholder rather than a value. Four vendor wordings disagree about what the
        threshold even gates and none of the four says what an absent one does.

        Materialising any number here would assert that a review window exists."""
        row = self._normalize({"deviceconfig": {"system": {
            "hostname": "fw-upd",
            "update-schedule": {"threats": {"recurring": {"hourly": {
                "action": "download-and-install"}}}},
        }}})
        self.assertIsNone(row.threats_threshold_hours)
        self.assertIsNone(row.threats_new_app_threshold_hours)

    def test_an_absent_threshold_records_provenance_saying_nothing_was_assumed(self):
        """The two keys this model reads are the two that carry a `FieldProvenance` row, and an
        absent key records one too - models/provenance.py:59-68, changed 2026-09-21. A MISSING row
        would mean only that the field is not tracked, which would make every unconfigured
        threshold look untracked."""
        row = self._normalize({"deviceconfig": {"system": {
            "hostname": "fw-upd",
            "update-schedule": {"threats": {"recurring": {"hourly": None}}},
        }}})
        rows = {entry.field_name: entry for entry in FieldProvenance.objects.filter(
            content_type=ContentType.objects.get_for_model(ContentUpdateSchedule),
            object_id=row.pk)}
        self.assertEqual(
            rows["threats_threshold_hours"].provenance_type, "not_configured")
        self.assertEqual(
            rows["threats_new_app_threshold_hours"].provenance_type, "not_configured")

    def test_a_present_threshold_records_a_local_provenance_row(self):
        row = self._normalize({"deviceconfig": {"system": {
            "hostname": "fw-upd",
            "update-schedule": {"threats": {"recurring": {
                "hourly": None, "new-app-threshold": "24"}}},
        }}})
        entry = FieldProvenance.objects.get(
            content_type=ContentType.objects.get_for_model(ContentUpdateSchedule),
            object_id=row.pk, field_name="threats_new_app_threshold_hours")
        self.assertEqual(entry.provenance_type, "local")
        self.assertEqual(row.threats_new_app_threshold_hours, 24)

    # -------------------------------------------------- the unknown, and its companion

    def test_an_appliance_whose_system_node_arrived_empty_holds_the_empty_string(self):
        """"We never asked" must not look like "we asked and it was fine". The empty string is a
        DIFFERENT state from `none` and both fire - but the remediation differs completely, and
        `update_schedule_collected` is the column that tells a reader which one they are looking
        at. A `none` here would say the appliance was read and has nothing scheduled."""
        row = self._normalize({"deviceconfig": {}})
        self.assertFalse(row.update_schedule_collected)
        for column in ("av_recurrence", "av_action", "threats_recurrence", "threats_action",
                       "wildfire_recurrence", "wildfire_action",
                       "gp_datafile_recurrence", "gp_datafile_action",
                       "gp_clientless_vpn_recurrence", "gp_clientless_vpn_action"):
            self.assertEqual(getattr(row, column), "", column)

    def test_the_empty_string_satisfies_the_negated_equality_every_clause_uses(self):
        """The whole reason these ten columns are non-nullable text. Every clause in this domain
        is a negated equality, so an appliance nobody read REPORTS rather than passing, with no
        companion column and no second firing group. A nullable column would have been invisible
        to both polarities, and a boolean would have defaulted false and read as compliant."""
        row = self._normalize({"deviceconfig": {}})
        self.assertNotEqual(row.av_recurrence, "daily")
        self.assertNotEqual(row.av_recurrence, "hourly")
        self.assertNotEqual(row.av_action, "download-and-install")
        self.assertNotEqual(row.wildfire_recurrence, "real-time")

    def test_a_verdict_may_not_outlive_the_reading_it_rested_on(self):
        row = ContentUpdateSchedule(update_schedule_collected=False, av_recurrence="daily")
        with self.assertRaises(ValidationError):
            row.clean()
        ContentUpdateSchedule(update_schedule_collected=False).clean()

    def test_no_row_is_written_without_a_merged_snapshot(self):
        """The residual case `update_schedule_collected` cannot plug, and it is stage 5's to
        record rather than this module's to fix: such an appliance is absent from every query
        rather than present and false."""
        from optivedge_integrations.integrations.platforms.pan_os.normalization import (
            normalize_appliance_content_update_schedule)
        appliance = self._appliance()
        counts = normalize_appliance_content_update_schedule(appliance)
        self.assertEqual(counts, {"content_update_schedules": 0})
        self.assertFalse(ContentUpdateSchedule.objects.filter(appliance=appliance).exists())

    # ------------------------------------------------------------------ grain and shape

    def test_each_ha_peer_gets_its_own_row_and_nothing_deduplicates_them(self):
        """threat p.35 STEP 3 item 5: `the update schedule does not sync across peers; you must
        manually configure the schedule on both peers`. Measured in this lab: the active PA-5220
        013201001475 carries four content types and no `threats` node, and its passive peer
        013201001085 carries a `threats` schedule and nothing else."""
        station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="panorama.ha-upd")
        group = ApplianceGroup.objects.create(
            management_station=station, name="ha-pair-upd")
        active = Appliance.objects.create(
            management_station=station, appliance_group=group,
            serial_number="013201001475", hostname="fw-core-tpa-a")
        passive = Appliance.objects.create(
            management_station=station, appliance_group=group,
            serial_number="013201001085", hostname="fw-core-tpa-b")
        self._normalize({"deviceconfig": {"system": {
            "hostname": "fw-core-tpa-a",
            "update-schedule": {"anti-virus": {"recurring": {"daily": {
                "at": "23:45", "action": "download-and-install"}}}},
        }}}, appliance=active)
        self._normalize({"deviceconfig": {"system": {
            "hostname": "fw-core-tpa-b",
            "update-schedule": {"threats": {"recurring": {"weekly": {
                "day-of-week": "wednesday", "at": "01:02", "action": "download-only"}}}},
        }}}, appliance=passive)
        self.assertEqual(ContentUpdateSchedule.objects.filter(
            appliance__appliance_group=group).count(), 2)
        self.assertEqual(
            ContentUpdateSchedule.objects.get(appliance=active).av_recurrence, "daily")
        self.assertEqual(
            ContentUpdateSchedule.objects.get(appliance=active).threats_recurrence, "none")
        self.assertEqual(
            ContentUpdateSchedule.objects.get(appliance=passive).threats_recurrence, "weekly")
        self.assertEqual(
            ContentUpdateSchedule.objects.get(appliance=passive).av_recurrence, "none")

    def test_renormalizing_updates_the_one_row_rather_than_adding_another(self):
        appliance = self._appliance()
        self._normalize({"deviceconfig": {"system": {
            "hostname": "fw-upd",
            "update-schedule": {"anti-virus": {"recurring": {"weekly": {
                "day-of-week": "sunday", "action": "download-and-install"}}}},
        }}}, appliance=appliance)
        row = self._normalize({"deviceconfig": {"system": {
            "hostname": "fw-upd",
            "update-schedule": {"anti-virus": {"recurring": {"hourly": {
                "action": "download-only"}}}},
        }}}, appliance=appliance)
        self.assertEqual(ContentUpdateSchedule.objects.filter(appliance=appliance).count(), 1)
        self.assertEqual(row.av_recurrence, "hourly")
        self.assertEqual(row.av_action, "download-only")

    def test_the_derived_fields_are_declared_and_the_two_measured_ones_are_not(self):
        """A field in neither list reads as untracked; a measured field wrongly declared derived
        would tell a reader "we computed this" about a value the firewall holds."""
        for column in ("av_recurrence", "av_action", "update_schedule_collected", "scope",
                       "wildfire_recurrence", "gp_clientless_vpn_action"):
            self.assertIn(column, ContentUpdateSchedule.DERIVED_FIELDS, column)
        self.assertNotIn("threats_threshold_hours", ContentUpdateSchedule.DERIVED_FIELDS)
        self.assertNotIn(
            "threats_new_app_threshold_hours", ContentUpdateSchedule.DERIVED_FIELDS)

    def test_the_cadence_columns_are_non_nullable_text_defaulting_to_empty(self):
        """The declaration the ten clauses in this domain rest on. A nullable column inverts every
        one of them in silence."""
        for column in ("av_recurrence", "av_action", "threats_recurrence", "threats_action",
                       "wildfire_recurrence", "wildfire_action",
                       "gp_datafile_recurrence", "gp_datafile_action",
                       "gp_clientless_vpn_recurrence", "gp_clientless_vpn_action"):
            field = ContentUpdateSchedule._meta.get_field(column)
            self.assertFalse(field.null, column)
            self.assertEqual(field.default, "", column)

    def test_the_two_threshold_columns_are_nullable_which_is_the_opposite_choice(self):
        """Stage 5's, and declared `passes` with the reason in writing: a NULL is unreachable by
        every operator the query grammar has, so both columns read as compliant when nobody
        looked, and `update_schedule_collected` is the declared companion that carries it."""
        for column in ("threats_threshold_hours", "threats_new_app_threshold_hours"):
            self.assertTrue(ContentUpdateSchedule._meta.get_field(column).null, column)

    def test_one_row_per_appliance_is_enforced_by_the_database(self):
        appliance = self._appliance()
        snapshot = self._snapshot(appliance, {"deviceconfig": {}})
        ContentUpdateSchedule.objects.create(
            management_station=appliance.management_station, appliance=appliance,
            source_snapshot=snapshot)
        with self.assertRaises(IntegrityError), transaction.atomic():
            ContentUpdateSchedule.objects.create(
                management_station=appliance.management_station, appliance=appliance,
                source_snapshot=snapshot)


class ContentDeploymentScheduleNormalizationTests(TestCase):
    """A verdict over one management station's content deployment schedules. PAN-UPD-006.

    The payload shapes are the ones stage 4 measured on the lab's one Panorama, including the two
    that bite: `action` is a CONTAINER here where it is a LEAF on the firewall, and within one
    response some leaves arrive as bare strings and some as `{"#text": ...}` dicts because the
    dict form is what a leaf still carrying `@dirtyId` looks like.
    """

    def _station(self, hostname="panorama.dep"):
        return ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname=hostname)

    def _snapshot(self, station, payload):
        return Snapshot.objects.create(
            management_station=station,
            source_type="config_deployment_update_schedule",
            collected_at=timezone.now(),
            payload=payload,
        )

    def _normalize(self, payload, station=None, snapshot=True):
        from optivedge_integrations.integrations.platforms.pan_os.normalization import (
            normalize_station_content_deployment_schedule)
        station = station or self._station()
        if snapshot:
            self._snapshot(station, payload)
        normalize_station_content_deployment_schedule(station)
        return ContentDeploymentSchedule.objects.get(management_station=station)

    @staticmethod
    def _entry(name, content_type="app-and-threat", recurrence="every-30-mins",
               action="download-and-install", devices=(), disabled=None):
        installing = {}
        if action == "download-and-install":
            installing = {"devices": {"member": list(devices)}} if devices else None
        entry = {
            "@name": name,
            "download-source": {"update-server": None},
            content_type: {"recurring": {recurrence: {"action": {action: installing}}}},
        }
        if disabled is not None:
            entry["disabled"] = disabled
        return entry

    # ---------------------------------------------------------------- the three states

    def test_a_station_nobody_read_holds_the_empty_string_and_fires(self):
        """A station nobody collected must NOT be absent from every query: then an uncollected
        estate and a standalone one with no management station at all read identically. The row is
        written at its firing values instead."""
        row = self._normalize({}, snapshot=False)
        self.assertFalse(row.deployment_schedule_read)
        self.assertEqual(row.central_schedule_state, "")
        self.assertEqual(row.rollout_staging_shape, "")
        self.assertEqual(row.enabled_schedule_count, 0)
        self.assertEqual(row.installing_schedule_count, 0)
        self.assertEqual(row.schedules, [])
        self.assertIsNone(row.source_snapshot)
        self.assertNotEqual(row.central_schedule_state, "enabled")

    def test_a_station_with_no_schedule_at_all_holds_none_and_says_it_was_read(self):
        """ABSENCE IS THE FINDING for PAN-UPD-006's first half, measured twice: the lab held NO
        deployment schedule before stage 4's fixtures and holds none after them. `none` is a
        DIFFERENT state from the empty string above and both fire - but one says the estate has no
        central governance and the other says nobody looked."""
        row = self._normalize({})
        self.assertTrue(row.deployment_schedule_read)
        self.assertEqual(row.central_schedule_state, "none")
        self.assertEqual(row.rollout_staging_shape, "none")
        self.assertEqual(row.schedules, [])

    def test_entries_that_are_all_disabled_read_as_all_disabled_and_not_as_a_count(self):
        """DISABLED IS A THIRD STATE AND A COUNT PASSES IT. `disabled` is the only way to switch a
        deployment schedule off - there is no `none` branch on this object's recurrence - and the
        operational oracle omits everything about a disabled schedule except that it is disabled.
        An estate whose single schedule is disabled has no central governance whatsoever."""
        row = self._normalize({"deployment-update-schedule": {"entry": [
            self._entry("oep-dep-1", disabled="yes"),
            self._entry("oep-dep-2", disabled={"@dirtyId": "1", "#text": "yes"}),
        ]}})
        self.assertEqual(row.central_schedule_state, "all_disabled")
        self.assertEqual(row.enabled_schedule_count, 0)
        self.assertEqual(row.installing_schedule_count, 2)
        self.assertNotEqual(row.central_schedule_state, "enabled")

    def test_one_enabled_entry_is_enough_for_the_state_to_read_enabled(self):
        row = self._normalize({"deployment-update-schedule": {"entry": [
            self._entry("oep-dep-1", disabled="yes"),
            self._entry("oep-dep-2"),
        ]}})
        self.assertEqual(row.central_schedule_state, "enabled")
        self.assertEqual(row.enabled_schedule_count, 1)

    def test_an_absent_disabled_leaf_reads_as_enabled(self):
        """With the key committed as `yes` the operational oracle answers `Schedule "<n>" is
        disabled`; with the key deleted and committed it answers the cadence and `is in waiting`.
        Stage 4 never wrote an explicit `no`, so it declines to promote the implicit - but the
        behaviour either side of it is measured and both readings count the schedule towards
        governance."""
        row = self._normalize({"deployment-update-schedule": {
            "entry": self._entry("oep-dep-1")}})
        self.assertEqual(row.enabled_schedule_count, 1)
        self.assertEqual(row.central_schedule_state, "enabled")

    # --------------------------------------------------- installing, and the staging shape

    def test_a_download_only_schedule_is_not_counted_as_installing(self):
        """The measured fact that makes `installing_schedule_count` more than bookkeeping: a
        `download-only` schedule names NO DEVICES AT ALL by construction, because `devices` is a
        child of `download-and-install` and not of the action container. So an estate could hold
        two schedules, look staged by count, and have one of them pushing to nobody."""
        row = self._normalize({"deployment-update-schedule": {"entry": [
            self._entry("oep-dep-1", action="download-only"),
            self._entry("oep-dep-2", devices=["691665AC334B458"]),
        ]}})
        self.assertEqual(row.enabled_schedule_count, 2)
        self.assertEqual(row.installing_schedule_count, 1)
        self.assertEqual(row.rollout_staging_shape, "single")
        self.assertEqual([record["devices"] for record in row.schedules],
                         [[], ["691665AC334B458"]])

    def test_two_installing_schedules_over_disjoint_lists_read_as_staged(self):
        """STAGING PHYSICALLY IS TWO SCHEDULES OVER TWO DISJOINT DEVICE LISTS, because the product
        has no ring, canary or test-group construct at all. This is the only half a computation
        can reach; whether the staging was INTENDED is discharged onto an engineer."""
        row = self._normalize({"deployment-update-schedule": {"entry": [
            self._entry("oep-dep-ring1", devices=["691665AC334B458"]),
            self._entry("oep-dep-ring2", devices=["6A9C0A9904E7D6E"]),
        ]}})
        self.assertEqual(row.installing_schedule_count, 2)
        self.assertEqual(row.rollout_staging_shape, "multiple_disjoint")

    def test_two_installing_schedules_sharing_a_firewall_are_not_disjoint(self):
        row = self._normalize({"deployment-update-schedule": {"entry": [
            self._entry("oep-dep-ring1", devices=["691665AC334B458", "6A9C0A9904E7D6E"]),
            self._entry("oep-dep-ring2", devices=["6A9C0A9904E7D6E"]),
        ]}})
        self.assertEqual(row.rollout_staging_shape, "multiple_overlapping")

    def test_an_installing_schedule_naming_nobody_is_not_a_disjoint_ring(self):
        """An absent `devices` list asserts that the schedule installs to NO firewall - measured -
        so two schedules where one names nobody cannot be shown to stage anything. The answer is
        the less-staged of the two, which is the direction a reader should be wrong in."""
        row = self._normalize({"deployment-update-schedule": {"entry": [
            self._entry("oep-dep-ring1", devices=["691665AC334B458"]),
            self._entry("oep-dep-ring2"),
        ]}})
        self.assertEqual(row.installing_schedule_count, 2)
        self.assertEqual(row.rollout_staging_shape, "multiple_overlapping")

    def test_a_device_member_carrying_a_dirty_marker_is_read_through_its_text(self):
        """On a committed read each member is a bare string; on a candidate one it is
        `{"#text": "<serial>"}`. The declared read is the CANDIDATE, so the dict form is the one
        to expect, and a reader that stringifies the dict would compare a serial against a dict's
        repr and find every list disjoint."""
        row = self._normalize({"deployment-update-schedule": {"entry": [
            self._entry("oep-dep-ring1", devices=[{"#text": "691665AC334B458"}]),
            self._entry("oep-dep-ring2", devices=[{"#text": "691665AC334B458"}]),
        ]}})
        self.assertEqual(row.schedules[0]["devices"], ["691665AC334B458"])
        self.assertEqual(row.rollout_staging_shape, "multiple_overlapping")

    def test_a_single_member_list_parses_as_a_list(self):
        """`<member>` arrives as a scalar when there is one of it and as a list when there are
        several - `ensure_list` is the shipped answer and six runs wrote their own before it was
        written down."""
        row = self._normalize({"deployment-update-schedule": {"entry": self._entry(
            "oep-dep-1", devices=["691665AC334B458"])}})
        self.assertEqual(row.schedules[0]["devices"], ["691665AC334B458"])

    # --------------------------------------------------------------- shape and grain

    def test_the_per_entry_detail_survives_as_a_display_column(self):
        """The price of the verdict grain, paid where a reader can see it: the entry-grained
        detail is what PAN-UPD-006's second record hands an engineer."""
        row = self._normalize({"deployment-update-schedule": {"entry": self._entry(
            "oep-dep-1", content_type="wildfire", recurrence="daily",
            devices=["6A9C0A9904E7D6E"])}})
        self.assertEqual(row.schedules, [{
            "name": "oep-dep-1",
            "enabled": True,
            "content_type": "wildfire",
            "recurrence": "daily",
            "action": "download-and-install",
            "devices": ["6A9C0A9904E7D6E"],
        }])

    def test_one_entry_holds_exactly_one_content_type(self):
        """Enforced by SILENT REPLACEMENT, measured three times through one entry on committed
        configuration: writing a second content-type element returned the entry holding ONLY the
        new one, the whole first subtree gone, with no message."""
        row = self._normalize({"deployment-update-schedule": {"entry": self._entry(
            "oep-dep-1", content_type="anti-virus", recurrence="daily")}})
        self.assertEqual(row.schedules[0]["content_type"], "anti-virus")

    def test_a_verdict_may_not_outlive_the_reading_it_rested_on(self):
        row = ContentDeploymentSchedule(
            deployment_schedule_read=False, central_schedule_state="none")
        with self.assertRaises(ValidationError):
            row.clean()
        counted = ContentDeploymentSchedule(
            deployment_schedule_read=False, enabled_schedule_count=1)
        with self.assertRaises(ValidationError):
            counted.clean()
        ContentDeploymentSchedule(deployment_schedule_read=False).clean()

    def test_renormalizing_updates_the_one_row_rather_than_adding_another(self):
        station = self._station()
        self._normalize({"deployment-update-schedule": {
            "entry": self._entry("oep-dep-1")}}, station=station)
        row = self._normalize({}, station=station)
        self.assertEqual(ContentDeploymentSchedule.objects.filter(
            management_station=station).count(), 1)
        self.assertEqual(row.central_schedule_state, "none")

    def test_the_snapshot_this_row_was_built_from_is_the_station_s_own(self):
        """`appliance__isnull=True` is part of the lookup and not decoration: every other config
        snapshot in the estate is a firewall's, taken through `target=`, and one of those matching
        on source_type alone would make a firewall's payload the estate's verdict."""
        from optivedge_integrations.integrations.platforms.pan_os.normalization.content_updates \
            import latest_deployment_schedule_snapshot
        station = self._station()
        appliance = Appliance.objects.create(
            management_station=station, serial_number="SERIAL-DEP", hostname="fw-dep")
        Snapshot.objects.create(
            management_station=station, appliance=appliance,
            source_type="config_deployment_update_schedule",
            collected_at=timezone.now(), payload={"deployment-update-schedule": {
                "entry": self._entry("not-the-estates")}})
        self.assertIsNone(latest_deployment_schedule_snapshot(station))
        own = self._snapshot(station, {})
        self.assertEqual(latest_deployment_schedule_snapshot(station), own)

    def test_every_column_is_declared_derived_because_none_reads_a_key(self):
        """A row that is a verdict over entries reads no key off any one of them, so no column can
        carry a `FieldProvenance` row. Without the declaration they would be indistinguishable
        from fields nothing tracks."""
        for column in ("scope", "deployment_schedule_read", "central_schedule_state",
                       "enabled_schedule_count", "installing_schedule_count",
                       "rollout_staging_shape", "schedules"):
            self.assertIn(column, ContentDeploymentSchedule.DERIVED_FIELDS, column)

    def test_one_row_per_management_station_is_enforced_by_the_database(self):
        station = self._station()
        ContentDeploymentSchedule.objects.create(management_station=station)
        with self.assertRaises(IntegrityError), transaction.atomic():
            ContentDeploymentSchedule.objects.create(management_station=station)


class ContentUpdateCollectorTests(SimpleTestCase):
    """The one read in this estate addressed at the management station's OWN configuration."""

    def test_the_station_read_passes_no_target(self):
        """THE ABSENCE OF `target=` IS THE WHOLE OF IT. The same xpath through `target=<serial>` is
        answered `code=6 Invalid sequence` by a firewall, so a collector that reaches every
        appliance and never addresses the station collects nothing about this object no matter how
        many firewalls it reads."""
        from optivedge_integrations.integrations.platforms.pan_os.collectors import (
            collect_content_deployment_schedule)
        session = SimpleNamespace(
            target="691665AC334B458",
            request_xml_api=lambda params, target=None: self._capture(params, target),
        )
        collected = collect_content_deployment_schedule(session)
        self.assertIsNone(self.captured_target)
        self.assertEqual(self.captured["action"], "get")
        self.assertEqual(self.captured["type"], "config")
        self.assertTrue(self.captured["xpath"].endswith(
            "/deviceconfig/system/deployment-update-schedule"))
        self.assertTrue(self.captured["xpath"].startswith("/config/devices/entry["))
        self.assertEqual(collected.source_type, "config_deployment_update_schedule")

    def _capture(self, params, target):
        self.captured = params
        self.captured_target = target
        return {"response": {"@status": "success", "result": None}}

    def test_an_xpath_matching_nothing_is_a_reading_and_not_a_crash(self):
        """Stage 4 measured that the CONTAINER read returns a bare absence here rather than the
        `total-count="0"` envelope an ENTRY read returns. Left as None it would reach persistence
        as a null payload and trip the snapshot's NOT NULL constraint, turning a legitimate
        reading - "this estate has no central schedule" - into a crash."""
        from optivedge_integrations.integrations.platforms.pan_os.collectors import (
            collect_content_deployment_schedule)
        session = SimpleNamespace(
            target=None,
            request_xml_api=lambda params, target=None: self._capture(params, target),
        )
        collected = collect_content_deployment_schedule(session)
        self.assertEqual(collected.response["response"]["result"], {})
# ===========================================================================
# The `globalprotect-gateway` domain. PAN-GPG-001 to PAN-GPG-007.
# ===========================================================================


class _GlobalProtectGatewayBase(TestCase):
    """Shared fixture for the three gateway models and the posture columns.

    NO GLOBALPROTECT GATEWAY EXISTS ANYWHERE IN THE LAB, and that is the reason these payloads
    look different from `_GlobalProtectBase`'s. Stage 6 spent ELEVEN LEASE WINDOWS on the one
    candidate-clean appliance that has interfaces at all and could not commit one: eleven
    distinct requirements, nine of them in no stage file, from `validate full` inside the
    window. So the gateway ENTRY shapes below are CONSTRUCTED from the key set and the refusals
    stage 4 and stage 6 measured, and they are marked as such on each constant.

    WHAT IS NOT CONSTRUCTED, and it is what the readback rests on: every CONTAINER state here
    was read off the four appliances on 2026-10-30 through Panorama's `target=` proxy with no
    write of any kind, and cross-read with `action=show` as well as from the merged view -
    `network/tunnel/global-protect-gateway` present-and-empty on three appliances and absent on
    the fourth, `global-protect-app-crypto-profiles` absent / present-and-empty / populated with
    the vendor's `default` across the estate, `shared/log-settings/hipmatch` absent on all four,
    and one standing HIP object on vsys4 of both PA-5220s. The two views agreed at every node.
    """

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.gpg")
        self.group = ApplianceGroup.objects.create(
            management_station=self.station, name="g-gpg",
            group_type=ApplianceGroup.TYPE_STANDALONE)
        self.appliance = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            serial_number="S-GPG", hostname="fw-gpg", software_version="11.2.5")
        self.group.active_appliance = self.appliance
        self.group.save()

    def _merged(self, vsys_entries, *, network=None, shared=None):
        device_entry = {"@name": "localhost.localdomain", "vsys": {"entry": vsys_entries}}
        if network is not None:
            device_entry["network"] = network
        config = {"devices": {"entry": [device_entry]}}
        if shared is not None:
            config["shared"] = shared
        return Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": config})

    def _licence(self, payload):
        return Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="request_license_info", collected_at=timezone.now(), payload=payload)

    def _vsys(self, gateways, *, name="vsys1", extra=None):
        entry = {"@name": name,
                 "global-protect": {"global-protect-gateway": {"entry": gateways}}}
        entry.update(extra or {})
        return entry

    #: THE NETWORKING HALF READ OFF pan-fw-111, fw-core-tpa-a AND fw-core-tpa-b verbatim:
    #: present and EMPTY. `action=show` answers the same shape on all three and RAISES
    #: `No such node` on 691665AC334B458, where the whole `network/tunnel` node is absent. A
    #: normalizer must read those two as one state or it reports two different things about one
    #: estate.
    LAB_EMPTY_NETWORKING_HALF = {"tunnel": {"global-protect-gateway": None}}

    #: The vendor's shipped GlobalProtect IPSec crypto profile, read off 691665AC334B458
    #: verbatim under BOTH views. Its single encryption proposal is the one block cipher of the
    #: three the leaf accepts, and it is the whole of PAN-GPG-006's crypto half on this estate.
    LAB_VENDOR_APP_CRYPTO = {
        "ike": {"crypto-profiles": {"global-protect-app-crypto-profiles": {"entry": [
            {"@name": "default",
             "encryption": {"member": ["aes-128-cbc"]},
             "authentication": {"member": ["sha1"]}}]}}},
        "tunnel": {"global-protect-gateway": None},
    }

    #: The standing HIP object on vsys4 of both PA-5220s, read under `action=show` so it is
    #: COMMITTED and not a staged edit. It belongs to the `globalprotect-portal` domain's stage
    #: 6 run and was read and left exactly as found.
    LAB_STANDING_HIP_OBJECT = {
        "@name": "oep-gpp6-hip-a",
        "host-info": {"criteria": {"client-version": {"contains": "6."}}},
    }

    #: CONSTRUCTED, and the measurement that licenses it is stage 4's key set plus stage 6's
    #: eleven refusals: the two keys the device refuses to commit a gateway without are
    #: `ssl-tls-service-profile` and `tunnel-mode` on the vsys half, and a same-named
    #: `network/tunnel` entry with `tunnel-interface` and `local-address`. Everything optional is
    #: left OFF, which is the point of this constant - it is the absent-key fixture.
    GATEWAY_BARE = {
        "@name": "oep-gpg-01",
        "ssl-tls-service-profile": "oep-crt6-32",
        "tunnel-mode": "yes",
    }

    #: CONSTRUCTED from the same measurements, with every optional key this domain reads PRESENT
    #: so the measured branch of each column is exercised beside the absent branch above.
    GATEWAY_FULL = {
        "@name": "oep-gpg-02",
        "ssl-tls-service-profile": "oep-crt6-32",
        "tunnel-mode": "yes",
        "certificate-profile": "oep-crt6-10",
        "block-quarantined-devices": "yes",
        "client-auth": {"entry": [
            {"@name": "win", "os": "Windows",
             "authentication-profile": "oep-aaa6-p14",
             "user-credential-or-client-cert-required": "no"},
            {"@name": "any", "os": "Any",
             "authentication-profile": "oep-aaa6-p12",
             "user-credential-or-client-cert-required": "no"},
        ]},
        "roles": {"entry": [
            {"@name": "default",
             "login-lifetime": {"days": "30"},
             "inactivity-logout": "240"},
        ]},
        "remote-user-tunnel-configs": {"entry": [
            {"@name": "cfg-1",
             "authentication-override": {
                 "generate-cookie": "yes",
                 "cookie-encrypt-decrypt-cert": "pan-fw-111",
                 "accept-cookie": {"cookie-lifetime": {"lifetime-in-days": "90"}}},
             "no-direct-access-to-local-network": "yes",
             "split-tunneling": {
                 "exclude-access-route": {"member": ["10.9.0.0/16"]},
                 "include-applications": {"member": ["any"]},
                 "exclude-domains": {"list": {"entry": [
                     {"@name": "example.invalid", "ports": {"member": ["443"]}}]}}}},
        ]},
    }

    #: The networking half of GATEWAY_FULL, joined on the ENTRY NAME and on nothing else -
    #: measured, because commit job 260 aborted naming the vsys entry's own name as the thing it
    #: could not find in the network level.
    NETWORK_HALF_FULL = {
        "ike": {"crypto-profiles": {"global-protect-app-crypto-profiles": {"entry": [
            {"@name": "oep-gpg-crypto",
             "encryption": {"member": ["aes-256-gcm", "aes-128-gcm"]},
             "authentication": {"member": ["sha256"]}}]}}},
        "tunnel": {"global-protect-gateway": {"entry": [
            {"@name": "oep-gpg-02",
             "tunnel-interface": "tunnel.68",
             "local-address": {"interface": "ethernet1/1", "ip": {"ipv4": "10.0.1.4/24"}},
             "ipsec": {"enable": "yes", "ipsec-crypto-profile": "oep-gpg-crypto"},
             "client": {"exclude-video-traffic": {"enabled": "yes"}}},
        ]}},
    }

    def _profiles(self):
        """The three bound-object rows a gateway's resolution runs over, as the lab holds them.

        Written directly rather than through `normalize_certificate_objects`, so that a failure
        in this domain's resolution cannot be mistaken for a failure in another domain's
        normalizer. Every value here was read off pan-fw-111 on 2026-10-30.
        """
        # NOT `show_merged_config`: these rows only need an anchor, and a second merged
        # snapshot would become the LATEST one and shadow the payload under test.
        snapshot = Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="stage7_readback_anchor", collected_at=timezone.now(), payload={})
        common = {"management_station": self.station, "appliance": self.appliance,
                  "appliance_group": self.group, "source_snapshot": snapshot}
        SslTlsServiceProfile.objects.create(
            name="oep-crt6-32", scope=SslTlsServiceProfile.SCOPE_SHARED,
            min_version="tls1-2", max_version="tls1-3",
            has_explicit_protocol_settings=True, **common)
        CertificateProfile.objects.create(
            name="oep-crt6-10", scope=CertificateProfile.SCOPE_SHARED,
            block_unauthenticated_cert=False, **common)
        AuthenticationProfile.objects.create(
            name="oep-aaa6-p14", scope=AuthenticationProfile.SCOPE_SHARED,
            method="radius", **common)
        AuthenticationProfile.objects.create(
            name="oep-aaa6-p12", scope=AuthenticationProfile.SCOPE_SHARED,
            method="local-database", **common)


class GlobalProtectGatewayAbsentKeyTests(_GlobalProtectGatewayBase):
    """What the normalizer STORES when a key is absent, column by column.

    THIS IS THE CHEAPEST PLACE IN THE PIPELINE TO LOSE A MEASUREMENT: the device reading sits in
    a handback, the value sits in the normalizer, and nothing fails when a later edit changes
    what an absence stores. Every assertion here is a VALUE and not a shape, so none of them
    would still pass if the normalizer stopped storing the column.
    """

    def test_every_optional_gateway_key_absent_stores_null_and_not_a_guess(self):
        self._merged([self._vsys([self.GATEWAY_BARE])],
                     network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        counts = normalize_globalprotect_gateways(self.appliance)

        self.assertEqual(counts["globalprotect_gateways"], 1)
        gateway = GlobalProtectGateway.objects.get()
        # MANDATORY AT COMMIT, so these two are never absent on a committed gateway and the
        # value is what a query reads.
        self.assertEqual(gateway.ssl_tls_service_profile, "oep-crt6-32")
        self.assertIs(gateway.tunnel_mode, True)
        # The five stage 4 recorded as UNMEASURED. NULL, not a guess, and the direction matters:
        # a materialised `no` on any of them would report a weaker estate as hardened.
        self.assertIsNone(gateway.certificate_profile_name)
        self.assertIsNone(gateway.block_quarantined_devices)
        self.assertIsNone(gateway.ipsec_enabled)
        self.assertIsNone(gateway.ipsec_crypto_profile_name)
        self.assertIsNone(gateway.video_traffic_excluded)
        # The two bounds, null because the gateway carries no role entry at all - the state
        # every appliance in this lab is in. A materialised 30 days or 180 minutes would be the
        # vendor's documented default expanded into a measurement nobody took.
        self.assertIsNone(gateway.login_lifetime_hours)
        self.assertIsNone(gateway.inactivity_logout_minutes)
        self.assertEqual(gateway.login_lifetime_unit, "")
        self.assertIsNone(gateway.login_lifetime_as_entered)
        # The companions are what keep those nulls inside a threshold comparison.
        self.assertFalse(gateway.login_lifetime_known)
        self.assertFalse(gateway.inactivity_logout_known)
        self.assertFalse(gateway.ipsec_enabled_known)

    def test_a_gateway_with_no_networking_half_reports_false_and_not_nothing(self):
        # The vsys half exists and the device-local collection is PRESENT AND EMPTY, which is
        # the state three of the four lab appliances are in.
        self._merged([self._vsys([self.GATEWAY_BARE])],
                     network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        self.assertFalse(GlobalProtectGateway.objects.get().networking_half_present)

    def test_an_absent_network_tunnel_node_reads_the_same_as_an_empty_one(self):
        # 691665AC334B458 has no `network/tunnel` node at all, where the other three carry it
        # present and empty. Measured under both views. Reading the two differently would report
        # two different things about one estate.
        self._merged([self._vsys([self.GATEWAY_BARE])], network={})
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        gateway = GlobalProtectGateway.objects.get()
        self.assertFalse(gateway.networking_half_present)
        self.assertIsNone(gateway.ipsec_enabled)
        self.assertIsNone(gateway.video_traffic_excluded)

    def test_an_agent_row_with_no_keys_at_all_stores_nulls_and_no_cookie(self):
        # Stage 4 measured that this entry has NO mandatory key, so a row carrying nothing but
        # its name is legal and `validate full` accepts it.
        bare_row = dict(self.GATEWAY_BARE)
        bare_row["remote-user-tunnel-configs"] = {"entry": [{"@name": "cfg-bare"}]}
        self._merged([self._vsys([bare_row])], network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)

        row = GlobalProtectGatewayAgentConfig.objects.get()
        self.assertEqual(row.entry_name, "cfg-bare")
        self.assertEqual(row.gateway_name, "oep-gpg-01")
        self.assertIsNone(row.generate_cookie)
        self.assertIsNone(row.no_direct_access_to_local_network)
        # THE ONE MEASURED IMPLICIT IN THIS DOMAIN: an absent cookie certificate asserts that
        # NOTHING is bound, and a consumer must not render this null as "not collected".
        self.assertIsNone(row.cookie_encrypt_decrypt_cert)
        # Container presence, not truthiness.
        self.assertFalse(row.accept_cookie_configured)
        self.assertFalse(row.authentication_override_configured)
        self.assertIsNone(row.cookie_lifetime_hours)
        self.assertFalse(row.cookie_lifetime_known)
        # AN ABSENT MEMBER LIST IS NOT AN EMPTY ONE and the two are kept apart.
        self.assertIsNone(row.split_tunnel_exclude_access_routes)
        self.assertIsNone(row.split_tunnel_include_access_routes)
        self.assertIsNone(row.split_tunnel_exclude_applications)
        self.assertIsNone(row.split_tunnel_include_applications)
        self.assertIsNone(row.split_tunnel_exclude_domains)
        self.assertIsNone(row.split_tunnel_include_domains)
        # ONE axis still counts: the local-network switch is NULL, which most likely leaves
        # direct access allowed, and counting the null as open is the firing direction.
        self.assertEqual(row.uninspected_egress_path_count, 1)
        self.assertTrue(row.egress_inventory_computed)

    def test_a_client_auth_row_with_the_switch_absent_stores_null_and_counts_permissive(self):
        row = dict(self.GATEWAY_BARE)
        row["client-auth"] = {"entry": [
            {"@name": "any", "os": "Any", "authentication-profile": "oep-aaa6-p14"}]}
        self._merged([self._vsys([row])], network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)

        auth_row = GlobalProtectGatewayClientAuth.objects.get()
        # NULL, declined: the schema's @default='yes' sits on the HARDENED value `no`, so
        # materialising it would report every unset row as requiring both factors.
        self.assertIsNone(auth_row.user_credential_or_client_cert_required)
        self.assertEqual(auth_row.client_os, "Any")
        # AN UNMEASURED ABSENCE COUNTS AS PERMISSIVE on the gateway's aggregate, which is the
        # claim that has to be disproved rather than assumed.
        self.assertTrue(GlobalProtectGateway.objects.get().any_client_auth_row_permits_either_or)


class GlobalProtectGatewayResolutionTests(_GlobalProtectGatewayBase):
    """The five columns resolved through a NAME onto another model's row, and the verdicts."""

    def test_a_fully_configured_gateway_resolves_every_binding_it_names(self):
        self._merged([self._vsys([self.GATEWAY_FULL])], network=self.NETWORK_HALF_FULL)
        self._profiles()
        counts = normalize_globalprotect_gateways(self.appliance)

        self.assertEqual(counts["globalprotect_gateways"], 1)
        self.assertEqual(counts["globalprotect_gateway_client_auth_rows"], 2)
        self.assertEqual(counts["globalprotect_gateway_agent_configs"], 1)
        gateway = GlobalProtectGateway.objects.get()
        self.assertEqual(gateway.entry_name, "oep-gpg-02")
        self.assertTrue(gateway.networking_half_present)
        # PAN-GPG-001: the floor is copied off the bound profile's row, not off the gateway.
        self.assertEqual(gateway.bound_tls_min_version, "tls1-2")
        self.assertTrue(gateway.tls_profile_resolves_to_an_explicit_floor)
        # PAN-GPG-006: the HEAD of the bound profile's proposal list, which is the order the
        # firewall applies.
        self.assertIs(gateway.ipsec_enabled, True)
        self.assertTrue(gateway.ipsec_enabled_known)
        self.assertEqual(gateway.ipsec_crypto_profile_name, "oep-gpg-crypto")
        self.assertEqual(gateway.bound_app_crypto_first_encryption, "aes-256-gcm")
        self.assertTrue(gateway.app_crypto_offers_gcm_first)
        # PAN-GPG-002: the bound certificate profile does NOT refuse an unauthenticated
        # certificate, so the certificate is not a second factor even though both rows demand
        # credentials AND a certificate.
        self.assertEqual(gateway.certificate_profile_name, "oep-crt6-10")
        self.assertFalse(gateway.bound_certificate_profile_blocks_unauthenticated_cert)
        self.assertFalse(gateway.any_client_auth_row_permits_either_or)
        self.assertFalse(gateway.client_certificate_is_a_second_factor)
        # PAN-GPG-007: 30 days is the ceiling of the leaf's range and converts to 720 hours.
        self.assertEqual(gateway.login_lifetime_unit, "days")
        self.assertEqual(gateway.login_lifetime_as_entered, 30)
        self.assertEqual(gateway.login_lifetime_hours, 720)
        self.assertTrue(gateway.login_lifetime_known)
        self.assertEqual(gateway.inactivity_logout_minutes, 240)
        self.assertTrue(gateway.inactivity_logout_known)
        self.assertIs(gateway.video_traffic_excluded, True)

    def test_the_vendor_default_app_crypto_profile_does_not_offer_gcm_first(self):
        # The only GlobalProtect app crypto profile in the estate, read off 691665AC334B458
        # under both views: one proposal, and it is the single block cipher of the three the
        # leaf accepts. False is the firing side and the measured state.
        gateway = dict(self.GATEWAY_FULL)
        network = {
            "ike": self.LAB_VENDOR_APP_CRYPTO["ike"],
            "tunnel": {"global-protect-gateway": {"entry": [
                {"@name": "oep-gpg-02",
                 "ipsec": {"enable": "yes", "ipsec-crypto-profile": "default"}}]}},
        }
        self._merged([self._vsys([gateway])], network=network)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)

        row = GlobalProtectGateway.objects.get()
        self.assertEqual(row.bound_app_crypto_first_encryption, "aes-128-cbc")
        self.assertFalse(row.app_crypto_offers_gcm_first)

    def test_a_binding_that_resolves_to_nothing_fires_rather_than_passing(self):
        # The commonest cause measured is that the name resolves into /config/predefined, which
        # no merge view carries - so the most plausible correctly-configured gateway is the one
        # whose profile a collector cannot find. It must report itself, not pass.
        gateway = dict(self.GATEWAY_BARE)
        gateway["ssl-tls-service-profile"] = "TLSv1.3_Default"
        self._merged([self._vsys([gateway])], network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)

        row = GlobalProtectGateway.objects.get()
        self.assertEqual(row.ssl_tls_service_profile, "TLSv1.3_Default")
        self.assertEqual(row.bound_tls_min_version, "")
        self.assertFalse(row.tls_profile_resolves_to_an_explicit_floor)

    def test_a_row_naming_a_sequence_resolves_to_no_back_end_and_fires(self):
        # The leaf accepts an authentication PROFILE or an authentication SEQUENCE and the
        # stored string does not say which, so a sequence-backed row resolves to nothing - the
        # state a check resolving only among profiles reports as "no identity service at all".
        gateway = dict(self.GATEWAY_BARE)
        gateway["client-auth"] = {"entry": [
            {"@name": "seq", "os": "Any", "authentication-profile": "oep-aaa6-seq",
             "user-credential-or-client-cert-required": "no"}]}
        self._merged([self._vsys([gateway])], network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)

        row = GlobalProtectGatewayClientAuth.objects.get()
        self.assertEqual(row.authentication_profile_name, "oep-aaa6-seq")
        self.assertEqual(row.authentication_backend_method, "")
        self.assertFalse(row.backend_can_deliver_a_second_factor)

    def test_only_the_two_vendor_named_back_ends_can_deliver_a_second_factor(self):
        self._merged([self._vsys([self.GATEWAY_FULL])], network=self.NETWORK_HALF_FULL)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)

        by_name = {r.entry_name: r for r in GlobalProtectGatewayClientAuth.objects.all()}
        self.assertEqual(by_name["win"].authentication_backend_method, "radius")
        self.assertTrue(by_name["win"].backend_can_deliver_a_second_factor)
        # `local-database` is the firewall's OWN user store. A gateway whose `Any` row points at
        # it is the per-platform defect this grain exists to name.
        self.assertEqual(by_name["any"].authentication_backend_method, "local-database")
        self.assertFalse(by_name["any"].backend_can_deliver_a_second_factor)

    def test_a_gateway_naming_no_certificate_profile_is_not_failed_for_it(self):
        # "No client certificates in use" is read as "names no certificate profile", because no
        # key says a per-platform row ASKS for one. The error direction is suppression and it is
        # recorded rather than hidden.
        self._merged([self._vsys([self.GATEWAY_BARE])],
                     network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        self.assertTrue(GlobalProtectGateway.objects.get().client_certificate_is_a_second_factor)


class GlobalProtectGatewayLifetimeTests(_GlobalProtectGatewayBase):
    """One value in three keys, and exactly one key ever exists."""

    def _agent_row(self, branch, value):
        gateway = dict(self.GATEWAY_BARE)
        gateway["remote-user-tunnel-configs"] = {"entry": [
            {"@name": "cfg", "authentication-override": {
                "accept-cookie": {"cookie-lifetime": {branch: value}}}}]}
        self._merged([self._vsys([gateway])], network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        return GlobalProtectGatewayAgentConfig.objects.get()

    def test_a_cookie_lifetime_in_days_converts_to_hours(self):
        # 90 days was WRITTEN and read back by stage 4, and it grades at the worst band only
        # once converted: the asserted hours leaf caps at 72.
        row = self._agent_row("lifetime-in-days", "90")
        self.assertEqual(row.cookie_lifetime_unit, "lifetime-in-days")
        self.assertEqual(row.cookie_lifetime_as_entered, 90)
        self.assertEqual(row.cookie_lifetime_hours, 2160)
        self.assertTrue(row.cookie_lifetime_known)
        self.assertTrue(row.accept_cookie_configured)
        self.assertTrue(row.authentication_override_configured)

    def test_a_cookie_lifetime_in_minutes_rounds_up_and_never_down(self):
        # The minutes branch is the one the vendor documents nowhere and it holds the most
        # compliant value the field can take. Rounding DOWN would move a boundary in the
        # reassuring direction, so 90 minutes is 2 hours and not 1.
        row = self._agent_row("lifetime-in-minutes", "90")
        self.assertEqual(row.cookie_lifetime_unit, "lifetime-in-minutes")
        self.assertEqual(row.cookie_lifetime_as_entered, 90)
        self.assertEqual(row.cookie_lifetime_hours, 2)

    def test_a_cookie_lifetime_in_hours_is_carried_through_unconverted(self):
        row = self._agent_row("lifetime-in-hours", "72")
        self.assertEqual(row.cookie_lifetime_unit, "lifetime-in-hours")
        self.assertEqual(row.cookie_lifetime_hours, 72)

    def test_a_committed_empty_accept_cookie_container_still_accepts_a_cookie(self):
        """THE BRANCH A MUTATION OF THIS MODULE SURVIVED, and the lab cannot produce the row.

        Added after mutation-testing this domain's own harness: replacing the key test
        `"accept-cookie" in override` with `bool(override.get("accept-cookie"))` left all 36
        tests GREEN, because every payload above either omits the container or gives it a
        populated child. The two readings differ on exactly one shape - a COMMITTED EMPTY
        container, which xmltodict parses to `None` - and that shape decides whether PAN-GPG-003
        applies to the row at all.

        CONSTRUCTED, because no gateway exists anywhere in this lab to carry it. The shape is not
        invented: `models/globalprotect.py::GlobalProtectEnforcementPoint`'s own docstring
        records it measured on the sibling node - *"deleting the last entry leaves the container
        present and empty... a committed empty one parses to None"* - and an appliance in this
        estate carries exactly that residue at `global-protect -> global-protect-portal -> null`.

        The direction of the error is why it matters: truthiness reads this row as accepting NO
        cookie, which SUPPRESSES the control on a row that accepts one and bounds nothing.
        """
        gateway = dict(self.GATEWAY_BARE)
        gateway["remote-user-tunnel-configs"] = {"entry": [
            {"@name": "cfg", "authentication-override": {"accept-cookie": None}}]}
        self._merged([self._vsys([gateway])], network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)

        row = GlobalProtectGatewayAgentConfig.objects.get()
        self.assertTrue(row.accept_cookie_configured)
        self.assertTrue(row.authentication_override_configured)
        # It accepts a cookie and bounds nothing, which is the state the companion exists for.
        self.assertIsNone(row.cookie_lifetime_hours)
        self.assertEqual(row.cookie_lifetime_unit, "")
        self.assertFalse(row.cookie_lifetime_known)

    def test_a_committed_empty_authentication_override_container_still_counts(self):
        """The same shape one level up, and the same suppression if it is read by truthiness."""
        gateway = dict(self.GATEWAY_BARE)
        gateway["remote-user-tunnel-configs"] = {"entry": [
            {"@name": "cfg", "authentication-override": None}]}
        self._merged([self._vsys([gateway])], network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)

        row = GlobalProtectGatewayAgentConfig.objects.get()
        self.assertTrue(row.authentication_override_configured)
        self.assertFalse(row.accept_cookie_configured)
        self.assertIsNone(row.generate_cookie)
        self.assertIsNone(row.cookie_encrypt_decrypt_cert)

    def test_the_weakest_login_lifetime_across_the_roles_is_the_one_stored(self):
        # CONSTRUCTED: the `roles` entry name is constrained to `default`, measured, so a real
        # gateway carries ONE role. The aggregate is written for the estate where that is not
        # true, and a check taking the first or the strictest role would report a gateway
        # leaving a session up for a month as bounded at an hour.
        gateway = dict(self.GATEWAY_BARE)
        gateway["roles"] = {"entry": [
            {"@name": "r-strict", "login-lifetime": {"hours": "2"}, "inactivity-logout": "5"},
            {"@name": "r-weak", "login-lifetime": {"days": "30"}, "inactivity-logout": "240"},
        ]}
        self._merged([self._vsys([gateway])], network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)

        row = GlobalProtectGateway.objects.get()
        self.assertEqual(row.login_lifetime_hours, 720)
        self.assertEqual(row.login_lifetime_unit, "days")
        self.assertEqual(row.login_lifetime_as_entered, 30)
        self.assertEqual(row.inactivity_logout_minutes, 240)


class GlobalProtectGatewayEgressCountTests(_GlobalProtectGatewayBase):
    """Eight axes, one of them on another model, and what each one counts."""

    def _count(self, split=None, *, local=None, video=None, override=None):
        row = {"@name": "cfg"}
        if split is not None:
            row["split-tunneling"] = split
        if local is not None:
            row["no-direct-access-to-local-network"] = local
        if override is not None:
            row["authentication-override"] = override
        gateway = dict(self.GATEWAY_BARE)
        gateway["@name"] = "oep-gpg-02"
        gateway["remote-user-tunnel-configs"] = {"entry": [row]}
        network = {"tunnel": {"global-protect-gateway": {"entry": [
            {"@name": "oep-gpg-02",
             "client": ({"exclude-video-traffic": {"enabled": video}} if video else {})}]}}}
        self._merged([self._vsys([gateway])], network=network)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        return GlobalProtectGatewayAgentConfig.objects.get()

    def test_a_full_tunnel_with_the_local_network_closed_counts_nothing(self):
        row = self._count(split={}, local="yes")
        self.assertEqual(row.uninspected_egress_path_count, 0)
        self.assertTrue(row.egress_inventory_computed)

    def test_an_open_local_network_is_a_path_the_split_tunnel_container_cannot_see(self):
        # It is a SIBLING of `split-tunneling` rather than a child, and the vendor puts the
        # local subnet inside the split-tunnel decision itself while the control does not.
        self.assertEqual(self._count(split={}, local="no").uninspected_egress_path_count, 1)

    def test_an_include_list_of_only_any_is_not_narrower_than_everything(self):
        # The literal `any` is an accepted member, measured at the write and stored verbatim. A
        # list holding only it routes everything into the tunnel, so it is not a split tunnel.
        row = self._count(split={"include-applications": {"member": ["any"]}}, local="yes")
        self.assertEqual(row.split_tunnel_include_applications, ["any"])
        self.assertEqual(row.uninspected_egress_path_count, 0)

    def test_a_narrow_include_list_is_a_split_tunnel_even_with_no_exclusions(self):
        # A gateway with zero exclusions and a narrow include list is a split tunnel an
        # exclusion-only read calls full, which is why the assertion is about every path.
        row = self._count(split={"access-route": {"member": ["10.0.0.0/8"]}}, local="yes")
        self.assertEqual(row.uninspected_egress_path_count, 1)

    def test_the_video_exclusion_on_the_gateway_reaches_this_rows_count(self):
        # PAN-GPG-004's fourth axis and the only one outside the split-tunnel container: it sits
        # on the device-local networking half, so an inventory built on this collection alone
        # returns zero on a gateway excluding all video streaming.
        row = self._count(split={}, local="yes", video="yes")
        self.assertEqual(row.uninspected_egress_path_count, 1)

    def test_a_domain_exclusion_keeps_its_ports_rather_than_flattening_to_a_name(self):
        # The shape is list/entry[@name] with a `ports` key, so a reader written for a member
        # list loses every port restriction.
        row = self._count(
            split={"exclude-domains": {"list": {"entry": [
                {"@name": "example.invalid", "ports": {"member": ["443", "8443"]}}]}}},
            local="yes")
        self.assertEqual(row.split_tunnel_exclude_domains,
                         [{"domain": "example.invalid", "ports": ["443", "8443"]}])
        self.assertEqual(row.uninspected_egress_path_count, 1)

    def test_every_axis_at_once_counts_them_all(self):
        row = self._count(
            split={"exclude-access-route": {"member": ["10.9.0.0/16"]},
                   "access-route": {"member": ["10.0.0.0/8"]},
                   "exclude-applications": {"member": ["C:\\\\bin\\\\x.exe"]},
                   "include-applications": {"member": ["chrome"]},
                   "exclude-domains": {"list": {"entry": [{"@name": "a.invalid"}]}},
                   "include-domains": {"list": {"entry": [{"@name": "b.invalid"}]}}},
            local="no", video="yes")
        self.assertEqual(row.uninspected_egress_path_count, 8)


class GlobalProtectPostureTests(_GlobalProtectGatewayBase):
    """PAN-GPG-005, on `GlobalProtectEnforcementPoint` by ruling P374a."""

    def test_the_standing_hip_object_is_counted_and_decides_nothing(self):
        # vsys4 of both PA-5220s, read under `action=show` so it is COMMITTED. One HIP object,
        # no HIP profile, no rule - the pipeline is defined and enforces nothing, which is the
        # state the verdict exists to report.
        self._merged([self._vsys([], name="vsys4", extra={
            "profiles": {"hip-objects": {"entry": [self.LAB_STANDING_HIP_OBJECT]}}})])
        self._profiles()
        counts = normalize_globalprotect_gateways(self.appliance)

        self.assertEqual(counts["globalprotect_posture_points"], 1)
        point = GlobalProtectEnforcementPoint.objects.get()
        self.assertEqual(point.hip_object_count, 1)
        self.assertEqual(point.hip_profile_count, 0)
        self.assertEqual(point.rules_referencing_a_hip_profile_count, 0)
        self.assertFalse(point.posture_referenced_in_policy)

    def test_a_vsys_with_no_posture_at_all_still_gets_a_row(self):
        # The commonest failing state is that NONE of the four things exists, and at the entry
        # grain there would be no row to report it with.
        self._merged([self._vsys([])])
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        point = GlobalProtectEnforcementPoint.objects.get()
        self.assertEqual(point.hip_object_count, 0)
        self.assertFalse(point.posture_referenced_in_policy)

    def test_the_three_bare_keywords_are_not_a_posture_match(self):
        # `any`, `no-hip` and `quarantine` are keywords measured at the write path, never
        # references, and `any` is the commonest member in this estate. Counting a populated
        # member list would report the whole lab as matching on posture.
        self._merged([self._vsys([], extra={
            "profiles": {"hip-objects": {"entry": [self.LAB_STANDING_HIP_OBJECT]},
                         "hip-profiles": {"entry": [{"@name": "hp-1", "match": "'oep-gpp6-hip-a'"}]}},
            "rulebase": {"security": {"rules": {"entry": [
                {"@name": "r-any", "source-hip": {"member": ["any"]}},
                {"@name": "r-nohip", "source-hip": {"member": ["no-hip"]}},
                {"@name": "r-quarantine", "destination-hip": {"member": ["quarantine"]}},
            ]}}}})])
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        point = GlobalProtectEnforcementPoint.objects.get()
        self.assertEqual(point.hip_profile_count, 1)
        self.assertEqual(point.rules_referencing_a_hip_profile_count, 0)
        self.assertFalse(point.posture_referenced_in_policy)

    def test_a_rule_naming_a_real_hip_profile_completes_the_pipeline(self):
        self._merged([self._vsys([], extra={
            "profiles": {"hip-objects": {"entry": [self.LAB_STANDING_HIP_OBJECT]},
                         "hip-profiles": {"entry": [{"@name": "hp-1", "match": "'oep-gpp6-hip-a'"}]}},
            "rulebase": {"security": {"rules": {"entry": [
                {"@name": "r-posture", "source-hip": {"member": ["any", "hp-1"]}},
            ]}}}})])
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        point = GlobalProtectEnforcementPoint.objects.get()
        self.assertEqual(point.rules_referencing_a_hip_profile_count, 1)
        self.assertTrue(point.posture_referenced_in_policy)

    def test_an_absent_hipmatch_container_reports_no_automatic_quarantine(self):
        # Measured absent on all four appliances under BOTH views - the merged payload carries
        # no `hipmatch` key and `action=show` raises `No such node`. False is the firing side
        # and the real state of the estate.
        self._merged([self._vsys([])], shared={"log-settings": {"syslog": None}})
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        self.assertFalse(
            GlobalProtectEnforcementPoint.objects.get().automatic_quarantine_action_present)

    def test_a_hipmatch_match_list_carrying_quarantine_is_the_automatic_route(self):
        # CONSTRUCTED: no appliance in this estate holds a hipmatch match list at all, so the
        # true branch has no device instance here. The shape is the CLI grammar's.
        self._merged([self._vsys([])], shared={"log-settings": {"hipmatch": {"match-list": {
            "entry": [{"@name": "ml-1", "filter": "All Logs",
                       "actions": {"quarantine": None}}]}}}})
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        self.assertTrue(
            GlobalProtectEnforcementPoint.objects.get().automatic_quarantine_action_present)
        # And it reaches the gateway's own copy of the reading, which is where PAN-GPG-005's
        # second clause group reads it.
        self._merged([self._vsys([self.GATEWAY_BARE])],
                     shared={"log-settings": {"hipmatch": {"match-list": {"entry": [
                         {"@name": "ml-1", "actions": {"quarantine": None}}]}}}},
                     network=self.LAB_EMPTY_NETWORKING_HALF)
        normalize_globalprotect_gateways(self.appliance)
        self.assertTrue(GlobalProtectGateway.objects.get().automatic_quarantine_path_exists)


class GlobalProtectGatewayLicenceTests(_GlobalProtectGatewayBase):
    """Three licence shapes from one command, measured on four appliances."""

    def test_an_appliance_naming_the_gateway_feature_unexpired_is_licensed(self):
        # 691665AC334B458's reply verbatim, trimmed to the two GlobalProtect features: the
        # GATEWAY and the PORTAL are SEPARATE features, so a control asserting "a GlobalProtect
        # licence" has to say which.
        self._licence({"licenses": {"entry": [
            {"feature": "GlobalProtect Gateway", "expires": "Never", "expired": "no"},
            {"feature": "GlobalProtect Portal", "expires": "Never", "expired": "no"},
        ]}})
        self._merged([self._vsys([self.GATEWAY_BARE])],
                     network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        gateway = GlobalProtectGateway.objects.get()
        self.assertTrue(gateway.globalprotect_gateway_licensed)
        self.assertTrue(gateway.licence_state_known)

    def test_a_populated_reply_with_no_gateway_feature_is_known_and_unlicensed(self):
        # 6A9C0A9904E7D6E's reply verbatim: three features and none of them GlobalProtect.
        self._licence({"licenses": {"entry": [
            {"feature": "Adv Threat Prevention", "expired": "no"},
            {"feature": "PA-VM", "expired": "no"},
            {"feature": "Threat Prevention", "expired": "no"},
        ]}})
        self._merged([self._vsys([self.GATEWAY_BARE])],
                     network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        gateway = GlobalProtectGateway.objects.get()
        self.assertFalse(gateway.globalprotect_gateway_licensed)
        # THE READ ANSWERED. That is a different fact from "it answered nothing", and the two
        # must not be conflated: conflating them suppresses a control on a read that said
        # nothing.
        self.assertTrue(gateway.licence_state_known)

    def test_the_empty_envelope_both_pa_5220s_answer_is_not_a_no(self):
        # `{'licenses': None}` arrives with status=success on both PA-5220s. It is TRUTHY at the
        # outer dict and falsy one level in, so a consumer testing the reply's truthiness
        # concludes licences are present on an appliance that reported none.
        self._licence({"licenses": None})
        self._merged([self._vsys([self.GATEWAY_BARE])],
                     network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        gateway = GlobalProtectGateway.objects.get()
        self.assertFalse(gateway.globalprotect_gateway_licensed)
        self.assertFalse(gateway.licence_state_known)

    def test_a_licence_read_nobody_took_is_not_a_no_either(self):
        self._merged([self._vsys([self.GATEWAY_BARE])],
                     network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        gateway = GlobalProtectGateway.objects.get()
        self.assertFalse(gateway.globalprotect_gateway_licensed)
        self.assertFalse(gateway.licence_state_known)

    def test_an_expired_gateway_entitlement_does_not_count_as_licensed(self):
        # CONSTRUCTED: every licence in this estate carries `expired: no` beside
        # `expires: Never`, so nothing here exercises the difference. The stage 5 declaration
        # asks for `expired = no` in as many words, and this column is never claused on - it
        # goes into the finding's wording - so reading `expired` costs nothing.
        self._licence({"licenses": {"entry": [
            {"feature": "GlobalProtect Gateway", "expires": "January 01, 2020",
             "expired": "yes"}]}})
        self._merged([self._vsys([self.GATEWAY_BARE])],
                     network=self.LAB_EMPTY_NETWORKING_HALF)
        self._profiles()
        normalize_globalprotect_gateways(self.appliance)
        gateway = GlobalProtectGateway.objects.get()
        self.assertFalse(gateway.globalprotect_gateway_licensed)
        self.assertTrue(gateway.licence_state_known)


class SslTlsExplicitProtocolSettingsTests(TestCase):
    """`has_explicit_protocol_settings`, and the bug the stage 7 readback caught in it."""

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_PANORAMA, hostname="pano.eps")
        self.group = ApplianceGroup.objects.create(
            management_station=self.station, name="g-eps",
            group_type=ApplianceGroup.TYPE_STANDALONE)
        self.appliance = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            serial_number="S-EPS", hostname="fw-eps", software_version="11.2.5")
        self.group.active_appliance = self.appliance
        self.group.save()

    def _shared_profiles(self, entries):
        Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": {
                "shared": {"ssl-tls-service-profile": {"entry": entries}},
                "devices": {"entry": [{"@name": "localhost.localdomain"}]}}})

    def test_a_profile_stating_only_a_ceiling_still_states_a_range(self):
        # oep-crt6-34 verbatim, vsys1 of 6A9C0A9904E7D6E, read 2026-10-30: `protocol-settings`
        # carries `max-version` and NO `min-version`. Stage 6 recorded it as "a ceiling and no
        # floor" and the store was reporting it with both, because `min_version` is
        # materialised - which is how this column's first implementation was caught.
        self._shared_profiles([{"@name": "oep-crt6-34", "certificate": "c",
                                "protocol-settings": {"max-version": "tls1-3"}}])
        normalize_certificate_objects(self.appliance)
        profile = SslTlsServiceProfile.objects.get(name="oep-crt6-34")
        # The MATERIALISED floor is still stored - that reading is another domain's and is not
        # changed here.
        self.assertEqual(profile.min_version, "tls1-2")
        self.assertEqual(profile.max_version, "tls1-3")
        self.assertTrue(profile.has_explicit_protocol_settings)

    def test_a_profile_stating_neither_bound_states_no_range_at_all(self):
        # CONSTRUCTED, and the measurement that licenses it is that NO profile in this lab omits
        # both bounds - twelve profiles across four appliances, every one carrying at least one.
        # So this branch has no device instance here, which is exactly why it needs a test: the
        # first implementation read the PARSED values, both of which are materialised, so this
        # profile reported that somebody had chosen a range. That is the reassuring side, and a
        # gateway verdict resting on it would have passed.
        self._shared_profiles([{"@name": "oep-no-range", "certificate": "c",
                                "protocol-settings": None}])
        normalize_certificate_objects(self.appliance)
        profile = SslTlsServiceProfile.objects.get(name="oep-no-range")
        self.assertEqual(profile.min_version, "tls1-2")
        self.assertEqual(profile.max_version, "tls1-3")
        self.assertFalse(profile.has_explicit_protocol_settings)

    def test_a_profile_stating_both_bounds_states_a_range(self):
        # The estate's `default` profile on 6A9C0A9904E7D6E, trimmed to the two bounds.
        self._shared_profiles([{"@name": "default", "certificate": "c",
                                "protocol-settings": {"min-version": "tls1-2",
                                                      "max-version": "tls1-3"}}])
        normalize_certificate_objects(self.appliance)
        self.assertTrue(
            SslTlsServiceProfile.objects.get(name="default").has_explicit_protocol_settings)


# ===========================================================================================
# zone-dos-protection - PAN-ZON-001 to PAN-ZON-008
# ===========================================================================================
#
# WHAT THESE TESTS ARE FOR, in the words stage 7's contract added on 2026-10-29: a column whose
# absent-key behaviour was MEASURED owes a test asserting it, because that is the cheapest place
# in the pipeline to lose a measurement - the device reading sits in a handback, the value sits
# in the normaliser, and nothing fails when a later edit changes what an absence stores. A test
# that would still pass if the normaliser stopped storing the column is not that test.
#
# EVERY PAYLOAD HERE IS A LAB SHAPE, read off 6A9C0A9904E7D6E and 691665AC334B458 on 2026-10-30
# through Panorama's `target=` proxy, trimmed to the keys under test. Two are CONSTRUCTED and
# say so in their own comment: the two branches a readback over this lab could not discriminate,
# which the mutation harness found and which are therefore the two that most need a test.
#
# Appliances are named by SERIAL, because 691665AC334B458 answers to the factory-default
# hostname `PA-VM` while every artifact calls it `pan-fw-201`.

from optivedge_integrations.integrations.models import (  # noqa: E402
    DosPolicyRule as _ZdpRule,
    ZoneProtectionProfile as _ZdpProfile,
)
from optivedge_integrations.integrations.platforms.pan_os.normalization.network_hardening import (  # noqa: E402
    normalize_session_settings as _zdp_session,
)
from optivedge_integrations.integrations.platforms.pan_os.normalization.zone_dos_protection import (  # noqa: E402
    attachment_sweep_is_complete as _zdp_sweep,
    dos_flood_and_resource_settings as _zdp_dos_settings,
    dos_profile_references as _zdp_refs,
    normalize_dos_policy_rules as _zdp_rules,
    normalize_zone_protection_profiles as _zdp_profiles,
    scan_weakest_action as _zdp_weakest,
)
from optivedge_integrations.integrations.platforms.pan_os.normalization.zones import (  # noqa: E402
    normalize_zones as _zdp_zones,
    zone_attachment_verdict as _zdp_verdict,
    zone_can_receive_traffic as _zdp_can_receive,
)


class _ZoneDosBase(TestCase):
    """One appliance, one vsys, one merged snapshot the caller shapes."""

    def setUp(self):
        self.station = ManagementStation.objects.create(
            station_type=ManagementStation.StationType.PAN_FIREWALL, hostname="pano-zdp.net")
        self.group = ApplianceGroup.objects.create(
            management_station=self.station, name="g-zdp",
            group_type=ApplianceGroup.TYPE_STANDALONE)
        self.appliance = Appliance.objects.create(
            management_station=self.station, appliance_group=self.group,
            serial_number="6A9C0A9904E7D6E", hostname="fw-zdp",
            software_version="11.2.3-h3")
        self.group.active_appliance = self.appliance
        self.group.save()
        self.point = EnforcementPoint.objects.create(
            management_station=self.station, appliance=self.appliance, vsys_name="vsys1",
            in_scope=True)

    def _merged(self, *, profiles=None, zones=None, deviceconfig=None, rulebase=None,
                extra_device=None):
        device = {
            "@name": "localhost.localdomain",
            "network": {"profiles": {"zone-protection-profile": {"entry": profiles}}
                        if profiles is not None else {}},
            "deviceconfig": deviceconfig or {},
            "vsys": {"entry": [{
                "@name": "vsys1",
                **({"zone": {"entry": zones}} if zones is not None else {}),
                **({"rulebase": rulebase} if rulebase is not None else {}),
            }]},
        }
        device.update(extra_device or {})
        return Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            enforcement_point=self.point,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": {"devices": {"entry": [device]}}})

    def _bare_profile(self, name="oep-zdp6-p01"):
        """oep-zdp6-p01's measured shape: committed carrying nothing but its own name.

        Stage 4 built it, committed it, and read it back from `show config running` still
        carrying only `description` - so every absence this fixture asserts is a state a
        RUNNING device holds and not a candidate artefact.
        """
        self._merged(profiles=[{"@name": name}])
        _zdp_profiles(self.appliance)
        return _ZdpProfile.objects.get(profile_name=name)


class ZoneProtectionProfileAbsentKeyTests(_ZoneDosBase):
    """What the profile stores when a key is absent, and what the row says it rests on."""

    def test_an_absent_flood_enable_means_the_type_is_NOT_metered(self):
        """All five, on oep-zdp6-p01. FALSE IS THE FIRING SIDE of PAN-ZON-002 and -003, so a
        profile nobody configured reports rather than reassuring."""
        row = self._bare_profile()

        self.assertFalse(row.syn_flood_enabled)
        self.assertFalse(row.udp_flood_enabled)
        self.assertFalse(row.icmp_flood_enabled)
        self.assertFalse(row.icmpv6_flood_enabled)
        self.assertFalse(row.other_ip_flood_enabled)

    def test_an_absent_flood_enable_records_the_MEASURED_vendor_default(self):
        """The provenance row is the only thing separating a key absent with PAN-OS supplying
        the value from a key nobody has measured, and these five are measured."""
        row = self._bare_profile()

        for column in ("syn_flood_enabled", "udp_flood_enabled", "icmp_flood_enabled",
                       "icmpv6_flood_enabled", "other_ip_flood_enabled"):
            self.assertEqual(
                row.provenance_for(column).provenance_type, "pan_os_default", column)

    def test_an_absent_packet_drop_means_the_firewall_does_NOT_discard(self):
        row = self._bare_profile()

        for column in ("discard_ip_spoof", "strict_ip_check",
                       "discard_strict_source_routing", "discard_loose_source_routing",
                       "discard_malformed_option",
                       "discard_overlapping_tcp_segment_mismatch",
                       "discard_record_route", "discard_timestamp"):
            self.assertIs(getattr(row, column), False, column)
            self.assertEqual(
                row.provenance_for(column).provenance_type, "pan_os_default", column)

    def test_an_absent_tcp_reject_non_syn_stores_the_POINTER_and_not_a_value(self):
        """`global` is NEITHER the asserted `yes` NOR a readable `no` - the shape stage 4 named
        as one a consumer gets wrong, measured wrong in both directions."""
        row = self._bare_profile()

        self.assertEqual(row.non_syn_reject_configured, "global")
        self.assertEqual(
            row.provenance_for("non_syn_reject_configured").provenance_type, "pan_os_default")

    def test_an_absent_scan_ENTRY_means_the_type_is_not_detected_AT_ALL(self):
        """THE WORSE OF THE TWO ABSENCES, and the one a normaliser that collapses them loses:
        with no entry the outer grid's four scan columns render BLANK and the `scan` node is
        absent from the committed entry. The empty string is the sentinel, not `alert`."""
        row = self._bare_profile()

        self.assertEqual(row.scan_tcp_port_action, "")
        self.assertEqual(row.scan_udp_port_action, "")
        self.assertEqual(row.scan_host_sweep_action, "")
        self.assertEqual(row.scan_ip_protocol_action, "")
        # And no provenance row at all: nothing is tracked, because there is no key.
        self.assertIsNone(row.provenance_for("scan_tcp_port_action"))

    def test_a_scan_entry_with_no_ACTION_child_records_the_event(self):
        """oep-zdp6-p07's measured shape: the four entries exist carrying an interval and a
        threshold and NO action element. Measured separately on entry 8002 - its action child
        deleted and the entry committed carrying only `interval`, `show config running`
        returning {'@name': '8002', 'interval': '102'}, and the dialog rendering `alert`."""
        self._merged(profiles=[{"@name": "oep-zdp6-p07", "scan": {"entry": [
            {"@name": "8001", "interval": "5", "threshold": "100"},
            {"@name": "8002", "interval": "5", "threshold": "100"},
            {"@name": "8003", "interval": "5", "threshold": "100"},
            {"@name": "8006", "interval": "5", "threshold": "100"},
        ]}}])
        _zdp_profiles(self.appliance)
        row = _ZdpProfile.objects.get(profile_name="oep-zdp6-p07")

        self.assertEqual(row.scan_tcp_port_action, "alert")
        self.assertEqual(row.scan_host_sweep_action, "alert")
        self.assertEqual(
            row.provenance_for("scan_tcp_port_action").provenance_type, "pan_os_default")
        # AND THE EVENT IS RECORDED, which is the whole difference from the absence above.
        self.assertFalse(row.scan_detection_gap)

    def test_the_sensitivity_keys_store_NOTHING_when_nobody_measured_them(self):
        """`not_assumed`, and the two leads disagree: help p.672 gives 100 for every scan type
        and the device's own form prefills 4 for IP Protocol Scan. The integer parser returns a
        genuine NULL, which NO operator reaches - which is why the companion exists."""
        row = self._bare_profile()

        self.assertIsNone(row.scan_interval)
        self.assertIsNone(row.scan_threshold)
        self.assertEqual(row.scan_block_ip_track_by, "")
        self.assertEqual(
            row.provenance_for("scan_interval").provenance_type, "not_configured")
        self.assertEqual(
            row.provenance_for("scan_threshold").provenance_type, "not_configured")
        self.assertFalse(row.scan_sensitivity_known)

    def test_an_absent_exclusion_list_means_NOTHING_is_exempt(self):
        """The safe direction, and stage 4's weakest promotion on this object - the positive
        control was not paid, and it is promoted only because an empty entry-list has no other
        reading."""
        row = self._bare_profile()

        self.assertEqual(row.scan_white_list, [])
        self.assertEqual(row.scan_white_list_count, 0)
        self.assertEqual(
            row.provenance_for("scan_white_list").provenance_type, "pan_os_default")

    def test_an_absent_flood_rate_set_stores_NOTHING_rather_than_the_dialog_hint(self):
        """ExtJS writes emptyText into the input's `value` and the hint reads
        `10000 [0 - 2000000]` - the shipped number AND the range in one placeholder. Stage 4
        recorded these implicits as a RELATION rather than a constant and set `merge_as: hold`,
        so there is no value to put in the column."""
        self.assertIsNone(self._bare_profile().flood_rates)

    def test_the_action_is_WHICH_CONTAINER_EXISTS_and_neither_is_blank(self):
        """`flood/tcp-syn` has no `action` leaf: the response is which of two sibling CONTAINERS
        is present, and there is no third state the configuration expresses."""
        self.assertEqual(self._bare_profile().syn_flood_action, "")
        self._merged(profiles=[{"@name": "p-red", "flood": {"tcp-syn": {
            "enable": "yes", "red": {"activate-rate": "1000"}}}}])
        _zdp_profiles(self.appliance)
        row = _ZdpProfile.objects.get(profile_name="p-red")
        self.assertEqual(row.syn_flood_action, "red")
        # AND THE RESOLVED BRANCH TRAVELS WITH THE NUMBERS, because the same activate-rate
        # means a different response under each container.
        self.assertEqual(row.flood_rates["syn_flood_action"], "red")
        self.assertEqual(row.flood_rates["rates"]["tcp-syn"]["red"]["activate-rate"], "1000")

    def test_an_unmarked_entry_records_LOCAL_and_never_the_parents_marker(self):
        """THE SPECIFIC ERROR STAGE 4 MEASURED ON THIS OBJECT: `network/profiles` is itself
        @ptpl='shared-single-vsys' while the profile collection beneath it carries no mark at
        all, so a normaliser inheriting the parent's would label every locally-created profile
        template-supplied AND name the wrong template."""
        Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            source_type="show_merged_config", collected_at=timezone.now(),
            payload={"config": {"devices": {"entry": [{
                "@name": "localhost.localdomain",
                "network": {"profiles": {
                    "@ptpl": "shared-single-vsys",
                    "zone-protection-profile": {"entry": [{"@name": "oep-zdp6-p01"}]}}},
                "vsys": {"entry": [{"@name": "vsys1"}]}}]}}})
        _zdp_profiles(self.appliance)
        row = _ZdpProfile.objects.get(profile_name="oep-zdp6-p01")

        self.assertEqual(row.provenance_for("__entry__").provenance_type, "local")

    def test_a_template_supplied_entry_records_TEMPLATE_from_its_OWN_marker(self):
        # CONSTRUCTED. No zone protection profile in this lab is template-supplied - all
        # thirteen record `local` - so the readback proved only one arm of this branch and a
        # mutation that hardcoded the parent's marker moved nothing until the harness learned to
        # compare provenance at all. That is exactly why this arm needs a test.
        self._merged(profiles=[{"@name": "p-tpl", "@ptpl": "ptpl-pan-fw-111"}])
        _zdp_profiles(self.appliance)
        row = _ZdpProfile.objects.get(profile_name="p-tpl")

        self.assertEqual(row.provenance_for("__entry__").provenance_type, "template")
        self.assertEqual(row.provenance_for("__entry__").raw_value, "ptpl-pan-fw-111")


class ZoneProtectionProfileVerdictTests(_ZoneDosBase):
    """The computed columns, each asserted at the value its own control reads."""

    def test_every_gap_verdict_FIRES_on_a_profile_that_stores_nothing(self):
        """The direction rules.md asks for: a profile nobody configured reports itself rather
        than reading as a clean one, and that is what its inputs' own defaults compute to."""
        row = self._bare_profile()

        self.assertTrue(row.volumetric_flood_gap)
        self.assertTrue(row.packet_drop_gap)
        self.assertTrue(row.scan_detection_gap)

    def test_the_volumetric_verdict_IGNORES_the_half_open_connection_flood(self):
        """PAN-ZON-002 owns the SYN flood and PAN-ZON-003 owns the other four. A verdict that
        counted all five would fire on oep-zdp6-p04 - whose only gap is the SYN flood - under
        the wrong control, and the two have different severities."""
        self._merged(profiles=[{"@name": "oep-zdp6-p04", "flood": {
            "tcp-syn": {"enable": "no"}, "udp": {"enable": "yes"},
            "icmp": {"enable": "yes"}, "icmpv6": {"enable": "yes"},
            "other-ip": {"enable": "yes"}}}])
        _zdp_profiles(self.appliance)
        row = _ZdpProfile.objects.get(profile_name="oep-zdp6-p04")

        self.assertFalse(row.syn_flood_enabled)
        self.assertFalse(row.volumetric_flood_gap)

    def test_the_packet_drop_verdict_reads_the_FOUR_asserted_drops_and_not_all_eight(self):
        """oep-zdp6-p09's shape: the spoofed-source drop is off and the four PAN-ZON-006 names
        are on. `discard-ip-spoof` is PAN-ZON-005's and belongs to a different finding."""
        self._merged(profiles=[{"@name": "oep-zdp6-p09",
                                "discard-ip-spoof": "no",
                                "discard-strict-source-routing": "yes",
                                "discard-loose-source-routing": "yes",
                                "discard-malformed-option": "yes",
                                "discard-overlapping-tcp-segment-mismatch": "yes"}])
        _zdp_profiles(self.appliance)
        row = _ZdpProfile.objects.get(profile_name="oep-zdp6-p09")

        self.assertFalse(row.discard_ip_spoof)
        self.assertFalse(row.packet_drop_gap)

    def test_the_pointer_resolves_through_the_DEVICE_WIDE_leaf_in_both_directions(self):
        """HALF OF PAN-ZON-006'S ANSWER IS NOT ON THE PROFILE AT ALL. oep-zdp6-sess carries
        `tcp-reject-non-syn: no` device-wide, so a profile at `global` enforces NO."""
        self._merged(
            profiles=[{"@name": "p-global"}],
            deviceconfig={"setting": {"session": {"tcp-reject-non-syn": "no"}}})
        _zdp_profiles(self.appliance)
        self.assertEqual(
            _ZdpProfile.objects.get(profile_name="p-global").non_syn_reject_effective, "no")

        _ZdpProfile.objects.all().delete()
        Snapshot.objects.all().delete()
        self._merged(profiles=[{"@name": "p-global"}], deviceconfig={"setting": {}})
        _zdp_profiles(self.appliance)
        # The device-wide key absent means the firewall DOES reject, measured, so the same
        # profile at `global` now enforces YES.
        self.assertEqual(
            _ZdpProfile.objects.get(profile_name="p-global").non_syn_reject_effective, "yes")

    def test_a_profile_stating_its_OWN_refusal_needs_no_second_reading(self):
        """oep-zdp6-p10's shape - `no` on the profile - which resolves without the device-wide
        node and must not be overwritten by it."""
        self._merged(
            profiles=[{"@name": "oep-zdp6-p10", "tcp-reject-non-syn": "no"}],
            deviceconfig={"setting": {}})
        _zdp_profiles(self.appliance)
        row = _ZdpProfile.objects.get(profile_name="oep-zdp6-p10")

        self.assertEqual(row.non_syn_reject_configured, "no")
        self.assertEqual(row.non_syn_reject_effective, "no")

    def test_an_UNRECOGNISED_literal_resolves_through_the_device_and_does_not_invent_yes(self):
        # CONSTRUCTED, and the licence is a refusal stage 4 recorded because it looks like
        # evidence and is not: writing `global` to the DEVICE-WIDE <yes|no> leaf was ACCEPTED at
        # the write and never committed, so whether commit validation rejects a third value
        # there IS NOT ESTABLISHED - and a normaliser must not assume this leaf's committed
        # value set is closed.
        self._merged(
            profiles=[{"@name": "p-odd", "tcp-reject-non-syn": "something-else"}],
            deviceconfig={"setting": {"session": {"tcp-reject-non-syn": "no"}}})
        _zdp_profiles(self.appliance)

        self.assertEqual(
            _ZdpProfile.objects.get(profile_name="p-odd").non_syn_reject_effective, "no")

    def test_the_weakest_scan_action_is_NOT_a_lexical_or_numeric_ORDER(self):
        """THE ORDERING IS NOT A LADDER. Stage 3 grades `block` as acceptable and `block-ip`
        tracking the source-and-destination PAIR as low, because a scanner that moves to
        another destination is no longer blocked - so the pair form sorts BELOW the plain block
        despite being the more elaborate setting."""
        pair = _zdp_weakest(
            {"8001": "block", "8002": "block-ip", "8003": "block", "8006": "block"},
            "source-and-destination")
        self.assertEqual(pair, "block-ip-source-and-destination")
        # And the SOURCE form outranks the plain block, which no comparison on the strings
        # produces in either direction.
        source = _zdp_weakest(
            {"8001": "block-ip", "8002": "block-ip", "8003": "block-ip", "8006": "block-ip"},
            "source")
        self.assertEqual(source, "block-ip-source")
        # A MISSING ENTRY IS WORSE THAN ANY ACTION, which is the whole point of the sentinel.
        self.assertEqual(
            _zdp_weakest({"8001": "allow", "8002": "", "8003": "block", "8006": "block"}, ""),
            "")

    def test_an_UNRANKED_action_sorts_WORST_and_is_never_graded_as_the_best(self):
        # CONSTRUCTED. The four measured arms are the whole value set `action=complete`
        # returned, so no lab profile can produce this - and a value outside the set is a
        # reading nobody has graded. Ranking it best would grade a profile on a guess.
        self.assertEqual(
            _zdp_weakest({"8001": "block", "8002": "a-new-action", "8003": "block",
                          "8006": "block"}, ""),
            "a-new-action")

    def test_a_blockip_whose_track_by_was_never_read_grades_at_the_GENTLER_rank(self):
        """The reassuring direction, chosen deliberately and named in stage 5's not_measured:
        `scan_sensitivity_known` beside it is what says the reading was incomplete, and no
        clause rests on this column."""
        self.assertEqual(
            _zdp_weakest({"8001": "block-ip", "8002": "block-ip", "8003": "block-ip",
                          "8006": "block-ip"}, ""),
            "block-ip-source")

    def test_the_exemption_count_walks_BOTH_address_leaves(self):
        # CONSTRUCTED IN ONE HALF, and the half that is constructed is the one this lab cannot
        # discriminate: oep-zdp6-p03 holds two entries each carrying exactly one `ipv4` and no
        # `ipv6`, so an entry count and an address count are EQUAL on every profile in this
        # estate and a mutation counting entries moved nothing. The Help describes ONE address
        # field with a type selector and the configuration holds TWO leaves, so a reader
        # checking one of them sees half the list.
        self._merged(profiles=[{"@name": "p-wl", "scan-white-list": {"entry": [
            {"@name": "oep-zdp6-wl1", "ipv4": "10.90.1.10/32"},
            {"@name": "both", "ipv4": "10.90.1.11/32", "ipv6": "2001:db8::1/128"},
        ]}}])
        _zdp_profiles(self.appliance)
        row = _ZdpProfile.objects.get(profile_name="p-wl")

        self.assertEqual(row.scan_white_list_count, 3)
        self.assertEqual(len(row.scan_white_list), 2)

    def test_the_two_reference_verdicts_are_NOT_each_others_negation(self):
        """They answer the same join and carry OPPOSITE defaults, because the two controls that
        read them fail in opposite directions: a content control that falls silent hides a real
        exposure, and a hygiene control that fires wrongly gets a profile deleted."""
        self._merged(
            profiles=[{"@name": "oep-zdp6-p02"}, {"@name": "oep-zdp6-p12"}],
            zones=[{"@name": "oep-zdp6-z02", "network": {
                "layer3": {"member": "ethernet1/1"},
                "zone-protection-profile": "oep-zdp6-p02"}}])
        _zdp_zones(self.point)
        _zdp_profiles(self.appliance)

        attached = _ZdpProfile.objects.get(profile_name="oep-zdp6-p02")
        self.assertEqual(attached.attached_zone_count, 1)
        self.assertTrue(attached.is_in_force)
        self.assertFalse(attached.is_unreferenced)

        orphan = _ZdpProfile.objects.get(profile_name="oep-zdp6-p12")
        self.assertEqual(orphan.attached_zone_count, 0)
        self.assertFalse(orphan.is_in_force)
        self.assertTrue(orphan.is_unreferenced)

    def test_an_INCOMPLETE_sweep_suppresses_the_deletion_candidate_and_nothing_else(self):
        # CONSTRUCTED: no appliance in this lab has a shared gateway, which needs multi-vsys
        # with external zones, so the readback proved only the complete arm and a mutation
        # hardcoding false was caught on the flag alone. The suppression is the behaviour that
        # matters - PAN-ZON-008's remediation is a DELETION.
        self._merged(profiles=[{"@name": "oep-zdp6-p12"}], zones=[],
                     extra_device={"shared-gateway": {"entry": [{"@name": "sg1"}]}})
        _zdp_profiles(self.appliance)
        row = _ZdpProfile.objects.get(profile_name="oep-zdp6-p12")

        self.assertFalse(row.attachment_sweep_complete)
        self.assertFalse(row.is_unreferenced)
        # AND THE CONTENT CONTROLS STILL SEE THE ROW: `is_in_force` does not depend on the
        # sweep, so an incomplete sweep costs a deletion candidate and not five findings.
        self.assertFalse(row.is_in_force)

    def test_an_appliance_with_no_shared_gateway_HAS_a_complete_sweep(self):
        """The measured lab state on both appliances, and the reason the flag is not simply
        false for ever: the question is whether a surface exists to have been missed."""
        self.assertTrue(_zdp_sweep({"vsys": {"entry": []}}))
        self.assertFalse(_zdp_sweep({"shared-gateway": {"entry": [{"@name": "sg1"}]}}))

    def test_a_profile_whose_name_differs_only_in_CASE_is_not_in_force(self):
        # CONSTRUCTED, and this is the second branch the readback could not discriminate: no
        # name pair on this lab differs only in case, so a mutation that case-folded the join
        # moved nothing. Profile names are case-sensitive and not normalised (help p.663), so a
        # case-folded join would report a profile as attached that the dataplane does not
        # resolve - which is the unsafe direction for `is_in_force`.
        self.assertTrue(_zdp_verdict("OEP-ZDP6-P02", {"oep-zdp6-p02"}))
        self.assertFalse(_zdp_verdict("oep-zdp6-p02", {"oep-zdp6-p02"}))


class ZoneAttachmentColumnTests(_ZoneDosBase):
    """PAN-ZON-001's three columns on the shipped `Zone`."""

    def test_a_zone_naming_a_profile_that_does_NOT_EXIST_reads_as_unresolved(self):
        """THE COLUMN THE MEASUREMENT BOUGHT. The configuration expresses no referential
        integrity at this leaf - stage 4 measured it as a free string - so a dangling name
        reads as configured and the zone meters nothing. `is_empty` on
        `zone_protection_profile` is the clause a reviewer would write and it misses this."""
        self._merged(
            profiles=[{"@name": "oep-zdp6-p02"}],
            zones=[{"@name": "z-dangling", "network": {
                "layer3": {"member": "ethernet1/1"},
                "zone-protection-profile": "a-profile-that-is-not-there"}}])
        _zdp_zones(self.point)
        _zdp_profiles(self.appliance)
        row = Zone.objects.get(name="z-dangling")

        self.assertEqual(row.zone_protection_profile, "a-profile-that-is-not-there")
        self.assertTrue(row.zone_protection_unresolved)

    def test_a_zone_with_NO_attachment_leaf_reads_as_unresolved(self):
        """24 committed zones across four appliances have never held the key, and a zone with
        no attachment has NO entry in `show zone-protection` at all."""
        self._merged(profiles=[], zones=[{"@name": "oep-zdp6-z21", "network": {
            "external": {"member": "vsys2"}}}])
        _zdp_zones(self.point)
        row = Zone.objects.get(name="oep-zdp6-z21")

        self.assertEqual(row.zone_protection_profile, "")
        self.assertTrue(row.zone_protection_unresolved)

    def test_a_zone_naming_a_profile_that_EXISTS_reads_as_resolved(self):
        self._merged(
            profiles=[{"@name": "oep-zdp6-p02"}],
            zones=[{"@name": "oep-zdp6-z02", "network": {
                "layer3": {"member": "ethernet1/1"},
                "zone-protection-profile": "oep-zdp6-p02"}}])
        _zdp_zones(self.point)
        self.assertFalse(Zone.objects.get(name="oep-zdp6-z02").zone_protection_unresolved)

    def test_an_EXTERNAL_zone_with_no_interfaces_stays_IN_the_population(self):
        """oep-zdp6-z21's shape. An external zone carries inter-vsys traffic and has no
        interface list of its own, and it still offers the attachment - so the applicability
        gate is a DISJUNCTION and not a count."""
        self.assertTrue(_zdp_can_receive("external", 0))
        self.assertTrue(_zdp_can_receive("layer3", 1))
        self.assertFalse(_zdp_can_receive("layer3", 0))

    def test_a_zone_with_NO_type_subtree_is_OUTSIDE_the_population(self):
        """oep-zdp6-z24's shape: committed carrying no `network` subtree at all, which stage 4
        measured is a legal committable state. Such a zone receives no traffic, so it is
        outside PAN-ZON-001 rather than at the gentle end of it."""
        self._merged(profiles=[], zones=[{"@name": "oep-zdp6-z24"}])
        _zdp_zones(self.point)
        row = Zone.objects.get(name="oep-zdp6-z24")

        self.assertEqual(row.zone_type, "unknown")
        self.assertEqual(row.interface_count, 0)
        self.assertFalse(row.can_receive_traffic)

    def test_the_interface_count_matches_the_type_subtrees_member_list(self):
        self._merged(profiles=[], zones=[{"@name": "trust", "network": {
            "layer3": {"member": ["ethernet1/1", "ethernet1/2", "loopback.906"]}}}])
        _zdp_zones(self.point)
        row = Zone.objects.get(name="trust")

        self.assertEqual(row.interface_count, 3)
        self.assertTrue(row.can_receive_traffic)


class DosPolicyRuleTests(_ZoneDosBase):
    """PAN-ZON-007's rulebase - the rule that reads as protection and consults nothing."""

    def _rules(self, entries):
        self._merged(rulebase={"dos": {"rules": {"entry": entries}}})
        return _zdp_rules(self.point)

    def test_the_action_is_WHICH_CHILD_EXISTS_and_only_protect_consults_the_profile(self):
        """Three child nodes, not three values, with the stored shape
        `action: {'protect': None}`. A later stage reading the parent's path expecting a string
        gets an ELEMENT instead."""
        self._rules([
            {"@name": "oep-zdp6-r01", "action": {"protect": None}, "disabled": "yes",
             "protection": {"aggregate": {"profile": "oep-zdp6-d01"}}},
            {"@name": "oep-zdp6-r02", "action": {"allow": None}, "disabled": "yes",
             "protection": {"aggregate": {"profile": "oep-zdp6-d01"}}},
        ])
        rows = {r.rule_name: r for r in _ZdpRule.objects.all()}

        self.assertEqual(rows["oep-zdp6-r01"].rule_action, "protect")
        self.assertEqual(rows["oep-zdp6-r02"].rule_action, "allow")
        # Both NAME a profile; only one consults it, and that is the finding PAN-ZON-007 makes.
        self.assertTrue(rows["oep-zdp6-r01"].names_a_profile)
        self.assertTrue(rows["oep-zdp6-r02"].names_a_profile)

    def test_the_applicability_gate_reads_BOTH_profile_slots(self):
        """A GATE THAT READS ONE SLOT CALLS EVERY CLASSIFIED-ONLY RULE INAPPLICABLE: the
        catalogue row for this control asserts the AGGREGATE slot alone, and the two are
        sibling nodes with no exclusivity the grammar expresses."""
        self._rules([
            {"@name": "oep-zdp6-r03", "action": {"deny": None}, "disabled": "yes",
             "protection": {"classified": {
                 "profile": "oep-zdp6-d02",
                 "classification-criteria": {"address": "source-ip-only"}}}},
            {"@name": "oep-zdp6-r04", "action": {"deny": None}, "disabled": "yes"},
        ])
        rows = {r.rule_name: r for r in _ZdpRule.objects.all()}

        self.assertEqual(rows["oep-zdp6-r03"].classified_profile, "oep-zdp6-d02")
        self.assertEqual(rows["oep-zdp6-r03"].aggregate_profile, "")
        self.assertTrue(rows["oep-zdp6-r03"].names_a_profile)
        self.assertFalse(rows["oep-zdp6-r04"].names_a_profile)

    def test_an_absent_AGGREGATE_profile_means_no_aggregate_thresholds_are_in_force(self):
        """help p.205 - 'An Aggregate profile setting of None means there are no threshold
        settings in place for the aggregate traffic' - measured on the bare committed rule."""
        self._rules([{"@name": "r-bare", "action": {"deny": None}}])
        row = _ZdpRule.objects.get(rule_name="r-bare")

        self.assertEqual(row.aggregate_profile, "")
        self.assertEqual(
            row.provenance_for("aggregate_profile").provenance_type, "pan_os_default")

    def test_the_three_UNMEASURED_rule_keys_store_nothing_and_say_so(self):
        """The classified arm was never written and the one surface that renders an answer is a
        dialog measured to prefill - and the prefill is the value the vendor WARNS about for an
        internet-facing zone. `disabled` is unmeasured on this object too: the shipped
        `SecurityRule` and `DecryptionRule` both materialise false off THEIR own measurements,
        and carrying that across would assume two rulebases share a default."""
        self._rules([{"@name": "r-bare", "action": {"deny": None}}])
        row = _ZdpRule.objects.get(rule_name="r-bare")

        for column in ("classified_profile", "classification_address", "rule_disabled"):
            self.assertEqual(getattr(row, column), "", column)
            self.assertEqual(
                row.provenance_for(column).provenance_type, "not_configured", column)

    def test_the_array_ORDER_is_preserved_because_no_key_holds_it(self):
        """The order is the evaluation order and no key holds it, so a reader that does not
        preserve array order loses the only statement the device makes about sequence."""
        self._rules([{"@name": f"r{n}", "action": {"deny": None}} for n in range(1, 5)])
        self.assertEqual(
            [(r.rule_name, r.rule_position) for r in _ZdpRule.objects.all()],
            [("r1", 1), ("r2", 2), ("r3", 3), ("r4", 4)])

    def test_the_rulebase_is_part_of_the_identity(self):
        """One rule name can exist in the vsys-local rulebase and in a pushed pre- and
        post-rulebase at once, which are three objects at three evaluation positions."""
        self._rules([{"@name": "shared-name", "action": {"deny": None}}])
        Snapshot.objects.create(
            management_station=self.station, appliance=self.appliance,
            enforcement_point=self.point, source_type="show_pushed_shared_policy_vsys",
            collected_at=timezone.now(),
            payload={"policy": {"panorama": {
                "pre-rulebase": {"dos": {"rules": {"entry": [
                    {"@name": "shared-name", "action": {"protect": None},
                     "@loc": "dg-edge",
                     "protection": {"aggregate": {"profile": "oep-zdp6-d01"}}}]}}}}}})
        _zdp_rules(self.point)

        rows = {r.config_source: r for r in _ZdpRule.objects.filter(rule_name="shared-name")}
        self.assertEqual(sorted(rows), ["local", "pushed_pre"])
        self.assertEqual(rows["pushed_pre"].rule_action, "protect")
        self.assertEqual(
            rows["pushed_pre"].provenance_for("__entry__").provenance_type, "device_group")


class DosProtectionProfileKindTests(_ZoneDosBase):
    """The DoS kind on the shipped `SecurityProfile` - two columns and the referrer walk."""

    def test_an_absent_type_stores_NOTHING_because_the_key_is_MANDATORY_at_commit(self):
        """Measured rather than inferred: stage 4 built a second bare profile for this question
        alone and the commit was refused with `missing 'type'`. The merge view is
        candidate-derived, so a STAGED profile can reach a normaliser without it, and the blank
        says exactly that rather than naming a default."""
        from optivedge_integrations.integrations.platforms.pan_os.normalization.zone_dos_protection import (  # noqa: E501
            dos_protection_profile_values,
        )
        values, provenance = dos_protection_profile_values({"@name": "oep-zdp-dosp2"})

        self.assertEqual(values["profile_type"], "")
        self.assertIsNone(values["flood_and_resource_settings"])
        self.assertEqual(provenance[0][0], "profile_type")
        self.assertEqual(provenance[0][1].provenance_type, "not_configured")

    def test_the_two_types_are_read_as_the_device_spells_them(self):
        from optivedge_integrations.integrations.platforms.pan_os.normalization.zone_dos_protection import (  # noqa: E501
            dos_protection_profile_values,
        )
        for token in ("aggregate", "classified"):
            values, _p = dos_protection_profile_values({"@name": "d", "type": token})
            self.assertEqual(values["profile_type"], token)

    def test_the_flood_structure_carries_the_TYPE_beside_the_numbers(self):
        """A threshold means two different things under `aggregate` and under `classified` -
        the whole matched group counted together, or each device in it individually - so a
        number read without the type is ambiguous."""
        settings = _zdp_dos_settings(
            {"type": "classified",
             "flood": {"udp": {"enable": "yes", "red": {
                 "activate-rate": "1000", "block-probability": "50",
                 "block": {"duration": "300"}}}},
             "resource": {"sessions": {"enabled": "yes",
                                       "max-concurrent-limit": "1024"}}},
            "classified")

        self.assertEqual(settings["profile_type"], "classified")
        self.assertEqual(settings["flood"]["udp"]["activate-rate"], "1000")
        self.assertEqual(settings["flood"]["udp"]["block-probability"], "50")
        self.assertEqual(settings["flood"]["udp"]["block/duration"], "300")
        self.assertEqual(settings["resource"]["max-concurrent-limit"], "1024")

    def test_the_DOS_flood_node_is_NOT_the_zone_profiles_flood_node(self):
        """Measured on three appliances: this object's `flood` has FIVE children - no
        `sctp-init`, and `action=complete` at `flood/sctp-init` answers code=6. A reader that
        shared the zone profile's constant would store a key this object cannot hold."""
        settings = _zdp_dos_settings(
            {"flood": {"sctp-init": {"enable": "yes",
                                     "red": {"activate-rate": "1"}}}}, "aggregate")

        self.assertIsNone(settings)

    def test_the_referrer_walk_reads_BOTH_slots_at_EVERY_rulebase(self):
        """THE SURFACE THE SHIPPED WALK CANNOT SEE. `collect_profile_and_group_references`
        matches a payload key whose NAME is a profile kind carrying a member list, and a DoS
        rule names its profile at `protection/aggregate/profile` - a text leaf under a key
        called `profile`. Without this the reach would read `unreferenced` on every DoS profile
        in every estate with nothing erroring."""
        root = {
            "rulebase": {"dos": {"rules": {"entry": [
                {"@name": "r01", "protection": {"aggregate": {"profile": "d01"}}},
                {"@name": "r03", "protection": {"classified": {"profile": "d02"}}},
                {"@name": "r04"},
            ]}}},
            "pre-rulebase": {"dos": {"rules": {"entry": [
                {"@name": "r-pushed", "@loc": "shared",
                 "protection": {"aggregate": {"profile": "d05"},
                                "classified": {"profile": "d06"}}},
            ]}}},
        }
        found = _zdp_refs(root)

        self.assertEqual(
            sorted((name, referrer) for name, referrer, _loc in found),
            [("d01", "rulebase/dos/r01"), ("d02", "rulebase/dos/r03"),
             ("d05", "pre-rulebase/dos/r-pushed"), ("d06", "pre-rulebase/dos/r-pushed")])
        # THE @loc TRAVELS OUT UNINTERPRETED, so the caller classifies scope from the marker
        # and never from which query returned the entry.
        self.assertEqual({loc for name, _r, loc in found if name == "d05"}, {"shared"})

    def test_a_rulebase_with_no_dos_node_contributes_no_referrer(self):
        """The measured state of vsys1 on 691665AC334B458: the whole `rulebase/dos` node is
        absent, parent and all."""
        self.assertEqual(_zdp_refs({"rulebase": {"security": {"rules": {}}}}), [])
        self.assertEqual(_zdp_refs(None), [])


class SessionSettingsDosColumnTests(_NetworkHardeningBase):
    """PAN-ZON-006's device-wide half, on the class that already owns the node."""

    def test_an_absent_key_means_the_firewall_DOES_reject_non_SYN_TCP(self):
        """THE REASSURING SIDE, AND CORRECT ANYWAY. Measured in both directions on a committed
        state: the node has never existed on 691665AC334B458 and `show session info` answers
        `tcp-nonsyn-rej: True`; `no` committed moved it to False; the leaf deleted and that
        delete committed returned it to True. A collector reporting 'not configured' here
        would be reporting the OPPOSITE of what the firewall does."""
        self._merged(deviceconfig={"setting": {"config": {"rematch": "no"}}})
        _nh_session(self.appliance)
        row = _NhSession.objects.get()

        self.assertTrue(row.tcp_reject_non_syn)
        self.assertEqual(
            row.provenance_for("tcp_reject_non_syn").provenance_type, "pan_os_default")

    def test_a_configured_no_is_read_and_marked_LOCAL(self):
        """oep-zdp6-sess's shape on 6A9C0A9904E7D6E, which is the only reason PAN-ZON-006's
        deferring state is demonstrable at all."""
        self._merged(deviceconfig={"setting": {
            "session": {"tcp-reject-non-syn": "no"}}})
        _nh_session(self.appliance)
        row = _NhSession.objects.get()

        self.assertFalse(row.tcp_reject_non_syn)
        self.assertEqual(row.provenance_for("tcp_reject_non_syn").provenance_type, "local")

    def test_the_three_absence_shapes_of_this_node_all_read_as_the_default(self):
        """Stage 4 measured all three: `action=get` returns None where the node has never
        existed, `{'session': null}` - TRUTHY, with a single null value - where it is committed
        and empty, and a truthy dict of @admin/@dirtyId/@time with no child where it is empty
        and uncommitted."""
        for shape in ({}, {"setting": {"session": None}},
                      {"setting": {"session": {"@admin": "admin", "@dirtyId": "1"}}}):
            _NhSession.objects.all().delete()
            Snapshot.objects.all().delete()
            self._merged(deviceconfig=shape)
            _nh_session(self.appliance)
            self.assertTrue(_NhSession.objects.get().tcp_reject_non_syn, shape)
